(function clearAppLocalStorage(){ try { if(typeof localStorage!=='undefined') localStorage.clear(); } catch(_e){} })();
// Bloqueo si se abrió como file:// (las APIs no funcionarán)
(function fileProtocolGuard(){
  try {
    if(location.protocol === 'file:' && !window.__fileProtocolNotified){
      window.__fileProtocolNotified = true;
      const msg = 'Estás abriendo index.html directamente (file://). Debes iniciar el servidor con "node server.js" y luego entrar a http://localhost:3000 para que /api/restock y otras rutas funcionen.';
      console.error('[FILE_PROTOCOL_BLOCK]', msg);
      // Overlay visual
      const div = document.createElement('div');
      div.style.position='fixed'; div.style.inset='0'; div.style.zIndex='999999'; div.style.background='#0f172acc'; div.style.display='flex'; div.style.flexDirection='column'; div.style.justifyContent='center'; div.style.alignItems='center'; div.style.padding='30px'; div.style.fontFamily='system-ui,Segoe UI,Roboto,sans-serif'; div.style.color='#f1f5f9';
      div.innerHTML = '<div style="max-width:640px;text-align:center;">\n<h2 style="margin:0 0 14px 0;font-size:1.6rem;">⚠️ Modo local (file://) detectado</h2>\n<p style="font-size:.95rem;line-height:1.4;margin:0 0 18px 0;">Las peticiones API se están resolviendo al mismo archivo y regresan HTML. Para continuar:</p>\n<ol style="text-align:left;font-size:.8rem;line-height:1.35;margin:0 0 18px 30px;">\n<li>Abrí PowerShell en la carpeta del proyecto.</li>\n<li>Ejecuta: <code style="background:#1e293b;padding:2px 4px;border-radius:4px;">node server.js</code></li>\n<li>En el navegador ve a: <code style="background:#1e293b;padding:2px 4px;border-radius:4px;">http://localhost:3000/</code></li>\n<li>Cierra esta pestaña file:// para no confundirte.</li>\n</ol>\n<button id="fileProtoDismiss" style="background:#0ea5e9;border:none;color:#fff;font-weight:600;padding:10px 18px;border-radius:6px;cursor:pointer;font-size:.85rem;">Entendido (ocultar)</button></div>';
      document.addEventListener('DOMContentLoaded', ()=> document.body.appendChild(div));
      document.body && document.body.appendChild(div);
      document.addEventListener('click', e=>{ if(e.target && e.target.id==='fileProtoDismiss'){ div.remove(); } });
      window.__BLOCK_API_CALLS__ = true;
      const origFetch = window.fetch;
      window.fetch = function(){ return Promise.reject(new Error('Bloqueado: abrir usando http://localhost:3000 (no file://)')); };
    }
  }catch(_e){}
})();

var API_KEY_STORAGE_PREFIX = 'app_api_key_v2';

function getApiKeyStorageKey(uid){
  const suffix = uid && typeof uid === 'string' ? uid : 'anon';
  return API_KEY_STORAGE_PREFIX + ':' + suffix;
}

function getStoredApiKey(){
  try{
    if(typeof sessionStorage === 'undefined') return '';
    const uid = window.auth?.currentUser?.uid || null;
    const key = sessionStorage.getItem(getApiKeyStorageKey(uid));
    if(key) return key;
    const legacy = sessionStorage.getItem('app_api_key');
    if(legacy){
      sessionStorage.setItem(getApiKeyStorageKey(uid), legacy);
      sessionStorage.removeItem('app_api_key');
      return legacy;
    }
  }catch(_e){}
  return '';

}

function lookupProductById(id){
  if(!id) return null;
  const pid = String(id).trim();
  if(!pid) return null;
  const searchIn = (arr)=> Array.isArray(arr)
    ? arr.find(p=>{
        const cand = String(p?._id || p?.id || p?.docId || '').trim();
        if(cand && cand === pid) return true;
        const alt = String(p?.productoId || '').trim();
        return alt && alt === pid;
      })
    : null;
  return searchIn(window.products) || searchIn(window.supplies) || null;
}

function getBomVariantEl(id){
  return typeof document !== 'undefined' ? document.getElementById(id) : null;
}

const __ventaItemsGlobal = typeof window !== 'undefined' ? window : globalThis;
let items = Array.isArray(__ventaItemsGlobal.__ventaItems)
  ? __ventaItemsGlobal.__ventaItems
  : [];
if(!Array.isArray(__ventaItemsGlobal.__ventaItems)){
  __ventaItemsGlobal.__ventaItems = items;
}

function resolveRenderItemsFn(){
  if(typeof renderItems === 'function') return renderItems;
  if(typeof window !== 'undefined' && typeof window.renderItems === 'function') return window.renderItems;
  return null;
}

function requestRenderItems(attempt){
  const fn = resolveRenderItemsFn();
  if(fn){
    try{ fn(); }catch(_e){}
    return;
  }
  if(typeof window === 'undefined') return;
  const nextAttempt = (Number(attempt)||0) + 1;
  const delay = Math.min(1000, 30 + (nextAttempt * 35));
  setTimeout(()=> requestRenderItems(nextAttempt), delay);
}

function buildPreparedMillar(context){
    if(!context || !context.baseLine) return null;
    const line = {
      descripcion: context.baseLine.descripcion,
      cantidad: context.baseLine.cantidad,
      precio: Number(context.baseLine.precio)||0,
      productoId: context.baseLine.productoId || null,
      costoUnit: Number(context.baseLine.costoUnit)||0
    };
    if(context.extrasMode === 'inline'){
      line.precio = roundCurrency((Number(line.precio)||0) + (Number(context.extrasPriceDelta)||0));
      line.costoUnit = roundCurrency((Number(line.costoUnit)||0) + (Number(context.extrasCostDelta)||0));
    }
    const extraLines = [];
    if(context.extrasMode === 'lines' && Array.isArray(context.extraLines) && context.extraLines.length){
      context.extraLines.forEach(extraLine=>{
        extraLines.push({
          descripcion: extraLine.descripcion,
          cantidad: extraLine.cantidad,
          precio: Number(extraLine.precio)||0,
          productoId: null,
          costoUnit: Number(extraLine.costoUnit)||0
        });
      });
    }
    return { primaryLine: line, extraLines, context, type:'millar' };
  }

  function buildPreparedFraction(context, pieces, pieceCalc){
    if(!context || !context.baseLine || !pieceCalc) return null;
    const basePieces = getFraccionadoBaseCantidad(context.prod);
    const unitFromTramo = Number(pieceCalc.unitPrice)||0;
    let unitPrice = unitFromTramo;
    let costoUnitBase = Number(context.baseLine.costoUnit)||0;
    if(basePieces>0){
      costoUnitBase = costoUnitBase / basePieces;
      if(context.extrasMode === 'inline'){
        unitPrice += (Number(context.extrasPriceDelta)||0) / basePieces;
        costoUnitBase += (Number(context.extrasCostDelta)||0) / basePieces;
      }
    }
    unitPrice = roundCurrency(unitPrice);
    const costoUnit = roundCurrency(costoUnitBase);
    const tramo = pieceCalc.tramo || null;
    const descSuffix = tramo ? ` (${pieces} piezas · ${formatFraccionadoRange(tramo)})` : ` (${pieces} piezas)`;
    const line = {
      descripcion: `${context.baseLine.descripcion}${descSuffix}`,
      cantidad: pieces,
      precio: unitPrice,
      productoId: context.baseLine.productoId || null,
      costoUnit
    };
    return { primaryLine: line, extraLines: [], context, type:'fraction' };
  }

  function commitPreparedLines(prepared, opts){
    if(!prepared || !prepared.primaryLine) return;
      const debug = typeof window !== 'undefined' && window.__debugVenta;
      if(debug){
        console.debug('[venta][commitPreparedLines] before ensure alias', { itemsLen: Array.isArray(items)? items.length : 'n/a', prepared });
      }
    if(typeof ensureItemsAliasActive === 'function'){
      try{ ensureItemsAliasActive(); }catch(_e){}
    }
      if(debug){
        console.debug('[venta][commitPreparedLines] after ensure alias', { itemsLen: Array.isArray(items)? items.length : 'n/a', activeTicket: typeof ticketsState !== 'undefined' ? ticketsState.active : 'n/a' });
      }
    const insertIndex = Number.isInteger(opts?.insertIndex) ? Math.max(0, Math.min(items.length, opts.insertIndex)) : -1;
    let nextIndex = insertIndex;
    const placeLine = (entry)=>{
      const copy = {
        descripcion: entry.descripcion,
        cantidad: entry.cantidad,
        precio: Number(entry.precio)||0,
        productoId: entry.productoId || null,
        costoUnit: Number(entry.costoUnit)||0
      };
      if(Array.isArray(entry.bomVariants) && entry.bomVariants.length){
        copy.bomVariants = entry.bomVariants.map(v=> ({ ...v }));
      }
      if(Array.isArray(entry.bomVariantShortages) && entry.bomVariantShortages.length){
        copy.bomVariantShortages = entry.bomVariantShortages.map(v=> ({ ...v }));
      }
      if(nextIndex>=0){
        items.splice(nextIndex, 0, copy);
        nextIndex++;
      } else {
        items.push(copy);
      }
    };
    placeLine(prepared.primaryLine);
    if(Array.isArray(prepared.extraLines) && prepared.extraLines.length){
      prepared.extraLines.forEach(extra => placeLine(extra));
    }
    if(debug){
      console.debug('[venta][commitPreparedLines] after placement', { itemsLen: Array.isArray(items)? items.length : 'n/a', itemsSnapshot: JSON.stringify(items,null,2) });
    }
    requestRenderItems(0);
    opts?.onAfter?.();
  }

  function buildBomVariantPlan(context, prepared){
    if(!prepared || !prepared.primaryLine) return null;
    const lineQty = Number(prepared.primaryLine.cantidad)||0;
    if(!(lineQty>0)) return null;
    const baseProductId = context?.baseLine?.productoId || context?.prod?._id || context?.prod?.id || null;
    const baseProduct = context?.prod || (baseProductId ? lookupProductById(baseProductId) : null);
    if(!baseProduct) return null;
    const receta = Array.isArray(baseProduct.receta) ? baseProduct.receta : null;
    if(!receta || !receta.length) return null;
    const components = [];
    receta.forEach((comp)=>{
      const compId = String(comp?.productoId || comp?.insumoId || comp?.id || '').trim();
      if(!compId) return;
      const perUnit = Number(comp?.cantidadPorUnidad || comp?.cantidad || 0);
      if(!(perUnit>0)) return;
      const tipo = String(comp?.tipo || 'INSUMO').toUpperCase();
      if(tipo === 'CONSUMIBLE') return;
      const compProd = lookupProductById(compId);
      const variants = Array.isArray(compProd?.variantes)
        ? compProd.variantes.filter(v=> String(v?.nombre||'').trim().length>0)
        : [];
      if(!variants.length) return;
      const required = perUnit * lineQty;
      components.push({
        idx: components.length,
        productoId: compId,
        productoNombre: compProd?.descripcion || comp?.descripcion || `Insumo ${compId}`,
        proveedor: compProd?.proveedor || '',
        perUnit,
        requiredQty: required,
        unitLabel: compProd?.unidad || comp?.unidad || 'u',
        variants: variants.map(v=>({
          nombre: String(v.nombre||'').trim(),
          existencias: Number(v.existencias||0)||0,
          costo: Number(v.costo||0)||0,
          precio: Number(v.precio||0)||0
        })),
        selectedIndex: -1
      });
    });
    if(!components.length) return null;
    return {
      baseProductNombre: baseProduct.descripcion || prepared.primaryLine.descripcion || '',
      baseProductId: baseProductId || null,
      components,
      lineQty,
      type: prepared.type
    };
  }

  function updateBomVariantConfirmEnabled(){
    if(!bomVariantConfirmBtn) return;
    if(!ventaVariantState || !ventaVariantState.plan){
      bomVariantConfirmBtn.disabled = true;
      return;
    }
    const ready = ventaVariantState.plan.components.every(comp=> Number.isInteger(comp.selectedIndex) && comp.selectedIndex>=0 && comp.variants[comp.selectedIndex]);
    bomVariantConfirmBtn.disabled = !ready;
  }

  function formatQty(val){
    const num = Number(val);
    if(!Number.isFinite(num)) return '0';
    if(Math.abs(num - Math.round(num)) < 1e-6) return String(Math.round(num));
    if(Math.abs(num) >= 10) return num.toFixed(1);
    return num.toFixed(2);
  }

  function renderBomVariantRows(plan){
    if(!bomVariantList) return;
    const esc = escapeHtml;
    const rows = plan.components.map(comp=>{
      const controlId = `ventaBomVariantSelect_${comp.idx}`;
      const options = comp.variants.map((variant, vIdx)=>{
        const selectedAttr = vIdx === comp.selectedIndex ? ' selected' : '';
        return `<option value="${vIdx}"${selectedAttr}>${esc(variant.nombre||'Variante')} · stock ${formatQty(variant.existencias||0)}</option>`;
      }).join('');
      const providerHtml = comp.proveedor ? `<div class="bom-variant-provider">Proveedor: ${esc(comp.proveedor)}</div>` : '';
      return `
      <div class="bom-variant-item" data-comp-idx="${comp.idx}">
        <div class="bom-variant-head">
          <div class="bom-variant-title">${esc(comp.productoNombre)}</div>
          <div class="bom-variant-required">Necesario: ${formatQty(comp.requiredQty)} ${esc(comp.unitLabel||'u')}</div>
        </div>
        ${providerHtml}
        <label class="bom-variant-label" for="${controlId}">Variante
          <select id="${controlId}" data-variant-select="${comp.idx}">${options}</select>
        </label>
        <div class="bom-variant-summary" data-role="summary"></div>
        <div class="bom-variant-warning" data-role="warning"></div>
      </div>`;
    }).join('');
    bomVariantList.innerHTML = rows;
  }

  function updateBomVariantComponent(comp){
    if(!ventaVariantState || !ventaVariantState.plan) return;
    const row = bomVariantList ? bomVariantList.querySelector(`.bom-variant-item[data-comp-idx="${comp.idx}"]`) : null;
    const selectEl = row ? row.querySelector('select[data-variant-select]') : null;
    if(selectEl && Number(selectEl.value) !== comp.selectedIndex && comp.selectedIndex>=0){
      selectEl.value = String(comp.selectedIndex);
    }
    const summaryEl = row ? row.querySelector('[data-role="summary"]') : null;
    const warnEl = row ? row.querySelector('[data-role="warning"]') : null;
    const variant = Number.isInteger(comp.selectedIndex) && comp.selectedIndex>=0 ? comp.variants[comp.selectedIndex] : null;
    if(variant){
      const available = Number(variant.existencias||0)||0;
      const shortage = Math.max(0, comp.requiredQty - available);
      comp.shortage = shortage;
      comp.selectedVariantNombre = variant.nombre;
      comp.selectedVariantExistencias = available;
      if(summaryEl){
        summaryEl.textContent = `Stock actual: ${formatQty(available)} · Requerido: ${formatQty(comp.requiredQty)}`;
      }
      if(warnEl){
        if(shortage>0){
          warnEl.textContent = `Faltan ${formatQty(shortage)} (${formatQty(available)} disponibles). Se agregará a orden de compra.`;
          warnEl.style.color = '#b91c1c';
        } else {
          warnEl.textContent = '';
          warnEl.style.color = '';
        }
      }
    } else {
      comp.shortage = comp.requiredQty;
      if(summaryEl){
        summaryEl.textContent = `Selecciona una variante. Requerido: ${formatQty(comp.requiredQty)}`;
      }
      if(warnEl){ warnEl.textContent = ''; warnEl.style.color=''; }
    }
    updateBomVariantConfirmEnabled();
  }

  function tryOpenBomVariantModal(context, prepared, opts){
    const plan = buildBomVariantPlan(context, prepared);
    if(!plan) return false;
    plan.components.forEach(comp=>{
      if(!Array.isArray(comp.variants) || !comp.variants.length) return;
      let pick = comp.variants.findIndex(v=> Number(v.existencias||0) >= comp.requiredQty);
      if(pick < 0) pick = 0;
      comp.selectedIndex = pick;
    });
    ventaVariantState = { context, prepared, opts: opts||null, plan };
    openVentaBomVariantModal();
    return true;
  }

  function openVentaBomVariantModal(){
    if(!ventaVariantState || !ventaVariantState.plan) return;
    const { plan } = ventaVariantState;
    if(bomVariantProductName) bomVariantProductName.textContent = plan.baseProductNombre || 'Producto';
    if(bomVariantHint) bomVariantHint.textContent = 'Selecciona la variante de cada insumo. Los faltantes se enviarán a una orden de compra automáticamente.';
    if(bomVariantAuto) bomVariantAuto.style.display = 'none';
    renderBomVariantRows(plan);
    plan.components.forEach(comp=> updateBomVariantComponent(comp));
    updateBomVariantConfirmEnabled();
    if(bomVariantOverlay){
      bomVariantOverlay.classList.remove('hidden');
      bomVariantOverlay.setAttribute('aria-hidden','false');
      try{ bomVariantOverlay.style.display='flex'; }catch(_e){}
    }
    document.body.classList.add('modal-open');
    setTimeout(()=>{
      try{
        const focusable = bomVariantList?.querySelector('select[data-variant-select]');
        focusable?.focus?.();
      }catch(_e){}
    },0);
  }

  function closeVentaBomVariantModal(cancelled){
    if(bomVariantOverlay){
      bomVariantOverlay.classList.add('hidden');
      bomVariantOverlay.setAttribute('aria-hidden','true');
      try{ bomVariantOverlay.style.display='none'; }catch(_e){}
    }
    try{
      const anyOpen = document.querySelector('.modal-overlay:not(.hidden)');
      if(!anyOpen) document.body.classList.remove('modal-open');
    }catch(_e){ document.body.classList.remove('modal-open'); }
    if(bomVariantList) bomVariantList.innerHTML='';
    const state = ventaVariantState;
    ventaVariantState = null;
    if(cancelled && state && state.opts && typeof state.opts.onCancel === 'function'){
      try{ state.opts.onCancel(); }catch(_e){}
    }
  }

  function applyVentaVariantSelection(){
    if(!ventaVariantState || !ventaVariantState.plan) return;
    const state = ventaVariantState;
    const { plan, prepared, opts } = state;
    const selections = [];
    const shortages = [];
    for(const comp of plan.components){
      const variant = Number.isInteger(comp.selectedIndex) && comp.selectedIndex>=0 ? comp.variants[comp.selectedIndex] : null;
      if(!variant){
        try{ notify && notify('Selecciona la variante para cada insumo.','warn'); }catch(_e){}
        return;
      }
      const available = Number(variant.existencias||0)||0;
      const required = comp.perUnit * plan.lineQty;
      const shortage = Math.max(0, required - available);
      const selection = {
        productoId: comp.productoId,
        productoNombre: comp.productoNombre,
        varianteNombre: variant.nombre || '',
        cantidad: required,
        porUnidad: comp.perUnit,
        lineCantidad: plan.lineQty,
        existenciasAntes: available,
        faltante: shortage,
        proveedor: comp.proveedor || null
      };
      selections.push(selection);
      if(shortage>0){
        shortages.push({
          productoId: selection.productoId,
          productoNombre: selection.productoNombre,
          varianteNombre: selection.varianteNombre,
          cantidad: selection.cantidad,
          faltante: shortage,
          proveedor: selection.proveedor || null
        });
      }
    }
    prepared.primaryLine.bomVariants = selections;
    prepared.primaryLine.bomVariantShortages = shortages;
    closeVentaBomVariantModal(false);
    commitPreparedLines(prepared, opts);
  }
const DEFAULT_COUNTRY_CODE = '+52';

function normalizePhone(raw){
  if(raw == null) return '';
  let value = String(raw).trim();
  if(!value) return '';
  value = value.replace(/[^0-9+]/g, '');
  if(!value) return '';
  if(value.startsWith('00')){
    value = '+' + value.slice(2);
  }
  if(value[0] !== '+'){
    if(value.length === 10){
      value = DEFAULT_COUNTRY_CODE + value;
    } else if(value.length === 11 && value.startsWith('1')){
      value = '+' + value;
    } else {
      value = '+' + value;
    }
  } else {
    value = '+' + value.slice(1).replace(/\+/g,'');
  }
  return value;
}

function decomposePhone(raw){
  const normalized = normalizePhone(raw);
  if(!normalized){
    return { e164:'', country:'', national:'' };
  }
  const digits = normalized.replace(/\D+/g,'');
  let country;
  let national;
  if(normalized.startsWith('+52') && digits.length >= 12){
    country = '+52';
    national = digits.slice(-10);
  } else if(normalized.startsWith('+1') && digits.length >= 11){
    country = '+1';
    national = digits.slice(-10);
  } else if(digits.length > 10){
    const cc = digits.slice(0, digits.length - 10);
    country = cc ? `+${cc}` : DEFAULT_COUNTRY_CODE;
    national = digits.slice(-10);
  } else {
    country = DEFAULT_COUNTRY_CODE;
    national = digits;
  }
  return { e164: `${country}${national}`, country, national };
}

function composeTelefonoValue(telefonoRaw, telefonoPaisRaw, telefonoE164){
  const prefer = normalizePhone(telefonoE164 || telefonoRaw);
  if(prefer) return prefer;
  const chunks = [];
  if(telefonoPaisRaw) chunks.push(String(telefonoPaisRaw).trim());
  if(telefonoRaw) chunks.push(String(telefonoRaw).trim());
  const fallback = normalizePhone(chunks.join(' '));
  return fallback || '';
}

function buildTelefonoPersistence(normalized){
  if(!normalized){
    return { telefono:'', telefonoPais:'', telefonoE164:'', telefonoCompleto:'' };
  }
  const parts = decomposePhone(normalized);
  return {
    telefono: parts.national || '',
    telefonoPais: parts.country || '',
    telefonoE164: parts.e164 || '',
    telefonoCompleto: parts.e164 || ''
  };
}

function formatDisplayPhone(raw){
  const normalized = normalizePhone(raw);
  if(!normalized) return '';
  const digits = normalized.replace(/\D+/g,'');
  if(normalized.startsWith('+52') && digits.length >= 12){
    const local = digits.slice(-10);
    return `+52 ${local.slice(0,3)} ${local.slice(3,6)} ${local.slice(6)}`;
  }
  if(normalized.startsWith('+1') && digits.length === 11){
    const local = digits.slice(-10);
    return `+1 ${local.slice(0,3)} ${local.slice(3,6)} ${local.slice(6)}`;
  }
  return normalized;
}

try{
  window.__AUTH_STATE_KNOWN__ = false;
  window.__AUTH_SHOW_LOGIN_TIMER__ = null;
}catch(_e){}

let __lastBrandHeaderH = 48;
let __lastAppHeaderH = 60;
let __headerResizeObserver = null;

function ensureHeaderObserver(){
  try {
    if(typeof ResizeObserver !== 'function') return;
    if(__headerResizeObserver) return;
    const brandHeader = document.getElementById('brandHeader');
    const appHeader = document.getElementById('appHeader');
    if(!brandHeader && !appHeader) return;
    __headerResizeObserver = new ResizeObserver((entries)=>{
      let dirty = false;
      for(const entry of entries){
        if(!entry || !entry.target) continue;
        const id = entry.target.id;
        const blockSize = (entry.borderBoxSize && entry.borderBoxSize[0] && entry.borderBoxSize[0].blockSize) || entry.contentRect?.height || entry.target.offsetHeight || 0;
        if(id === 'brandHeader'){
          const newVal = Math.round(blockSize);
          if(newVal > 0 && newVal !== __lastBrandHeaderH){ __lastBrandHeaderH = newVal; dirty = true; }
        } else if(id === 'appHeader'){
          const newVal = Math.round(blockSize);
          if(newVal > 0 && newVal !== __lastAppHeaderH){ __lastAppHeaderH = newVal; dirty = true; }
        }
      }
      if(dirty){
        const docEl = document.documentElement;
        docEl.style.setProperty('--brandHeaderH', __lastBrandHeaderH + 'px');
        docEl.style.setProperty('--appHeaderH', __lastAppHeaderH + 'px');
      }
    });
    if(brandHeader) __headerResizeObserver.observe(brandHeader);
    if(appHeader) __headerResizeObserver.observe(appHeader);
  } catch(_e){}
}

function syncHeaderVars(opts){
  const options = opts && typeof opts === 'object' ? opts : {};
  const allowHiddenZero = !!options.allowHiddenZero;
  try {
    const docEl = document.documentElement;
    const brandHeader = document.getElementById('brandHeader');
    const appHeader = document.getElementById('appHeader');
  const brandVisible = !!(brandHeader && !brandHeader.classList.contains('hidden'));
  const appVisible = !!(appHeader && !appHeader.classList.contains('hidden'));
    if(brandVisible){
      const measured = Math.max(brandHeader.offsetHeight || 0, 0);
      if(measured > 0) __lastBrandHeaderH = measured;
    }
    if(appVisible){
      const measured = Math.max(appHeader.offsetHeight || 0, 0);
      if(measured > 0) __lastAppHeaderH = measured;
    }
    const brandOutput = allowHiddenZero && !brandVisible ? 0 : __lastBrandHeaderH;
    const appOutput = allowHiddenZero && !appVisible ? 0 : __lastAppHeaderH;
    docEl.style.setProperty('--brandHeaderH', brandOutput + 'px');
    docEl.style.setProperty('--appHeaderH', appOutput + 'px');
    ensureHeaderObserver();
  } catch(_e){}
}
if(typeof window !== 'undefined'){
  try{ window.syncHeaderVars = syncHeaderVars; }catch(_e){}
}

function enforceAuthShell(){
  try{
    const authed = !!(window.auth && window.auth.currentUser);
    const stateKnown = !!window.__AUTH_STATE_KNOWN__;
    const loadingOverlay = document.getElementById('appLoadingOverlay');
    const body = document.body;
    const brandHeader = document.getElementById('brandHeader');
    const appHeader = document.getElementById('appHeader');
    const loginSection = document.getElementById('login-section');
    const moduleDescBar = document.getElementById('moduleDescBar');
    const topNavPortal = document.getElementById('topNavPortal');
    if(!authed){
      body?.classList.remove('auth-loading');
      brandHeader?.classList.add('hidden');
      appHeader?.classList.add('hidden');
      loginSection?.classList.remove('hidden');
      loadingOverlay?.classList.add('hidden');
      moduleDescBar?.classList.add('hidden');
      topNavPortal?.classList.add('hidden');
      try{ sessionStorage.removeItem('noCajaUnlocked'); }catch(_e){}
      return;
    }
    body?.classList.remove('auth-loading');
    loginSection?.classList.add('hidden');
    brandHeader?.classList.remove('hidden');
    appHeader?.classList.remove('hidden');
    loadingOverlay?.classList.add('hidden');
    moduleDescBar?.classList.remove('hidden');
    topNavPortal?.classList.remove('hidden');
    if(!stateKnown){
      syncHeaderVars();
    }
  }catch(_e){}
}

try{ enforceAuthShell(); }catch(_e){}
document.addEventListener('authResolved', ()=>{
  try{
    clearTimeout(window.__AUTH_SHOW_LOGIN_TIMER__);
    window.__AUTH_SHOW_LOGIN_TIMER__ = null;
    window.__AUTH_STATE_KNOWN__ = true;
  }catch(_ex){}
  try{ enforceAuthShell(); }catch(_e){}
});

// Client init: detect server flags (allowDemo, requireApiKey) and adapt UI/fetch
(function clientServerFlagsInit(){
  if(typeof window === 'undefined') return;
  const origFetch = window.fetch.bind(window);
  window.__origFetch = origFetch;

  async function loadFlags(){
    try{
      const r = await origFetch('/api/_buildinfo', { cache:'no-store' });
      const j = await r.json().catch(()=>({ ok:false }));
      window.__APP_ALLOW_DEMO__ = !!(j && j.allowDemo);
      window.__APP_REQUIRE_API_KEY__ = !!(j && j.requireApiKey);
      if(!window.__APP_ALLOW_DEMO__){
        const demoBtns = document.querySelectorAll('#restockDemoBtn, #restockDemoSeedBtn, [data-demo]');
        demoBtns.forEach(b=>{ try{ b.style.display='none'; b.disabled = true; }catch(_e){} });
      }
      if(window.__APP_REQUIRE_API_KEY__ && !getStoredApiKey()){
        showApiKeyBanner();
      }
    }catch(e){
      console.warn('[APPFLAGS] Could not load /api/_buildinfo', e.message);
    }
  }

  function showApiKeyBanner(){
    try{
      if(getStoredApiKey()) return;
      if(document.getElementById('appApiKeyBanner')) return;
      const div = document.createElement('div');
      div.id = 'appApiKeyBanner';
      div.style.position = 'fixed'; div.style.left='12px'; div.style.bottom='12px'; div.style.zIndex='99999'; div.style.background='#111827'; div.style.color='#fff'; div.style.padding='10px 12px'; div.style.borderRadius='8px'; div.style.boxShadow='0 8px 24px rgba(0,0,0,.35)'; div.style.fontSize='.9rem';
      div.innerHTML = `<div style="display:flex;gap:8px;align-items:center;">
        <span style="font-weight:600;">API Key:</span>
        <input id="appApiKeyInput" placeholder="x-app-key" style="padding:6px 8px;border-radius:6px;border:none;background:#0f172a;color:#fff;min-width:180px;">
        <button id="appApiKeySaveBtn" class="btn btn-primary" style="height:32px;">Guardar</button>
        <button id="appApiKeyCloseBtn" class="btn" style="height:32px;">Cerrar</button>
      </div>
      <div style="font-size:.78rem;margin-top:6px;color:#cbd5e1;">La clave se almacenará en la sesión del navegador y se incluirá en las peticiones a la API.</div>`;
      const append = ()=>{ try{ document.body.appendChild(div); }catch(_e){} };
      if(document.readyState === 'complete' || document.readyState === 'interactive') append();
      else document.addEventListener('DOMContentLoaded', append, { once:true });
      document.getElementById('appApiKeySaveBtn').addEventListener('click', ()=>{
        const v = document.getElementById('appApiKeyInput').value || '';
        if(!v) return alert('Ingresa la API key');
        setStoredApiKey(v.trim());
        document.getElementById('appApiKeyBanner').remove();
        alert('API key guardada en sesión');
      });
      document.getElementById('appApiKeyCloseBtn').addEventListener('click', ()=>{
        document.getElementById('appApiKeyBanner').remove();
      });
    }catch(_e){ console.warn('No se pudo mostrar banner API key'); }
  }

  function normalizeFetchUrl(target){
    if(!target) return '';
    if(typeof target === 'string') return target;
    try{
      if(typeof Request !== 'undefined' && target instanceof Request){
        return target.url || '';
      }
    }catch(_e){}
    if(target && typeof target === 'object' && typeof target.url === 'string') return target.url;
    return '';
  }

  function shouldTrackLoading(target){
    try{
      const href = normalizeFetchUrl(target);
      if(!href) return false;
      const hasLocation = typeof location !== 'undefined' && location;
      const baseOrigin = hasLocation ? (location.origin || (location.protocol + '//' + location.host)) : '';
      if(href.startsWith('http')){
        if(!hasLocation) return false;
        const urlObj = new URL(href);
        if(urlObj.origin !== baseOrigin) return false;
        return urlObj.pathname.indexOf('/api/') === 0 || urlObj.pathname === '/api';
      }
      if(href.startsWith('/api/') || href === '/api' || href.startsWith('/api?')) return true;
      if((href.startsWith('./') || href.startsWith('../')) && hasLocation){
        const abs = new URL(href, location.href || (baseOrigin + '/'));
        return abs.pathname.indexOf('/api/') === 0 || abs.pathname === '/api';
      }
    }catch(_e){}
    return false;
  }

  function isSameOrigin(target){
    try{
      const href = normalizeFetchUrl(target);
      if(!href) return true;
      if(!/^https?:\/\//i.test(href)) return true; // relative URLs
      if(typeof location === 'undefined' || !location || !location.origin) return true;
      const urlObj = new URL(href);
      return urlObj.origin === location.origin;
    }catch(_e){
      return true;
    }
  }

  window.fetch = async function(url, opts){
    opts = opts || {};
    const sameOrigin = isSameOrigin(url);
    if(sameOrigin){
      const headers = opts.headers || {};
      try{
        const key = getStoredApiKey();
        if(key){
          if(headers instanceof Headers){
            headers.set('x-app-key', key);
          } else {
            headers['x-app-key'] = key;
          }
        }
      }catch(_e){}
      opts.headers = headers;
    }
    const track = sameOrigin && shouldTrackLoading(url);
    if(track) adjustGlobalLoading(1);
    try{
      const res = await origFetch(url, opts);
      return res;
    } finally {
      if(track) adjustGlobalLoading(-1);
    }
  };

  try{ loadFlags(); }catch(_e){}

  function handleAuthStateChange(user){
    try{
      if(user){
        if(window.__AUTH_SHOW_LOGIN_TIMER__){
          clearTimeout(window.__AUTH_SHOW_LOGIN_TIMER__);
          window.__AUTH_SHOW_LOGIN_TIMER__ = null;
        }
        window.__AUTH_STATE_KNOWN__ = true;
        enforceAuthShell();
      } else {
        if(window.__AUTH_STATE_KNOWN__){
          if(window.__AUTH_SHOW_LOGIN_TIMER__){
            clearTimeout(window.__AUTH_SHOW_LOGIN_TIMER__);
            window.__AUTH_SHOW_LOGIN_TIMER__ = null;
          }
          enforceAuthShell();
          return;
        }
        if(!window.__AUTH_SHOW_LOGIN_TIMER__){
          window.__AUTH_SHOW_LOGIN_TIMER__ = setTimeout(()=>{
            try{ window.__AUTH_SHOW_LOGIN_TIMER__ = null; window.__AUTH_STATE_KNOWN__ = true; enforceAuthShell(); }catch(_et){}
          }, 1200);
        }
      }
    }catch(_ez){}
    try{
      if(user){
        if(window.__APP_REQUIRE_API_KEY__ && !getStoredApiKey()) showApiKeyBanner();
      } else {
        clearStoredApiKeys();
      }
    }catch(_eb){}
    try{ setTimeout(applyNavAccessControls, 0); }catch(_ec){}
  }

  try{
    if(window.auth && !window.__appAuthShellInit){
      window.__appAuthShellInit = true;
      window.auth.onAuthStateChanged(handleAuthStateChange);
      handleAuthStateChange(window.auth.currentUser || null);
    }
  }catch(_ed){}

  if(!window.auth){
    let __authWaitRetries = 12;
    const waitForAuth = ()=>{
      try{
        if(window.auth){
          if(!window.__appAuthShellInit){
            window.__appAuthShellInit = true;
            window.auth.onAuthStateChanged(handleAuthStateChange);
          }
          handleAuthStateChange(window.auth.currentUser || null);
          return;
        }
      }catch(_e){}
      if(__authWaitRetries-- > 0) setTimeout(waitForAuth, 500);
    };
    waitForAuth();
  }
})();

// ==============================
// Reabastecimiento (procura_restock) UI Logic
// ==============================
(function initRestockUI(){
  const fechaInput = document.getElementById('restockFecha');
  const loadBtn = document.getElementById('restockLoadBtn');
  const tableBody = document.getElementById('restockTbody');
  const selAll = document.getElementById('restockSelAll');
  const markOrderedBtn = document.getElementById('restockMarkOrderedBtn');
  const receiveBtn = document.getElementById('restockReceiveBtn');
  const receiveAllBtn = document.getElementById('restockReceiveAllBtn');
  const exportBtn = document.getElementById('restockExportCsvBtn');
  const diagBtn = document.getElementById('restockDiagBtn');
  const logBtn = document.getElementById('restockLogBtn');
  const logOverlay = document.getElementById('eventLogOverlay');
  const logCloseBtn = document.getElementById('eventLogCloseBtn');
  const logRefreshBtn = document.getElementById('eventLogRefreshBtn');
  const logLimitInput = document.getElementById('eventLogLimit');
  const logTypeInput = document.getElementById('eventLogType');
  const logFromInput = document.getElementById('eventLogFrom');
  const logToInput = document.getElementById('eventLogTo');
  const logSearchInput = document.getElementById('eventLogSearch');
  const logExportBtn = document.getElementById('eventLogExportBtn');
  const logBody = document.getElementById('eventLogBody');
  const logStatus = document.getElementById('eventLogStatus');
  const demoBtn = document.getElementById('restockDemoBtn');
  const createOrderBtn = document.getElementById('restockCreateOrderBtn');
  const statusMsg = document.getElementById('restockStatusMsg');
  const restockSection = document.getElementById('restock-section') || null;
  let lastEventLogEntries = [];
  if(!fechaInput || !loadBtn || !tableBody) return; // sección no presente

  function today(){ return new Date().toISOString().slice(0,10); }
  if(!fechaInput.value) fechaInput.value = today();

  // Detectar si se abrió como archivo local y definir base API
  const API_BASE = (location.protocol === 'file:' ? 'http://localhost:3000' : '');


  function setStatus(msg, type){
    if(restockSection){ restockSection.setAttribute('aria-busy', type === 'loading' ? 'true' : 'false'); }
    if(!statusMsg) return;
    statusMsg.style.color = type==='err'? '#dc2626':'#64748b';
    if(type === 'loading'){
      statusMsg.innerHTML = '<span class="inline-spinner" aria-hidden="true"></span><span class="inline-msg">'+escapeHtml(msg||'')+'</span>';
      statusMsg.setAttribute('role','status');
    } else {
      statusMsg.textContent = msg||'';
      statusMsg.removeAttribute('role');
    }
  }

  function render(items){
    tableBody.innerHTML='';
    items.forEach(it=>{
        const tr = document.createElement('tr');
        const falt = typeof it.faltante === 'number' ? it.faltante : 0;
        tr.innerHTML = `
          <td><input type="checkbox" class="restockRowSel" data-id="${it.productoId}" /></td>
          <td style="font-family:monospace;font-size:.65rem;">${it.productoId}</td>
          <td>${escapeHtml(it.descripcion || '')}</td>
          <td style="text-align:right;">${falt.toFixed(2)}</td>
          <td><span class="restock-status restock-status-${(it.status || '').toLowerCase()}">${it.status || ''}</span></td>
          <td><input type="number" min="0" step="1" class="restockReceiveQty" data-id="${it.productoId}" style="width:70px;" placeholder="auto" /></td>`;
        tableBody.appendChild(tr);
    });
  }

  async function load(){
    const f = fechaInput.value || today();
  setStatus('Cargando...', 'loading');
    try {
      const url = `${API_BASE}/api/restock/${encodeURIComponent(f)}`;
      console.log('[RESTOCK] GET', url);
      const r = await fetch(url, { cache:'no-store' });
      let j;
      try {
        j = await r.json();
      } catch(parseErr){
        const txt = await r.text();
        console.warn('[RESTOCK] Respuesta no JSON', txt.slice(0,200));
        if(txt.startsWith('<!DOCTYPE')){
          // fallback intentar endpoint sin fecha (mismo base)
          const fbUrl = `${API_BASE}/api/restock`;
          console.log('[RESTOCK] HTML fallback detectado, reintentando', fbUrl);
          const r2 = await fetch(fbUrl, { cache:'no-store' });
          try { j = await r2.json(); }
          catch(_e2){
            if(location.protocol==='file:'){
              throw new Error('Abriste index.html directo (file://). Levanta el servidor y entra a http://localhost:3000');
            }
            throw new Error('Respuesta HTML (fallback)');
          }
        } else {
          throw new Error('Respuesta no JSON');
        }
      }
      if(!j || !j.ok) throw new Error((j&&j.error)||'Error');
      render(j.items||[]);
      setStatus(`${(j.items||[]).length} items`, '');
    }catch(e){ console.error('[RESTOCK] load error', e); setStatus('Error: '+e.message,'err'); }
  }

  loadBtn.addEventListener('click', load);
  selAll && selAll.addEventListener('change', ()=>{
    document.querySelectorAll('.restockRowSel').forEach(ch=>{ ch.checked = selAll.checked; });
  });

  async function mark(status){
    const f = fechaInput.value || today();
    const ids = Array.from(document.querySelectorAll('.restockRowSel:checked')).map(ch=> ch.getAttribute('data-id'));
    if(!ids.length) { setStatus('Selecciona al menos un item','err'); return; }
    try{
  setStatus('Marcando...','loading');
      const r = await fetch(`/api/restock/${f}/mark`, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ items: ids.map(id=>({ productoId:id, status })) }) });
      const j = await r.json();
      if(!j.ok) throw new Error(j.error||'Error');
      await load();
      setStatus('Actualizado','');
    }catch(e){ setStatus('Error: '+e.message,'err'); }
  }
  markOrderedBtn && markOrderedBtn.addEventListener('click', async ()=>{
    try{
      const proceed = typeof confirmAction==='function' ? await confirmAction('¿Marcar como ORDENADO los ítems seleccionados?', { variant:'warn' }) : (window.confirm? window.confirm('¿Marcar como ORDENADO los ítems seleccionados?'):true);
      if(!proceed){ setStatus('Operación cancelada',''); return; }
    }catch(_e){}
    mark('ORDENADO');
  });

  async function receive(){
    const f = fechaInput.value || today();
    const rows = Array.from(document.querySelectorAll('.restockRowSel:checked'));
    if(!rows.length){ setStatus('Selecciona al menos un item','err'); return; }
    const items = rows.map(ch=>{
      const id = ch.getAttribute('data-id');
      const qtyInput = document.querySelector(`.restockReceiveQty[data-id="${id}"]`);
      const val = qtyInput && qtyInput.value ? Number(qtyInput.value) : undefined;
      return { productoId: id, cantidad: val };
    });
    try{
  setStatus('Recibiendo...','loading');
      const r = await fetch(`/api/restock/${f}/receive`, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ items }) });
      const j = await r.json();
      if(!j.ok) throw new Error(j.error||'Error');
      await load();
      setStatus('Inventario actualizado','');
    }catch(e){ setStatus('Error: '+e.message,'err'); }
  }
  receiveBtn && receiveBtn.addEventListener('click', receive);

  // Recibir todos los items pendientes (faltante > 0)
  receiveAllBtn && receiveAllBtn.addEventListener('click', async ()=>{
    const f = fechaInput.value || today();
    try {
      let proceed = true;
      try{
        if(typeof confirmAction === 'function') proceed = await confirmAction('¿Recibir todos los faltantes para esta fecha? Esta acción ajustará inventario.', { variant:'warn' });
        else proceed = window.confirm ? window.confirm('¿Recibir todos los faltantes para esta fecha? Esta acción ajustará inventario.') : true;
      }catch(_e){}
      if(!proceed){ setStatus('Operación cancelada',''); return; }
      setStatus('Recibiendo todos...','');
      // Cargar estado actual para saber faltantes
      const r1 = await fetch(`/api/restock/${f}`);
      const j1 = await r1.json();
      if(!j1.ok) throw new Error(j1.error||'Error carga');
      const pending = (j1.items||[]).filter(it=> (it.faltante||0) > 0);
      if(!pending.length){ setStatus('No hay faltantes pendientes',''); return; }
      const payload = { items: pending.map(p=> ({ productoId: p.productoId, cantidad: p.faltante })) };
      const r2 = await fetch(`/api/restock/${f}/receive`, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(payload) });
      const j2 = await r2.json();
      if(!j2.ok) throw new Error(j2.error||'Error recibir');
      await load();
      setStatus('Todos recibidos','');
    }catch(e){ setStatus('Error recibir todo: '+e.message,'err'); }
  });

  exportBtn && exportBtn.addEventListener('click', ()=>{
    const f = fechaInput.value || today();
    window.open(`/api/restock/${f}/csv`, '_blank');
  });

  function syncLogBusy(flag){
    try{
      if(logOverlay){ logOverlay.setAttribute('aria-busy', flag ? 'true' : 'false'); }
    }catch(_e){}
  }

  function setLogStatus(msg, type){
    if(!logStatus) return;
    logStatus.style.color = type === 'err' ? '#dc2626' : '#64748b';
    if(type === 'loading'){
      logStatus.innerHTML = '<span class="inline-spinner" aria-hidden="true"></span><span class="inline-msg">'+escapeHtml(msg||'')+'</span>';
      logStatus.setAttribute('role','status');
    } else {
      logStatus.textContent = msg || '';
      logStatus.removeAttribute('role');
    }
  }

  function renderEventLog(entries){
    if(!logBody) return;
    logBody.innerHTML='';
    lastEventLogEntries = Array.isArray(entries) ? entries.slice() : [];
    if(!entries || !entries.length){
      const tr = document.createElement('tr');
      tr.innerHTML = '<td colspan="3" style="padding:10px;text-align:center;color:#94a3b8;">Sin eventos</td>';
      logBody.appendChild(tr);
      return;
    }
    entries.forEach(ev=>{
      const tr = document.createElement('tr');
      tr.innerHTML = `<td style="padding:6px 8px;font-family:monospace;">${escapeHtml(ev.createdAt||'')}</td><td style="padding:6px 8px;font-family:monospace;">${escapeHtml(ev.type||'')}</td><td style="padding:6px 8px;font-family:monospace;white-space:pre-wrap;">${escapeHtml(JSON.stringify(ev.payload, null, 2) || '')}</td>`;
      logBody.appendChild(tr);
    });
  }

  async function loadEventLog(){
    if(!logStatus) return;
    let limitVal = Number(logLimitInput && logLimitInput.value ? logLimitInput.value : 50);
    if(!isFinite(limitVal) || limitVal<=0) limitVal = 50;
    limitVal = Math.min(Math.max(Math.round(limitVal), 10), 200);
    if(logLimitInput) logLimitInput.value = limitVal;
    syncLogBusy(true);
    setLogStatus('Cargando...','loading');
    try{
      const params = new URLSearchParams();
      params.set('limit', String(limitVal));
      const typeVal = logTypeInput && logTypeInput.value ? logTypeInput.value.trim() : '';
      const fromVal = logFromInput && logFromInput.value ? logFromInput.value.trim() : '';
      const toVal = logToInput && logToInput.value ? logToInput.value.trim() : '';
      const searchVal = logSearchInput && logSearchInput.value ? logSearchInput.value.trim() : '';
      if(typeVal) params.set('type', typeVal);
      if(fromVal) params.set('from', fromVal);
      if(toVal) params.set('to', toVal);
      if(searchVal) params.set('search', searchVal);
      const r = await fetch(`/api/event-log?${params.toString()}`);
      const j = await r.json();
      if(!j.ok) throw new Error(j.error||'Error');
      renderEventLog(j.entries||[]);
      setLogStatus(`${(j.entries||[]).length} eventos`, '');
    }catch(e){ setLogStatus('Error: '+e.message, 'err'); }
    finally { syncLogBusy(false); }
  }

  async function exportEventLogCsv(){
    try{
      const params = new URLSearchParams();
      const limitVal = Number(logLimitInput && logLimitInput.value ? logLimitInput.value : 50);
      if(isFinite(limitVal) && limitVal > 0) params.set('limit', String(Math.min(Math.max(Math.round(limitVal),10),200)));
      const typeVal = logTypeInput && logTypeInput.value ? logTypeInput.value.trim() : '';
      const fromVal = logFromInput && logFromInput.value ? logFromInput.value.trim() : '';
      const toVal = logToInput && logToInput.value ? logToInput.value.trim() : '';
      const searchVal = logSearchInput && logSearchInput.value ? logSearchInput.value.trim() : '';
      if(typeVal) params.set('type', typeVal);
      if(fromVal) params.set('from', fromVal);
      if(toVal) params.set('to', toVal);
      if(searchVal) params.set('search', searchVal);
      params.set('format','csv');
      const r = await fetch(`/api/event-log?${params.toString()}`);
      if(!r.ok) throw new Error(`HTTP ${r.status}`);
      const blob = await r.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      const ts = new Date().toISOString().replace(/[:T]/g,'-').split('.')[0];
      a.download = `bitacora_eventos_${ts}.csv`;
      document.body.appendChild(a);
      a.click();
      setTimeout(()=>{
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      }, 0);
    }catch(e){
      if(logStatus) setLogStatus('Error exportando: ' + e.message, 'err');
    }
  }

  function openEventLog(){
    if(!logOverlay) return;
    logOverlay.style.display='flex';
    logOverlay.classList.remove('hidden');
    loadEventLog();
  }
  function closeEventLog(){
    if(!logOverlay) return;
    logOverlay.style.display='none';
    logOverlay.classList.add('hidden');
  }

  logBtn && logBtn.addEventListener('click', openEventLog);
  logCloseBtn && logCloseBtn.addEventListener('click', closeEventLog);
  logOverlay && logOverlay.addEventListener('click', e=>{ if(e.target===logOverlay) closeEventLog(); });
  logRefreshBtn && logRefreshBtn.addEventListener('click', loadEventLog);
  logTypeInput && logTypeInput.addEventListener('change', loadEventLog);
  logFromInput && logFromInput.addEventListener('change', loadEventLog);
  logToInput && logToInput.addEventListener('change', loadEventLog);
  logSearchInput && logSearchInput.addEventListener('keyup', e=>{ if(e.key === 'Enter') loadEventLog(); });
  logExportBtn && logExportBtn.addEventListener('click', exportEventLogCsv);

  demoBtn && demoBtn.addEventListener('click', async ()=>{
    const f = fechaInput.value || today();
    setStatus('Insertando demo...','');
    try{
      let r = await fetch(`/api/restock/${f}/demo`, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({}) });
      if(r.status===404){
        // fallback alternativo
        r = await fetch(`/api/restock_demo_seed?fecha=${encodeURIComponent(f)}`, { method:'POST' });
      }
      const j = await r.json().catch(()=>({ ok:false, error:'resp no json'}));
      if(!j.ok) throw new Error(j.error||'Error');
      await load();
      setStatus('Demo listo','');
    }catch(e){ console.error('[RESTOCK][DEMO]', e); setStatus('Error demo: '+e.message,'err'); }
  });

  // Crear Orden de Compra desde seleccionados del restock
  createOrderBtn && createOrderBtn.addEventListener('click', async ()=>{
    const f = fechaInput.value || today();
    const selected = Array.from(document.querySelectorAll('.restockRowSel:checked'));
    if(!selected.length){ setStatus('Selecciona items para la OC','err'); return; }
    // Obtener estado actual para faltantes y descripciones
    try{
      const r = await fetch(`/api/restock/${f}`); const j = await r.json(); if(!j.ok) throw new Error(j.error||'Error');
      const map = new Map((j.items||[]).map(it=> [it.productoId, it]));
      const items = selected.map(ch=>{
        const pid = ch.getAttribute('data-id'); const info = map.get(pid)||{};
        const falt = typeof info.faltante==='number'? info.faltante:0;
        return { productoId: pid, descripcion: info.descripcion||pid, cantidad: falt>0? falt:1 };
      });
      const proveedor = prompt('Proveedor (opcional)','');
      const eta = prompt('ETA (YYYY-MM-DD opcional)','');
      let proceed = true;
      try{
        const msg = `Crear OC con ${items.length} ítems para fecha ${f}?`;
        if(typeof confirmAction === 'function') proceed = await confirmAction(msg, { variant:'info' });
        else proceed = window.confirm ? window.confirm(msg) : true;
      }catch(_e){}
      if(!proceed){ setStatus('OC cancelada',''); return; }
      setStatus('Creando OC...','');
      const r2 = await fetch('/api/purchase-orders/create', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ items, proveedor: proveedor||null, eta: eta||null, fromRestockFecha: f }) });
      const j2 = await r2.json();
      if(!j2.ok){
        if(j2.error==='items_already_linked'){
          setStatus('Algunos productos ya están ligados a otra OC','err');
          notify && notify('Productos ya tienen OC asignada','warn');
          return;
        }
        throw new Error(j2.error||'Error');
      }
      setStatus('OC creada','');
      notify && notify('Orden creada','ok');
    }catch(e){ setStatus('Error OC: '+e.message,'err'); }
  });

  diagBtn && diagBtn.addEventListener('click', async ()=>{
    const tests = [];
    function log(label, ok, detail){ tests.push({ label, ok, detail }); }
    const base = API_BASE || '';
    const todayStr = today();
    setStatus('Diagnóstico en curso...','');
    try {
      // Test 1: fetch raw (text)
      const u1 = `${base}/api/restock/${todayStr}`;
      let resp1 = await fetch(u1, { cache:'no-store' });
      const text1 = await resp1.text();
      log('GET /api/restock/{hoy} texto inicia', true, text1.slice(0,80));
      // JSON parse attempt
      try { JSON.parse(text1); log('Parse JSON /api/restock/{hoy}', true, 'OK'); }
      catch(pe){ log('Parse JSON /api/restock/{hoy}', false, 'No es JSON: '+(text1.slice(0,30))); }
      if(text1.startsWith('<!DOCTYPE')){
        log('Detección HTML', false, 'Se devolvió HTML (prob file:// o fallback)');
        if(location.protocol==='file:') log('Causa probable', false, 'Abriste file:// en vez de http://localhost:3000');
      }
      // Test 2: endpoint sin fecha
      const u2 = `${base}/api/restock`;
      let resp2 = await fetch(u2, { cache:'no-store' });
      const text2 = await resp2.text();
      log('GET /api/restock (sin fecha)', true, text2.slice(0,80));
      try { JSON.parse(text2); log('Parse JSON /api/restock', true, 'OK'); }
      catch(pe2){ log('Parse JSON /api/restock', false, 'No es JSON: '+text2.slice(0,30)); }
    } catch(e){ log('Diagnóstico error', false, e.message); }
    const summary = tests.map(t=> `${t.ok? '✅':'❌'} ${t.label}: ${t.detail||''}`).join('\n');
    console.log('[RESTOCK][DIAG]\n'+summary);
    alert('Diagnóstico Reabastecimiento:\n'+summary+ (location.protocol==='file:'? '\n\n>> Usa http://localhost:3000 para evitar HTML':'') );
    setStatus('Diagnóstico listo','');
  });

  // Observa cuando se muestra la sección y carga si vacío
  const observer = new MutationObserver(()=>{
    const sec = document.getElementById('restock-section');
    if(sec && !sec.classList.contains('hidden')){
      if(!tableBody.childElementCount) load();
    }
  });
  observer.observe(document.body, { subtree:true, attributes:true, attributeFilter:['class'] });
})();

// ==============================
// Órdenes de Compra UI
// ==============================
(function initPurchaseOrdersUI(){
  const sec = document.getElementById('purchase-orders-section');
  const tbody = document.getElementById('purchaseOrdersBody');
  const statusMsg = document.getElementById('poStatusMsg');
  const refreshBtn = document.getElementById('poRefreshBtn');
  const newBtn = document.getElementById('poNewBtn');
  const createModal = document.getElementById('poCreateModal');
  const createCloseBtn = document.getElementById('poCreateCloseBtn');
  const createCancelBtn = document.getElementById('poCreateCancelBtn');
  const createSubmitBtn = document.getElementById('poCreateSubmitBtn');
  const createProv = document.getElementById('poCreateProveedor');
  const createEta = document.getElementById('poCreateEta');
  const createItems = document.getElementById('poCreateItems');
  const createStatus = document.getElementById('poCreateStatus');
  const recvModal = document.getElementById('poReceiveModal');
  const recvCloseBtn = document.getElementById('poReceiveCloseBtn');
  const recvSubmitBtn = document.getElementById('poReceiveSubmitBtn');
  const recvInfo = document.getElementById('poReceiveInfo');
  const recvBody = document.getElementById('poReceiveBody');
  const recvStatus = document.getElementById('poReceiveStatus');
  const detailModal = document.getElementById('poDetailModal');
  const detailTitle = document.getElementById('poDetailTitle');
  const detailCloseBtn = document.getElementById('poDetailCloseBtn');
  const detailMeta = document.getElementById('poDetailMeta');
  const detailProveedor = document.getElementById('poDetailProveedor');
  const detailEta = document.getElementById('poDetailEta');
  const detailNotes = document.getElementById('poDetailNotes');
  const detailItemsBody = document.getElementById('poDetailItemsBody');
  const detailStatus = document.getElementById('poDetailStatus');
  const detailHints = document.getElementById('poDetailHints');
  const detailSaveBtn = document.getElementById('poDetailSaveBtn');
  const detailCancelBtn = document.getElementById('poDetailCancelBtn');
  if(!sec) return;

  let detailCurrentOrder = null;
  let lastLoadedOrders = [];

  function parseDateYMD(str){
    if(!str || typeof str !== 'string') return null;
    const trimmed = str.trim();
    if(!/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) return null;
    const dt = new Date(trimmed + 'T00:00:00');
    if(Number.isNaN(dt.getTime())) return null;
    return dt;
  }

  function isOrderOverdue(order){
    if(!order) return false;
    const status = String(order.status||'').toLowerCase();
    if(status === 'cancelada' || status === 'completa') return false;
    const etaDate = parseDateYMD(order.eta);
    if(!etaDate) return false;
    const today = new Date();
    today.setHours(0,0,0,0);
    return etaDate.getTime() < today.getTime();
  }

  function setPOStatus(msg,type){
    if(sec) sec.setAttribute('aria-busy', type === 'loading' ? 'true' : 'false');
    if(!statusMsg) return;
    const colors = { err:'#dc2626', warn:'#d97706', info:'#64748b' };
    statusMsg.style.color = colors[type] || colors.info;
    if(type === 'loading'){
      statusMsg.innerHTML = '<span class="inline-spinner" aria-hidden="true"></span><span class="inline-msg">'+escapeHtml(msg||'')+'</span>';
      statusMsg.setAttribute('role','status');
    } else {
      statusMsg.textContent = msg || '';
      statusMsg.removeAttribute('role');
    }
  }
  function openCreate(){ createStatus.textContent=''; createModal.style.display='flex'; createModal.classList.remove('hidden'); }
  function closeCreate(){ createModal.style.display='none'; createModal.classList.add('hidden'); }
  function openRecv(){ recvStatus.textContent=''; recvModal.style.display='flex'; recvModal.classList.remove('hidden'); }
  function closeRecv(){ recvModal.style.display='none'; recvModal.classList.add('hidden'); }

  function setDetailStatus(msg, type){
    if(!detailStatus) return;
    detailStatus.textContent = msg || '';
    detailStatus.style.color = type === 'err' ? '#dc2626' : (type === 'warn' ? '#d97706' : '#64748b');
  }

  function closeDetail(){
    if(!detailModal) return;
    detailModal.style.display = 'none';
    detailModal.classList.add('hidden');
    detailCurrentOrder = null;
    if(detailItemsBody) detailItemsBody.innerHTML='';
    setDetailStatus('', '');
  }

  function showDetailModal(){
    if(!detailModal) return;
    detailModal.style.display = 'flex';
    detailModal.classList.remove('hidden');
  }

  function buildDetailItemRow(item, editable){
    const tr = document.createElement('tr');
    tr.dataset.pid = item.productoId || '';
    const tdId = document.createElement('td');
    tdId.style.fontFamily = 'monospace';
    tdId.style.fontSize = '.65rem';
    tdId.textContent = item.productoId || '';
    tr.appendChild(tdId);

    const tdDesc = document.createElement('td');
    const descInput = document.createElement('input');
    descInput.type = 'text';
    descInput.value = item.descripcion || '';
    descInput.dataset.initial = item.descripcion || '';
    descInput.dataset.field = 'desc';
    descInput.dataset.pid = item.productoId || '';
    descInput.style.width = '100%';
    descInput.style.boxSizing = 'border-box';
    descInput.disabled = !editable;
    tdDesc.appendChild(descInput);
    tr.appendChild(tdDesc);

    const tdSolic = document.createElement('td');
    tdSolic.style.textAlign = 'right';
    const qtyInput = document.createElement('input');
    qtyInput.type = 'number';
    qtyInput.min = Math.max(0, Number(item.qtyRecibida || 0));
    qtyInput.step = '1';
    qtyInput.value = Number(item.qtySolicitada || 0) || 0;
    qtyInput.dataset.initial = Number(item.qtySolicitada || 0) || 0;
    qtyInput.dataset.field = 'qty';
    qtyInput.dataset.pid = item.productoId || '';
    qtyInput.style.width = '90px';
    qtyInput.style.textAlign = 'right';
    qtyInput.disabled = !editable;
    tdSolic.appendChild(qtyInput);
    tr.appendChild(tdSolic);
    const statusLower = statusText.toLowerCase();
    const badge = `<span class="po-status po-status-${statusLower}">${esc(statusText)}</span>`;
    const metaParts = [];
    const overdue = typeof order.overdue === 'boolean' ? order.overdue : isOrderOverdue(order);
    metaParts.push(`Folio: <span style="font-family:monospace;">${esc(order.id)}</span>`);
    metaParts.push(`Fecha: ${esc(order.fecha || '')}`);
    metaParts.push(`Status: ${badge}`);
    if(order.eta) metaParts.push(`ETA: ${esc(order.eta)}`);
    if(order.restockFecha) metaParts.push(`Origen restock: ${esc(order.restockFecha)}`);
    if(order.cancelReason) metaParts.push(`Motivo cancelación: ${esc(order.cancelReason)}`);
    if(order.updatedAtIso) metaParts.push(`Actualizado: ${esc(order.updatedAtIso)}`);
    if(detailMeta) detailMeta.innerHTML = metaParts.join(' · ');
    if(detailTitle) detailTitle.textContent = `Orden de Compra ${order.id}`;
    if(detailProveedor) detailProveedor.value = order.proveedor || '';
    if(detailEta) detailEta.value = order.eta || '';
    if(detailNotes) detailNotes.value = order.notes || '';
    if(detailItemsBody){
      detailItemsBody.innerHTML = '';
      const list = Array.isArray(order.items) ? order.items : [];
      const editable = statusText.toUpperCase() !== 'CANCELADA';
      if(!list.length){
        const tr = document.createElement('tr');
        const td = document.createElement('td'); td.colSpan = 5; td.style.padding = '10px'; td.style.textAlign = 'center'; td.style.color = '#94a3b8'; td.textContent = 'Sin partidas'; tr.appendChild(td); detailItemsBody.appendChild(tr);
      } else {
        list.forEach(it=> detailItemsBody.appendChild(buildDetailItemRow(it, editable)));
      }
      if(detailHints){
        let hint = editable ? 'Las cantidades solicitadas deben ser ≥ las ya recibidas.' : 'Orden cancelada: no se puede modificar.';
        if(overdue){
          const etaTxt = order.eta ? ` (ETA ${esc(order.eta)})` : '';
          hint = editable ? `⚠️ Orden vencida${etaTxt}. Prioriza su recepción o ajusta la solicitud.` : `⚠️ Orden vencida${etaTxt}.`;
        }
        detailHints.innerHTML = hint;
      }
      if(detailSaveBtn) detailSaveBtn.disabled = !editable;
      if(detailCancelBtn) detailCancelBtn.disabled = !editable && statusText.toUpperCase() === 'CANCELADA';
    }
  }

  async function loadDetail(id){
    setDetailStatus('Cargando...', '');
    try{
      const r = await fetch(`/api/purchase-orders/${id}`);
      const j = await r.json();
      if(!r.ok || !j.ok) throw new Error(j.error || 'Error');
      populateDetail(j.order);
      setDetailStatus('', '');
    }catch(err){
      setDetailStatus('Error: ' + (err.message || err), 'err');
    }
  }

  function poErrorMessage(code, details){
    switch(String(code||'')){
      case 'sin_cambios': return 'No hay cambios por guardar.';
      case 'qty_invalida': return `Cantidad inválida para el producto ${(details&&details.productoId)||''}.`;
      case 'qty_menor_recibido': return `La cantidad solicitada no puede ser menor a lo ya recibido (${(details&&details.qtyRecibida)||0}).`;
      case 'item_no_existente': return `El producto ${(details&&details.productoId)||''} no existe en esta orden.`;
      case 'ya_cancelada': return 'La orden ya está cancelada.';
      case 'no_encontrado': return 'Orden no encontrada.';
      default: return 'Operación no completada.';
    }
  }

  async function saveDetailChanges(){
    if(!detailCurrentOrder || !detailSaveBtn) return;
    if((detailCurrentOrder.status||'').toUpperCase() === 'CANCELADA'){
      setDetailStatus('La orden está cancelada; no se puede editar.', 'warn');
      return;
    }
    const payload = {};
    let changeCount = 0;
    if(detailProveedor){
      const nextProvRaw = detailProveedor.value != null ? detailProveedor.value.trim() : '';
      if(nextProvRaw !== (detailCurrentOrder.proveedor || '')){
        payload.proveedor = nextProvRaw || null;
        changeCount++;
      }
    }
    if(detailEta){
      const nextEtaRaw = detailEta.value != null ? detailEta.value.trim() : '';
      if(nextEtaRaw !== (detailCurrentOrder.eta || '')){
        payload.eta = nextEtaRaw || null;
        changeCount++;
      }
    }
    if(detailNotes){
      const nextNotesRaw = detailNotes.value != null ? detailNotes.value.trim() : '';
      if(nextNotesRaw !== (detailCurrentOrder.notes || '')){
        payload.notes = nextNotesRaw || null;
        changeCount++;
      }
    }
    if(detailItemsBody){
      const rows = Array.from(detailItemsBody.querySelectorAll('tr[data-pid]'));
      const items = [];
      rows.forEach(row=>{
        const pid = row.dataset.pid;
        if(!pid) return;
        const qtyInput = row.querySelector('input[data-field="qty"]');
        const descInput = row.querySelector('input[data-field="desc"]');
        const initialQty = Number(qtyInput?.dataset.initial || 0);
        let nextQty;
        if(!qtyInput || qtyInput.disabled){
          nextQty = initialQty;
        } else if(qtyInput.value === '' || qtyInput.value == null){
          nextQty = initialQty;
        } else {
          nextQty = Number(qtyInput.value);
        }
        if(!Number.isFinite(nextQty)) nextQty = initialQty;
        nextQty = Math.round(nextQty);
        if(nextQty < 0) nextQty = 0;
        const initialDesc = descInput?.dataset.initial || '';
        const nextDesc = (descInput && !descInput.disabled && descInput.value != null) ? descInput.value.trim() : initialDesc;
        if(nextQty !== initialQty || nextDesc !== initialDesc){
          items.push({ productoId: pid, qtySolicitada: nextQty, descripcion: nextDesc });
        }
      });
      if(items.length){
        payload.items = items;
        changeCount++;
      }
    }
    if(!changeCount){
      setDetailStatus('No hay cambios por guardar.', 'warn');
      return;
    }
    try{
      detailSaveBtn.disabled = true;
      setDetailStatus('Guardando cambios...', '');
      const r = await fetch(`/api/purchase-orders/${detailCurrentOrder.id}`, { method:'PATCH', headers:{'Content-Type':'application/json'}, body: JSON.stringify(payload) });
      const j = await r.json().catch(()=>({ ok:false, error:'resp_invalid' }));
      if(!r.ok || !j.ok){
        const friendly = poErrorMessage(j.error, j.details);
        throw new Error(friendly || j.error || 'Error');
      }
      detailCurrentOrder = j.order;
      populateDetail(detailCurrentOrder);
      setDetailStatus('Cambios guardados.', '');
      if(typeof notify === 'function') notify('Orden actualizada', 'ok');
      await loadPO();
    }catch(err){
      setDetailStatus('Error: ' + (err.message || err), 'err');
    } finally {
      if(detailCurrentOrder && (detailCurrentOrder.status||'').toUpperCase() !== 'CANCELADA'){
        detailSaveBtn.disabled = false;
      }
    }
  }

  async function cancelDetailOrder(){
    if(!detailCurrentOrder || !detailCancelBtn) return;
    if((detailCurrentOrder.status||'').toUpperCase() === 'CANCELADA'){
      setDetailStatus('La orden ya está cancelada.', 'warn');
      return;
    }
    let proceed = true;
    try{
      if(typeof confirmAction === 'function') proceed = await confirmAction('¿Cancelar esta orden de compra?', { variant:'warn' });
      else proceed = window.confirm ? window.confirm('¿Cancelar esta orden de compra?') : true;
    }catch(_e){ proceed = true; }
    if(!proceed) return;
    let reason = '';
    try{
      reason = window.prompt ? (window.prompt('Motivo de cancelación (opcional):', detailCurrentOrder.cancelReason || '') || '') : '';
    }catch(_e){ reason = ''; }
    try{
      detailCancelBtn.disabled = true;
      if(detailSaveBtn) detailSaveBtn.disabled = true;
      setDetailStatus('Cancelando orden...', '');
      const r = await fetch(`/api/purchase-orders/${detailCurrentOrder.id}/cancel`, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ reason }) });
      const j = await r.json().catch(()=>({ ok:false, error:'resp_invalid' }));
      if(!r.ok || !j.ok){
        const friendly = poErrorMessage(j.error, j.details);
        throw new Error(friendly || j.error || 'Error');
      }
      detailCurrentOrder = j.order;
      populateDetail(detailCurrentOrder);
      setDetailStatus('Orden cancelada.', '');
      if(typeof notify === 'function') notify('Orden cancelada', 'warn');
      await loadPO();
    }catch(err){
      setDetailStatus('Error: ' + (err.message || err), 'err');
      if(detailCurrentOrder && (detailCurrentOrder.status||'').toUpperCase() !== 'CANCELADA'){
        detailCancelBtn.disabled = false;
        if(detailSaveBtn) detailSaveBtn.disabled = false;
      }
    }
  }

  function applyEtaIndicators(orders){
    const stats = { overdue:0, dueToday:0, upcoming:0 };
    if(!tbody) return stats;
    const rows = Array.from(tbody.querySelectorAll('tr[data-po-id]'));
    const map = new Map(Array.isArray(orders)? orders.map(o=> [String(o.id), o]) : []);
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const msDay = 86400000;
    rows.forEach(row=>{
      row.classList.remove('po-row-overdue','po-row-due','po-row-upcoming');
      const etaCell = row.querySelector('[data-po-eta-cell]');
      if(etaCell){
        const pill = etaCell.querySelector('.po-eta-pill');
        if(pill) pill.remove();
      }
      const id = row.dataset.poId;
      if(!id) return;
      const order = map.get(String(id));
      if(!order) return;
      const status = String(order.status||'').toUpperCase();
      if(status === 'CANCELADA' || status === 'COMPLETA') return;
      const etaStr = order.eta || '';
      if(!etaStr) return;
      const parsed = new Date(etaStr + 'T00:00:00');
      if(Number.isNaN(parsed.getTime())) return;
      const etaDate = new Date(parsed.getFullYear(), parsed.getMonth(), parsed.getDate());
      const diffDays = Math.floor((etaDate.getTime() - today.getTime()) / msDay);
      let badge = null;
      const overdue = (typeof order.overdue === 'boolean') ? order.overdue : (diffDays < 0);
      if(overdue){
        row.classList.add('po-row-overdue');
        stats.overdue += 1;
        badge = 'Atrasada';
      } else if(diffDays === 0){
        row.classList.add('po-row-due');
        stats.dueToday += 1;
        badge = 'Vence hoy';
      } else if(diffDays > 0 && diffDays <= 2){
        row.classList.add('po-row-upcoming');
        stats.upcoming += 1;
        badge = diffDays === 1 ? 'En 1 día' : `En ${diffDays} días`;
      }
      if(badge && etaCell){
        const pill = document.createElement('span');
        pill.className = 'po-eta-pill';
        pill.textContent = badge;
        etaCell.appendChild(pill);
      }
    });
    return stats;
  }

  async function loadPO(){
  setPOStatus('Cargando...','loading');
    try{
      const r = await fetch('/api/purchase-orders');
      const j = await r.json();
      if(!j.ok) throw new Error(j.error||'Error');
      const orders = Array.isArray(j.orders)? j.orders : [];
      lastLoadedOrders = orders;
      renderPO(orders);
      const etaStats = applyEtaIndicators(orders);
      const overdue = etaStats.overdue;
      const incomplete = orders.filter(o=>{
        const status = String(o.status||'').toLowerCase();
        return status !== 'completa' && status !== 'cancelada';
      }).length;
      const statusParts = [`${orders.length} órdenes`, `${incomplete} activas`];
      if(overdue) statusParts.push(`${overdue} vencidas`);
      if(etaStats.dueToday) statusParts.push(`${etaStats.dueToday} vencen hoy`);
      if(etaStats.upcoming) statusParts.push(`${etaStats.upcoming} vencen pronto`);
      const statusMsg = statusParts.join(' · ');
      setPOStatus(statusMsg, overdue? 'warn':'');
    }catch(e){ setPOStatus('Error: '+e.message,'err'); }
  }

  function esc(s){ return String(s==null?'':s).replace(/[&<>"]/g, c=> ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }

  function renderPO(list){
    tbody.innerHTML='';
    list.forEach(o=>{
      const totalItems = (o.items||[]).length;
      const recibidos = (o.items||[]).filter(i=> (i.qtyRecibida||0) >= (i.qtySolicitada||0) && (i.qtySolicitada||0)>0).length;
      const statusText = o.status || 'PENDIENTE';
      const statusLowerRaw = (statusText || '').toLowerCase();
      const statusLower = statusLowerRaw.replace(/[^a-z0-9_-]/g,'');
      const statusClass = `po-status po-status-${statusLower}`;
      const recvDisabled = statusLowerRaw === 'cancelada' || statusLowerRaw === 'completa';
      const detailBtn = `<button class="mini-btn" data-po-act="detail" data-id="${o.id}">Detalle</button>`;
      const printBtn = statusLowerRaw === 'cancelada' ? '' : `<button class="mini-btn" data-po-act="print" data-id="${o.id}">Imprimir</button>`;
      const recvBtn = `<button class="mini-btn" data-po-act="recv" data-id="${o.id}"${recvDisabled?' disabled title="No disponible"':''}>Recibir</button>`;
      const tr = document.createElement('tr');
      tr.dataset.poId = o.id;
      tr.dataset.poStatus = statusText;
      tr.innerHTML = `
        <td style="font-family:monospace;font-size:.65rem;">${o.id}</td>
        <td>${esc(o.proveedor||'')}</td>
        <td>${esc(o.fecha||'')}</td>
        <td data-po-eta-cell>${esc(o.eta||'')}</td>
        <td><span class="${statusClass}">${esc(statusText)}</span></td>
        <td style="text-align:right;">${totalItems}</td>
        <td style="text-align:right;">${recibidos}</td>
        <td>${detailBtn} ${printBtn} ${recvBtn}</td>`;
      tbody.appendChild(tr);
    });
  }

  function openDetailOrder(id){
    if(!id) return;
    showDetailModal();
    if(detailItemsBody) detailItemsBody.innerHTML='';
    if(detailMeta) detailMeta.textContent='';
    setDetailStatus('Cargando...', '');
    loadDetail(id);
  }

  async function openReceive(id){
    recvInfo.textContent = 'Cargando...'; recvBody.innerHTML=''; openRecv();
    try{
      const r = await fetch(`/api/purchase-orders/${id}`); const j = await r.json(); if(!j.ok) throw new Error(j.error||'Error');
      const o = j.order; recvInfo.textContent = `OC ${o.id} - Proveedor: ${o.proveedor||''} - Status: ${o.status}`;
      (o.items||[]).forEach(it=>{
        const pend = Math.max(0,(it.qtySolicitada||0)-(it.qtyRecibida||0));
        const tr = document.createElement('tr');
        tr.innerHTML = `<td style="font-family:monospace;">${it.productoId}</td><td>${esc(it.descripcion||'')}</td><td style="text-align:right;">${it.qtySolicitada||0}</td><td style="text-align:right;">${it.qtyRecibida||0}</td><td style="text-align:right;">${pend}</td><td style="text-align:right;"><input type="number" min="0" max="${pend}" step="1" data-po-recv="${it.productoId}" style="width:70px;" placeholder="${pend>0?pend:''}"></td>`;
        recvBody.appendChild(tr);
      });
      recvSubmitBtn.onclick = async ()=>{
        const inputs = Array.from(recvBody.querySelectorAll('input[data-po-recv]'));
        const items = inputs.map(inp=>{ const pid = inp.getAttribute('data-po-recv'); const valRaw = inp.value.trim(); const val = valRaw? Number(valRaw): Number(inp.getAttribute('placeholder'))||0; return { productoId: pid, cantidad: val }; }).filter(x=> x.cantidad>0);
        if(!items.length){ recvStatus.textContent='Nada que recibir'; return; }
        recvStatus.textContent='Enviando...';
        try{
          const r2 = await fetch(`/api/purchase-orders/${id}/receive`, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ items }) });
          const j2 = await r2.json(); if(!j2.ok) throw new Error(j2.error||'Error');
          recvStatus.textContent='Actualizado'; notify && notify('Recepción aplicada','ok');
          await loadPO();
          setTimeout(()=> closeRecv(), 600);
        }catch(e){ recvStatus.textContent='Error: '+e.message; }
      };
    }catch(e){ recvInfo.textContent='Error: '+e.message; }
  }

  tbody && tbody.addEventListener('click', e=>{
    const btn = e.target.closest('button[data-po-act]'); if(!btn) return;
    const id = btn.getAttribute('data-id'); const act = btn.getAttribute('data-po-act');
    if(act==='detail') openDetailOrder(id);
    else if(act==='recv') openReceive(id);
    else if(act==='print' && id){ window.open(`/api/purchase-orders/${id}/print`, '_blank'); }
  });

  detailCloseBtn && detailCloseBtn.addEventListener('click', closeDetail);
  detailModal && detailModal.addEventListener('click', e=>{ if(e.target === detailModal) closeDetail(); });
  detailSaveBtn && detailSaveBtn.addEventListener('click', saveDetailChanges);
  detailCancelBtn && detailCancelBtn.addEventListener('click', cancelDetailOrder);

  refreshBtn && refreshBtn.addEventListener('click', loadPO);
  newBtn && newBtn.addEventListener('click', openCreate);
  createCloseBtn && createCloseBtn.addEventListener('click', closeCreate);
  createCancelBtn && createCancelBtn.addEventListener('click', closeCreate);
  createSubmitBtn && createSubmitBtn.addEventListener('click', async ()=>{
    createStatus.textContent='Creando...';
    try{
      const raw = (createItems.value||'').split(/\n+/).map(l=> l.trim()).filter(Boolean);
      const items = raw.map(line=>{ const [id, desc, cant] = line.split('|').map(s=> (s||'').trim()); return { productoId:id, descripcion:desc, cantidad:Number(cant)||0 }; }).filter(i=> i.productoId && i.cantidad>0);
      if(!items.length){ createStatus.textContent='Sin items válidos'; return; }
      const body = { proveedor: createProv.value||null, eta: createEta.value||null, items };
      const r = await fetch('/api/purchase-orders/create', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(body) });
      const j = await r.json(); if(!j.ok) throw new Error(j.error||'Error');
      createStatus.textContent='Creada'; notify && notify('OC creada','ok');
      await loadPO();
      setTimeout(()=> closeCreate(), 600);
    }catch(e){ createStatus.textContent='Error: '+e.message; }
  });

  // Auto carga al mostrar sección
  const observer = new MutationObserver(()=>{ if(sec && !sec.classList.contains('hidden') && !tbody.childElementCount){ loadPO(); } });
  observer.observe(document.body, { subtree:true, attributes:true, attributeFilter:['class'] });
})();

// ===================== Helpers globales: notify y exportToExcel (fallbacks) =====================
(function ensureNotifyAndExport(){
  if(typeof window === 'undefined') return;
  // Toast notifications fallback
  if(typeof window.notify !== 'function'){
    window.notify = function(msg, type){
      try{
        const variants = {
          ok: { icon:'\u2713', title:'Listo' },
          info: { icon:'\u2139', title:'Actualización' },
          warn: { icon:'\u26A0', title:'Atención' },
          err: { icon:'\u26D4', title:'Revisar' }
        };
        let variantKey = typeof type === 'string' && type.trim() ? type.trim().toLowerCase() : 'info';
        if(variantKey === 'error') variantKey = 'err';
        if(!variants[variantKey]) variantKey = 'info';
        const variant = variants[variantKey];
        const messageText = typeof msg === 'string' ? msg : (msg && typeof msg.message === 'string' ? msg.message : String(msg||''));
        const textLen = messageText.length;
        let duration = (variantKey === 'warn' || variantKey === 'err') ? 5200 : 3800;
        if(textLen > 90) duration += 1000;
        if(textLen > 160) duration += 1200;
        // Ensure styles once
        if(!document.getElementById('toastStyles')){
          const st = document.createElement('style');
          st.id = 'toastStyles';
          st.textContent = [
            '#toastContainer{position:fixed;right:18px;bottom:18px;display:flex;flex-direction:column;gap:14px;z-index:99999;align-items:flex-end;pointer-events:none;}',
            '#toastContainer .toast{pointer-events:auto;min-width:260px;max-width:min(420px,92vw);display:flex;gap:14px;align-items:flex-start;position:relative;padding:20px 24px 20px 22px;border-radius:20px;background:linear-gradient(160deg, rgba(255,247,237,0.97), rgba(255,237,213,0.92));border:1px solid rgba(249,115,22,0.32);color:#7c2d12;box-shadow:0 28px 60px -26px rgba(124,45,18,0.55);backdrop-filter:blur(8px);animation:toast-pop-in .1s ease-out;}',
            '#toastContainer .toast.toast--closing{animation:toast-pop-out .08s ease-in forwards;}',
            '#toastContainer .toast .toast-icon{width:42px;height:42px;border-radius:12px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:var(--toast-icon-bg,rgba(249,115,22,0.14));color:var(--toast-accent,#f97316);box-shadow:inset 0 0 0 1px rgba(249,115,22,0.18);}',
            '#toastContainer .toast .toast-content{display:flex;flex-direction:column;gap:5px;}',
            '#toastContainer .toast .toast-title{font-weight:650;font-size:0.96rem;letter-spacing:0.015em;color:#9a3412;}',
            '#toastContainer .toast .toast-message{font-size:0.85rem;line-height:1.4;color:#7c2d12;}',
            '#toastContainer .toast.toast--ok{--toast-accent:#f97316;--toast-icon-bg:rgba(249,115,22,0.18);}',
            '#toastContainer .toast.toast--info{--toast-accent:#fb923c;--toast-icon-bg:rgba(251,146,60,0.2);}',
            '#toastContainer .toast.toast--warn{--toast-accent:#ea580c;--toast-icon-bg:rgba(234,88,12,0.2);}',
            '#toastContainer .toast.toast--err{--toast-accent:#c2410c;--toast-icon-bg:rgba(194,65,12,0.24);}',
            '@keyframes toast-pop-in{from{opacity:0;transform:translate(12px, 12px) scale(0.94);}to{opacity:1;transform:translate(0,0) scale(1);}}',
            '@keyframes toast-pop-out{from{opacity:1;transform:translate(0,0) scale(1);}to{opacity:0;transform:translate(12px, 16px) scale(0.94);}}'
          ].join('');
          document.head.appendChild(st);
        }
        // Ensure container
        let cont = document.getElementById('toastContainer');
        if(!cont){
          cont = document.createElement('div');
          cont.id = 'toastContainer';
          cont.setAttribute('role','status');
          cont.setAttribute('aria-live','polite');
          cont.setAttribute('aria-atomic','true');
          document.body.appendChild(cont);
        }
        // Create toast
        const t = document.createElement('div');
        t.className = `toast toast--${variantKey}`;
        t.dataset.type = variantKey;
        t.setAttribute('role','alert');
        const iconWrap = document.createElement('div');
        iconWrap.className = 'toast-icon';
        iconWrap.textContent = variant.icon;
        const content = document.createElement('div');
        content.className = 'toast-content';
        const titleEl = document.createElement('div');
        titleEl.className = 'toast-title';
        titleEl.textContent = variant.title;
        const msgEl = document.createElement('div');
        msgEl.className = 'toast-message';
        msgEl.textContent = messageText;
        if(!messageText){ msgEl.style.display = 'none'; }
        content.appendChild(titleEl);
        content.appendChild(msgEl);
        let timerId = null;
        const removeToast = ()=>{
          if(t.classList.contains('toast--closing')) return;
          t.classList.add('toast--closing');
          if(timerId) clearTimeout(timerId);
          setTimeout(()=>{ try{ t.remove(); }catch(_err2){} }, 180);
        };
        t.__toastRemove = removeToast;
        timerId = setTimeout(removeToast, duration);
        t.appendChild(iconWrap);
        t.appendChild(content);
        cont.appendChild(t);
        if(!window.__toastOutsideHandler){
          const outsideHandler = (evt)=>{
            const container = document.getElementById('toastContainer');
            if(!container) return;
            if(evt.target && container.contains(evt.target)) return;
            container.querySelectorAll('.toast').forEach(node=>{
              const closer = node.__toastRemove;
              if(typeof closer === 'function') closer();
            });
          };
          document.addEventListener('pointerdown', outsideHandler, true);
          window.__toastOutsideHandler = outsideHandler;
        }
      }catch(_e){ try{ console.log('[notify]', msg); }catch(_e2){} }
    };
  }
  // Excel export fallback (supports 2 signatures)
  if(typeof window.exportToExcel !== 'function'){
    window.exportToExcel = function(arg1, arg2, arg3){
      try{
        let headers=[], rows=[], filename='export.xls';
        if(Array.isArray(arg1) && Array.isArray(arg2)){
          headers = arg1; rows = arg2; filename = arg3 || filename;
        } else if(arg1 && typeof arg1==='object'){
          headers = Array.isArray(arg1.headers)? arg1.headers : [];
          rows = Array.isArray(arg1.rows)? arg1.rows : [];
          filename = arg1.filename || arg1.fileName || filename;
        } else { console.warn('exportToExcel: argumentos inválidos'); return; }
        const esc = (v)=> String(v==null? '': v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
        let html = '<table><thead><tr>' + headers.map(h=>`<th>${esc(h)}</th>`).join('') + '</tr></thead><tbody>';
        rows.forEach(r=>{ html += '<tr>'+ (Array.isArray(r)? r: headers.map((_,i)=> r[i])).map(c=>`<td>${esc(c)}</td>`).join('') + '</tr>'; });
        html += '</tbody></table>';
        // BOM to preserve UTF-8 in Excel
        const blob = new Blob(["\uFEFF"+html], { type:'application/vnd.ms-excel' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a'); a.href=url; a.download=filename; document.body.appendChild(a); a.click(); setTimeout(()=>{ document.body.removeChild(a); URL.revokeObjectURL(url); }, 0);
        window.notify && window.notify('Exportación generada','ok');
      }catch(e){ console.error('exportToExcel error', e); window.notify && window.notify('Error exportando','err'); }
    };
  }
  // Exponer también como identificadores globales si no existen
  try { if(typeof notify === 'undefined') { var notify = window.notify; } } catch(_e){}
  try { if(typeof exportToExcel === 'undefined') { var exportToExcel = window.exportToExcel; } } catch(_e){}
})();

// ===================== ConfirmAction fallback (promise-based modal) =====================
(function ensureConfirmAction(){
  if(typeof window === 'undefined') return;
  if(typeof window.confirmAction === 'function') return;

  let overlay = null;
  let titleEl = null;
  let messageEl = null;
  let detailsEl = null;
  let confirmBtn = null;
  let cancelBtn = null;
  let pendingResolve = null;
  let lastActive = null;

  function close(result){
    if(!overlay || overlay.classList.contains('hidden')) return;
    overlay.classList.add('hidden');
    overlay.setAttribute('aria-hidden', 'true');
    overlay.removeAttribute('data-variant');
    const resolver = pendingResolve;
    pendingResolve = null;
    const focusTarget = lastActive;
    lastActive = null;
    if(resolver) resolver(!!result);
    if(focusTarget && typeof focusTarget.focus === 'function'){
      setTimeout(()=>{ try{ focusTarget.focus(); }catch(_e){} }, 0);
    }
  }

  function onKeyDown(ev){
    if(!overlay || overlay.classList.contains('hidden')) return;
    if(ev.key === 'Escape'){
      ev.preventDefault();
      close(false);
    } else if(ev.key === 'Enter'){
      if(ev.target === confirmBtn){
        ev.preventDefault();
        close(true);
      } else if(ev.target === cancelBtn){
        ev.preventDefault();
        close(false);
      }
    }
  }

  function ensureElements(){
    if(overlay) return true;
    if(!document || !document.body) return false;
    overlay = document.createElement('div');
    overlay.id = 'confirmActionOverlay';
    overlay.className = 'modal-overlay hidden';
    overlay.setAttribute('aria-hidden', 'true');
    overlay.innerHTML = '<div class="modal" role="dialog" aria-modal="true" aria-labelledby="confirmActionTitle" aria-describedby="confirmActionMessage">'
      + '<h3 id="confirmActionTitle" style="margin:0 0 12px;font-size:1.05rem;color:#1f2937;">Confirmar acción</h3>'
      + '<p id="confirmActionMessage" style="white-space:pre-wrap;margin:0 0 12px;color:#334155;"></p>'
      + '<p id="confirmActionDetails" style="display:none;white-space:pre-wrap;margin:0 0 18px;color:#475569;font-size:0.85rem;"></p>'
      + '<div style="display:flex;justify-content:flex-end;gap:8px;">'
        + '<button type="button" class="btn btn-secondary" id="confirmActionCancel">Cancelar</button>'
        + '<button type="button" class="btn btn-primary" id="confirmActionConfirm">Aceptar</button>'
      + '</div>'
    + '</div>';
    document.body.appendChild(overlay);
    titleEl = overlay.querySelector('#confirmActionTitle');
    messageEl = overlay.querySelector('#confirmActionMessage');
    detailsEl = overlay.querySelector('#confirmActionDetails');
    confirmBtn = overlay.querySelector('#confirmActionConfirm');
    cancelBtn = overlay.querySelector('#confirmActionCancel');
    confirmBtn.addEventListener('click', ()=> close(true));
    cancelBtn.addEventListener('click', ()=> close(false));
    overlay.addEventListener('click', ev=>{ if(ev.target === overlay) close(false); });
    document.addEventListener('keydown', onKeyDown, true);
    return true;
  }

  window.confirmAction = function(message, options){
    const opts = options && typeof options === 'object' ? options : {};
    if(!ensureElements()){
      const fallback = typeof window.confirm === 'function' ? window.confirm(String(message || '')) : true;
      return Promise.resolve(!!fallback);
    }
    if(!overlay.classList.contains('hidden')) close(false);
    return new Promise(resolve => {
      pendingResolve = resolve;
      overlay.classList.remove('hidden');
      overlay.setAttribute('aria-hidden', 'false');
      const variant = opts.variant ? String(opts.variant).toLowerCase() : '';
      if(variant) overlay.setAttribute('data-variant', variant);
      else overlay.removeAttribute('data-variant');
      lastActive = document.activeElement instanceof HTMLElement ? document.activeElement : null;

      titleEl.textContent = opts.title ? String(opts.title) : 'Confirmar acción';
      messageEl.textContent = String(message || '');
      if(detailsEl){
        if(opts.description){
          detailsEl.textContent = String(opts.description);
          detailsEl.style.display = 'block';
        } else {
          detailsEl.textContent = '';
          detailsEl.style.display = 'none';
        }
      }

      confirmBtn.textContent = opts.confirmText ? String(opts.confirmText) : (variant === 'warn' || variant === 'danger' || variant === 'error' ? 'Continuar' : 'Aceptar');
      cancelBtn.textContent = opts.cancelText ? String(opts.cancelText) : 'Cancelar';
      cancelBtn.style.display = opts.hideCancel ? 'none' : 'inline-flex';

      confirmBtn.className = 'btn btn-primary';
      if(variant === 'warn' || variant === 'danger' || variant === 'error') confirmBtn.className = 'btn btn-danger';
      else if(variant === 'secondary') confirmBtn.className = 'btn btn-secondary';

      confirmBtn.disabled = !!opts.disableConfirm;
      cancelBtn.disabled = !!opts.disableCancel;

      const focusCancel = opts.focus === 'cancel' && !opts.hideCancel;
      setTimeout(()=>{
        try{
          if(focusCancel) cancelBtn.focus();
          else confirmBtn.focus();
        }catch(_e){}
      }, 20);
    });
  };

  window.confirmAction.close = function(result){
    close(!!result);
  };

  try { if(typeof confirmAction === 'undefined') { var confirmAction = window.confirmAction; } } catch(_e){}
})();

