// Se declaran antes de construir AppState para que 'caja: cashRecords' no lance error.
var cashRecords = window.cashRecords || [];
var historicalCashRecords = window.historicalCashRecords || [];
window.cashRecords = cashRecords;
window.historicalCashRecords = historicalCashRecords;
try{ if(typeof window.__cajasListenerReady === 'undefined') window.__cajasListenerReady = false; }catch(_e){}

// ---------------------------------------------------------------
// Bloqueo por Caja no asignada o inhabilitada (overlay de sesión)
// ---------------------------------------------------------------
(function initCajaBlocker(){
  const blocker = document.getElementById('noCajaBlocker');
  const reasonEl = document.getElementById('noCajaReason');
  const retryBtn = document.getElementById('noCajaRetryBtn');
  const retryBtn2 = document.getElementById('noCajaRetryBtn2');
  const adminBox = document.getElementById('noCajaAdminUnlock');
  const pwdInput = document.getElementById('noCajaPwd');
  const unlockBtn = document.getElementById('noCajaUnlockBtn');
  const errEl = document.getElementById('noCajaError');
  const userActions = document.getElementById('noCajaUserActions');
  if(!blocker) return;

  const setVisible = (show, reason) => {
    try{
      if(reasonEl && reason) reasonEl.textContent = reason;
      blocker.style.display = show ? 'flex' : 'none';
    }catch(_e){}
  };

  const check = () => {
    try{
      const uid = window.auth?.currentUser?.uid || null;
      if(!uid){ setVisible(false); return; }
      const users = Array.isArray(window.usuarios)? window.usuarios : [];
      const me = users.find(u=> String(u.id||u.uid)===String(uid));
      // Si no hay usuario cargado aun, no bloquear (deja cargar listeners) y volverá a evaluar cuando lleguen usuarios
      if(!me){ setVisible(false); return; }
  // Mostrar panel de desbloqueo solo si es admin
  const role = String(me.role||'').toLowerCase();
  const perfil = String(me.perfil||'').toLowerCase();
  const isAdmin = (role==='admin' || perfil.includes('admin'));
      const est = String(me.estatus||'Activo').toLowerCase();
      if(est !== 'activo'){ setVisible(false); return; }

      const cajaId = me.cajaId || null;
      const cajaName = me.caja || null;
      const cajas = Array.isArray(window.cajas)? window.cajas : [];
      const catalogReady = window.__cajasListenerReady === true;
      const hasAssignment = !!cajaId || !!cajaName;
      // No tiene caja asignada
      if(!cajaId && !cajaName){ 
        // Permitir bypass sólo en el caso de "sin caja asignada"
        let unlocked = false; try{ unlocked = sessionStorage.getItem('noCajaUnlocked')==='1'; }catch(_e){}
        if(unlocked){ setVisible(false); return; }
        setVisible(true, 'No tienes una Caja asignada. Solicítala al administrador.');
        if(adminBox) adminBox.style.display = isAdmin? 'block':'none';
        if(userActions) userActions.style.display = isAdmin? 'none':'block';
        return; 
      }
      if(hasAssignment && !catalogReady){
        setVisible(false);
        return;
      }
      if(hasAssignment && catalogReady && cajas.length === 0){
        setVisible(false);
        return;
      }
      // Validar contra catálogo: si hay cajaId, usarlo; si no, intentar por nombre (legado)
      let cajaOk = false;
      if(cajaId){
        const c = cajas.find(x=> String(x.id)===String(cajaId));
        if(c && String(c.estatus||'Activa').toLowerCase()==='activa') cajaOk = true;
      } else if(cajaName){
        const cn = String(cajaName).toLowerCase();
        const suc = String(me.sucursal||'').toLowerCase();
        const c = cajas.find(x=> String(x.nombre||x.caja||'').toLowerCase()===cn && (!suc || !x.sucursal || String(x.sucursal).toLowerCase()===suc));
        if(c && String(c.estatus||'Activa').toLowerCase()==='activa') cajaOk = true;
      }
  const mustBlock = !cajaOk;
  if(mustBlock){
    // Forzar bloqueo SIEMPRE cuando la Caja esté inactiva o no exista, sin importar rol ni desbloqueos previos
    try{ sessionStorage.removeItem('noCajaUnlocked'); }catch(_e){}
    setVisible(true, 'Tu Caja asignada está inhabilitada o no existe. Solicita una Caja activa al administrador.');
    if(adminBox) adminBox.style.display = isAdmin? 'block':'none';
    if(userActions) userActions.style.display = isAdmin? 'none':'block';
  } else {
    setVisible(false);
  }
    }catch(_e){ /* no-op */ }
  };

  // Reintentar: fuerza re-evaluación (útil si el admin acaba de reasignar)
  try{ retryBtn?.addEventListener('click', check); }catch(_e){}
  try{ retryBtn2?.addEventListener('click', check); }catch(_e){}
  try{ unlockBtn?.addEventListener('click', async ()=>{
    try{
      if(!pwdInput) return;
      const pwd = String(pwdInput.value||'');
      if(!pwd){ if(errEl) errEl.textContent = 'Ingresa la contraseña.'; return; }
      const user = window.auth?.currentUser || null;
      if(!user || !user.email){ if(errEl) errEl.textContent = 'Sesion de admin requerida (correo).'; return; }
      // Reautenticar admin con contraseña
      const cred = firebase.auth.EmailAuthProvider.credential(user.email, pwd);
      await user.reauthenticateWithCredential(cred);
      // Flag de sesión para mantener desbloqueado hasta refrescar
      try{ sessionStorage.setItem('noCajaUnlocked','1'); }catch(_e){}
      // Limpiar UI y ocultar
      if(errEl) errEl.textContent = '';
      if(pwdInput) pwdInput.value = '';
      setVisible(false);
    }catch(e){ if(errEl) errEl.textContent = 'Contraseña inválida.'; }
  }); }catch(_e){}

  // Eventos que pueden cambiar el estado
  try{ document.addEventListener('cajas:updated', check); }catch(_e){}
  try{ document.addEventListener('usuariosUpdated', check); }catch(_e){}
  try{ document.addEventListener('usuarios:updated', check); }catch(_e){}
  try{ window.auth?.onAuthStateChanged?.(()=> setTimeout(check, 0)); }catch(_e){}

  // Intento inicial (con pequeño delay para esperar listeners)
  try{ setTimeout(check, 500); }catch(_e){}
})();

// Ensure login section is only visible when no session
(function loginSectionVisibility(){
  const loginSection = document.getElementById('login-section');
  if (!loginSection) return;
  const hide = ()=> loginSection.classList.add('hidden');
  const show = ()=> loginSection.classList.remove('hidden');
  try{
    const user = window.auth?.currentUser || null;
    if (user) hide(); else show();
    window.auth?.onAuthStateChanged?.(u => { if (u) hide(); else show(); });
  }catch(_e){
  // If auth not ready, show login to avoid a blank screen
  show();
  }
})();

