// ----------------------------
// Vista derivada de Insumos
// ----------------------------
function __toBool(v){
  if(v === true || v === false) return v;
  if(v === 'true' || v === '1' || v === 1) return true;
  if(v === 'false' || v === '0' || v === 0) return false;
  return undefined; // no asumir
}
// Booleans helpers for legacy/missing fields
function __isTrue(v){ return v === true || v === 1 || v === '1' || v === 'true'; }
function __isFalseish(v){ return v === false || v === 0 || v === '0' || v === 'false' || v == null || v === ''; }
function __normStr(v){ return String(v == null ? '' : v).trim(); }
function __normUp(v){ return __normStr(v).toUpperCase(); }
function __normLo(v){ return __normStr(v).toLowerCase(); }
function getSuppliesView(){

function normalizeStr(s){
  try{
    return String(s||'').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ');
  }catch(_e){
    // Fallback for older environments
    return String(s||'').trim().toLowerCase().replace(/\s+/g,' ');
  }
}


  try {
    const prods = Array.isArray(window.products) ? window.products : [];
    const insColRaw = Array.isArray(window.supplies) ? window.supplies : [];
    // Solo consumibles (esConsumible === true). NO exigir cantidad>0 para listarlos.
    const isConsumibleOnly = (x) => x && __isTrue(x.esConsumible) === true;
    const fromProducts = prods
      .filter(isConsumibleOnly)
      // Normaliza cantidad para evitar NaN en sumatorias posteriores
      .map(p => ({ ...p, cantidad: Number(p.cantidad || 0) }));
    const fromInsumos = insColRaw
      .filter(isConsumibleOnly)
      .map(s => ({ ...s, cantidad: Number(s.cantidad || 0) }));
    return [...fromProducts, ...fromInsumos];
  } catch(_e){
    const prods = Array.isArray(window.products) ? window.products : [];
    const isConsumibleOnly = (x)=> x && __isTrue(x.esConsumible) === true;
    return prods.filter(isConsumibleOnly).map(p => ({ ...p, cantidad: Number(p.cantidad || 0) }));
  }
}

