// -------------------------------------------------------------------
// Funciones para la pestaña Ventas vs costos
// -------------------------------------------------------------------
function renderVentasCostos() {
  if (!vvcBody) return;
  vvcBody.innerHTML = '';
    let totalVentas = 0; // Total de ventas
  let totalCostos = 0; // Total de costos
    const start = ventasFilterStartDate ? new Date(ventasFilterStartDate) : null;
    const end = ventasFilterEndDate ? new Date(ventasFilterEndDate) : null;
    // Filtrar registros de ventas por rango de fechas y excluir canceladas
    const filtered = (window.ventas || []).filter((rec) => {
      if ((rec.status || '') === 'CANCELADA' || (rec.status || '') === 'CANCELLED') return false;
      const rf = rec.fecha ? new Date(rec.fecha) : null;
      if (start && rf && rf < start) return false;
      if (end && rf && rf > end) return false;
      return true;
    });
    filtered.forEach((rec) => {
        const venta = Number(rec.total || 0);
        const costo = Number(rec.costoTotal || 0);
        totalVentas += venta;
        totalCostos += costo;
        const utilidad = venta - costo;
        const tr = document.createElement('tr');
        const id = rec.folio || '';
        const cliente = rec.clienteNombre || rec.cliente || '';
        // Productos: mostramos conteo de items si está disponible
          const productos = (typeof rec.itemsCount === 'number') ? `${rec.itemsCount} item(s)` : '0 item(s)';
  tr.innerHTML = `<td>${cliente}</td><td>${rec.fecha || ''}</td><td>${productos}</td><td style="text-align:right;">${money(venta)}</td><td style="text-align:right;">${money(costo)}</td><td style="text-align:right;">${money(utilidad)}</td><td>${id}</td>`;
    vvcBody.appendChild(tr);
    });
  // Actualizar totales de tarjetas (fuera del bucle)
  if (vvcVentasTotalElem) vvcVentasTotalElem.textContent = `$ ${totalVentas.toFixed(2)}`;
  if (vvcCostosTotalElem) vvcCostosTotalElem.textContent = `$ ${totalCostos.toFixed(2)}`;
  const utilidadTotal = totalVentas - totalCostos;
  if (vvcUtilidadTotalElem) vvcUtilidadTotalElem.textContent = `$ ${utilidadTotal.toFixed(2)}`;
}

