function switchVentasTab() {
  ventasActiveTab = 'vvc';
  if (ventasCostosPanel) ventasCostosPanel.classList.remove('hidden');
  renderVentasCostos();
}

function applyVentasDateFilter() {
  // Obtener fechas del único input de rango
  if (ventasDateRangeInput && ventasDateRangeInput.value) {
    const raw = ventasDateRangeInput.value.trim();
    let [start, end] = raw.split(/\s+(?:to|a)\s+/i);
    if (!end) end = start;
    ventasFilterStartDate = start || '';
    ventasFilterEndDate = end || '';
  } else {
    ventasFilterStartDate = '';
    ventasFilterEndDate = '';
  }
    // Renderizar pestaña activa
  renderVentasCostos();
}

// Inicializar sección de Ventas/Utilidad
function initVentasSection() {
  // Establecer rango de fechas por defecto (mes actual)
  const today = new Date();
  const startOfMonth = new Date(today.getFullYear(), today.getMonth(), 1);
  ventasFilterStartDate = startOfMonth.toISOString().slice(0, 10); // Establecer fecha de inicio por defecto
  ventasFilterEndDate = today.toISOString().slice(0, 10);
  if (ventasDateRangeInput) ventasDateRangeInput.value = `${ventasFilterStartDate} to ${ventasFilterEndDate}`;
  // Inicializar Flatpickr si está disponible
  try {
    if (typeof flatpickr !== 'undefined' && document.querySelector('#ventasDateRange')) {
      flatpickr('#ventasDateRange', {
        mode: 'range',
        dateFormat: 'Y-m-d',
        locale: 'es',
        allowInput: true,
        onChange: (selectedDates, dateStr) => {
          if (!dateStr) { ventasFilterStartDate=''; ventasFilterEndDate=''; return; }
          let [s,e] = dateStr.split(/\s+(?:to|a)\s+/i); if(!e) e=s; ventasFilterStartDate=s||''; ventasFilterEndDate=e||'';
        }
      });
    }
  } catch (e) {
    console.warn('Flatpickr para ventas no se inicializó: ' + e.message);
  }
  // Renderizar pestaña activa
  switchVentasTab('vvc');
}

