          function facturarVenta(clienteNombre, ventaId){
            try {
              if(!window.facturas) window.facturas=[];
              const existente = window.facturas.find(f=> f.ventaId===ventaId);
              if(existente){
                if(existente.status==='BORRADOR') notify('Ya existe borrador folio '+existente.folio,'info');
                else notify('Ya facturada folio '+existente.folio,'info');
                return;
              }
              const ventasCli=(window.cxcVentasPorCliente||{})[clienteNombre]||[];
              const venta=ventasCli.find(v=> String(v.ventaId)===String(ventaId));
              if(!venta){ notify('Venta no encontrada','err'); return; }
              const folio = window.facturas.length? Math.max(...window.facturas.map(f=> parseInt(f.folio)||0))+1 : 1;
              window.facturas.push({ folio, ventaId, cliente:clienteNombre, fecha:new Date().toISOString().slice(0,10), total:venta.total, status:'BORRADOR', abonado:0, saldo:venta.total });
              if(window.AppState) window.AppState.facturas=window.facturas;
              persistState && persistState();
              recalcDashboardKPIs && recalcDashboardKPIs();
              notify('Borrador creado folio '+folio,'ok');
            } catch(err){ console.error('facturarVenta', err); notify('Error al facturar','err'); }
          }
