let currentInventorySchema = null;

function applyInventorySchema(view){
  if(!inventoryTable || !inventoryTableHeadRow) return;
  const schema = INVENTORY_SCHEMAS[view];
  if(!schema) return;
  if(currentInventorySchema === view) return;
  currentInventorySchema = view;
  inventoryTableHeadRow.innerHTML = schema.columns.map(col => `<th>${col.label}</th>`).join('');
  if(inventoryTotalLabelCell){
    const span = Math.max(1, schema.columns.length - 1);
    inventoryTotalLabelCell.colSpan = span;
  }
  inventoryTable?.setAttribute('data-view', view);
}

function resetInventoryScrollPosition(){
  try{
    if(inventoryHost){
      if(typeof inventoryHost.scrollTo === 'function') inventoryHost.scrollTo(0, 0);
      else inventoryHost.scrollTop = 0;
    }
  }catch(_e){}
  if(inventoryTableWrapper){
    try{
      if(typeof inventoryTableWrapper.scrollTo === 'function'){
        inventoryTableWrapper.scrollTo({ top:0, left:0, behavior:'auto' });
      } else {
        inventoryTableWrapper.scrollTop = 0;
        inventoryTableWrapper.scrollLeft = 0;
      }
    }catch(_e){
      inventoryTableWrapper.scrollTop = 0;
      inventoryTableWrapper.scrollLeft = 0;
    }
  }
  try{
    const main = document.querySelector('main.main-content');
    if(main){
      if(typeof main.scrollTo === 'function') main.scrollTo(0, 0);
      else main.scrollTop = 0;
    }
  }catch(_e){}
  try{
    if(typeof window !== 'undefined' && window.scrollTo){
      window.scrollTo({ top:0, left:0, behavior:'auto' });
    }
  }catch(_e){}
  try{
    const scrollEl = document.scrollingElement || document.documentElement || document.body;
    if(scrollEl) scrollEl.scrollTop = 0;
    if(document.body) document.body.scrollTop = 0;
    if(document.documentElement) document.documentElement.scrollTop = 0;
  }catch(_e){}
}

