let clienteRequiredOkBtn = document.getElementById('clienteRequiredOkBtn');
let clienteRequiredPrevFocus = null;
let clienteRequiredOverlayBound = false;

function ensureClienteOverlay(){
  if(!clienteRequiredOverlay){
    const overlay = document.createElement('div');
    overlay.id = 'clienteRequiredOverlay';
    overlay.className = 'simple-modal-overlay';
    overlay.setAttribute('role','alertdialog');
    overlay.setAttribute('aria-modal','true');
    overlay.setAttribute('aria-hidden','true');
    overlay.setAttribute('tabindex','-1');
    overlay.innerHTML = `
      <div class="cliente-required-card" role="document">
        <div class="cliente-required-icon" aria-hidden="true">⚠️</div>
        <h3 id="clienteRequiredTitle">Necesitas asignar un cliente para cobrar</h3>
        <p id="clienteRequiredMessage">Usa Alt+C o haz clic en el chip de cliente para seleccionarlo antes de continuar.</p>
        <div class="cliente-required-actions">
          <button id="clienteRequiredOkBtn" type="button" class="btn btn-primary">Entendido</button>
        </div>
      </div>
    `;
    document.body.appendChild(overlay);
    clienteRequiredOverlay = overlay;
    clienteRequiredMessageEl = overlay.querySelector('#clienteRequiredMessage');
    clienteRequiredTitleEl = overlay.querySelector('#clienteRequiredTitle');
    clienteRequiredOkBtn = overlay.querySelector('#clienteRequiredOkBtn');
    clienteRequiredOverlayBound = false;
  }
  if(!clienteRequiredOverlayBound){
    clienteRequiredOkBtn?.addEventListener('click', ()=>{ closeClienteRequiredModal(); });
    clienteRequiredOverlay?.addEventListener('click', (e)=>{
      if(e.target === clienteRequiredOverlay){ closeClienteRequiredModal(); }
    });
    document.addEventListener('keydown', handleClienteRequiredKeydown, { capture:true });
    clienteRequiredOverlayBound = true;
  }
}

function openClienteRequiredModal(message){
  ensureClienteOverlay();
  const fallbackMsg = 'Debes asignar un cliente antes de continuar. Usa Alt+C para abrir el buscador.';
  const text = message || fallbackMsg;
  if(clienteRequiredMessageEl){ clienteRequiredMessageEl.textContent = text; }
  if(clienteRequiredTitleEl){ clienteRequiredTitleEl.textContent = text; }
  if(clienteRequiredOverlay){
    clienteRequiredPrevFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    clienteRequiredOverlay.classList.add('open');
    clienteRequiredOverlay.style.display = 'flex';
    clienteRequiredOverlay.style.pointerEvents = 'auto';
    clienteRequiredOverlay.setAttribute('aria-hidden','false');
    document.body.classList.add('cliente-required-open');
    try{ clienteRequiredOverlay.focus(); }catch(_e){}
    setTimeout(()=>{ try{ clienteRequiredOkBtn?.focus?.(); }catch(_e){} }, 0);
  } else if(typeof notify === 'function'){
    notify(message || fallbackMsg, 'warn');
  }
}

function closeClienteRequiredModal(){
  ensureClienteOverlay();
  if(clienteRequiredOverlay){
    clienteRequiredOverlay.classList.remove('open');
    clienteRequiredOverlay.style.display = 'none';
    clienteRequiredOverlay.style.pointerEvents = 'none';
    clienteRequiredOverlay.setAttribute('aria-hidden','true');
  }
  document.body.classList.remove('cliente-required-open');
  const restore = clienteRequiredPrevFocus || document.getElementById('ventaClienteQuickBtn');
  clienteRequiredPrevFocus = null;
  try{ restore?.focus?.(); }catch(_e){}
}

function promptAssignCliente(message){
  const msg = message || 'Necesitas asignar un cliente para cobrar';
  try { if(typeof notify === 'function') notify(msg, 'warn'); } catch(_e){}
  openClienteRequiredModal(msg);
}

function handleClienteRequiredKeydown(e){
  if(clienteRequiredOverlay && clienteRequiredOverlay.classList.contains('open')){
    if(e.key === 'Escape'){
      e.preventDefault();
      closeClienteRequiredModal();
    } else if(e.key === 'Enter' && e.target === clienteRequiredOverlay){
      e.preventDefault();
      closeClienteRequiredModal();
    }
  }
}

