function populateHistoricoUsuarios(){
  try{
    if(!historicoUserSelect) return;
    const prev = historicoUserSelect.value;
    const users = Array.isArray(window.usuarios)? window.usuarios : [];
    const opts = [{ value:'all', label:'Todos los usuarios' }]
      .concat(users.map(u=> ({ value:String(u.id||u.uid), label:String(u.nombre||u.displayName||u.email||u.id||'Usuario') })));
    historicoUserSelect.innerHTML = opts.map(o=> `<option value="${o.value}">${o.label}</option>`).join('');
    // Restaurar selección previa si sigue existiendo
    if(opts.some(o=> String(o.value)===String(prev))) historicoUserSelect.value = prev;
  }catch(_e){}
}
