// Poblar el select de usuarios (Histórico) desde window.usuarios y mantener selección
function populateHistoricoUsuarios(){
  try{
    if(!historicoUserSelect) return;
    const prev = historicoUserSelect.value || 'all';
    const users = Array.isArray(window.usuarios)? window.usuarios : [];
    const options = [{ value:'all', label:'Todos los usuarios' }]
      .concat(users.map(u=> ({ value: String(u.id||u.uid), label: String(u.nombre||u.displayName||u.email||u.id||'Usuario') })));
    // Render options
    historicoUserSelect.innerHTML = options.map(o=> `<option value="${o.value}">${o.label}</option>`).join('');
    // Restaurar selección si existe
    if(options.some(o=> String(o.value)===String(prev))) historicoUserSelect.value = prev; else historicoUserSelect.value = 'all';
  }catch(_e){}
}
