let categoriaHabilitadaWarnEl = null;
function ensureCategoriaHabilitadaWarnEl(){
  if(categoriaHabilitadaWarnEl && categoriaHabilitadaWarnEl.isConnected) return categoriaHabilitadaWarnEl;
  categoriaHabilitadaWarnEl = document.createElement('div');
  categoriaHabilitadaWarnEl.id = 'categoriaHabilitadaWarning';
  categoriaHabilitadaWarnEl.style.cssText = 'margin-top:6px;font-size:12px;line-height:1.3;color:#991b1b;background:#FEF2F2;border:1px solid #FECACA;border-radius:6px;padding:8px;display:none;';
  const host = categoriaHabilitadaInput?.closest('label') || categoriaHabilitadaInput?.parentElement || null;
  if(host){ host.insertAdjacentElement('afterend', categoriaHabilitadaWarnEl); }
  return categoriaHabilitadaWarnEl;
}
function updateCategoriaHabilitadaWarning(){
  try{
    const el = ensureCategoriaHabilitadaWarnEl(); if(!el) return;
    const isChecked = !!categoriaHabilitadaInput?.checked;
    if(isChecked){ el.style.display = 'none'; el.textContent = ''; return; }
    const id = categoriaEditingIdInput && categoriaEditingIdInput.value ? String(categoriaEditingIdInput.value) : null;
    let relatedCount = 0;
    if(id){ try{ relatedCount = (window.products||[]).filter(p=> String(p.categoriaId||'')===id).length; }catch(_e){} }
    el.textContent = `Al deshabilitar esta categoría, ${relatedCount} clientes relacionados se desasignarán automáticamente.`;
    el.style.display = 'block';
  }catch(_e){}
}
