let mapLibreLoadedPromise = null;

const MAPTILER_STYLES = {
  normal: 'streets',
  satellite: 'hybrid',
  terrain: 'outdoor'
};

function normalizeMaptilerLanguage(lang){
  if(!lang) return '';
  const raw = String(lang).trim().toLowerCase();
  if(!raw) return '';
  const allowed = [
    'en','es','de','fr','it','pt','ru','pl','cs','sk','hu','ja','zh','nl','sv','no','da','fi','tr','uk','ar','he'
  ];
  if(allowed.includes(raw)) return raw;
  const primary = raw.split(/[-_]/)[0];
  return allowed.includes(primary) ? primary : '';
}

function ensureHereLoaded(){
  if(typeof maplibregl !== 'undefined') return Promise.resolve();
  if(mapLibreLoadedPromise) return mapLibreLoadedPromise;
  mapLibreLoadedPromise = new Promise((resolve, reject)=>{
    try{
      const head = document.head || document.getElementsByTagName('head')[0];
      if(head && !document.querySelector('link[data-maplibre]')){
        const link = document.createElement('link');
        link.rel = 'stylesheet';
        link.href = 'https://unpkg.com/maplibre-gl@4.2.0/dist/maplibre-gl.css';
        link.setAttribute('data-maplibre','true');
        head.appendChild(link);
      }
      if(typeof maplibregl !== 'undefined'){ resolve(); return; }
      if(document.querySelector('script[data-maplibre]')){
        const existing = document.querySelector('script[data-maplibre]');
        existing.addEventListener('load', ()=> resolve());
        existing.addEventListener('error', (err)=> reject(err));
        return;
      }
      const script = document.createElement('script');
      script.src = 'https://unpkg.com/maplibre-gl@4.2.0/dist/maplibre-gl.js';
      script.async = true;
      script.setAttribute('data-maplibre','true');
      script.onload = ()=> resolve();
      script.onerror = (err)=> reject(err);
      (document.body || document.documentElement).appendChild(script);
    }catch(err){ reject(err); }
  });
  return mapLibreLoadedPromise.catch(err=>{
    console.error('[MapLibre] load failed', err);
    throw err;
  });
}

function buildMaptilerStyle(mode){
  const key = window.__MAPTILER_KEY__ || '';
  const styleName = MAPTILER_STYLES[mode] || MAPTILER_STYLES.normal;
  return key ? `https://api.maptiler.com/maps/${styleName}/style.json?key=${key}` : '';
}

function createMapTilerService(apiKey){
  const base = 'https://api.maptiler.com/geocoding';
  const toItems = (features)=> (features||[]).map(maptilerFeatureToItem).filter(Boolean);

  function maptilerFeatureToItem(feature){
    try{
      if(!feature || !feature.geometry) return null;
      const coords = feature.geometry.coordinates || [];
      const lng = Number(coords[0]);
      const lat = Number(coords[1]);
      if(!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
      const props = feature.properties || {};
      const embeddedAddr = props.address || {};
      const street = props.street || props.street_name || props.road || embeddedAddr.road || embeddedAddr.street || embeddedAddr.name || '';
      const houseNumber = props.housenumber || props.house_number || embeddedAddr.house_number || embeddedAddr.housenumber || embeddedAddr.number || '';
      const postalCode = props.postcode || props.zip || embeddedAddr.postcode || embeddedAddr.zip || embeddedAddr.postal_code || '';
      const district = props.district || props.neighbourhood || props.neighborhood || props.suburb || props.quarter || props.locality || embeddedAddr.neighbourhood || embeddedAddr.neighborhood || embeddedAddr.suburb || '';
      const city = props.city || props.town || props.village || props.locality || props.municipality || props.county || embeddedAddr.city || embeddedAddr.town || embeddedAddr.village || embeddedAddr.municipality || '';
      const state = props.state || props.state_code || props.region || props.province || embeddedAddr.state || embeddedAddr.region || '';
      const countryName = props.country || props.country_name || embeddedAddr.country || '';
      const countryCodeRaw = props.country_code || props.iso2 || embeddedAddr.country_code || embeddedAddr.iso2 || '';
      const countryCode = countryCodeRaw ? String(countryCodeRaw).toUpperCase() : '';
      const baseLabel = props.formatted || props.label || props.name || props.place || '';
      const address = {
        label: baseLabel,
        display_name: baseLabel,
        street,
        road: street,
        houseNumber,
        housenumber: houseNumber,
        house_number: houseNumber,
        postalCode,
        postcode: postalCode,
        zip: postalCode,
        district,
        suburb: district,
        neighbourhood: district,
        neighborhood: district,
        city,
        town: city,
        village: city,
        municipality: city,
        state,
        stateCode: props.state_code || state,
        region: state,
        province: props.province || state,
        countryName,
        country: countryName,
        countryCode,
        country_code: countryCode ? countryCode.toLowerCase() : ''
      };
      return {
        position: { lat, lng },
        title: props.formatted || props.label || props.name || '',
        address,
        categories: props.category ? [{ name: props.category }] : []
      };
    }catch(_e){ return null; }
  }

  function buildQueryFromQQ(qq){
    if(!qq) return '';
    return String(qq).split(';').map(part=>{
      const [k,v] = part.split('=');
      if(v==null) return part.trim();
      try{ return decodeURIComponent(v); }catch(_e){ return v; }
    }).filter(Boolean).join(', ');
  }

  function fetchJson(url, onSuccess, onError){
    fetch(url, { headers:{ 'Accept':'application/json' } })
      .then(res=>{ if(!res.ok) throw new Error('HTTP '+res.status); return res.json(); })
      .then(data=> onSuccess(data))
      .catch(err=>{
        console.warn('[MapTiler] request failed', err);
        if(typeof onError === 'function') onError(err);
      });
  }

  return {
    geocode(params={}, onSuccess=()=>{}, onError){
      let query = '';
      if(params.qq){ query = buildQueryFromQQ(params.qq); }
      else if(params.q){ query = params.q; }
      if(!query){ onSuccess({ items: [] }); return; }
      const langParam = normalizeMaptilerLanguage(params.lang);
      const queryParams = [`key=${encodeURIComponent(apiKey)}`];
      if(langParam) queryParams.push(`language=${encodeURIComponent(langParam)}`);
      let limitVal = Number.isFinite(params.limit) ? params.limit : 10;
      limitVal = Math.max(1, Math.min(10, limitVal));
      queryParams.push(`limit=${encodeURIComponent(limitVal)}`);
      const allowedTypes = ['country','region','subregion','locality','neighborhood','place','address','poi','postcode'];
      const normalizeTypes = (value)=>{
        if(!value) return [];
        const parts = Array.isArray(value) ? value : String(value).split(/[\,\s]+/);
        return parts
          .map(v=>String(v||'').trim().toLowerCase())
          .filter(v=>allowedTypes.includes(v));
      };
      let typesList = normalizeTypes(params.types);
      if(!typesList.length && Array.isArray(CLIENTE_ADDR_SEARCH_MAPTILER_TYPES)){
        typesList = normalizeTypes(CLIENTE_ADDR_SEARCH_MAPTILER_TYPES);
      }
      if(typesList.length) queryParams.push(`types=${encodeURIComponent(typesList.join(','))}`);
      const countryParam = normalizeCountryParamList(params.country);
      if(countryParam) queryParams.push(`country=${encodeURIComponent(countryParam.toUpperCase())}`);
      const proximityParam = (function(val){
        if(!val) return '';
        if(typeof val === 'string') return val;
        const lat = Number(val.lat ?? val.latitude);
        const lng = Number(val.lng ?? val.lon ?? val.longitude);
        if(Number.isFinite(lat) && Number.isFinite(lng)) return `${lng},${lat}`;
        return '';
      })(params.proximity);
      if(proximityParam) queryParams.push(`proximity=${encodeURIComponent(proximityParam)}`);
      const url = `${base}/${encodeURIComponent(query)}.json?${queryParams.join('&')}`;
      fetchJson(url, data=>{
        onSuccess({ items: toItems((data && data.features) || []) });
      }, onError);
    },
    reverseGeocode(params={}, onSuccess=()=>{}, onError){
      let lat = null;
      let lng = null;
      if(params.at){
        const parts = String(params.at).split(',');
        lat = parseFloat(parts[0]);
        lng = parseFloat(parts[1]);
      } else if(params.lat != null && params.lng != null){
        lat = Number(params.lat);
        lng = Number(params.lng);
      }
      if(!Number.isFinite(lat) || !Number.isFinite(lng)){
        onSuccess({ items: [] });
        return;
      }
      let url = `${base}/${lng},${lat}.json?key=${apiKey}`;
  const langParam = normalizeMaptilerLanguage(params.lang);
  if(langParam) url += `&language=${encodeURIComponent(langParam)}`;
      if(params.limit){
        let reverseLimit = Number.isFinite(params.limit) ? params.limit : 5;
        reverseLimit = Math.max(1, Math.min(10, reverseLimit));
        url += `&limit=${encodeURIComponent(reverseLimit)}`;
      }
      fetchJson(url, data=>{
        onSuccess({ items: toItems((data && data.features) || []) });
      }, onError);
    },
    browse(_params, onSuccess=()=>{}){ onSuccess({ items: [] }); },
    discover(_params, onSuccess=()=>{}){ onSuccess({ items: [] }); }
  };
}

function ensureMaptilerService(){
  const apiKey = window.__MAPTILER_KEY__ || '';
  if(!apiKey) { maptilerService = null; return null; }
  if(!maptilerService || maptilerService.__apiKey !== apiKey){
    maptilerService = createMapTilerService(apiKey);
    if(maptilerService){
      maptilerService.__kind = 'maptiler';
      maptilerService.__apiKey = apiKey;
    }
  }
  return maptilerService;
}

function ensureNominatimService(){
  if(!nominatimService){
    nominatimService = createNominatimService();
    if(nominatimService) nominatimService.__kind = 'nominatim';
  }
  return nominatimService;
}

function ensurePhotonService(){
  if(!ENABLE_PHOTON_SERVICE){
    photonService = null;
    return null;
  }
  try{
    if(typeof window !== 'undefined'){
      const proto = (window.location && window.location.protocol) || '';
      if(proto === 'file:'){
        photonService = null;
        return null;
      }
    }
  }catch(_e){ /* ignore */ }
  if(!photonService){
    photonService = createPhotonService();
    if(photonService) photonService.__kind = 'photon';
  }
  return photonService;
}

