const CARTO_LIGHT_STYLE = {
  version: 8,
  sources: {
    carto: {
      type: 'raster',
      tiles: [
        'https://a.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png',
        'https://b.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png',
        'https://c.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png',
        'https://d.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png'
      ],
      tileSize: 256,
      attribution: '© OpenStreetMap contributors, © CARTO'
    }
  },
  layers: [{ id: 'carto-tiles', type: 'raster', source: 'carto' }]
};

const OSM_RASTER_STYLE = {
  version: 8,
  sources: {
    osm: {
      type: 'raster',
      tiles: ['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],
      tileSize: 256,
      attribution: '© OpenStreetMap contributors'
    }
  },
  layers: [{ id: 'osm-tiles', type: 'raster', source: 'osm' }]
};

function resolveBasemapStyle(){
  const apiKey = window.__MAPTILER_KEY__ || '';
  if(apiKey){
    const styleUrl = buildMaptilerStyle('normal');
    if(styleUrl) return styleUrl;
  }
  return CARTO_LIGHT_STYLE || OSM_RASTER_STYLE;
}

function getGeoServicesPriority(mode='geocode'){
  const services = [];
  const mapSvc = ensureMaptilerService();
  const nomSvc = ensureNominatimService();
  const phoSvc = ensurePhotonService();
  if(mode === 'reverse'){
    if(nomSvc) services.push(nomSvc);
    if(phoSvc && phoSvc !== nomSvc) services.push(phoSvc);
    if(mapSvc && mapSvc !== nomSvc) services.push(mapSvc);
  } else {
    if(mapSvc) services.push(mapSvc);
    if(phoSvc && phoSvc !== mapSvc) services.push(phoSvc);
    if(nomSvc && nomSvc !== mapSvc) services.push(nomSvc);
  }
  if(!services.length){
    if(mapSvc) services.push(mapSvc);
    else if(phoSvc) services.push(phoSvc);
    else if(nomSvc) services.push(nomSvc);
  }
  return services;
}

function createNominatimService(){
  // Lightweight wrapper matching MapTiler service API used in the app
  const base = 'https://nominatim.openstreetmap.org';
  const USER_AGENT = window.__NOMINATIM_USER_AGENT__ || 'MAQ-Imprenta/1.0 (+https://github.com/)';
  const EMAIL = window.__NOMINATIM_EMAIL__ || '';
  function fetchJson(url, onSuccess, onError){
    const headers = { 'Accept':'application/json' };
    // Nota: navegadores impiden establecer User-Agent manualmente; solo adjúntalo cuando se ejecute fuera del DOM (p.ej. Node).
    try {
      if(typeof window === 'undefined' && USER_AGENT){ headers['User-Agent'] = USER_AGENT; }
    } catch(_e){}
    fetch(url, { headers })
      .then(res=>{ if(!res.ok) throw new Error('HTTP '+res.status); return res.json(); })
      .then(data=> onSuccess(data))
      .catch(err=>{ console.warn('[Nominatim] request failed', err); if(typeof onError === 'function') onError(err); });
  }
  const resolveLang = (params)=>{
    if(!params) return '';
    const raw = params.lang || params.language || params.acceptLanguage || '';
    if(!raw) return '';
    const normalized = normalizeMaptilerLanguage(raw) || String(raw).split(/[-_]/)[0];
    return normalized || '';
  };
  function toItemsFromSearch(list){
    return (list||[]).map(i=>{
      const lat = Number(i.lat||i.latitude||0);
      const lon = Number(i.lon||i.longitude||0);
      const address = i.address || {};
      const countryCode = address.country_code ? String(address.country_code).toUpperCase() : '';
      const countryName = address.country || countryCode;
      return {
        position: { lat, lng: lon },
        title: i.display_name || i.name || '',
        address: {
          label: i.display_name || '',
          display_name: i.display_name || '',
          street: address.road || address.pedestrian || address.cycleway || address.street || '',
          houseNumber: address.house_number || address.housenumber || '',
          postalCode: address.postcode || '',
          district: address.suburb || address.neighbourhood || address.village || address.hamlet || address.city_district || address.state_district || '',
          city: address.city || address.town || address.village || address.municipality || address.county || '',
          state: address.state || address.region || address.state_code || '',
          countryName,
          countryCode
        },
        categories: []
      };
    }).filter(Boolean);
  }

  return {
    geocode(params={}, onSuccess=()=>{}, onError){
      // support q or qq fallback
      let q = params.q || '';
      if(params.qq) q = String(params.qq).split(';').map(s=>{ const kv=s.split('='); return kv[1]||kv[0]; }).join(', ');
      if(!q){ onSuccess({ items: [] }); return; }
      const lang = resolveLang(params);
      let url = `${base}/search?format=json&addressdetails=1&q=${encodeURIComponent(q)}&limit=${encodeURIComponent(params.limit||10)}`;
      if(lang) url += `&accept-language=${encodeURIComponent(lang)}`;
      if(params.countrycodes){
        const codes = normalizeCountryParamList(params.countrycodes).toLowerCase();
        if(codes) url += `&countrycodes=${encodeURIComponent(codes)}`;
      }
      if(params.viewbox){
        url += `&viewbox=${encodeURIComponent(params.viewbox)}`;
        if(params.bounded) url += '&bounded=1';
      }
      if(EMAIL) url += `&email=${encodeURIComponent(EMAIL)}`;
      fetchJson(url, data=> onSuccess({ items: toItemsFromSearch(data) }), onError);
    },
    reverseGeocode(params={}, onSuccess=()=>{}, onError){
      let lat = null, lng = null;
      if(params.at){ const parts = String(params.at).split(','); lat = parseFloat(parts[0]); lng = parseFloat(parts[1]); }
      else if(params.lat!=null && params.lng!=null){ lat = Number(params.lat); lng = Number(params.lng); }
      if(!Number.isFinite(lat) || !Number.isFinite(lng)){ onSuccess({ items: [] }); return; }
      const lang = resolveLang(params);
  let url = `${base}/reverse?format=json&addressdetails=1&zoom=18&lat=${encodeURIComponent(lat)}&lon=${encodeURIComponent(lng)}`;
      if(lang) url += `&accept-language=${encodeURIComponent(lang)}`;
      if(EMAIL) url += `&email=${encodeURIComponent(EMAIL)}`;
      fetchJson(url, data=>{ const items = data ? [data] : []; onSuccess({ items: toItemsFromSearch(items) }); }, onError);
    },
    browse(_params, onSuccess=()=>{}){ onSuccess({ items: [] }); },
    discover(_params, onSuccess=()=>{}){ onSuccess({ items: [] }); }
  };
}

function createPhotonService(){
  const base = 'https://photon.komoot.io';
  const fetchJson = (url, onSuccess, onError)=>{
    fetch(url, { headers:{ 'Accept':'application/json' }, mode:'cors', credentials:'omit' })
      .then(res=>{ if(!res.ok) throw new Error('HTTP '+res.status); return res.json(); })
      .then(data=> onSuccess(data))
      .catch(err=>{ console.warn('[Photon] request failed', err); if(typeof onError === 'function') onError(err); });
  };
  const toItems = (features)=> (features||[]).map(feature=>{
    if(!feature || !feature.geometry) return null;
    const coords = feature.geometry.coordinates || [];
    const lng = Number(coords[0]);
    const lat = Number(coords[1]);
    if(!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
    const props = feature.properties || {};
    const address = {
      label: props.name || props.street || props.city || '',
      street: props.street || props.name || '',
      houseNumber: props.housenumber || '',
      postalCode: props.postcode || '',
      district: props.district || props.suburb || props.neighbourhood || props.neighborhood || '',
      city: props.city || props.town || props.village || props.county || '',
      state: props.state || props.statecode || props.region || '',
      countryName: props.country || '',
      countryCode: props.countrycode ? String(props.countrycode).toUpperCase() : ''
    };
    return {
      position: { lat, lng },
      title: props.name || address.label || '',
      address,
      categories: []
    };
  }).filter(Boolean);

  return {
    geocode(params={}, onSuccess=()=>{}, onError){
      let q = params.q || '';
      if(params.qq){ q = String(params.qq).split(';').map(part=>{ const [k,v] = part.split('='); return v||k; }).join(', '); }
      if(!q){ onSuccess({ items: [] }); return; }
      const lang = normalizeMaptilerLanguage(params.lang) || 'es';
      let limit = Number.isFinite(params.limit) ? params.limit : 10;
      limit = Math.max(1, Math.min(10, limit));
      const qs = [`q=${encodeURIComponent(q)}`, `lang=${encodeURIComponent(lang)}`, `limit=${encodeURIComponent(limit)}`];
      const lat = Number(params.lat ?? params.latitude);
      const lon = Number(params.lon ?? params.lng ?? params.longitude);
      if(Number.isFinite(lat) && Number.isFinite(lon)){
        qs.push(`lat=${encodeURIComponent(lat)}`);
        qs.push(`lon=${encodeURIComponent(lon)}`);
      }
      const url = `${base}/api/?${qs.join('&')}`;
      fetchJson(url, data=> onSuccess({ items: toItems((data && data.features) || []) }), onError);
    },
    reverseGeocode(params={}, onSuccess=()=>{}, onError){
      let lat = null;
      let lng = null;
      if(params.at){ const parts = String(params.at).split(','); lat = parseFloat(parts[0]); lng = parseFloat(parts[1]); }
      else if(params.lat!=null && params.lng!=null){ lat = Number(params.lat); lng = Number(params.lng); }
      if(!Number.isFinite(lat) || !Number.isFinite(lng)){ onSuccess({ items: [] }); return; }
      const lang = normalizeMaptilerLanguage(params.lang) || 'es';
      const url = `${base}/reverse?lat=${encodeURIComponent(lat)}&lon=${encodeURIComponent(lng)}&lang=${encodeURIComponent(lang)}`;
      fetchJson(url, data=> onSuccess({ items: toItems((data && data.features) || []) }), onError);
    },
    browse(_params, onSuccess=()=>{}){ onSuccess({ items: [] }); },
    discover(_params, onSuccess=()=>{}){ onSuccess({ items: [] }); }
  };
}

// Returns the best available geo service: MapTiler (if key) or Nominatim as fallback
function ensureGeoService(prefer='auto'){
  if(prefer==='maptiler'){
    const svc = ensureMaptilerService();
    if(svc){ hereService = svc; return svc; }
  }
  if(prefer==='nominatim'){
    const nom = ensureNominatimService();
    if(nom){ hereService = nom; return nom; }
  }
  const apiKey = window.__MAPTILER_KEY__ || '';
  if(apiKey){
    const mapSvc = ensureMaptilerService();
    if(mapSvc){ hereService = mapSvc; return mapSvc; }
  }
  const nomSvc = ensureNominatimService();
  if(nomSvc){ hereService = nomSvc; return nomSvc; }
  return null;
}

function buildMapLibreFallbackImage(size=28){
  const dim = Math.max(12, Math.min(64, size|0));
  const data = new Uint8Array(dim * dim * 4);
  const center = (dim - 1) / 2;
  const radius = dim / 2 - 2;
  for(let y=0; y<dim; y++){
    for(let x=0; x<dim; x++){
      const dx = x - center;
      const dy = y - center;
      const dist = Math.sqrt(dx*dx + dy*dy);
      const idx = (y * dim + x) * 4;
      if(dist <= radius){
        data[idx] = 49;      // R
        data[idx+1] = 120;   // G
        data[idx+2] = 198;   // B
        data[idx+3] = 210;   // A
      } else if(dist <= radius + 1.2){
        data[idx] = 30;
        data[idx+1] = 64;
        data[idx+2] = 175;
        data[idx+3] = 160;
      } else {
        data[idx] = 0;
        data[idx+1] = 0;
        data[idx+2] = 0;
        data[idx+3] = 0;
      }
    }
  }
  return { width: dim, height: dim, data };
}

function attachMapLibreMissingImageHandler(map){
  try{
    if(!map || typeof map.on !== 'function') return;
    if(map.__missingImageHandlerBound) return;
    const provided = new Set();
    map.on('styleimagemissing', (event)=>{
      const id = event && event.id ? String(event.id) : '';
      if(!id || provided.has(id)) return;
      provided.add(id);
      try{
        const fallback = buildMapLibreFallbackImage();
        map.addImage(id, fallback, { pixelRatio: 1 });
      }catch(err){
        console.warn('[MapLibre] fallback icon failed', id, err);
      }
    });
    map.__missingImageHandlerBound = true;
  }catch(err){ console.warn('[MapLibre] missing-image handler error', err); }
}

async function initHere(){
  try{
    if(!clienteMapaEl) return;
    if(hereMap) return;
    await ensureHereLoaded();
  let styleSource = resolveBasemapStyle() || OSM_RASTER_STYLE;
    if(!hereOsmNoticeShown){
      hereOsmNoticeShown = true;
      try{ notify('Mapas de OpenStreetMap habilitados','info'); }catch(_e){}
    }
    hereService = ensureGeoService();
    const mapStyle = (styleSource && typeof styleSource === 'object') ? JSON.parse(JSON.stringify(styleSource)) : styleSource;
    hereMap = new maplibregl.Map({
      container: clienteMapaEl,
      style: mapStyle,
      center: [-99.1332, 19.4326],
      zoom: 12,
      attributionControl: true
    });
    attachMapLibreMissingImageHandler(hereMap);
    hereMap.addControl(new maplibregl.NavigationControl(), 'top-left');
    hereMap.on('load', ()=>{
      try{ hereMap.resize(); }catch(_e){}
      renderAllSlotMarkers();
    });
    hereMap.on('styledata', ()=>{
      Object.entries(hereLabelMarkers).forEach(([slot, marker])=>{
        if(marker){ updateSlotLabelElement(marker.getElement(), slot); }
      });
    });
    bindHereInteractions();
    buildHereControls();
    bindFullscreenResize();
  }catch(err){
    console.error('[MapLibre] init error', err);
  }
}

function bindHereInteractions(){
  if(!hereMap || hereInteractionsBound) return;
  hereMap.on('click', (ev)=>{
    const { lat, lng } = ev.lngLat || {};
    if(!Number.isFinite(lat) || !Number.isFinite(lng)) return;
    setMapMarker(lat, lng);
    if(clienteCoordsInput) clienteCoordsInput.value = `${lat.toFixed(6)}, ${lng.toFixed(6)}`;
    try{ saveActiveSlotFields(); }catch(_e){}
    handleCoordsChange();
  });
  hereInteractionsBound = true;
}

function buildHereControls(){
  if(hereControlsBuilt || !clienteMapaEl) return;
  const wrap = document.createElement('div');
  wrap.id = 'hereCustomControls';
  wrap.style.position = 'absolute';
  // Ubicar en esquina superior izquierda, debajo del zoom nativo
  wrap.style.top = '64px';
  wrap.style.left = '8px';
  wrap.style.right = 'auto';
  wrap.style.display = 'flex';
  wrap.style.flexDirection = 'column';
  wrap.style.gap = '6px';
  wrap.style.zIndex = '5';
  const mkBtn = (id, text, title)=>{ const b=document.createElement('button'); b.id=id; b.textContent=text; b.title=title||''; b.type='button'; b.style.padding='6px 8px'; b.style.border='1px solid #d1d5db'; b.style.borderRadius='6px'; b.style.background='#fff'; b.style.cursor='pointer'; b.style.boxShadow='0 1px 2px rgba(0,0,0,0.08)'; return b; };
  const fullscreenBtn = mkBtn('hereFullscreenBtn','⛶','Pantalla completa');
  const recenterBtn = mkBtn('hereRecenterBtn','🎯','Centrar al pin');
  // Orden: Pantalla completa, Centrar
  wrap.appendChild(fullscreenBtn);
  wrap.appendChild(recenterBtn);
  // Ensure parent is positioned
  const parent = clienteMapaEl;
  const prevPos = getComputedStyle(parent).position;
  if(prevPos==='static') parent.style.position='relative';
  parent.appendChild(wrap);
  // Bind actions
  recenterBtn.addEventListener('click', ()=>{
    if(!hereMap) return;
    const marker = hereMarkers[getActiveSlot()] || hereMarker;
    if(!marker || typeof marker.getLngLat !== 'function') return;
    const pos = marker.getLngLat();
    if(!pos) return;
    try{
      const currentZoom = hereMap.getZoom();
      const nextZoom = typeof currentZoom === 'number' && currentZoom >= 15 ? currentZoom : 16;
      hereMap.easeTo({ center: [pos.lng, pos.lat], zoom: nextZoom, duration: 350 });
    }catch(_e){}
  });
  fullscreenBtn.addEventListener('click', ()=>{ toggleHereFullscreen(); });
  // Solo los dos botones solicitados
  hereControlsBuilt = true;
}

function toggleHereTraffic(btn){
  notify('OpenStreetMap no incluye capa de tráfico en esta vista.','info');
  if(btn) btn.blur();
}

function toggleHereBaseMap(btn){
  if(!hereMap) return;
  notify('Solo está disponible el estilo base de OpenStreetMap.', 'info');
  if(btn) btn.blur();
}

function toggleHereFullscreen(){
  const el = clienteMapaEl; if(!el) return;
  const isFs = document.fullscreenElement === el;
  if(!isFs){
    if(el.requestFullscreen) el.requestFullscreen();
  } else {
    if(document.exitFullscreen) document.exitFullscreen();
  }
}

function bindFullscreenResize(){
  document.addEventListener('fullscreenchange', ()=>{
    if(hereMap){ try{ hereMap.resize(); }catch(_e){} }
  });
}

function toggleHerePlaces(btn){
  notify('Lugares cercanos no disponible con MapTiler','info');
  if(btn) btn.blur();
}

function bindPOIViewportListener(){}
function unbindPOIViewportListener(){}
function refreshHerePOIs(){}
function renderPOIs(){ }
function createPOIIcon(){ return null; }
function showPOIBubble(){ }
// Nuevas utilidades de marcador y etiquetas se definen más adelante
function getSlotColor(slot){
  return slot==='casa' ? '#0ea5e9' : (slot==='trabajo' ? '#22c55e' : '#a855f7');
}

// UI tinting for segmented botones (CASA/TRABAJO/PUNTO MEDIO) matching map colors
function getSlotUiColors(slot){
  switch(slot){
    case 'casa': return { bg:'#e0f2fe', border:'#7dd3fc', text:'#0c4a6e' }; // sky
    case 'trabajo': return { bg:'#dcfce7', border:'#86efac', text:'#065f46' }; // green
    case 'puntoMedio': return { bg:'#f3e8ff', border:'#d8b4fe', text:'#6b21a8' }; // purple
    default: return { bg:'#eef2f7', border:'#cbd5e1', text:'#334155' };
  }
}
function styleAddrTabs(active){
  if(!clienteAddrTabs) return;
  const btns = clienteAddrTabs.querySelectorAll('button.seg-item');
  btns.forEach(b=>{
    const slot = b.dataset.slot;
    const isActive = (slot===active);
    const col = getSlotUiColors(slot);
    b.style.background = isActive ? col.bg : '#fff';
    b.style.color = isActive ? col.text : '#334155';
    b.style.border = '0';
    // separator border-left for middle/right buttons
    if(slot!=='casa') b.style.borderLeft = '1px solid #cbd5e1';
  });
}
function createSlotMarkerElement(slot){
  const color = getSlotColor(slot);
  const el = document.createElement('div');
  el.className = 'map-slot-marker';
  el.style.width = '38px';
  el.style.height = '38px';
  el.style.transform = 'translate(-50%, -100%)';
  el.style.pointerEvents = 'auto';
  el.style.cursor = 'grab';
  el.style.transition = 'filter 0.2s ease';
  el.innerHTML = `<svg width="38" height="38" viewBox="0 0 24 24" fill="${color}" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 21s-6-5.686-6-10a6 6 0 1112 0c0 4.314-6 10-6 10z"/><circle cx="12" cy="11" r="3.2" fill="white"/></svg>`;
  return el;
}

function updateSlotMarkerElement(el, slot){
  if(!el) return;
  const color = getSlotColor(slot);
  const svg = el.querySelector('svg');
  if(svg) svg.setAttribute('fill', color);
  el.style.filter = slot === getActiveSlot() ? 'drop-shadow(0 6px 12px rgba(15,23,42,0.35))' : 'drop-shadow(0 3px 6px rgba(15,23,42,0.22))';
}

function createSlotLabelElement(slot){
  const el = document.createElement('div');
  el.className = 'map-slot-label';
  el.style.transform = 'translate(-50%, -135%)';
  el.style.background = '#fff';
  el.style.color = '#111827';
  el.style.border = '1px solid #d1d5db';
  el.style.borderRadius = '8px';
  el.style.padding = '6px 8px';
  el.style.font = '12px system-ui, Segoe UI, Arial, sans-serif';
  el.style.boxShadow = '0 4px 10px rgba(0,0,0,0.12)';
  el.style.whiteSpace = 'nowrap';
  el.style.display = 'flex';
  el.style.alignItems = 'center';
  el.style.gap = '6px';
  el.innerHTML = '<span data-dot style="display:inline-block;width:10px;height:10px;border-radius:50%;"></span><span data-text></span>';
  updateSlotLabelElement(el, slot);
  return el;
}

function updateSlotLabelElement(el, slot){
  if(!el) return;
  const dot = el.querySelector('[data-dot]');
  const label = el.querySelector('[data-text]');
  if(dot) dot.style.background = getSlotColor(slot);
  if(label) label.textContent = String(buildSlotLabelText(slot)||'');
}

function clearAllSlotMarkers(){
  try{
    ['casa','trabajo','puntoMedio'].forEach(slot=>{
      const marker = hereMarkers[slot];
      if(marker && typeof marker.remove === 'function'){ marker.remove(); }
      hereMarkers[slot] = null;
      const label = hereLabelMarkers[slot];
      if(label && typeof label.remove === 'function'){ label.remove(); }
      hereLabelMarkers[slot] = null;
    });
    hereMarker = null;
  }catch(_e){}
}

function ensureSlotLabel(slot, lat, lng){
  try{
    if(!hereMap) return;
    if(!Number.isFinite(lat) || !Number.isFinite(lng)) return;
    let marker = hereLabelMarkers[slot];
    if(!marker){
      const element = createSlotLabelElement(slot);
      marker = new maplibregl.Marker({ element, anchor: 'bottom' });
      marker.$slot = slot;
      marker.setLngLat([lng, lat]).addTo(hereMap);
      hereLabelMarkers[slot] = marker;
    } else {
      const el = marker.getElement && marker.getElement();
      if(el) updateSlotLabelElement(el, slot);
      marker.setLngLat([lng, lat]);
    }
  }catch(_e){}
}

function setSlotMarker(slot, lat, lng, opts={}){
  if(!hereMap) return;
  if(!['casa','trabajo','puntoMedio'].includes(slot)) slot = 'casa';
  if(!Number.isFinite(lat) || !Number.isFinite(lng)) return;
  const coords = [lng, lat];
  let marker = hereMarkers[slot];
  if(!marker){
    const element = createSlotMarkerElement(slot);
    marker = new maplibregl.Marker({ element, draggable: slot === getActiveSlot() });
    marker.$slot = slot;
    marker.setLngLat(coords).addTo(hereMap);
    marker.on('dragstart', ()=>{ try{ element.style.cursor = 'grabbing'; }catch(_e){} });
    marker.on('drag', ()=>{
      const pos = marker.getLngLat();
      ensureSlotLabel(slot, pos.lat, pos.lng);
    });
    marker.on('dragend', ()=>{
      try{ element.style.cursor = 'grab'; }catch(_e){}
      const pos = marker.getLngLat();
      ensureSlotLabel(slot, pos.lat, pos.lng);
      if(slot === getActiveSlot()){
        if(clienteCoordsInput) clienteCoordsInput.value = `${pos.lat.toFixed(6)}, ${pos.lng.toFixed(6)}`;
        try{ saveActiveSlotFields(); }catch(_e){}
        handleCoordsChange();
      } else {
        try{
          const record = Object.assign({}, clienteDirecciones[slot] || {});
          record.coords = `${pos.lat.toFixed(6)}, ${pos.lng.toFixed(6)}`;
          clienteDirecciones[slot] = record;
        }catch(_e){}
      }
    });
    hereMarkers[slot] = marker;
  } else {
    marker.setLngLat(coords);
    marker.setDraggable(slot === getActiveSlot());
    updateSlotMarkerElement(marker.getElement && marker.getElement(), slot);
  }
  updateSlotMarkerElement(marker.getElement && marker.getElement(), slot);
  ensureSlotLabel(slot, lat, lng);
  if(slot === getActiveSlot()) hereMarker = marker;
  if(opts.center !== false){
    try{
      const currentZoom = hereMap.getZoom();
      const nextZoom = typeof currentZoom === 'number' && currentZoom >= 15 ? currentZoom : 16;
      hereMap.easeTo({ center: coords, zoom: nextZoom, duration: 350 });
    }catch(_e){}
  }
}

function setMapMarker(lat, lng, opts){
  setSlotMarker(getActiveSlot(), lat, lng, opts||{});
}

function refreshMarkersDraggable(){
  const active = getActiveSlot();
  ['casa','trabajo','puntoMedio'].forEach((slot)=>{
    const marker = hereMarkers[slot];
    if(!marker) return;
    try{ marker.setDraggable(slot === active); }catch(_e){}
    updateSlotMarkerElement(marker.getElement && marker.getElement(), slot);
  });
}

// Mini dialog helper (fallback) — simple modal with title, html content and buttons
if(typeof window.miniDialog !== 'function'){
  window.miniDialog = function(title, html, buttons){
    try{
      const overlay = document.createElement('div');
      overlay.className = 'modal-overlay';
      const modal = document.createElement('div');
      modal.className = 'modal';
      modal.style.maxWidth = '520px';
      modal.innerHTML = `
        <div class="modal-header">
          <h3>${String(title||'').replace(/[<>]/g,'')}</h3>
          <button class="close-btn" aria-label="Cerrar">×</button>
        </div>
        <div class="modal-body">${html||''}</div>
        <div class="modal-footer" style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px;"></div>
      `;
      overlay.appendChild(modal);
      document.body.appendChild(overlay);
      const close = ()=>{ try{ document.body.removeChild(overlay); }catch(_e){} };
      modal.querySelector('.close-btn')?.addEventListener('click', close);
      const footer = modal.querySelector('.modal-footer');
      const btns = Array.isArray(buttons) && buttons.length ? buttons : [{ label:'Cerrar', variant:'primary' }];
      btns.forEach((b)=>{
        const btn = document.createElement('button');
        btn.textContent = b.label || 'Aceptar';
        btn.className = 'btn ' + (b.variant==='secondary' ? 'btn-secondary' : 'btn-primary');
        btn.style.fontSize = '0.7rem';
        btn.addEventListener('click', async ()=>{
          if(typeof b.onClick === 'function'){
            const res = await b.onClick();
            if(res===false) return; // keep open
          }
          close();
        });
        footer.appendChild(btn);
      });
      return { close };
    }catch(_e){ alert(String(title||'')+"\n\n"+String(html||'')); }
  };
}
function renderAllSlotMarkers(){
  try{
    const slots = ['casa','trabajo','puntoMedio'];
    let any = false; let bounds = null;
    slots.forEach(s=>{
      const c = parseCoords((clienteDirecciones[s]&&clienteDirecciones[s].coords)||'');
      if(c){
        setSlotMarker(s, c.lat, c.lng, { center: false });
        try{ ensureSlotLabel(s, c.lat, c.lng); }catch(_e){}
        any = true;
        try{
          if(!bounds){ bounds = new maplibregl.LngLatBounds([c.lng, c.lat], [c.lng, c.lat]); }
          else { bounds.extend([c.lng, c.lat]); }
        }catch(_e){}
      }
    });
    refreshMarkersDraggable();
    if(any && hereMap){
      const act = hereMarkers[getActiveSlot()];
      if(act && typeof act.getLngLat === 'function'){
        const pos = act.getLngLat();
        try{
          const currentZoom = hereMap.getZoom();
          const nextZoom = typeof currentZoom === 'number' && currentZoom >= 15 ? currentZoom : 16;
          hereMap.easeTo({ center: [pos.lng, pos.lat], zoom: nextZoom, duration: 350 });
        }catch(_e){}
      } else if(bounds){
        try{ hereMap.fitBounds(bounds, { padding: 60, duration: 350 }); }catch(_e){}
      }
    } else if(hereMap){
      try{ hereMap.easeTo({ center: [-99.1332, 19.4326], zoom: 12, duration: 250 }); }catch(_e){}
    }
  }catch(_e){}
}
async function reverseGeocodeHere(lat,lng, opts={}){
  const { attempts=2, delayMs=250 } = opts;
  const services = getGeoServicesPriority('reverse');
  for(const svc of services){
    hereService = svc;
    const fetchOnce = ()=> new Promise((resolve)=>{
      svc.reverseGeocode({ at: `${lat},${lng}`, lang: 'es-MX' }, (result)=>{
        const item = result && result.items && result.items[0];
        resolve(item||null);
      }, ()=> resolve(null));
    });
    for(let i=0;i<attempts;i++){
      const item = await fetchOnce();
      if(item) return item;
      if(i < attempts-1) await delay(delayMs);
    }
  }
  return null;
}
// Normaliza Códigos Postales MX a 5 dígitos (solo números); devuelve '' si no hay 5
function sanitizeCP(value){
  const digits = String(value||'').replace(/\D+/g,'');
  if(digits.length >= 5) return digits.slice(0,5);
  return '';
}

function normalizeCountryCodeInput(value){
  if(!value) return '';
  const text = String(value).trim();
  if(!text) return '';
  if(/^[A-Za-z]{2}$/.test(text)) return text.toLowerCase();
  let normalized = text;
  try { normalized = text.normalize('NFD').replace(/[\u0300-\u036f]/g,''); } catch(_e){}
  normalized = normalized.toLowerCase();
  if(normalized.includes('mex')) return 'mx';
  if(normalized.includes('estados unidos') || normalized.includes('united states') || normalized.includes('usa')) return 'us';
  if(normalized.includes('canad')) return 'ca';
  if(normalized.includes('guatemal')) return 'gt';
  if(normalized.includes('colom')) return 'co';
  if(normalized.includes('argent')) return 'ar';
  if(normalized.includes('espana') || normalized.includes('espa\u00f1a') || normalized.includes('spain')) return 'es';
  if(normalized.includes('peru')) return 'pe';
  if(normalized.includes('chile')) return 'cl';
  if(normalized.includes('brasil') || normalized.includes('brazil')) return 'br';
  return '';
}

function normalizeCountryParamList(value){
  if(!value) return '';
  if(Array.isArray(value)){
    const codes = value.map(v=>normalizeCountryCodeInput(v||'')).filter(Boolean);
    return codes.join(',');
  }
  const parts = String(value).split(/[,\s]+/).map(v=>normalizeCountryCodeInput(v||''));
  const codes = parts.filter(Boolean);
  return codes.join(',');
}

function getClienteAddrCountryHint(){
  const raw = (clientePaisInput && clientePaisInput.value) ? clientePaisInput.value : '';
  const fromField = normalizeCountryCodeInput(raw);
  if(fromField) return fromField;
  return CLIENTE_ADDR_SEARCH_DEFAULT_COUNTRY;
}

function parseAddressQueryForStructuredSearch(input){
  const result = {};
  if(!input) return result;
  const cleaned = String(input).replace(/\s+/g,' ').trim();
  if(!cleaned) return result;
  const segments = cleaned.split(',').map(s=>s.trim()).filter(Boolean);
  const streetSegment = segments.length ? segments[0] : cleaned;
  const postalMatch = cleaned.match(/\b\d{5}\b/);
  const pseudoAddress = {
    label: cleaned,
    street: streetSegment
  };
  if(postalMatch) pseudoAddress.postalCode = postalMatch[0];
  if(segments[1]) pseudoAddress.city = segments[1];
  if(segments[2]) pseudoAddress.state = segments[2];
  if(segments.length >= 3) pseudoAddress.country = segments[segments.length-1];
  const fields = extractAddressFields(pseudoAddress, { address: { label: cleaned }, title: streetSegment });
  if(fields.calle) result.street = fields.calle;
  if(fields.numero) result.houseNumber = fields.numero;
  if(fields.cp) result.postalCode = fields.cp;
  if(fields.colonia) result.district = fields.colonia;
  if(fields.ciudad) result.city = fields.ciudad;
  if(fields.estado) result.state = fields.estado;
  if(fields.pais) result.country = fields.pais;
  if(!result.city && segments[1]) result.city = segments[1];
  if(!result.state && segments[2]) result.state = segments[2];
  if(!result.country && segments.length){
    const last = segments[segments.length-1];
    const normalized = normalizeCountryCodeInput(last);
    if(normalized) result.country = normalized.toUpperCase();
  }
  return result;
}

function buildViewboxAroundCoords(lat, lng, radiusKm){
  const latNum = Number(lat);
  const lngNum = Number(lng);
  if(!Number.isFinite(latNum) || !Number.isFinite(lngNum)) return '';
  const distanceKm = Number.isFinite(radiusKm) && radiusKm>0 ? radiusKm : 15;
  const latOffset = distanceKm / 111;
  const cosLat = Math.cos(latNum * Math.PI / 180) || 1;
  const lngOffset = distanceKm / (111 * cosLat);
  const minLat = latNum - latOffset;
  const maxLat = latNum + latOffset;
  const minLng = lngNum - lngOffset;
  const maxLng = lngNum + lngOffset;
  return `${minLng.toFixed(6)},${maxLat.toFixed(6)},${maxLng.toFixed(6)},${minLat.toFixed(6)}`;
}
function extractAddressFields(a, src){
  if(!a) return {};
  const pick = (...keys)=>{ for(const k of keys){ const val = a[k]; if(val!=null && val!=='') return val; } return ''; };
  const esc = (s)=> String(s||'').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const parseNumFromText = (text, street)=>{
    if(!text) return '';
    const t = String(text);
    // 1) Si conocemos la calle, buscar número tras el nombre
    if(street){
      const rxAfterStreet = new RegExp(`${esc(street)}\\s*(?:No\\.?|#)?\\s*(\\d{1,5}[A-Za-z\\-\\/]?)`, 'i');
      const m = t.match(rxAfterStreet); if(m && m[1]) return m[1];
    }
    // 2) Patrones comunes MX: No. 123, # 123
    const m2 = t.match(/(?:No\.?|#)\s*(\d{1,6}[A-Za-z\-\/]?)/i); if(m2 && m2[1]) return m2[1];
    // 3) Buscar de atrás hacia adelante ignorando códigos postales o numeraciones idénticas
    const all = [...t.matchAll(/\b(\d{1,6}[A-Za-z\-\/]?)\b/g)];
    if(all.length){
      for(let i=all.length-1; i>=0; i--){
        const token = all[i][1];
        if(!token) continue;
        const digits = token.replace(/\D+/g,'');
        if(cp && digits && digits === String(cp).replace(/\D+/g,'')) continue;
        return token;
      }
    }
    return '';
  };
  const detectSn = (text)=>{
    if(!text) return '';
    const lower = String(text).toLowerCase();
    if(/\b(s\/?n|sin numero|sin número)\b/.test(lower)) return 'S/N';
    return '';
  };
  const calle = pick('street','block','subblock','road','calle','route');
  const cp = sanitizeCP(pick('postalCode','postcode','zip'));
  let numero = pick('houseNumber','house-number','house_number','housenumber','addr:housenumber','addr:house_number','streetNumber','number','numero');
  if(!numero){
    const label = (src && src.address && src.address.label) || a.label || '';
    numero = parseNumFromText(label, calle);
  }
  if(!numero){
    const title = (src && src.title) || (src && src.name) || '';
    numero = parseNumFromText(title, calle);
  }
  if(!numero){
    const display = (src && src.address && src.address.display_name) || (src && src.display_name) || '';
    numero = parseNumFromText(display, calle);
  }
  if(!numero){
    const sn = detectSn((src && src.address && src.address.label) || (src && src.title) || a.label || '');
    if(sn) numero = sn;
  }
  // Evitar confundir CP como número exterior
  if(numero && cp && String(numero).replace(/\D/g,'') === String(cp).replace(/\D/g,'')){
    numero = '';
  }
  const colonia = pick('district','subdistrict','neighborhood','neighbourhood','suburb','quarter','block','locality');
  const ciudad = pick('city','municipality','town','village','locality','county','place');
  const estado = pick('state','stateCode','region','province');
  let pais = pick('countryName','country','countryCode');
  if(pais && pais.length === 2) pais = pais.toUpperCase();
  return { calle, numero, colonia, ciudad, estado, pais, cp };
}

function resolvePlaceCoords(place, opts={}){
  let lat = Number.isFinite(opts.lat) ? Number(opts.lat) : null;
  let lng = Number.isFinite(opts.lng) ? Number(opts.lng) : null;
  const pickNumber = (val)=>{
    const num = Number(val);
    return Number.isFinite(num) ? num : null;
  };
  if(place){
    const directLat = pickNumber(place.lat ?? place.latitude);
    const directLng = pickNumber(place.lng ?? place.lon ?? place.longitude);
    if(!Number.isFinite(lat) && Number.isFinite(directLat)) lat = directLat;
    if(!Number.isFinite(lng) && Number.isFinite(directLng)) lng = directLng;
    const pos = place.position || place.pos || place.location || null;
    if(pos && typeof pos === 'object' && !Array.isArray(pos)){
      const latCand = pickNumber(pos.lat ?? pos.latitude);
      const lngCand = pickNumber(pos.lng ?? pos.lon ?? pos.longitude);
      if(!Number.isFinite(lat) && Number.isFinite(latCand)) lat = latCand;
      if(!Number.isFinite(lng) && Number.isFinite(lngCand)) lng = lngCand;
    }
    if(Array.isArray(pos) && pos.length >= 2){
      const lngCand = pickNumber(pos[0]);
      const latCand = pickNumber(pos[1]);
      if(!Number.isFinite(lat) && Number.isFinite(latCand)) lat = latCand;
      if(!Number.isFinite(lng) && Number.isFinite(lngCand)) lng = lngCand;
    }
    const geom = place.geometry || null;
    if(Array.isArray(geom) && geom.length >= 2){
      const lngCand = pickNumber(geom[0]);
      const latCand = pickNumber(geom[1]);
      if(!Number.isFinite(lat) && Number.isFinite(latCand)) lat = latCand;
      if(!Number.isFinite(lng) && Number.isFinite(lngCand)) lng = lngCand;
    } else if(geom && typeof geom === 'object' && Array.isArray(geom.coordinates) && geom.coordinates.length >= 2){
      const lngCand = pickNumber(geom.coordinates[0]);
      const latCand = pickNumber(geom.coordinates[1]);
      if(!Number.isFinite(lat) && Number.isFinite(latCand)) lat = latCand;
      if(!Number.isFinite(lng) && Number.isFinite(lngCand)) lng = lngCand;
    }
  }
  return {
    lat: Number.isFinite(lat) ? lat : null,
    lng: Number.isFinite(lng) ? lng : null
  };
}

function formatClienteAddrSearchDisplay(place){
  if(!place) return '';
  const address = place.address || {};
  const fields = extractAddressFields(address, place);
  const parts = [];
  if(fields.calle){
    const street = fields.numero ? `${fields.calle} ${fields.numero}` : fields.calle;
    parts.push(street.trim());
  } else if(place.title){
    parts.push(String(place.title).trim());
  }
  if(fields.colonia) parts.push(fields.colonia);
  const localityParts = [];
  if(fields.cp) localityParts.push(fields.cp);
  if(fields.ciudad) localityParts.push(fields.ciudad);
  if(localityParts.length) parts.push(localityParts.join(' '));
  if(fields.estado) parts.push(fields.estado);
  const pais = fields.pais || address.countryName || address.countryCode || '';
  if(pais){
    const normalizedPais = String(pais).trim().toLowerCase();
    if(normalizedPais !== 'méxico' && normalizedPais !== 'mexico'){
      parts.push(String(pais).trim());
    }
  }
  const display = parts.filter(Boolean).join(', ');
  const fallback = (address.label || place.title || '').trim();
  return display || fallback;
}

function composeClienteAddrSearchLabels(place, meta={}){
  const primary = formatClienteAddrSearchDisplay(place) || String(meta.query || '').trim();
  const coords = resolvePlaceCoords(place, {});
  const coordText = (Number.isFinite(coords.lat) && Number.isFinite(coords.lng)) ? `${coords.lat.toFixed(5)}, ${coords.lng.toFixed(5)}` : '';
  const sourceRaw = meta.source || place.__source || '';
  let badge = '';
  if(sourceRaw){
    const lower = String(sourceRaw).trim().toLowerCase();
    if(lower === 'maptiler') badge = 'MapTiler';
    else if(lower === 'nominatim') badge = 'OSM';
    else if(lower === 'photon') badge = 'Photon';
    else if(sourceRaw) badge = String(sourceRaw).trim();
  }
  const datalistParts = [primary];
  if(coordText) datalistParts.push(coordText);
  if(badge) datalistParts.push(badge);
  return {
    primary,
    secondary: coordText,
    badge,
    datalistLabel: datalistParts.filter(Boolean).join(' | ')
  };
}

function renderClienteAddrSearchResults(list){
  if(clienteAddrSearchList){
    clienteAddrSearchList.innerHTML = '';
    (list||[]).forEach(entry=>{
      if(!entry || !entry.value) return;
      const opt = document.createElement('option');
      opt.value = entry.value;
      opt.label = entry.label || entry.value;
      clienteAddrSearchList.appendChild(opt);
    });
  }
  if(clienteAddrSearchPanel){
    if(list && list.length){
      clienteAddrSearchPanel.innerHTML = '';
      list.forEach((entry, idx)=>{
        const row = document.createElement('div');
        row.dataset.index = String(idx);
        row.setAttribute('role','button');
        row.style.padding = '8px 12px';
        row.style.display = 'flex';
        row.style.flexDirection = 'column';
        row.style.gap = '2px';
        row.style.cursor = 'pointer';
        row.style.userSelect = 'none';
        row.style.background = '#ffffff';
        row.style.borderBottom = '1px solid #e2e8f0';
        row.style.fontSize = '0.75rem';
        row.style.lineHeight = '1.3';
        const primary = escapeHtml(entry.primary || entry.value || '');
        const secondaryParts = [];
        if(entry.secondary){ secondaryParts.push(`<span>${escapeHtml(entry.secondary)}</span>`); }
        if(entry.badge){ secondaryParts.push(`<span style="display:inline-block;padding:1px 6px;border-radius:999px;background:#e0f2fe;color:#0f172a;font-weight:600;">${escapeHtml(entry.badge)}</span>`); }
        const secondaryHtml = secondaryParts.length ? `<div style="display:flex;gap:6px;align-items:center;font-size:0.7rem;color:#475569;">${secondaryParts.join('')}</div>` : '';
        row.innerHTML = `<div style="font-size:0.78rem;font-weight:600;color:#0f172a;">${primary}</div>${secondaryHtml}`;
        if(idx === list.length-1){ row.style.borderBottom = 'none'; }
        clienteAddrSearchPanel.appendChild(row);
      });
      clienteAddrSearchPanel.style.display = 'block';
    } else {
      clienteAddrSearchPanel.innerHTML = '';
      clienteAddrSearchPanel.style.display = 'none';
    }
  }
  updateClienteAddrSearchPanelHighlight();
}

function showClienteAddrSearchPanelMessage(message){
  if(!clienteAddrSearchPanel) return;
  if(!message){
    clienteAddrSearchPanel.innerHTML = '';
    clienteAddrSearchPanel.style.display = 'none';
    return;
  }
  clienteAddrSearchPanel.innerHTML = `<div style="padding:10px 12px;font-size:0.74rem;color:#475569;">${escapeHtml(message)}</div>`;
  clienteAddrSearchPanel.style.display = 'block';
  clienteAddrSearchActiveIndex = -1;
  updateClienteAddrSearchPanelHighlight();
}

function updateClienteAddrSearchPanelHighlight(){
  if(!clienteAddrSearchPanel) return;
  const nodes = clienteAddrSearchPanel.querySelectorAll('[data-index]');
  nodes.forEach(node=>{
    const idx = Number(node.dataset.index||'-1');
    const active = idx === clienteAddrSearchActiveIndex;
    node.style.background = active ? '#dbeafe' : '#ffffff';
    node.style.boxShadow = active ? 'inset 0 0 0 1px rgba(59,130,246,0.45)' : 'none';
  });
}

function setClienteAddrSearchActive(index, opts={}){
  const list = Array.isArray(clienteAddrSearchResults) ? clienteAddrSearchResults : [];
  if(!list.length){
    clienteAddrSearchActiveIndex = -1;
    updateClienteAddrSearchPanelHighlight();
    return;
  }
  const max = list.length - 1;
  let next = index;
  if(next > max){ next = opts.wrap ? 0 : max; }
  if(next < -1){ next = -1; }
  clienteAddrSearchActiveIndex = next;
  updateClienteAddrSearchPanelHighlight();
  if(clienteAddrSearchPanel && next >= 0 && opts.scrollIntoView !== false){
    const node = clienteAddrSearchPanel.querySelector(`[data-index="${next}"]`);
    if(node && typeof node.scrollIntoView === 'function'){
      try{ node.scrollIntoView({ block:'nearest', inline:'nearest' }); }catch(_e){}
    }
  }
  if(!clienteAddrSearchInput) return;
  if(next >= 0){
    const entry = list[next];
    if(entry && entry.value && opts.preview !== false){
      clienteAddrSearchSuppressChange = true;
      clienteAddrSearchInput.value = entry.value;
      clienteAddrSearchSuppressChange = false;
    }
  } else if(opts.restoreDraft !== false){
    clienteAddrSearchSuppressChange = true;
    clienteAddrSearchInput.value = clienteAddrSearchDraftValue || '';
    clienteAddrSearchSuppressChange = false;
  }
}

function resetClienteAddrSearchUI(opts={}){
  const keepQuery = !!opts.keepQuery;
  const keepLast = !!opts.keepLast;
  const cancelPending = !!opts.cancelPending;
  if(cancelPending) clienteAddrSearchToken++;
  if(clienteAddrSearchList) clienteAddrSearchList.innerHTML = '';
  clienteAddrSearchResults = [];
  if(clienteAddrSearchDebounceId){
    clearTimeout(clienteAddrSearchDebounceId);
    clienteAddrSearchDebounceId = null;
  }
  if(clienteAddrSearchPanel){
    clienteAddrSearchPanel.innerHTML = '';
    clienteAddrSearchPanel.style.display = 'none';
  }
  clienteAddrSearchActiveIndex = -1;
  if(keepQuery){
    clienteAddrSearchDraftValue = clienteAddrSearchInput ? (clienteAddrSearchInput.value||'') : '';
  } else {
    clienteAddrSearchDraftValue = '';
  }
  if(!keepQuery && clienteAddrSearchInput){
    clienteAddrSearchSuppressChange = true;
    clienteAddrSearchInput.value = '';
    clienteAddrSearchSuppressChange = false;
  }
  if(!keepLast) clienteAddrSearchLastResult = null;
  updateClienteAddrSearchPanelHighlight();
}

function setClienteAddrSearchLoading(isLoading){
  clienteAddrSearchLoading = !!isLoading;
  if(clienteAddrSearchBtn){
    clienteAddrSearchBtn.disabled = !!isLoading;
    clienteAddrSearchBtn.textContent = isLoading ? 'Buscando...' : 'Buscar';
  }
  if(clienteAddrSearchInput){
    if(isLoading) clienteAddrSearchInput.setAttribute('aria-busy','true');
    else clienteAddrSearchInput.removeAttribute('aria-busy');
  }
  if(clienteAddrSearchPanel){
    if(isLoading){
      showClienteAddrSearchPanelMessage('Buscando coincidencias…');
    }
  }
}

function getClienteAddrSearchResultByValue(value){
  if(!value) return null;
  const target = String(value).trim().toLowerCase();
  if(!target) return null;
  return clienteAddrSearchResults.find(entry=>{
    const val = entry && entry.value ? String(entry.value).trim().toLowerCase() : '';
    return val === target;
  }) || null;
}

function handleClienteAddrSearchApply(entry, opts={}){
  if(!entry || !entry.place) return false;
  const applied = applyClientePlaceResult(entry.place, opts);
  if(!applied) return false;
  const text = entry.value || entry.label || (clienteAddrSearchInput ? clienteAddrSearchInput.value : '');
  if(clienteAddrSearchInput){
    clienteAddrSearchSuppressChange = true;
    clienteAddrSearchInput.value = text || '';
    clienteAddrSearchSuppressChange = false;
  }
  clienteAddrSearchDraftValue = text || entry.value || '';
  clienteAddrSearchActiveIndex = -1;
  clienteAddrSearchLastResult = entry;
  resetClienteAddrSearchUI({ keepQuery:true, keepLast:true });
  setClienteAddrSearchLoading(false);
  return true;
}

async function performClienteAddrSearch(query, opts={}){
  const qRaw = query != null ? String(query) : '';
  const q = qRaw.trim();
  const { force=false, limit=6, applyFirst=false, notifyOnEmpty=false } = opts;
  if(!q){
    resetClienteAddrSearchUI({ cancelPending:true });
    setClienteAddrSearchLoading(false);
    return [];
  }
  if(!force && q.length < CLIENTE_ADDR_SEARCH_MIN_LEN){
    return [];
  }
  const services = getGeoServicesPriority('geocode');
  if(!services.length){
    if(notifyOnEmpty && typeof notify === 'function'){
      notify('No hay servicios de geocodificación disponibles', 'err');
    }
    return [];
  }
  const token = ++clienteAddrSearchToken;
  setClienteAddrSearchLoading(true);
  const limitNum = Math.max(1, limit|0);
  const countryHint = getClienteAddrCountryHint();
  const proximityHint = getClienteAddrProximityHint();
  const multipleServices = services.length > 1;
  const structuredHint = parseAddressQueryForStructuredSearch(q);
  const aggregated = [];
  const seen = new Set();
  try{
    for(const svc of services){
      const remainingSlots = Math.max(0, limitNum - aggregated.length);
      if(remainingSlots <= 0) break;
      const kindRaw = svc && (svc.__kind || svc.kind || '');
      const svcKind = String(kindRaw).toLowerCase();
      let svcQuota = remainingSlots;
      if(multipleServices && svcKind === 'maptiler'){
        svcQuota = Math.min(remainingSlots, Math.max(2, Math.ceil(limitNum / 2)));
      }
      if(svcQuota <= 0) continue;
      const svcLimit = Math.max(limitNum, svcQuota * 3);
      const params = { q, lang: 'es-MX', limit: svcLimit };
      if(countryHint){
        if(svcKind === 'maptiler') params.country = countryHint;
        else if(svcKind === 'nominatim') params.countrycodes = countryHint;
        else if(svcKind === 'photon') params.country = countryHint;
      }
      if(proximityHint){
        if(svcKind === 'maptiler') params.proximity = proximityHint;
        else if(svcKind === 'nominatim'){
          params.viewbox = buildViewboxAroundCoords(proximityHint.lat, proximityHint.lng, 18);
          params.bounded = true;
        } else if(svcKind === 'photon'){
          params.lat = proximityHint.lat;
          params.lon = proximityHint.lng;
        }
      }
      if(svcKind === 'maptiler' && structuredHint && (structuredHint.street || structuredHint.houseNumber)){
  const qqSegments = [];
  const structuredHouse = structuredHint.houseNumber && String(structuredHint.houseNumber).toUpperCase() === 'S/N' ? '' : structuredHint.houseNumber;
  if(structuredHouse) qqSegments.push(`houseNumber=${encodeURIComponent(structuredHouse)}`);
        if(structuredHint.street) qqSegments.push(`street=${encodeURIComponent(structuredHint.street)}`);
        if(structuredHint.district) qqSegments.push(`district=${encodeURIComponent(structuredHint.district)}`);
        if(structuredHint.postalCode) qqSegments.push(`postalCode=${encodeURIComponent(structuredHint.postalCode)}`);
        if(structuredHint.city) qqSegments.push(`city=${encodeURIComponent(structuredHint.city)}`);
        if(structuredHint.state) qqSegments.push(`state=${encodeURIComponent(structuredHint.state)}`);
        const structuredCountry = structuredHint.country ? normalizeCountryCodeInput(structuredHint.country) : '';
        const maptilerCountry = structuredCountry || countryHint;
        if(maptilerCountry) qqSegments.push(`country=${encodeURIComponent(maptilerCountry.toUpperCase())}`);
        if(qqSegments.length >= 2){
          params.qq = qqSegments.join(';');
          if(!params.country && maptilerCountry) params.country = maptilerCountry;
        }
      }
      const items = await new Promise(resolve=>{
        try{
          svc.geocode(params, res=> resolve((res && res.items) || []), ()=> resolve([]));
        }catch(err){
          console.warn('[geo] geocode failed', err);
          resolve([]);
        }
      });
      let accepted = 0;
      for(const item of items){
        if(!item) continue;
        const coords = resolvePlaceCoords(item, {});
        const key = [
          Number.isFinite(coords.lat) ? coords.lat.toFixed(6) : '',
          Number.isFinite(coords.lng) ? coords.lng.toFixed(6) : '',
          item.address && item.address.label ? item.address.label : (item.title || '')
        ].join('|');
        if(seen.has(key)) continue;
        seen.add(key);
        const labels = composeClienteAddrSearchLabels(item, { source: svc.__kind || svc.kind || '', query: q });
        const primaryText = (labels.primary || '').trim();
        const normalizeFold = (val)=>{
          if(!val) return '';
          let out = String(val).toLowerCase();
          try{ out = out.normalize('NFD').replace(/[\u0300-\u036f]/g,''); }catch(_e){}
          return out;
        };
        const normalizedPrimary = normalizeFold(primaryText);
        const address = item.address || {};
        const hasStreet = !!(address.street || address.road || address.houseNumber || address.housenumber);
        const hasLocality = !!(address.city || address.town || address.village || address.postalCode || address.district);
        const countryNameRaw = (address.countryName || address.country || address.countryCode || '').toString().trim();
        const countryName = normalizeFold(countryNameRaw);
        const isCountryOnly = !hasStreet && !hasLocality && primaryText && (primaryText.length <= 3 || (normalizedPrimary && normalizedPrimary === countryName));
        if(svcKind === 'maptiler' && isCountryOnly) continue;
        const entry = {
          place: item,
          value: labels.primary || q,
          label: labels.datalistLabel,
          primary: labels.primary || q,
          secondary: labels.secondary || '',
          badge: labels.badge || '',
          source: svc.__kind || svc.kind || ''
        };
        aggregated.push(entry);
        accepted++;
        if(accepted >= svcQuota) break;
        if(aggregated.length >= limitNum) break;
      }
      if(aggregated.length >= limitNum) break;
    }
    if(clienteAddrSearchToken !== token){
      return [];
    }
    clienteAddrSearchResults = aggregated;
    clienteAddrSearchActiveIndex = -1;
    renderClienteAddrSearchResults(aggregated);
    if(!aggregated.length){
      const msgBase = clienteAddrSearchInput ? (clienteAddrSearchInput.value||'').trim() : q;
      if(msgBase) showClienteAddrSearchPanelMessage(`Sin coincidencias para “${msgBase}”.`);
    }
    if(!aggregated.length && notifyOnEmpty && typeof notify === 'function'){
      notify('No se encontraron ubicaciones para esa búsqueda', 'warn');
    }
    if(applyFirst && aggregated.length){
      handleClienteAddrSearchApply(aggregated[0], { reason:'auto' });
    }
    return aggregated;
  } finally {
    if(clienteAddrSearchToken === token){
      setClienteAddrSearchLoading(false);
    }
  }
}

function handleClienteAddrSearchInput(){
  if(!clienteAddrSearchInput || clienteAddrSearchSuppressChange) return;
  const value = (clienteAddrSearchInput.value || '').trim();
  clienteAddrSearchDraftValue = value;
  clienteAddrSearchActiveIndex = -1;
  if(clienteAddrSearchDebounceId){
    clearTimeout(clienteAddrSearchDebounceId);
    clienteAddrSearchDebounceId = null;
  }
  if(!value){
    resetClienteAddrSearchUI({ cancelPending:true });
    setClienteAddrSearchLoading(false);
    return;
  }
  if(value.length < CLIENTE_ADDR_SEARCH_MIN_LEN){
    resetClienteAddrSearchUI({ keepQuery:true, cancelPending:true, keepLast:true });
  showClienteAddrSearchPanelMessage(`Escribe al menos ${CLIENTE_ADDR_SEARCH_MIN_LEN} caracteres para buscar.`);
    return;
  }
  clienteAddrSearchDebounceId = setTimeout(()=>{
    performClienteAddrSearch(value, { limit: 8 });
  }, value.length >= 8 ? 200 : 350);
}

function handleClienteAddrSearchChange(){
  if(!clienteAddrSearchInput || clienteAddrSearchSuppressChange) return;
  const value = (clienteAddrSearchInput.value || '').trim();
  clienteAddrSearchDraftValue = value;
  clienteAddrSearchActiveIndex = -1;
  if(!value){
    resetClienteAddrSearchUI({ cancelPending:true });
    setClienteAddrSearchLoading(false);
    return;
  }
  const entry = getClienteAddrSearchResultByValue(value);
  if(entry){
    handleClienteAddrSearchApply(entry, { reason:'change' });
    return;
  }
  performClienteAddrSearch(value, { force:true, applyFirst:true });
}

async function handleClienteAddrSearchSubmit(opts={}){
  if(!clienteAddrSearchInput) return;
  if(clienteAddrSearchDebounceId){
    clearTimeout(clienteAddrSearchDebounceId);
    clienteAddrSearchDebounceId = null;
  }
  const value = (clienteAddrSearchInput.value || '').trim();
  clienteAddrSearchDraftValue = value;
  clienteAddrSearchActiveIndex = -1;
  if(!value){
    if(typeof notify === 'function') notify('Escribe una dirección para buscar', 'warn');
    return;
  }
  if(value.length < CLIENTE_ADDR_SEARCH_MIN_LEN){
  showClienteAddrSearchPanelMessage(`Escribe al menos ${CLIENTE_ADDR_SEARCH_MIN_LEN} caracteres para buscar.`);
    return;
  }
  const entry = getClienteAddrSearchResultByValue(value);
  if(entry){
    handleClienteAddrSearchApply(entry, { reason:'submit-match' });
    return;
  }
  await performClienteAddrSearch(value, { force:true, applyFirst:true, notifyOnEmpty:true });
}

function applyClientePlaceResult(place, opts={}){
  if(!place) return false;
  const { setMarker=true, markDirty=true } = opts;
  const coords = resolvePlaceCoords(place, opts);
  const lat = Number.isFinite(coords.lat) ? Number(coords.lat) : null;
  const lng = Number.isFinite(coords.lng) ? Number(coords.lng) : null;
  if(Number.isFinite(lat) && Number.isFinite(lng)){
    if(setMarker){
      try{ setMapMarker(lat, lng); }catch(_e){}
      try{ renderAllSlotMarkers(); }catch(_e){}
    }
    if(clienteCoordsInput) clienteCoordsInput.value = `${(+lat).toFixed(6)}, ${(+lng).toFixed(6)}`;
    try{ ensureSlotLabel(getActiveSlot(), lat, lng); }catch(_e){}
  }
  if(place.address){
    const f = extractAddressFields(place.address, place);
    if(clienteCalleInput && f.calle) clienteCalleInput.value = f.calle;
    if(clienteNumeroInput && f.numero) clienteNumeroInput.value = f.numero;
    if(clienteColoniaInput && f.colonia) clienteColoniaInput.value = f.colonia;
    if(clienteCPInput && f.cp) clienteCPInput.value = f.cp;
    if(clienteCiudadInput && f.ciudad) clienteCiudadInput.value = f.ciudad;
    if(clienteEstadoInput && f.estado) clienteEstadoInput.value = f.estado;
    if(clientePaisInput){
      const nextPais = f.pais || clientePaisInput.value || 'México';
      clientePaisInput.value = nextPais;
    }
  }
  try{
    saveActiveSlotFields();
    if(markDirty && getActiveSlot && getActiveSlot()==='puntoMedio') clientePuntoMedioDirty = true;
  }catch(_e){}
  return true;
}

async function applyClienteGeocodeResult(lat, lng, fallbackPlace=null, opts={}){
  const attempts = Number.isFinite(opts.attempts) ? opts.attempts : 3;
  const delayMs = Number.isFinite(opts.delayMs) ? opts.delayMs : 250;
  let place = await reverseGeocodeHere(lat, lng, { attempts, delayMs });
  if(!place) place = fallbackPlace;
  if(!place){
    place = { position: { lat, lng }, address: {} };
  }
  return applyClientePlaceResult(place, { ...opts, lat, lng });
}
async function geocodeHereFromFields({ force=false }={}){
  // Lee campos manuales y posiciona el marcador mediante geocodificación directa
  if(!clienteCalleInput || !clienteCiudadInput || !clienteCPInput) return;
  const calle = (clienteCalleInput.value||'').trim();
  const numero = (clienteNumeroInput && clienteNumeroInput.value||'').trim();
  const colonia = (clienteColoniaInput && clienteColoniaInput.value||'').trim();
  const cp = (clienteCPInput && clienteCPInput.value||'').trim();
  const ciudad = (clienteCiudadInput && clienteCiudadInput.value||'').trim();
  const estado = (clienteEstadoInput && clienteEstadoInput.value||'').trim();
  const pais = (clientePaisInput && clientePaisInput.value||'').trim() || 'México';
  // Reglas mínimas para evitar geocodificar con datos insuficientes, salvo que sea forzado
  const hasStreet = !!calle;
  const hasLocality = !!ciudad || !!cp;
  if(!(force || (hasStreet && hasLocality))) return;
  await ensureHereLoaded();
  await initHere();
  const services = getGeoServicesPriority('geocode');
  if(!services.length) return false;
  // Construir consulta estructurada (qq) preferentemente
  const segments = [];
  if(numero) segments.push(`houseNumber=${encodeURIComponent(numero)}`);
  if(calle) segments.push(`street=${encodeURIComponent(calle)}`);
  if(colonia) segments.push(`district=${encodeURIComponent(colonia)}`);
  if(ciudad) segments.push(`city=${encodeURIComponent(ciudad)}`);
  if(estado) segments.push(`state=${encodeURIComponent(estado)}`);
  if(cp) segments.push(`postalCode=${encodeURIComponent(cp)}`);
  if(pais) segments.push(`country=${encodeURIComponent(pais)}`);
  const params = { lang: 'es-MX', limit: 1 };
  if(segments.length){ params.qq = segments.join(';'); }
  else {
    const q = [ (calle && numero) ? `${calle} ${numero}` : calle, colonia, cp, ciudad, estado, pais ].filter(Boolean).join(', ');
    if(!q) return; params.q = q;
  }
  for(let idx=0; idx<services.length; idx++){
    const svc = services[idx];
    const ok = await new Promise((resolve)=>{
      svc.geocode(params, async (result)=>{
        const it = result && result.items && result.items[0];
        if(it && it.position){
          hereService = svc;
          const { lat, lng } = it.position;
          setMapMarker(lat, lng);
          renderAllSlotMarkers();
          if(clienteCoordsInput) clienteCoordsInput.value = `${(+lat).toFixed(6)}, ${(+lng).toFixed(6)}`;
          let place = await reverseGeocodeHere(lat, lng, { attempts: 3 });
          if(place && place.address){
            const f = extractAddressFields(place.address, place);
            if(clienteCalleInput && f.calle) clienteCalleInput.value = f.calle;
            if(clienteNumeroInput && f.numero) clienteNumeroInput.value = f.numero;
            if(clienteColoniaInput && f.colonia) clienteColoniaInput.value = f.colonia;
            if(clienteCPInput && f.cp) clienteCPInput.value = f.cp;
            if(clienteCiudadInput && f.ciudad) clienteCiudadInput.value = f.ciudad;
            if(clienteEstadoInput && f.estado) clienteEstadoInput.value = f.estado;
            if(clientePaisInput){
              const nextPais = f.pais || clientePaisInput.value || 'México';
              clientePaisInput.value = nextPais;
            }
          }
          try{ saveActiveSlotFields(); }catch(_e){}
          try{ ensureSlotLabel(getActiveSlot(), lat, lng); }catch(_e){}
          resolve(true);
        } else {
          resolve(false);
        }
      }, ()=> resolve(false));
    });
    if(ok) return true;
    if(idx === 0) await delay(150);
  }
  return false;
}
function parseCoords(text){
  if(!text) return null;
  const m = text.split(',').map(s=>s.trim());
  if(m.length!==2) return null;
  const lat = parseFloat(m[0]); const lng = parseFloat(m[1]);
  if(Number.isFinite(lat) && Number.isFinite(lng)) return { lat, lng };
  return null;
}

function getClienteAddrProximityHint(){
  try{
    if(clienteCoordsInput && clienteCoordsInput.value){
      const parsed = parseCoords(clienteCoordsInput.value);
      if(parsed && Number.isFinite(parsed.lat) && Number.isFinite(parsed.lng)) return parsed;
    }
    const slot = typeof getActiveSlot === 'function' ? getActiveSlot() : 'casa';
    const marker = (hereMarkers && hereMarkers[slot]) || hereMarker;
    if(marker && typeof marker.getLngLat === 'function'){
      const ll = marker.getLngLat();
      if(ll && Number.isFinite(ll.lat) && Number.isFinite(ll.lng)) return { lat: ll.lat, lng: ll.lng };
    }
  }catch(_e){}
  return null;
}

function adjustGlobalLoading(delta){
  globalLoadingCounter += delta;
  if(globalLoadingCounter < 0) globalLoadingCounter = 0;
  const loader = document.getElementById('globalLoadingIndicator');
  if(loader){
    if(globalLoadingCounter > 0){
      loader.style.display = 'flex';
    } else {
      loader.style.display = 'none';
    }
  }
}

async function handleCoordsChange(){

  const btn = document.getElementById('clienteCoordsApplyBtn');
  const setLoading = (v)=>{ if(btn){ btn.disabled = v; /* mantener el texto sin cambios */ } };
  try{
    const coords = parseCoords(clienteCoordsInput && clienteCoordsInput.value && clienteCoordsInput.value.trim());
    if(!coords){ notify('Coordenadas inválidas. Formato: lat, lng','warn'); return; }
    setLoading(true);
    await ensureHereLoaded();
    await initHere();
    const service = ensureGeoService();
    if(!hereMap || !service){
      notify('El servicio de geocodificación no está disponible. Revisa la conexión e inténtalo de nuevo.','err');
      return;
    }
    hereService = service;
    setMapMarker(coords.lat, coords.lng);
    renderAllSlotMarkers();
    if(clienteCoordsInput) clienteCoordsInput.value = `${(+coords.lat).toFixed(6)}, ${(+coords.lng).toFixed(6)}`;
    let place = await reverseGeocodeHere(coords.lat, coords.lng, { attempts: 3 });
    if(!place){
      const fallback = ensureNominatimService();
      if(fallback && fallback !== service){
        hereService = fallback;
        place = await new Promise((resolve)=>{
          fallback.reverseGeocode({ at: `${coords.lat},${coords.lng}`, lang: 'es-MX' }, (result)=>{
            const item = result && result.items && result.items[0];
            resolve(item||null);
          }, ()=> resolve(null));
        });
      }
    }
    if(place && place.address){
      const f = extractAddressFields(place.address, place);
      if(clienteCalleInput && f.calle) clienteCalleInput.value = f.calle;
      if(clienteNumeroInput && f.numero) clienteNumeroInput.value = f.numero;
      if(clienteColoniaInput && f.colonia) clienteColoniaInput.value = f.colonia;
      if(clienteCPInput && f.cp) clienteCPInput.value = f.cp;
      if(clienteCiudadInput && f.ciudad) clienteCiudadInput.value = f.ciudad;
      if(clienteEstadoInput && f.estado) clienteEstadoInput.value = f.estado;
      if(clientePaisInput){
        const nextPais = f.pais || clientePaisInput.value || 'México';
        clientePaisInput.value = nextPais;
      }
    }
  // Persistir cambios en slot activo
  try{
    const currentSlot = getActiveSlot && getActiveSlot();
    saveActiveSlotFields();
    if(currentSlot === 'puntoMedio'){
      clientePuntoMedioDirty = true;
    }
  }catch(_e){}
  try{ ensureSlotLabel(getActiveSlot(), coords.lat, coords.lng); }catch(_e){}
  } catch(err){
    console.error('Coords apply error', err);
    notify('Error aplicando coordenadas','err');
  } finally {
    setLoading(false);
  }
}
