// Al seleccionar responsable, autocompletar teléfono y correo si existen en el usuario
function onSucursalResponsableChange(){
  try{
    const id = sucursalResponsableInput && sucursalResponsableInput.value;
    const users = Array.isArray(window.usuarios)? window.usuarios : [];
    const u = users.find(x=> String(x.id||x.uid)===String(id));
    if(!u){ return; }
    if(sucursalTelefonoInput && !sucursalTelefonoInput.value){
      const telCandidate = composeTelefonoValue(
        u.telefonoE164 || u.telefonoCompleto || u.telefono || u.phone || u.celular || '',
        u.telefonoPais || '',
        u.telefonoE164 || u.telefonoCompleto || ''
      );
      if(telCandidate) sucursalTelefonoInput.value = telCandidate;
    }
    if(sucursalEmailInput && !sucursalEmailInput.value){
      const mail = u.correo || u.email || '';
      if(mail) sucursalEmailInput.value = mail;
    }
  }catch(_e){}
}
