function generateSucursalId(){ return null; }

// Normaliza diferentes formatos de coordenadas a un string "lat, lng"
function coordsToString(v){
  try{
    if(!v) return '';
    if(typeof v==='string') return v;
    if(typeof v==='object' && Number.isFinite(v.lat) && Number.isFinite(v.lng)){
      return `${(+v.lat).toFixed(6)}, ${(+v.lng).toFixed(6)}`;
    }
  }catch(_e){}
  return '';
}

function renderSucursalesTable(){
  if(!sucursalesBody) return;
  sucursalesBody.innerHTML='';
  const q = (searchSucursalesInput?searchSucursalesInput.value.trim().toLowerCase():'');
  const list = Array.isArray(sucursales)? sucursales : [];
  let total = 0;
  const showInact = !!showInactSucursalesChk?.checked;
  list.filter(s=>{
    // Hide inhabilitadas (estatus !== 'Activa') unless toggle is on
    const isActive = String(s.estatus||'Activa').toLowerCase()==='activa';
    if(!showInact && !isActive) return false;
    if(!q) return true;
    try{
      const hay = [s.codigo, s.nombre, s.alias, s.responsable, s.telefono, s.telefonoPais, s.telefonoE164, s.telefonoCompleto, s.email, s.ciudad, s.estado, s.cp, s.calle, s.numero, s.colonia, s.horario, s.estatus, s.notas]
        .map(v=>String(v||'').toLowerCase()).join(' ');
      return hay.includes(q);
    }catch(_e){ return true; }
  }).forEach(s=>{
    const tr = document.createElement('tr');
  // Mostrar código 8+ dígitos; fallback a id para no dejar vacío
  const codigo = s.codigo ? String(s.codigo).padStart(8,'0') : (s.id||'');
    const telefonoCombinado = composeTelefonoValue(s.telefono||'', s.telefonoPais||s.telPais||'', s.telefonoE164||s.telefonoCompleto||'');
    const telefonoMostrar = formatDisplayPhone(telefonoCombinado) || telefonoCombinado || (s.telefono||'');
    tr.innerHTML = `
      <td>${codigo}</td>
      <td>${s.nombre||''}</td>
      <td>${s.alias||''}</td>
      <td>${s.responsable||''}</td>
      <td>${telefonoMostrar||''}</td>
      <td>${s.email||''}</td>
      <td>${s.ciudad||''}</td>
      <td>${s.estado||''}</td>
      <td>${s.cp||''}</td>
      <td>${s.calle||''}</td>
      <td>${s.numero||''}</td>
      <td>${s.colonia||''}</td>
      <td>${s.horario||''}</td>
      <td>${(String(s.estatus||'Activa').toLowerCase()==='activa'
        ? '<span style="padding:2px 8px;border-radius:999px;font-size:0.7rem;font-weight:700;color:#065f46;background:#d1fae5;border:1px solid #a7f3d0;">SI</span>'
        : '<span style="padding:2px 8px;border-radius:999px;font-size:0.7rem;font-weight:700;color:#991b1b;background:#fee2e2;border:1px solid #fecaca;">NO</span>'
      )}</td>
      <td>${s.notas||''}</td>
      <td>
  <button type="button" class="mini-btn" data-action="edit" data-id="${s.id}">✏️</button>
  <button type="button" class="mini-btn" data-action="mapa" data-id="${s.id}">🗺️</button>
      </td>
    `;
    sucursalesBody.appendChild(tr);
    total++;
  });
  if(sucursalesTotalCount) sucursalesTotalCount.textContent = String(total);
}

function openSucursalModal(editId=null){
  if(!sucursalOverlay) return;
  if(editId){
    const s = sucursales.find(x=>x.id===editId); if(!s) return;
    sucursalModalTitle.textContent='Editar sucursal';
    sucursalSubmitBtn.textContent='Actualizar';
    sucursalEditingIdInput.value=s.id;
    sucursalNombreInput.value=s.nombre||'';
    sucursalAliasInput.value=s.alias||'';
    // Responsable puede guardarse como id o nombre; si s.responsableId existe, usarlo; si no, intentar mapear por nombre
    if(s.responsableId){ sucursalResponsableInput.value = s.responsableId; onSucursalResponsableChange(); }
    else if(s.responsable){
      const match = (Array.isArray(window.usuarios)?window.usuarios:[]).find(u=> (u.nombre||u.displayName||u.email||'')===s.responsable);
      if(match){ sucursalResponsableInput.value = String(match.id||match.uid); onSucursalResponsableChange(); }
      else sucursalResponsableInput.value = '';
    } else { sucursalResponsableInput.value=''; }
    // Split stored phone like '+52 9514138990' or '529514138990'
    (function(){
      if(!sucursalTelefonoInput) return;
      const telPrefill = composeTelefonoValue(
        s.telefono || '',
        s.telefonoPais || s.telPais || '',
        s.telefonoE164 || s.telefonoCompleto || ''
      );
      sucursalTelefonoInput.value = telPrefill;
    })();
    sucursalEmailInput.value=s.email||'';
    sucursalCiudadInput.value=s.ciudad||'';
    sucursalEstadoInput.value=s.estado||'';
    sucursalCPInput.value=s.cp||'';
    sucursalCalleInput.value=s.calle||'';
    sucursalNumeroInput.value=s.numero||'';
    sucursalColoniaInput.value=s.colonia||'';
    // Horario: prefer structured UI; fallback to default if missing
    if(sucHorarioWrap){
      if(s.horarioStruct && typeof s.horarioStruct==='object'){
        applyHorarioStruct(s.horarioStruct);
      } else {
        // default best-effort
        applyHorarioStruct({ lun:{de:'09:00',a:'18:00'}, mar:{de:'09:00',a:'18:00'}, mie:{de:'09:00',a:'18:00'}, jue:{de:'09:00',a:'18:00'}, vie:{de:'09:00',a:'18:00'}, sab:{de:'09:00',a:'14:00'}, dom:{cerrado:true} });
      }
      if(sucHorarioMismoChk){ sucHorarioMismoChk.checked = true; applySameForAll(); }
    }
    sucursalEstatusInput.value=s.estatus||'Activa';
    sucursalNotasInput.value=s.notas||'';
  // coords
  if(sucursalCoordsInput) sucursalCoordsInput.value = coordsToString(s && s.coords);
  setTimeout(()=>{ try{ initSucursalMap(coordsToString(s && s.coords)); }catch(_e){} }, 50);
  } else {
    sucursalModalTitle.textContent='Nueva sucursal';
    sucursalSubmitBtn.textContent='Guardar';
    sucursalEditingIdInput.value='';
  [sucursalNombreInput,sucursalAliasInput,sucursalResponsableInput,sucursalTelefonoInput,sucursalEmailInput,sucursalCiudadInput,sucursalEstadoInput,sucursalCPInput,sucursalCalleInput,sucursalNumeroInput,sucursalColoniaInput,sucursalHorarioInput,sucursalNotasInput].forEach(i=>{ if(i) i.value=''; });
  // Reset horario UI to defaults: Lun-Vie 09-18, Sab 09-14, Dom cerrado
  if(sucHorarioWrap){ applyHorarioStruct({ lun:{de:'09:00',a:'18:00'}, mar:{de:'09:00',a:'18:00'}, mie:{de:'09:00',a:'18:00'}, jue:{de:'09:00',a:'18:00'}, vie:{de:'09:00',a:'18:00'}, sab:{de:'09:00',a:'14:00'}, dom:{cerrado:true} }); if(sucHorarioMismoChk){ sucHorarioMismoChk.checked = true; applySameForAll(); } }
  if(sucursalTelefonoInput) sucursalTelefonoInput.placeholder = '+529514138990';
    sucursalEstatusInput.value='Activa';
  if(sucursalCoordsInput) sucursalCoordsInput.value='';
  setTimeout(()=>{ try{ initSucursalMap(null); }catch(_e){} }, 50);
  }
  sucursalOverlay.classList.remove('hidden');
  setTimeout(()=>{ if(sucursalNombreInput) sucursalNombreInput.focus(); },50);
}
function closeSucursalModal(){
  if(sucursalOverlay) sucursalOverlay.classList.add('hidden');
  try{ if(sucursalMap && typeof sucursalMap.remove === 'function') sucursalMap.remove(); }catch(_e){}
  sucursalMap = null; sucursalMarker = null; sucursalLabelMarker = null;
}

function handleSucursalSubmit(e){
  e.preventDefault();
  const nombre = sucursalNombreInput.value.trim();
  if(!nombre){ notify('El nombre es obligatorio','warn'); return; }
  // Normalizar coordenadas antes de guardar
  const coordsRaw = (sucursalCoordsInput && sucursalCoordsInput.value && sucursalCoordsInput.value.trim()) || '';
  const parsedCoords = parseCoords(coordsRaw);
  const coordsStr = parsedCoords ? `${(+parsedCoords.lat).toFixed(6)}, ${(+parsedCoords.lng).toFixed(6)}` : '';
  const telefonoRaw = (sucursalTelefonoInput?.value||'').trim();
  const telefonoNormalized = telefonoRaw ? normalizePhone(telefonoRaw) : '';
  if(telefonoRaw && (!telefonoNormalized || !/^\+[0-9]{8,15}$/.test(telefonoNormalized))){
    notify('Teléfono de sucursal: usa formato internacional (+código país y dígitos).','warn');
    return;
  }
  const telefonoPersist = buildTelefonoPersistence(telefonoNormalized);
  const payload = {
    nombre,
    alias: sucursalAliasInput.value.trim(),
    // guardar id y nombre del responsable
    responsableId: sucursalResponsableInput.value || '',
    responsable: (function(){
      const id = sucursalResponsableInput.value || '';
      if(!id) return '';
      const u = (Array.isArray(window.usuarios)?window.usuarios:[]).find(x=> String(x.id||x.uid)===String(id));
      return (u&&(u.nombre||u.displayName||u.email||id)) || id;
    })(),
  telefono: telefonoPersist.telefono,
  telefonoPais: telefonoPersist.telefonoPais,
  telefonoE164: telefonoPersist.telefonoE164,
  telefonoCompleto: telefonoPersist.telefonoCompleto,
    email: sucursalEmailInput.value.trim(),
    ciudad: sucursalCiudadInput.value.trim(),
    estado: sucursalEstadoInput.value.trim(),
    cp: sucursalCPInput.value.trim(),
    calle: sucursalCalleInput.value.trim(),
    numero: sucursalNumeroInput.value.trim(),
  colonia: sucursalColoniaInput.value.trim(),
  // horario resumen + struct (compat)
  horario: (function(){ try{ return sucHorarioWrap ? horarioResumen(readHorarioStruct()) : (sucursalHorarioInput?.value||'').trim(); }catch(_){ return (sucursalHorarioInput?.value||'').trim(); } })(),
  horarioStruct: (function(){ try{ return sucHorarioWrap ? readHorarioStruct() : null; }catch(_){ return null; } })(),
    estatus: sucursalEstatusInput.value,
  notas: sucursalNotasInput.value.trim(),
  coords: coordsStr
  };
  const editingId = sucursalEditingIdInput.value ? sucursalEditingIdInput.value : null;
  (async ()=>{
    try {
      if(!window.firebaseBranchesApi){ notify('API sucursales no lista','err'); return; }
      if(editingId){
        await window.firebaseBranchesApi.updateSucursal(editingId, payload);
        notify('Sucursal actualizada','ok');
      } else {
        await window.firebaseBranchesApi.createSucursal(payload);
        notify('Sucursal agregada','ok');
      }
      closeSucursalModal();
    } catch(err){ console.error('guardar sucursal', err); notify('Error guardando','err'); }
  })();
}

// --- Sucursal Map helpers (MapLibre) ---
async function initSucursalMap(initialCoords){
  try{
    if(!sucursalMapaEl) return;
    await ensureHereLoaded();
  let styleSource = resolveBasemapStyle() || OSM_RASTER_STYLE;
    if(!hereOsmNoticeShown){
      hereOsmNoticeShown = true;
      try{ notify('Mapas de OpenStreetMap habilitados','info'); }catch(_e){}
    }
    hereService = ensureGeoService();
    const mapStyle = (styleSource && typeof styleSource === 'object') ? JSON.parse(JSON.stringify(styleSource)) : styleSource;
  if(sucursalMap){ try{ sucursalMap.remove(); }catch(_e){} }
  sucursalMap = null; sucursalMarker = null; sucursalLabelMarker = null;
    sucursalMap = new maplibregl.Map({
      container: sucursalMapaEl,
      style: mapStyle,
      center: [-99.1332, 19.4326],
      zoom: 12,
      attributionControl: true
    });
      attachMapLibreMissingImageHandler(sucursalMap);
    sucursalMap.addControl(new maplibregl.NavigationControl(), 'top-left');
    sucursalMap.on('load', ()=>{
      const coords = parseCoords(initialCoords||'');
      if(coords){
        setSucursalMarker(coords.lat, coords.lng, { center: true });
      } else {
        setTimeout(()=>{ geocodeSucursalFromFields({}); }, 150);
      }
      setTimeout(()=>{ try{ sucursalMap.resize(); }catch(_e){} }, 250);
    });
    sucursalMap.on('click', (ev)=>{
      const { lat, lng } = ev.lngLat || {};
      if(!Number.isFinite(lat) || !Number.isFinite(lng)) return;
      setSucursalMarker(lat, lng);
      applySucursalCoords(lat, lng);
    });
  }catch(err){
    console.error('[MapLibre] init sucursal error', err);
  }
}

function getSucursalLabelText(){
  const val = (sucursalNombreInput && sucursalNombreInput.value) || '';
  const trimmed = val.trim();
  return trimmed ? trimmed : 'SUCURSAL';
}

function createSucursalLabelElement(){
  const el = document.createElement('div');
  el.className = 'sucursal-map-label';
  el.style.transform = 'translate(-50%, -135%)';
  el.style.background = '#fff';
  el.style.color = '#111827';
  el.style.border = '1px solid #d1d5db';
  el.style.borderRadius = '8px';
  el.style.padding = '6px 8px';
  el.style.font = '12px system-ui, Segoe UI, Arial, sans-serif';
  el.style.boxShadow = '0 4px 10px rgba(0,0,0,0.12)';
  el.style.whiteSpace = 'nowrap';
  el.style.display = 'flex';
  el.style.alignItems = 'center';
  el.style.gap = '6px';
  el.innerHTML = '<span data-dot style="display:inline-block;width:10px;height:10px;border-radius:50%;background:#2563eb;"></span><span data-text></span>';
  updateSucursalLabelElement(el);
  return el;
}

function updateSucursalLabelElement(el){
  if(!el) return;
  const textNode = el.querySelector('[data-text]');
  if(textNode) textNode.textContent = getSucursalLabelText();
}

function ensureSucursalLabel(lat, lng){
  if(!sucursalMap || !Number.isFinite(lat) || !Number.isFinite(lng)) return;
  if(!sucursalLabelMarker){
    const element = createSucursalLabelElement();
    sucursalLabelMarker = new maplibregl.Marker({ element, anchor: 'bottom' }).setLngLat([lng, lat]).addTo(sucursalMap);
  } else {
    updateSucursalLabelElement(sucursalLabelMarker.getElement && sucursalLabelMarker.getElement());
    sucursalLabelMarker.setLngLat([lng, lat]);
  }
}

function setSucursalMarker(lat, lng, opts={}){
  if(!sucursalMap || !Number.isFinite(lat) || !Number.isFinite(lng)) return;
  const coords = [lng, lat];
  if(!sucursalMarker){
    const element = createSlotMarkerElement('trabajo');
    sucursalMarker = new maplibregl.Marker({ element, draggable: true });
    sucursalMarker.setLngLat(coords).addTo(sucursalMap);
    sucursalMarker.on('drag', ()=>{
      const pos = sucursalMarker.getLngLat();
      ensureSucursalLabel(pos.lat, pos.lng);
    });
    sucursalMarker.on('dragend', ()=>{
      const pos = sucursalMarker.getLngLat();
      ensureSucursalLabel(pos.lat, pos.lng);
      applySucursalCoords(pos.lat, pos.lng);
    });
  } else {
    sucursalMarker.setLngLat(coords);
  }
  ensureSucursalLabel(lat, lng);
  if(opts.center !== false){
    try{
      const currentZoom = sucursalMap.getZoom();
      const nextZoom = typeof currentZoom === 'number' && currentZoom >= 15 ? currentZoom : 16;
      sucursalMap.easeTo({ center: coords, zoom: nextZoom, duration: 350 });
    }catch(_e){}
  }
}

async function applySucursalCoords(lat, lng){
  try{
    if(sucursalCoordsInput) sucursalCoordsInput.value = `${(+lat).toFixed(6)}, ${(+lng).toFixed(6)}`;
    await ensureHereLoaded();
    hereService = ensureGeoService();
    if(!hereService) return;
    const place = await reverseGeocodeHere(lat, lng);
    if(place && place.address){
      const f = extractAddressFields(place.address, place);
      if(f.calle) sucursalCalleInput.value = f.calle;
      if(f.numero) sucursalNumeroInput.value = f.numero;
      if(f.colonia) sucursalColoniaInput.value = f.colonia;
      if(f.cp) sucursalCPInput.value = f.cp;
      if(f.ciudad) sucursalCiudadInput.value = f.ciudad;
      if(f.estado) sucursalEstadoInput.value = f.estado;
    }
  }catch(_e){}
}

async function geocodeSucursalFromFields({ force=false }={}){
  // mirror of geocodeHereFromFields but using sucursal inputs and sucursal map
  const calle = (sucursalCalleInput?.value||'').trim();
  const numero = (sucursalNumeroInput?.value||'').trim();
  const colonia = (sucursalColoniaInput?.value||'').trim();
  const cp = (sucursalCPInput?.value||'').trim();
  const ciudad = (sucursalCiudadInput?.value||'').trim();
  const estado = (sucursalEstadoInput?.value||'').trim();
  const pais = 'México';
  const hasStreet = !!calle;
  const hasLocality = !!ciudad || !!cp;
  if(!(force || (hasStreet && hasLocality))) return false;
  await ensureHereLoaded();
  const services = getGeoServicesPriority('geocode');
  if(!services.length) return false;
  const seg = [];
  if(numero) seg.push(`houseNumber=${encodeURIComponent(numero)}`);
  if(calle) seg.push(`street=${encodeURIComponent(calle)}`);
  if(colonia) seg.push(`district=${encodeURIComponent(colonia)}`);
  if(ciudad) seg.push(`city=${encodeURIComponent(ciudad)}`);
  if(estado) seg.push(`state=${encodeURIComponent(estado)}`);
  if(cp) seg.push(`postalCode=${encodeURIComponent(cp)}`);
  if(pais) seg.push(`country=${encodeURIComponent(pais)}`);
  const params = { lang: 'es-MX', limit: 1 };
  if(seg.length) params.qq = seg.join(';'); else {
    const q = [ (calle && numero) ? `${calle} ${numero}` : calle, colonia, cp, ciudad, estado, pais ].filter(Boolean).join(', ');
    if(!q) return false; params.q = q;
  }
  for(let idx=0; idx<services.length; idx++){
    const svc = services[idx];
    const ok = await new Promise((resolve)=>{
      svc.geocode(params, async (result)=>{
        const it = result && result.items && result.items[0];
        if(it && it.position){
          hereService = svc;
          const { lat, lng } = it.position;
          setSucursalMarker(lat, lng);
          await applySucursalCoords(lat, lng);
          resolve(true);
        } else {
          resolve(false);
        }
      }, ()=> resolve(false));
    });
    if(ok) return true;
    // Si MapTiler no responde, añadir una pausa antes de intentar Nominatim para no saturar
    if(idx === 0) await delay(150);
  }
  return false;
}

async function applySucursalCoordsFromInput(){
  const v = (sucursalCoordsInput?.value||'').trim();
  const c = parseCoords(v);
  if(!c){ notify('Coordenadas inválidas. Formato: lat, lng','warn'); return; }
  await ensureHereLoaded();
  hereService = ensureGeoService();
  if(!hereService) return;
  setSucursalMarker(c.lat, c.lng);
  await applySucursalCoords(c.lat, c.lng);
}

function handleSucursalesTableClick(e){
  const btn = e.target.closest('button[data-action]'); if(!btn) return;
  const id = btn.dataset.id; const action = btn.dataset.action; const s = sucursales.find(x=>String(x.id)===String(id)); if(!s) return;
  if(action==='edit') openSucursalModal(id);
  else if(action==='mapa'){
    if(s && s.coords){
      let c = null;
      if(typeof s.coords==='string') c = parseCoords(s.coords);
      else if(typeof s.coords==='object' && Number.isFinite(s.coords.lat) && Number.isFinite(s.coords.lng)) c = s.coords;
      if(c){ const url = `https://www.google.com/maps?q=${c.lat},${c.lng}`; try{ window.open(url, '_blank'); }catch(_e){ location.href = url; } }
      else { notify('Coordenadas inválidas','warn'); }
    }
    else { notify('Sin coordenadas guardadas','info'); }
  }
}

function exportSucursales(){
  if(!sucursales.length){ notify('No hay sucursales','info'); return; }
  exportToExcel({
    filename:'sucursales.xls',
    headers:['Codigo','Nombre','Alias','Responsable','Teléfono','Email','Ciudad','Estado','CP','Calle','Número','Colonia','Horario','Estatus','Notas','Coordenadas'],
    rows: sucursales.map(s=> {
      const telefonoCombinado = composeTelefonoValue(s.telefono||'', s.telefonoPais||s.telPais||'', s.telefonoE164||s.telefonoCompleto||'');
      const telefonoExport = formatDisplayPhone(telefonoCombinado) || telefonoCombinado || (s.telefono||'');
      return [ (s.codigo?String(s.codigo).padStart(8,'0'):(s.id||'')), s.nombre,s.alias||'',s.responsable||'',telefonoExport,s.email||'',s.ciudad||'',s.estado||'',s.cp||'',s.calle||'',s.numero||'',s.colonia||'',s.horario||'',s.estatus||'',s.notas||'', coordsToString(s.coords)];
    })
  });
}

