function renderProveedoresTable(){
  if(!proveedoresBody) return;
  proveedoresBody.innerHTML='';
  const search = (searchProveedoresInput?searchProveedoresInput.value.trim().toLowerCase():'');
  const showInact = !!document.getElementById('showInactProveedores')?.checked;
  let total=0;
  proveedores.forEach(p=>{
    const telefonoCombinado = composeTelefonoValue(p.telefono||'', p.telefonoPais||'', p.telefonoE164||p.telefonoCompleto||'');
    const telefonoSearchValue = telefonoCombinado.toLowerCase();
    if(!showInact && String(p.estatus||'Activo').toLowerCase()!=='activo') return;
    if(search && !(
      (p.nombre||'').toLowerCase().includes(search) ||
      (p.contacto||'').toLowerCase().includes(search) ||
      (p.ciudad||'').toLowerCase().includes(search) ||
      (p.estado||'').toLowerCase().includes(search) ||
      telefonoSearchValue.includes(search) ||
      (p.telefonoE164||'').toLowerCase().includes(search) ||
      (String(p.codigo||'').padStart(8,'0')).includes(search.replace(/\D+/g,''))
    )) return;
    total++;
    const tr=document.createElement('tr');
  const codigo = p.codigo ? String(p.codigo).padStart(8,'0') : '';
    const phoneDisp = formatDisplayPhone(telefonoCombinado) || telefonoCombinado || (p.telefono||'');
  const enabled = String(p.estatus||'Activo').toLowerCase()==='activo';
  const habHtml = `<span style="padding:2px 8px;border-radius:999px;font-size:0.7rem;font-weight:700;color:${enabled?'#065f46':'#991b1b'};background:${enabled?'#d1fae5':'#fee2e2'};border:1px solid ${enabled?'#a7f3d0':'#fecaca'};">${enabled?'SI':'NO'}</span>`;
  tr.innerHTML=`<td>${codigo}</td><td>${p.nombre}</td><td>${p.rfc||''}</td><td>${p.contacto||''}</td><td>${phoneDisp}</td><td>${p.email||''}</td><td>${p.ciudad||''}</td><td>${p.estado||''}</td><td>${p.calle||''}</td><td>${p.numero||''}</td><td>${p.colonia||''}</td><td>${p.cp||''}</td><td>${p.condPago||''}</td><td>${p.diasCredito||0}</td><td>${p.banco||''}</td><td>${p.cuenta||''}</td><td>${p.clabe||''}</td><td>${habHtml}</td><td>${p.notas||''}</td><td><button type="button" class="mini-btn" data-action="edit" data-id="${p.id}">✏️</button></td>`;
    proveedoresBody.appendChild(tr);
  });
  if(proveedoresTotalCount) proveedoresTotalCount.textContent = total;
}

function openProveedorModal(editId=null){
  if(!proveedorOverlay) return;
  if(editId){
    const p = proveedores.find(x=>x.id===editId); if(!p) return;
    proveedorModalTitle.textContent='Editar proveedor';
    proveedorSubmitBtn.textContent='Actualizar';
    proveedorEditingIdInput.value=p.id;
    proveedorNombreInput.value=p.nombre||'';
    proveedorRFCInput.value=p.rfc||'';
    proveedorContactoInput.value=p.contacto||'';
    (function(){
      if(!proveedorTelefonoInput) return;
      const telPrefill = composeTelefonoValue(
        p.telefono || '',
        p.telefonoPais || p.telPais || '',
        p.telefonoE164 || p.telefonoCompleto || ''
      );
      proveedorTelefonoInput.value = telPrefill;
    })();
    proveedorEmailInput.value=p.email||'';
    proveedorCiudadInput.value=p.ciudad||'';
    proveedorEstadoInput.value=p.estado||'';
    proveedorCalleInput.value=p.calle||'';
    proveedorNumeroInput.value=p.numero||'';
    proveedorColoniaInput.value=p.colonia||'';
    proveedorCPInput.value=p.cp||'';
    proveedorCondPagoInput.value=p.condPago||'';
    proveedorDiasCreditoInput.value=p.diasCredito||0;
    proveedorBancoInput.value=p.banco||'';
    proveedorCuentaInput.value=p.cuenta||'';
    proveedorClabeInput.value=p.clabe||'';
    proveedorEstatusInput.value=p.estatus||'Activo';
    proveedorNotasInput.value=p.notas||'';
  } else {
    proveedorModalTitle.textContent='Nuevo proveedor';
    proveedorSubmitBtn.textContent='Guardar';
    proveedorEditingIdInput.value='';
  [proveedorNombreInput,proveedorRFCInput,proveedorContactoInput,proveedorTelefonoInput,proveedorEmailInput,proveedorCiudadInput,proveedorEstadoInput,proveedorCalleInput,proveedorNumeroInput,proveedorColoniaInput,proveedorCPInput,proveedorCondPagoInput,proveedorBancoInput,proveedorCuentaInput,proveedorClabeInput,proveedorNotasInput].forEach(i=>{ if(i) i.value=''; });
  if(proveedorTelefonoInput) proveedorTelefonoInput.placeholder = '+529514138990';
    proveedorDiasCreditoInput.value=0;
    proveedorEstatusInput.value='Activo';
  }
  proveedorOverlay.classList.remove('hidden');
  setTimeout(()=>{ if(proveedorNombreInput) proveedorNombreInput.focus(); },50);
}
function closeProveedorModal(){ if(proveedorOverlay) proveedorOverlay.classList.add('hidden'); }

function handleProveedorSubmit(e){
  e.preventDefault();
  const nombre = proveedorNombreInput.value.trim();
  if(!nombre){ notify('El nombre es obligatorio','warn'); return; }
  const telefonoRaw = (proveedorTelefonoInput?.value||'').trim();
  const telefonoNormalized = telefonoRaw ? normalizePhone(telefonoRaw) : '';
  if(telefonoRaw && (!telefonoNormalized || !/^\+[0-9]{8,15}$/.test(telefonoNormalized))){
    notify('Teléfono inválido. Usa formato internacional (+código país y dígitos).','err');
    return;
  }
  const telefonoPersist = buildTelefonoPersistence(telefonoNormalized);
  const payload = {
    nombre,
    rfc: proveedorRFCInput.value.trim(),
    contacto: proveedorContactoInput.value.trim(),
    telefono: telefonoPersist.telefono,
    telefonoPais: telefonoPersist.telefonoPais,
    telefonoE164: telefonoPersist.telefonoE164,
    telefonoCompleto: telefonoPersist.telefonoCompleto,
    email: proveedorEmailInput.value.trim(),
    ciudad: proveedorCiudadInput.value.trim(),
    estado: proveedorEstadoInput.value.trim(),
    calle: proveedorCalleInput.value.trim(),
    numero: proveedorNumeroInput.value.trim(),
    colonia: proveedorColoniaInput.value.trim(),
    cp: proveedorCPInput.value.trim(),
    condPago: proveedorCondPagoInput.value.trim(),
    diasCredito: parseInt(proveedorDiasCreditoInput.value)||0,
    banco: proveedorBancoInput.value.trim(),
    cuenta: proveedorCuentaInput.value.trim(),
    clabe: proveedorClabeInput.value.trim(),
    estatus: proveedorEstatusInput.value,
    notas: proveedorNotasInput.value.trim()
  };
  const editingId = proveedorEditingIdInput.value ? proveedorEditingIdInput.value : null;
  (async ()=>{
    try{
      if(!window.firebaseApi){ notify('API Firebase no lista','err'); return; }
      if(editingId){
        await window.firebaseApi.updateProveedor(editingId, payload);
        notify('Proveedor actualizado','ok');
      } else {
        const id = await window.firebaseApi.addProveedor(payload);
        if(id) notify('Proveedor agregado','ok');
      }
      closeProveedorModal();
    }catch(err){ console.error('guardar proveedor', err); notify('Error guardando','err'); }
  })();
}

function handleProveedoresTableClick(e){
  const btn = e.target.closest('button[data-action]'); if(!btn) return;
  const id = btn.dataset.id; const action = btn.dataset.action; const p = proveedores.find(x=>String(x.id)===String(id)); if(!p) return;
  if(action==='edit') openProveedorModal(id);
  else if(action==='delete'){
    confirmAction('¿Deshabilitar proveedor?').then(ok=>{ if(ok){ (async()=>{ try{ await window.firebaseApi?.updateProveedor(id,{ estatus:'Inactivo' }); notify('Proveedor deshabilitado','info'); } catch(err){ console.error(err); notify('No se pudo deshabilitar','err'); } })(); } });
  }
}

function exportProveedores(){
  if(!proveedores.length){ notify('No hay proveedores','info'); return; }
  exportToExcel({ filename:'proveedores.xls', headers:['Codigo','Nombre','RFC','Contacto','Telefono','Email','Ciudad','Estado','Calle','Numero','Colonia','CP','CondPago','DiasCredito','Banco','Cuenta','CLABE','Estatus','Notas'], rows: proveedores.map(p=>{
    const code = p.codigo?String(p.codigo).padStart(8,'0'):'';
    const telefonoCombinado = composeTelefonoValue(p.telefono||'', p.telefonoPais||'', p.telefonoE164||p.telefonoCompleto||'');
    const phone = formatDisplayPhone(telefonoCombinado) || telefonoCombinado || (p.telefono||'');
    return [code,p.nombre,p.rfc||'',p.contacto||'',phone,p.email||'',p.ciudad||'',p.estado||'',p.calle||'',p.numero||'',p.colonia||'',p.cp||'',p.condPago||'',p.diasCredito||0,p.banco||'',p.cuenta||'',p.clabe||'',p.estatus||'',p.notas||''];
  }) });
}

