function applyVariantPriceCostLocks(){
  const variantsCount = Array.isArray(tempVariantes) ? tempVariantes.length : 0;
  const hasVariants = variantsCount > 0;
  const canFabricar = !!(catProductoPuedeFabricarChk && catProductoPuedeFabricarChk.checked);
  let selectedType = 'PRODUCTO';
  try { selectedType = getCatProductoSelectedType(); } catch(_e){}
  const isProducto = String(selectedType).toUpperCase() === 'PRODUCTO';
  const lockCosto = hasVariants || (canFabricar && isProducto);
  const lockPrecio = hasVariants;

  if(catProductoCostoInput){
    const costGroup = catProductoCostoInput.closest('.form-group');
    const originalPlaceholder = catProductoCostoInput.dataset.placeholderOriginal || '';
    if(lockCosto){
      catProductoCostoInput.disabled = true;
      catProductoCostoInput.required = false;
      catProductoCostoInput.classList.add('readonly');
      catProductoCostoInput.value = '';
      catProductoCostoInput.placeholder = hasVariants ? 'Costo definido en variantes' : 'Costo calculado desde la receta';
      if(costGroup){
        let hint = costGroup.querySelector('.variant-lock-hint-costo');
        if(!hint){
          hint = document.createElement('small');
          hint.className = 'variant-lock-hint-costo';
          hint.style.display = 'block';
          hint.style.fontSize = '0.75rem';
          hint.style.marginTop = '4px';
          hint.style.color = '#64748b';
          hint.textContent = hasVariants
            ? 'Costo se captura directamente en cada variante.'
            : 'Costo se calculará automáticamente según la receta configurada.';
          costGroup.appendChild(hint);
        } else {
          hint.style.display = 'block';
          hint.textContent = hasVariants
            ? 'Costo se captura directamente en cada variante.'
            : 'Costo se calculará automáticamente según la receta configurada.';
        }
      }
    } else {
      catProductoCostoInput.disabled = false;
      const shouldRequire = catProductoCostoInput.dataset.requiredOriginal === '1';
      catProductoCostoInput.required = shouldRequire;
      catProductoCostoInput.classList.remove('readonly');
      if(originalPlaceholder){
        catProductoCostoInput.placeholder = originalPlaceholder;
      } else {
        catProductoCostoInput.removeAttribute('placeholder');
      }
      if(costGroup){
        const hint = costGroup.querySelector('.variant-lock-hint-costo');
        if(hint){ hint.remove(); }
      }
    }
  }

  if(catProductoPrecioPublicoInput){
    const priceGroup = catProductoPrecioPublicoInput.closest('.form-group');
    const originalPlaceholder = catProductoPrecioPublicoInput.dataset?.placeholderOriginal || '';
    if(lockPrecio){
      catProductoPrecioPublicoInput.disabled = true;
      catProductoPrecioPublicoInput.classList.add('readonly');
      catProductoPrecioPublicoInput.value = '';
      catProductoPrecioPublicoInput.placeholder = 'Precio definido en variantes';
      if(priceGroup){
        let hint = priceGroup.querySelector('.variant-lock-hint-precio');
        if(!hint){
          hint = document.createElement('small');
          hint.className = 'variant-lock-hint-precio';
          hint.style.display = 'block';
          hint.style.fontSize = '0.75rem';
          hint.style.marginTop = '4px';
          hint.style.color = '#64748b';
          hint.textContent = 'El precio general se toma de las variantes configuradas.';
          priceGroup.appendChild(hint);
        } else {
          hint.style.display = 'block';
        }
      }
    } else {
      catProductoPrecioPublicoInput.disabled = false;
      catProductoPrecioPublicoInput.classList.remove('readonly');
      if(originalPlaceholder){
        catProductoPrecioPublicoInput.placeholder = originalPlaceholder;
      } else {
        catProductoPrecioPublicoInput.removeAttribute('placeholder');
      }
      if(priceGroup){
        const hint = priceGroup.querySelector('.variant-lock-hint-precio');
        if(hint){ hint.remove(); }
      }
    }
  }

  try { updateMargenPreview(); } catch(_e){}
}

// Receta (BOM) UI
const recetaRows = document.getElementById('recetaRows');
const recetaEmpty = document.getElementById('recetaEmpty');
const addRecetaBtn = document.getElementById('addRecetaBtn');
const catProductoRecetaFs = document.getElementById('catProductoRecetaFs');
let tempReceta = [];

function roundCurrency(value){
  const n = Number(value);
  if(!Number.isFinite(n)) return 0;
  return Math.round(n * 100) / 100;
}

function roundTo(value, decimals){
  const n = Number(value);
  if(!Number.isFinite(n)) return 0;
  const factor = Math.pow(10, Math.max(0, decimals|0));
  if(!(factor>0)) return 0;
  return Math.round(n * factor) / factor;
}

let fabricacionCantidadModo = 'VENTA';

function normalizeRecetaCantidadModo(raw, fallback){
  const ref = String(raw||'').trim().toUpperCase();
  if(ref === 'BASE' || ref === 'POR_BASE' || ref === 'UNIDAD_BASE') return 'BASE';
  if(ref === 'VENTA' || ref === 'POR_VENTA' || ref === 'UNIDAD_VENTA') return 'VENTA';
  return fallback || 'VENTA';
}

function getFabricacionCantidadModo(){
  return fabricacionCantidadModo;
}

function setFabricacionCantidadModo(mode){
  const normalized = normalizeRecetaCantidadModo(mode, 'VENTA');
  fabricacionCantidadModo = normalized;
  if(catProductoRecetaModoVentaInput) catProductoRecetaModoVentaInput.checked = normalized === 'VENTA';
  if(catProductoRecetaModoBaseInput) catProductoRecetaModoBaseInput.checked = normalized === 'BASE';
  updateRecetaModeSummary();
  applyRecetaQuantityHints();
}

function getRecetaUnidadContext(){
  const ventaMeta = getUnidadSelectionMeta(catProductoUnidadInput);
  const baseMeta = getUnidadSelectionMeta(catProductoUnidadFabricacionInput);
  const factorInfo = computeFactorFromUnitsSelection();
  const factorValue = factorInfo.type === 'ok' && Number.isFinite(factorInfo.value) && factorInfo.value > 0
    ? Number(factorInfo.value)
    : null;

  const resolveLabel = (meta)=>{
    if(!meta) return '';
    const optionLabel = meta.option?.textContent ? String(meta.option.textContent).trim() : '';
    const fallback = meta.label ? String(meta.label).trim() : '';
    return optionLabel || fallback;
  };

  const resolveShort = (label)=>{
    if(!label) return '';
    let short = label.split('(')[0].trim();
    if(short.includes(' - ')) short = short.split(' - ')[0].trim();
    return short || label;
  };

  const ventaLabel = resolveLabel(ventaMeta);
  const baseLabel = resolveLabel(baseMeta);
  const ventaShort = resolveShort(ventaLabel);
  const baseShort = resolveShort(baseLabel);

  return {
    ventaMeta,
    baseMeta,
    factorInfo,
    factorValue,
    ventaLabel,
    baseLabel,
    ventaShort,
    baseShort
  };
}

function buildRecetaConversionText(ctx){
  if(!ctx || !ctx.factorValue) return '';
  const factorText = formatFactorDisplay(ctx.factorValue);
  const ventaName = ctx.ventaShort || 'unidad de venta';
  const baseName = ctx.baseShort || 'unidad base';
  return `1 ${ventaName} = ${factorText} ${baseName}`;
}

function updateRecetaModeSummary(){
  const ctx = getRecetaUnidadContext();
  const mode = getFabricacionCantidadModo();
  const conversionText = buildRecetaConversionText(ctx);
  const ventaName = ctx.ventaShort || 'unidad de venta';
  const baseName = ctx.baseShort || 'unidad base';
  const factorText = ctx.factorValue ? formatFactorDisplay(ctx.factorValue) : '';
  const conversionResult = conversionText && conversionText.includes('=')
    ? conversionText.split('=')[1].trim()
    : '';

  if(catProductoRecetaModeSummary){
    if(!ctx.ventaLabel || !ctx.baseLabel){
      catProductoRecetaModeSummary.textContent = 'Selecciona la unidad de venta y la unidad base para ver el resumen de conversión.';
    } else {
      let summary = `Unidad base: ${ctx.baseLabel}. Unidad de venta: ${ctx.ventaLabel}.`;
      if(conversionText){
        summary += ` ${conversionText}.`;
      }
      catProductoRecetaModeSummary.textContent = summary;
    }
  }

  if(catProductoRecetaModeHint){
    if(!ctx.ventaLabel || !ctx.baseLabel){
      catProductoRecetaModeHint.textContent = 'Elige tus unidades para indicar cómo se capturan las cantidades de la receta.';
    } else if(mode === 'BASE'){
      if(conversionText && factorText){
        catProductoRecetaModeHint.textContent = `Captura los insumos por cada ${baseName} fabricada; el sistema multiplicará ×${factorText} cuando vendas 1 ${ventaName}.`;
      } else {
        catProductoRecetaModeHint.textContent = `Captura los insumos por cada ${baseName} fabricada.`;
      }
    } else {
      if(conversionText){
        const resultText = conversionResult || conversionText;
        catProductoRecetaModeHint.textContent = `Captura los insumos por cada ${ventaName} vendida; se descontará el equivalente de ${resultText} en inventario.`;
      } else {
        catProductoRecetaModeHint.textContent = `Captura los insumos por cada ${ventaName} vendida.`;
      }
    }
  }

  if(catProductoRecetaNote){
    if(!ctx.ventaLabel || !ctx.baseLabel){
      catProductoRecetaNote.textContent = 'Configura las unidades de venta y fabricación para ver instrucciones específicas con tus datos.';
    } else if(mode === 'BASE'){
      if(conversionText){
        const discountText = conversionResult || `${factorText || 'el factor'} ${ctx.baseShort || 'unidades base'}`;
        const multiplierText = factorText || 'el factor indicado';
        catProductoRecetaNote.textContent = `Con este modo, la receta se captura por ${baseName}. Al vender 1 ${ventaName}, se multiplicará ×${multiplierText} para descontar ${discountText} en inventario.`;
      } else {
        catProductoRecetaNote.textContent = `Con este modo, captura los componentes por cada ${baseName} fabricada.`;
      }
    } else {
      if(conversionText){
        catProductoRecetaNote.textContent = `Con este modo, captura los componentes por cada ${ventaName} vendida. El sistema usará ${conversionText} para ajustar el inventario en unidades base.`;
      } else {
        catProductoRecetaNote.textContent = `Con este modo, captura los componentes por cada ${ventaName} vendida.`;
      }
    }
  }
}

function applyRecetaQuantityHints(){
  const ctx = getRecetaUnidadContext();
  const mode = getFabricacionCantidadModo();
  const ventaName = ctx.ventaShort || 'unidad de venta';
  const baseName = ctx.baseShort || 'unidad base';
  const conversionText = buildRecetaConversionText(ctx);
  const conversionResult = conversionText && conversionText.includes('=')
    ? conversionText.split('=')[1].trim()
    : '';

  if(catProductoRecetaCantidadHeader){
    const baseLabel = mode === 'BASE' ? 'Cantidad por unidad base' : 'Cantidad por unidad de venta';
    const suffix = mode === 'BASE' ? baseName : ventaName;
    catProductoRecetaCantidadHeader.textContent = suffix ? `${baseLabel} (${suffix})` : baseLabel;
  }

  const placeholder = mode === 'BASE'
    ? `Ej. consumo por ${baseName}`
    : `Ej. consumo por ${ventaName}`;

  const titlePieces = [];
  if(mode === 'BASE'){
    titlePieces.push(`Se descontará esta cantidad por cada ${baseName} fabricada.`);
    if(conversionText) titlePieces.push(`Equivalencia: ${conversionText}.`);
  } else {
    titlePieces.push(`Se descontará esta cantidad por cada ${ventaName} vendida.`);
    if(conversionResult) titlePieces.push(`Esto representa ${conversionResult} en unidades base.`);
  }
  const titleText = titlePieces.join(' ');

  if(recetaRows){
    recetaRows.querySelectorAll('input[data-field="cantidadPorUnidad"]').forEach(inp=>{
      inp.placeholder = placeholder;
      if(titleText){
        inp.title = titleText;
      } else {
        inp.removeAttribute('title');
      }
    });
  }
}

