function shouldAutoCalcRecetaCost(){
  if(!catProductoPuedeFabricarChk?.checked) return false;
  if(getCatProductoSelectedType() !== 'PRODUCTO') return false;
  if(!Array.isArray(tempReceta) || !tempReceta.length) return false;
  return tempReceta.some(rc=>{
    if(!rc) return false;
    const pid = String(rc.productoId||'').trim();
    if(!pid) return false;
    const qty = Number(rc.cantidadPorUnidad);
    return qty>0;
  });
}

function getFabricacionFactorVenta(){
  if(!catProductoFactorVentaInput) return 1;
  const raw = parseFloat(catProductoFactorVentaInput.value);
  if(Number.isFinite(raw) && raw > 0) return raw;
  return 1;
}

function formatFactorDisplay(value){
  const n = Number(value);
  if(!Number.isFinite(n) || n <= 0) return '1';
  if(Math.abs(n - Math.round(n)) < 1e-9) return String(Math.round(n));
  const digits = n < 1 ? 4 : 3;
  return Number(n.toFixed(digits)).toString();
}

function ensureSelectOption(selectEl, value, label, meta){
  if(!selectEl || !value) return null;
  const existing = Array.from(selectEl.options||[]).find(opt=> opt.value === value);
  if(existing){
    if(label != null) existing.textContent = label;
    if(meta?.legacy) existing.dataset.legacy = '1';
    if(meta?.familia) existing.dataset.familia = meta.familia;
    if(meta?.factor != null) existing.dataset.factor = String(meta.factor);
    return existing;
  }
  const opt = document.createElement('option');
  opt.value = value;
  opt.textContent = label != null ? label : value;
  if(meta?.legacy) opt.dataset.legacy = '1';
  if(meta?.familia) opt.dataset.familia = meta.familia;
  if(meta?.factor != null) opt.dataset.factor = String(meta.factor);
  selectEl.appendChild(opt);
  return opt;
}

function getUnidadSelectionMeta(selectEl){
  if(!selectEl) return null;
  const value = selectEl.value || '';
  if(!value) return null;
  const catalogUnit = findUnidadById(value);
  if(catalogUnit){
    return {
      id: String(catalogUnit.id||catalogUnit._docId||value),
      label: formatUnidadLabel(catalogUnit, { includeFamilia:false }),
      familia: catalogUnit.familia || '',
      factor: getUnidadFactorRef(catalogUnit),
      legacy: false,
      option: selectEl.options[selectEl.selectedIndex] || null
    };
  }
  const opt = selectEl.options[selectEl.selectedIndex] || null;
  const familia = opt?.dataset?.familia || '';
  const factor = opt?.dataset?.factor ? Number(opt.dataset.factor) : null;
  const legacy = opt?.dataset?.legacy === '1';
  return {
    id: value,
    label: opt ? opt.textContent : value,
    familia,
    factor: (Number.isFinite(factor) && factor>0) ? factor : null,
    legacy,
    option: opt || null
  };
}

function computeFactorFromUnitsSelection(){
  const venta = getUnidadSelectionMeta(catProductoUnidadInput);
  const base = getUnidadSelectionMeta(catProductoUnidadFabricacionInput);
  if(!venta || !base) return { type:'missing', venta, base };
  if(venta.legacy || base.legacy) return { type:'legacy', venta, base };
  const famVenta = normalizeUnidadFamilia(venta.familia);
  const famBase = normalizeUnidadFamilia(base.familia);
  if(famVenta && famBase && famVenta !== famBase){
    return { type:'mismatch', venta, base };
  }
  const factorVenta = venta.factor != null ? venta.factor : getUnidadFactorRef(findUnidadById(venta.id));
  const factorBase = base.factor != null ? base.factor : getUnidadFactorRef(findUnidadById(base.id));
  if(!(Number.isFinite(factorVenta) && factorVenta>0) || !(Number.isFinite(factorBase) && factorBase>0)){
    return { type:'incomplete', venta, base };
  }
  return { type:'ok', value: factorVenta / factorBase, venta, base };
}

function populateUnidadSelects(){
  const selectEls = [catProductoUnidadInput, catProductoUnidadFabricacionInput];
  const active = getUnidadesCatalog()
    .filter(u=> String(u?.estatus||'Activa').toLowerCase() === 'activa')
    .sort((a,b)=>{
      const famA = String(a?.familia||'');
      const famB = String(b?.familia||'');
      const famCmp = famA.localeCompare(famB, undefined, { sensitivity:'base' });
      if(famCmp !== 0) return famCmp;
      const labA = String(a?.abreviatura||a?.nombre||'');
      const labB = String(b?.abreviatura||b?.nombre||'');
      return labA.localeCompare(labB, undefined, { sensitivity:'base' });
    });
  selectEls.forEach(selectEl=>{
    if(!selectEl) return;
    const currentVal = selectEl.value || '';
    const legacyValue = selectEl.dataset?.legacyValue || '';
    const legacyLabel = selectEl.dataset?.legacyLabel || '';
    selectEl.innerHTML = '<option value="">Selecciona unidad…</option>';
    active.forEach(unit=>{
      const id = String(unit.id||unit._docId||'');
      if(!id) return;
      const opt = document.createElement('option');
      opt.value = id;
      opt.textContent = formatUnidadLabel(unit);
      if(unit.familia) opt.dataset.familia = unit.familia;
      const factor = getUnidadFactorRef(unit);
      if(factor != null) opt.dataset.factor = String(factor);
      if(unit.esBase) opt.dataset.esBase = '1';
      selectEl.appendChild(opt);
    });
    let restored = '';
    if(currentVal && Array.from(selectEl.options).some(opt=> opt.value === currentVal)){
      restored = currentVal;
      delete selectEl.dataset.legacyValue;
      delete selectEl.dataset.legacyLabel;
    } else if(legacyValue){
      ensureSelectOption(selectEl, legacyValue, legacyLabel || legacyValue, { legacy:true });
      restored = legacyValue;
      selectEl.dataset.legacyValue = legacyValue;
      selectEl.dataset.legacyLabel = legacyLabel || legacyValue;
    } else if(currentVal){
      ensureSelectOption(selectEl, currentVal, currentVal, { legacy:true });
      restored = currentVal;
      selectEl.dataset.legacyValue = currentVal;
      selectEl.dataset.legacyLabel = currentVal;
    }
    selectEl.value = restored;
  });
  syncUnidadSelections({ skipPopulate:true });
}

function syncUnidadSelections(_options={}){
  const factorInfo = computeFactorFromUnitsSelection();
  if(catProductoFactorVentaInput){
    if(factorInfo.type === 'ok' && Number.isFinite(factorInfo.value) && factorInfo.value > 0){
      const rounded = Math.round(factorInfo.value * 10000) / 10000;
      const digits = rounded < 1 ? 4 : 3;
      catProductoFactorVentaInput.value = Number(rounded.toFixed(digits)).toString();
      catProductoFactorVentaInput.disabled = true;
      catProductoFactorVentaInput.classList.add('readonly');
      catProductoFactorVentaInput.dataset.factorSource = 'catalog';
    } else {
      const preserve = catProductoFactorVentaInput.value;
      catProductoFactorVentaInput.disabled = false;
      catProductoFactorVentaInput.classList.remove('readonly');
      delete catProductoFactorVentaInput.dataset.factorSource;
      catProductoFactorVentaInput.value = preserve;
    }
  }
  if(catProductoUnidadWarning){
    if(factorInfo.type === 'mismatch'){
      catProductoUnidadWarning.textContent = 'Las unidades seleccionadas pertenecen a familias distintas.';
      catProductoUnidadWarning.classList.remove('hidden');
    } else if(factorInfo.type === 'legacy'){
      catProductoUnidadWarning.textContent = 'Selecciona unidades registradas en el catálogo para habilitar la conversión automática.';
      catProductoUnidadWarning.classList.remove('hidden');
    } else if(factorInfo.type === 'incomplete'){
      catProductoUnidadWarning.textContent = 'Configura el factor en la unidad base desde el catálogo para completar la conversión.';
      catProductoUnidadWarning.classList.remove('hidden');
    } else {
      catProductoUnidadWarning.classList.add('hidden');
    }
  }
  updateConversionPreview();
  updateConversionVisibility();
  updateRecetaModeSummary();
  applyRecetaQuantityHints();
  try{ autoApplyRecetaTotals(); }catch(_e){}
}

function updateConversionPreview(){
  if(!catProductoConversionPreviewInput) return;
  const venta = getUnidadSelectionMeta(catProductoUnidadInput);
  const base = getUnidadSelectionMeta(catProductoUnidadFabricacionInput);
  const ventaLabel = venta ? venta.label : 'unidad de venta';
  const baseLabel = base ? base.label : 'unidad base';
  const factorStr = formatFactorDisplay(getFabricacionFactorVenta());
  catProductoConversionPreviewInput.value = `1 ${ventaLabel} = ${factorStr} ${baseLabel}`;
}

function updateConversionVisibility(){
  if(!catProductoConversionWrap) return;
  let selectedType = 'PRODUCTO';
  try { selectedType = getCatProductoSelectedType(); } catch(_e){}
  const isProducto = selectedType === 'PRODUCTO';
  const canMake = !!(catProductoPuedeFabricarChk && catProductoPuedeFabricarChk.checked) && isProducto;
  const hasUnit = !!(catProductoUnidadFabricacionInput && catProductoUnidadFabricacionInput.value);
  let hasFactor = false;
  if(catProductoFactorVentaInput){
    const raw = parseFloat(catProductoFactorVentaInput.value);
    hasFactor = Number.isFinite(raw) && raw > 0;
  }
  const show = canMake || hasUnit || hasFactor;
  catProductoConversionWrap.classList.toggle('hidden', !show);
}

function resolveProductoCosto(prod){
  if(!prod || typeof prod !== 'object') return 0;
  const direct = Number(prod.costo);
  if(Number.isFinite(direct) && direct > 0) return direct;
  const costoUnit = Number(prod.costoUnit);
  if(Number.isFinite(costoUnit) && costoUnit > 0) return costoUnit;
  const variants = Array.isArray(prod.variantes) ? prod.variantes : null;
  if(variants){
    let sum = 0;
    let count = 0;
    for(const variant of variants){
      if(!variant) continue;
      const vCost = Number(variant.costo);
      if(Number.isFinite(vCost) && vCost > 0){
        sum += vCost;
        count += 1;
      }
    }
    if(count > 0){
      return sum / count;
    }
  }
  const baseCost = Number(prod.fabricacionCostoUnidadBase);
  if(Number.isFinite(baseCost) && baseCost > 0){
    const factor = Number(prod.fabricacionFactorVenta);
    if(Number.isFinite(factor) && factor > 0) return baseCost * factor;
    return baseCost;
  }
  return 0;
}

function computeRecetaTotals(){
  const list = Array.isArray(tempReceta)? tempReceta : [];
  const src = Array.isArray(window.products)? window.products : [];
  const map = new Map();
  src.forEach(p=>{
    const id = String(p?.id||p?._id||'').trim();
    if(id && !map.has(id)) map.set(id, p);
  });
  let totalCost = 0;
  let totalPrice = 0;
  const missing = [];
  let componentCount = 0;
  let costfulCount = 0;
  const zeroCostIds = [];
  const salesWeightedCosts = new Map();
  try {
    if(window.__variantCostAverages__ && typeof window.__variantCostAverages__ === 'object'){
      Object.keys(window.__variantCostAverages__).forEach(pid=>{
        const meta = window.__variantCostAverages__[pid];
        if(meta && typeof meta.avg === 'number' && meta.avg > 0){
          salesWeightedCosts.set(pid, Number(meta.avg));
        }
      });
    }
  } catch(_e){}
  list.forEach(rc=>{
    if(!rc) return;
    const pid = String(rc.productoId||'').trim();
    if(!pid) return;
    const qtyBase = Number(rc.cantidadPorUnidad);
    if(!(qtyBase>0)) return;
    let qty = qtyBase;
    if(String(rc.tipo||'').toUpperCase()==='CONSUMIBLE'){
      const wear = Number(rc.wearPorUnidad);
      qty *= wear>0 ? wear : 1;
    }
    const prod = map.get(pid);
    if(!prod){
      if(!missing.includes(pid)) missing.push(pid);
      return;
    }
  componentCount++;
    let compCost;
    if(salesWeightedCosts.has(pid)) compCost = salesWeightedCosts.get(pid);
    else compCost = resolveProductoCosto(prod);
  if(compCost>0) costfulCount++; else zeroCostIds.push(pid);
    totalCost += compCost * qty;
    let compPrice = Number(prod.precio);
    if(!(compPrice>0)) compPrice = Number(prod.precioPublico)||0;
    if(!(compPrice>0)) compPrice = compCost;
    totalPrice += compPrice * qty;
  });
  return { totalCost, totalPrice, missing, componentCount, costfulCount, zeroCostIds };
}

function autoApplyRecetaTotals(){
  if(!shouldAutoCalcRecetaCost()){
    if(catProductoCostoInput){
      delete catProductoCostoInput.dataset.autoFromReceta;
      delete catProductoCostoInput.dataset.autoFromRecetaBase;
      delete catProductoCostoInput.dataset.autoFromRecetaFactor;
      delete catProductoCostoInput.dataset.autoFromRecetaPerSale;
      catProductoCostoInput.title = '';
    }
    return null;
  }
  const totals = computeRecetaTotals();
  const rawTotalCost = Number(totals.totalCost||0);
  const factor = getFabricacionFactorVenta();
  const cantidadModo = getFabricacionCantidadModo();
  let perSaleCost = 0;
  let perBaseCost = 0;
  if(cantidadModo === 'BASE'){
    perBaseCost = roundTo(rawTotalCost, 4);
    const multiplier = factor > 0 ? factor : 1;
    perSaleCost = roundCurrency(rawTotalCost * multiplier);
  } else {
    perSaleCost = roundCurrency(rawTotalCost);
    perBaseCost = factor > 0 ? roundTo(rawTotalCost / factor, 4) : roundTo(rawTotalCost, 4);
  }
  const hasVariants = Array.isArray(tempVariantes) && tempVariantes.length>0;
  if(catProductoCostoInput){
    catProductoCostoInput.value = hasVariants ? '' : perSaleCost.toFixed(2);
    catProductoCostoInput.dataset.autoFromReceta = '1';
    catProductoCostoInput.dataset.autoFromRecetaBase = perBaseCost.toFixed(4);
    catProductoCostoInput.dataset.autoFromRecetaFactor = factor.toString();
    catProductoCostoInput.dataset.autoFromRecetaPerSale = perSaleCost.toFixed(2);
    if(cantidadModo === 'BASE'){
      if(factor > 1){
        catProductoCostoInput.title = `Costo final = $${perSaleCost.toFixed(2)} (receta unidad base: $${perBaseCost.toFixed(4)} × ${formatFactorDisplay(factor)})`;
      } else {
        catProductoCostoInput.title = hasVariants
          ? `Costo receta por unidad base: $${perBaseCost.toFixed(4)} (aplicado en variantes)`
          : 'Costo calculado desde la receta (unidad base)';
      }
    } else {
      if(factor > 1){
        catProductoCostoInput.title = `Costo receta unitario: $${perSaleCost.toFixed(2)} (equivale a $${perBaseCost.toFixed(4)} por unidad base)`;
      } else {
        catProductoCostoInput.title = hasVariants
          ? `Costo calculado por receta: $${perSaleCost.toFixed(2)} (aplicado en variantes)`
          : 'Costo calculado desde la receta';
      }
    }
  }
  if(hasVariants){
    let variantsUpdated = false;
    for(const variant of tempVariantes){
      if(!variant) continue;
      if(typeof variant.autoCostoReceta === 'undefined'){ variant.autoCostoReceta = true; }
      if(variant.autoCostoReceta !== false){
        if(!Number.isFinite(variant.costo) || Math.abs(roundCurrency(variant.costo) - perSaleCost) > 0.009){
          variant.costo = perSaleCost;
          variantsUpdated = true;
        } else if(typeof variant.costo !== 'number'){
          variant.costo = perSaleCost;
          variantsUpdated = true;
        }
        variant.autoCostoReceta = true;
      }
    }
    if(variantsUpdated){
      renderVariantes();
    }
  }
  try { updateMargenPreview(); } catch(_e){}
  return { cost: perSaleCost, baseCost: perBaseCost, factor, meta: totals };
}

function renderReceta(){
  if(!recetaRows) return;
  recetaRows.innerHTML = '';
  const products = (Array.isArray(window.products)? window.products : [])
    .filter(p=> (__isTrue(p.esInsumo) || __isTrue(p.esConsumible)))
    .filter(p=> String(p.estatus||'Activo').toLowerCase()==='activo');
  tempReceta.forEach((rc, i)=>{
    const row = document.createElement('div');
    row.style.display='grid';
    row.style.gridTemplateColumns='1.2fr 0.6fr 0.8fr 0.9fr 40px';
    row.style.gap='8px';
    // options for products (components)
    const opts = products.map(p=>`<option value="${String(p.id||p._id)}">${String(p.descripcion||p.codigoInterno||'').replace(/"/g,'&quot;')}</option>`).join('');
    const prod = products.find(p=> String(p.id||p._id) === String(rc.productoId||''));
    const inferredTipo = prod ? (__isTrue(prod.esConsumible)? 'CONSUMIBLE' : 'INSUMO') : ((rc.tipo==='CONSUMIBLE')? 'CONSUMIBLE':'INSUMO');
    if(rc.tipo !== inferredTipo){
      tempReceta[i].tipo = inferredTipo;
      rc.tipo = inferredTipo;
    }
    let wearVal = (typeof rc.wearPorUnidad==='number' && !Number.isNaN(rc.wearPorUnidad))? rc.wearPorUnidad : undefined;
    if(inferredTipo==='CONSUMIBLE'){
      if(!(wearVal>0)){ wearVal = 1; tempReceta[i].wearPorUnidad = 1; }
    } else {
      if(typeof wearVal !== 'undefined'){ delete tempReceta[i].wearPorUnidad; }
      wearVal = undefined;
    }
    const tipo = inferredTipo;
    const qty = (typeof rc.cantidadPorUnidad==='number' && !Number.isNaN(rc.cantidadPorUnidad))? rc.cantidadPorUnidad : '';
    const wear = (typeof wearVal==='number')? wearVal : '';
    row.innerHTML = `
      <select data-kind="receta" data-idx="${i}" data-field="productoId">${opts}</select>
      <select data-kind="receta" data-idx="${i}" data-field="tipo" disabled>
        <option value="INSUMO" ${tipo==='INSUMO'?'selected':''}>INSUMO</option>
        <option value="CONSUMIBLE" ${tipo==='CONSUMIBLE'?'selected':''}>CONSUMIBLE</option>
      </select>
      <input type="number" min="0" step="0.0001" data-kind="receta" data-idx="${i}" data-field="cantidadPorUnidad" placeholder="0" value="${qty}">
      <input type="number" min="0" step="0.0001" data-kind="receta" data-idx="${i}" data-field="wearPorUnidad" placeholder="0" value="${wear}" ${tipo==='CONSUMIBLE'?'':'disabled'}>
      <button type="button" title="Eliminar" data-del="receta" data-idx="${i}" class="btn-icon">✕</button>
    `;
    recetaRows.appendChild(row);
    // set selected value after append (to tolerate missing ids)
    try{ const sel = row.querySelector('select[data-field="productoId"]'); if(sel) sel.value = String(rc.productoId||''); }catch(_e){}
  });
  if(recetaEmpty) recetaEmpty.style.display = tempReceta.length? 'none' : 'block';
  applyRecetaQuantityHints();
  autoApplyRecetaTotals();
}

function addReceta(){ tempReceta.push({ productoId:'', tipo:'INSUMO', cantidadPorUnidad:0, wearPorUnidad:1 }); renderReceta(); }

function handleRecetaInputs(e){
  const t = e.target; if(!t) return;
  if((e.type==='input' || e.type==='change') && t.dataset && t.dataset.kind==='receta'){
    const idx = parseInt(t.dataset.idx); const field = t.dataset.field;
    if(!Number.isInteger(idx) || !tempReceta[idx]) return;
    if(field==='productoId'){
      tempReceta[idx].productoId = String(t.value||'');
      const pid = tempReceta[idx].productoId;
      if(pid){
        const catalog = Array.isArray(window.products)? window.products : [];
        const prod = catalog.find(p=> String(p?.id||p?._id||'') === pid);
        if(prod){
          const inferredTipo = __isTrue(prod.esConsumible) ? 'CONSUMIBLE' : 'INSUMO';
          if(tempReceta[idx].tipo !== inferredTipo){
            tempReceta[idx].tipo = inferredTipo;
            const row = t.closest('div');
            const tipoSel = row? row.querySelector('select[data-field="tipo"]') : null;
            if(tipoSel){ tipoSel.value = inferredTipo; }
            const wearInp = row? row.querySelector('input[data-field="wearPorUnidad"]') : null;
            if(inferredTipo==='CONSUMIBLE'){
              const wearVal = (typeof tempReceta[idx].wearPorUnidad === 'number' && !Number.isNaN(tempReceta[idx].wearPorUnidad) && tempReceta[idx].wearPorUnidad>0)
                ? tempReceta[idx].wearPorUnidad
                : 1;
              tempReceta[idx].wearPorUnidad = wearVal;
              if(wearInp){ wearInp.disabled = false; wearInp.value = wearVal; }
            } else {
              delete tempReceta[idx].wearPorUnidad;
              if(wearInp){ wearInp.disabled = true; wearInp.value = ''; }
            }
          }
        }
      }
    }
    else if(field==='tipo'){
      tempReceta[idx].tipo = String(t.value||'INSUMO');
      // toggle wear field
      const row = t.closest('div');
      const wearInp = row? row.querySelector('input[data-field="wearPorUnidad"]') : null;
      if(wearInp){ wearInp.disabled = tempReceta[idx].tipo!=='CONSUMIBLE'; }
    }
    else if(field==='cantidadPorUnidad'){ tempReceta[idx].cantidadPorUnidad = t.value===''? undefined : (parseFloat(t.value)||0); }
    else if(field==='wearPorUnidad'){ tempReceta[idx].wearPorUnidad = t.value===''? undefined : (parseFloat(t.value)||0); }
  }
  const delBtn = t.closest('button[data-del="receta"]');
  if(delBtn){ const idx = parseInt(delBtn.dataset.idx); if(Number.isInteger(idx)){ tempReceta.splice(idx,1); renderReceta(); } }
  autoApplyRecetaTotals();
}

if(recetaRows){ recetaRows.addEventListener('input', handleRecetaInputs); recetaRows.addEventListener('change', handleRecetaInputs); recetaRows.addEventListener('click', handleRecetaInputs); }
if(addRecetaBtn){ addRecetaBtn.addEventListener('click', addReceta); }
