// Picker modal for receta components
const recetaPickerOverlay = document.getElementById('recetaPickerOverlay');
const recetaPickCloseBtn = document.getElementById('recetaPickCloseBtn');
const recetaPickCancelBtn = document.getElementById('recetaPickCancelBtn');
const recetaPickQuery = document.getElementById('recetaPickQuery');
const recetaPickResultsBody = document.getElementById('recetaPickResultsBody');
let _recetaPickResolve = null;
let _recetaReturnFocusEl = null;

function openRecetaPicker(){
  if(!recetaPickerOverlay) return Promise.resolve(null);
  // Ensure overlay is on top-level body to escape parent stacking and be above product modal
  try{
    if(!recetaPickerOverlay.__movedToBody){
      document.body.appendChild(recetaPickerOverlay);
      recetaPickerOverlay.__movedToBody = true;
    }
    recetaPickerOverlay.style.zIndex = '100005';
  }catch(_e){}
  try{ _recetaReturnFocusEl = document.activeElement; }catch(_e){}
  renderRecetaPicker('');
  recetaPickerOverlay.classList.remove('hidden');
  try{ recetaPickerOverlay.setAttribute('aria-hidden','false'); }catch(_e){}
  try{ recetaPickQuery.value=''; recetaPickQuery.focus(); }catch(_e){}
  return new Promise(resolve=>{ _recetaPickResolve = resolve; });
}
function closeRecetaPicker(result=null){
  try{ recetaPickQuery?.blur?.(); }catch(_e){}
  if(recetaPickerOverlay){
    recetaPickerOverlay.classList.add('hidden');
    try{ recetaPickerOverlay.setAttribute('aria-hidden','true'); }catch(_e){}
  }
  const resolver = _recetaPickResolve;
  _recetaPickResolve = null;
  if(typeof resolver === 'function'){
    try{ resolver(result); }catch(_e){}
  }
  try{ _recetaReturnFocusEl?.focus?.(); }catch(_e){}
}
function renderRecetaPicker(query){
  if(!recetaPickResultsBody) return;
  const q = String(query||'').trim().toLowerCase();
  const src = Array.isArray(window.products)? window.products : [];
  const rows = src
    .filter(p=> (__isTrue(p.esInsumo) || __isTrue(p.esConsumible)))
    // Ocultar productos inhabilitados/inactivos
    .filter(p=> String(p.estatus||'Activo').toLowerCase()==='activo')
    .filter(p=>{
      if(!q) return true;
      const code = String(p.codigoInterno||'').toLowerCase();
      const desc = String(p.descripcion||'').toLowerCase();
      return code.includes(q) || desc.includes(q);
    })
    .slice(0,200);
  const esc = s=> String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  recetaPickResultsBody.innerHTML = '';
  rows.forEach(p=>{
    const tr = document.createElement('tr');
    tr.className = 'row-hover';
    tr.style.cursor = 'pointer';
    tr.innerHTML = `
      <td style="padding:6px 10px;">${esc(p.codigoInterno||'')}</td>
      <td style="padding:6px 10px;">${esc(p.descripcion||'')}</td>
      <td style="padding:6px 10px;">${__isTrue(p.esConsumible)?'CONSUMIBLE':'INSUMO'}</td>
      <td style="padding:6px 10px;text-align:right;">${esc(p.existencias||0)}</td>
    `;
    tr.addEventListener('click', ()=>{
      closeRecetaPicker({ id: p.id||p._id, tipo: __isTrue(p.esConsumible)? 'CONSUMIBLE' : 'INSUMO', descripcion: p.descripcion||'' });
    });
    recetaPickResultsBody.appendChild(tr);
  });
}
if(recetaPickQuery){ recetaPickQuery.addEventListener('input', ()=> renderRecetaPicker(recetaPickQuery.value)); }
if(recetaPickCloseBtn){ recetaPickCloseBtn.addEventListener('click', ()=> closeRecetaPicker(null)); }
if(recetaPickCancelBtn){ recetaPickCancelBtn.addEventListener('click', ()=> closeRecetaPicker(null)); }

// Replace addReceta action to open picker and prefill selected component
if(addRecetaBtn){
  addRecetaBtn.removeEventListener?.('click', addReceta);
  addRecetaBtn.addEventListener('click', async ()=>{
    if(!recetaPickerOverlay){
      addReceta();
      return;
    }
    const picked = await openRecetaPicker();
    if(picked && picked.id){
      tempReceta.push({ productoId: String(picked.id), tipo: picked.tipo, cantidadPorUnidad: 1, wearPorUnidad: (picked.tipo==='CONSUMIBLE'?1:undefined) });
      renderReceta();
    }
  });
}

