function addExtra(){ tempExtras.push({ nombre:'', tipo:'fijo', precio:0, costo:0, unidadBase:1000 }); renderExtras(); }

function handleExtrasInputs(e){
  const t = e.target;
  if(!t) return;
  if((e.type==='input' || e.type==='change') && t.dataset && t.dataset.kind==='extra'){
    const idx = parseInt(t.dataset.idx);
    const field = t.dataset.field;
    if(!Number.isInteger(idx) || !tempExtras[idx]) return;
    if(field==='nombre') tempExtras[idx].nombre = t.value;
    else if(field==='tipo' && e.type==='change'){ tempExtras[idx].tipo = t.value; renderExtras(); return; }
  else if(field==='precio') tempExtras[idx].precio = t.value===''? undefined : (parseFloat(t.value)||0);
  else if(field==='costo') tempExtras[idx].costo = t.value===''? undefined : (parseFloat(t.value)||0);
    else if(field==='unidadBase') tempExtras[idx].unidadBase = t.value===''? undefined : (parseInt(t.value)||1000);
  }
}

if(extrasRows) extrasRows.addEventListener('input', (e)=>{ handleExtrasInputs(e); try{ updateMargenPreview(); }catch(_e){} });
if(extrasRows) extrasRows.addEventListener('change', (e)=>{ handleExtrasInputs(e); try{ updateMargenPreview(); }catch(_e){} });
// Click solo para eliminar filas, así evitamos re-render al abrir el select
if(extrasRows) extrasRows.addEventListener('click', (e)=>{
  const delBtn = e.target.closest('button[data-del="extra"]');
  if(delBtn){
    const idx = parseInt(delBtn.dataset.idx);
  if(Number.isInteger(idx)) { tempExtras.splice(idx,1); renderExtras(); try{ updateMargenPreview(); }catch(_e){} }
  }
});
if(addExtraBtn) addExtraBtn.addEventListener('click', ()=>{ addExtra(); try{ updateMargenPreview(); }catch(_e){} });

function renderVariantes(){
  if(!variantesRows) return;
  variantesRows.innerHTML = '';
  let selectedType = 'PRODUCTO';
  try { selectedType = getCatProductoSelectedType(); } catch(_e){}
  const isInsumo = String(selectedType).toUpperCase() === 'INSUMO';
  const canVenderBase = !!(catProductoPuedeVenderChk && catProductoPuedeVenderChk.checked);
  const canVenderPublico = !!(catProductoVentaPublicoChk && catProductoVentaPublicoChk.checked);
  const canCaptureVariantPrice = isInsumo ? canVenderPublico : canVenderBase;
  tempVariantes.forEach((v, i)=>{
    if(v && typeof v.autoCostoReceta === 'undefined') v.autoCostoReceta = true;
    if(!canCaptureVariantPrice && typeof v?.precio === 'number'){ tempVariantes[i].precio = undefined; }
    const row = document.createElement('div');
    row.style.display='grid';
    row.style.gridTemplateColumns='1fr 120px 160px 120px 40px';
    row.style.gap='8px';
    const costoVal = (typeof v?.costo === 'number' && Number.isFinite(v.costo)) ? v.costo : '';
    const precioVal = (typeof v?.precio === 'number' && Number.isFinite(v.precio) && canCaptureVariantPrice)? v.precio : '';
    const existVal = (typeof v?.existencias === 'number' && Number.isFinite(v.existencias)) ? v.existencias : 0;
    const precioPlaceholder = canCaptureVariantPrice ? '(opcional)' : 'No disponible';
    const precioDisabledAttr = canCaptureVariantPrice ? '' : 'disabled';
    const precioClass = canCaptureVariantPrice ? 'variant-price-input' : 'variant-price-input readonly';
    const autoCosto = v?.autoCostoReceta !== false;
    const costoClass = autoCosto ? 'variant-cost-input auto-receta' : 'variant-cost-input';
    row.innerHTML = `
      <input type="text" data-kind="var" data-idx="${i}" data-field="nombre" placeholder="Ej. Color Rojo" value="${(v.nombre||'').replace(/"/g,'&quot;')}">
      <input type="number" min="0" step="0.01" data-kind="var" data-idx="${i}" data-field="costo" placeholder="0" value="${costoVal}" class="${costoClass}" data-auto-receta="${autoCosto?'1':'0'}">
      <input type="number" min="0" step="0.01" data-kind="var" data-idx="${i}" data-field="precio" placeholder="${precioPlaceholder}" value="${precioVal}" class="${precioClass}" ${precioDisabledAttr}>
      <input type="number" min="0" step="1" data-kind="var" data-idx="${i}" data-field="existencias" placeholder="0" value="${existVal}">
      <button type="button" title="Eliminar" data-del="var" data-idx="${i}" class="btn-icon">✕</button>
    `;
    variantesRows.appendChild(row);
  });
  if(variantesEmpty) variantesEmpty.style.display = tempVariantes.length? 'none' : 'block';
  updateVariantExistenciaLock();
  applyVariantPriceCostLocks();
}

function addVariante(){ tempVariantes.push({nombre:'', precio: undefined, costo: undefined, existencias: 0, autoCostoReceta: true}); renderVariantes(); }

function handleVariantesInputs(e){
  const t = e.target;
  if(!t) return;
  if(t.dataset && t.dataset.kind==='var'){
    const idx = parseInt(t.dataset.idx);
    const field = t.dataset.field;
    if(!Number.isInteger(idx) || !tempVariantes[idx]) return;
    if(field==='nombre') tempVariantes[idx].nombre = t.value;
    else if(field==='costo'){
      if(t.value===''){
        tempVariantes[idx].costo = undefined;
        tempVariantes[idx].autoCostoReceta = true;
      } else {
        let next = parseFloat(t.value);
        if(!Number.isFinite(next) || next<0) next = 0;
        tempVariantes[idx].costo = next;
        tempVariantes[idx].autoCostoReceta = false;
        t.value = String(next);
      }
    }
    else if(field==='precio') tempVariantes[idx].precio = t.value===''? undefined : (parseFloat(t.value)||0);
    else if(field==='existencias'){
      let next = t.value===''
        ? 0
        : Number(t.value);
      if(!Number.isFinite(next) || next<0) next = 0;
      tempVariantes[idx].existencias = next;
      t.value = String(next);
      updateVariantExistenciaLock();
    }
  }
  const delBtn = t.closest('button[data-del="var"]');
  if(delBtn){ const idx = parseInt(delBtn.dataset.idx); if(Number.isInteger(idx)) { tempVariantes.splice(idx,1); renderVariantes(); } }
}

function updateVariantExistenciaLock(){
  const hasVariants = tempVariantes.length>0;
  const total = tempVariantes.reduce((sum, v)=> sum + (Number(v.existencias||0)||0), 0);
  if(catProductoExistenciasInput){
    if(hasVariants){
      catProductoExistenciasInput.disabled = true;
      catProductoExistenciasInput.classList.add('readonly');
      const totalVal = Number.isFinite(total)? total : 0;
      catProductoExistenciasInput.value = totalVal;
    } else {
      catProductoExistenciasInput.disabled = false;
      catProductoExistenciasInput.classList.remove('readonly');
    }
  }
  if(catProductoVariantExistNote){
    catProductoVariantExistNote.classList.toggle('hidden', !hasVariants);
    if(hasVariants){
      const totalVal = Number.isFinite(total)? total : 0;
      catProductoVariantExistNote.textContent = `Las existencias generales se calculan desde las variantes (total: ${totalVal}).`;
    } else {
      catProductoVariantExistNote.textContent = 'Las existencias generales se calculan desde las variantes.';
    }
  }
}

