function getFraccionadoBaseInputValue(){
  const raw = catProductoFraccionadoBaseInput ? Number(catProductoFraccionadoBaseInput.value) : 0;
  if(Number.isFinite(raw) && raw >= 2) return Math.floor(raw);
  return 1000;
}

function defaultFraccionadoTramos(base){
  const max = Math.max(2, base|0);
  const lastMax = Math.max(1, max - 1);
  return [
    { min:1, max:Math.min(99, lastMax), precio:0 },
    { min:Math.min(100, lastMax), max:Math.min(499, lastMax), precio:0 },
    { min:Math.min(500, lastMax), max:lastMax, precio:0 }
  ].filter(r=> r.min>=1 && r.min<=r.max);
}

function ensureFraccionadoConfigVisibility(){
  const enabled = !!(catProductoFraccionadoChk && catProductoFraccionadoChk.checked);
  if(catProductoFraccionadoConfig){
    catProductoFraccionadoConfig.classList.toggle('hidden', !enabled);
  }
  if(catProductoFraccionadoWrap){
    catProductoFraccionadoWrap.classList.toggle('fraccionado-enabled', enabled);
  }
  if(enabled && !tempPreciosFraccionados.length){
    tempPreciosFraccionados = defaultFraccionadoTramos(getFraccionadoBaseInputValue());
  }
  renderPreciosFraccionados();
}

function sanitizeFraccionadoRanges(base){
  const max = Math.max(2, base|0);
  tempPreciosFraccionados = tempPreciosFraccionados.map(r=>{
    const min = Math.max(1, Number(r?.min)||0);
    let maxVal = Number(r?.max)||0;
    if(!Number.isFinite(maxVal) || maxVal < min) maxVal = min;
    if(maxVal >= max) maxVal = max - 1;
    const precio = Number(r?.precio)||0;
    return { min, max: maxVal, precio };
  });
}

function renderPreciosFraccionados(){
  if(!catProductoFraccionadoTable) return;
  const tbody = catProductoFraccionadoTable.querySelector('tbody');
  if(tbody) tbody.innerHTML='';
  const list = tempPreciosFraccionados.slice().map(r=>({
    min: Math.max(1, Number(r?.min)||0),
    max: Math.max(Math.max(1, Number(r?.min)||0), Number(r?.max)||0),
    precio: Number(r?.precio)||0
  })).sort((a,b)=> a.min - b.min);
  tempPreciosFraccionados = list;
  if(!tbody) return;
  list.forEach((r,i)=>{
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td><input type="number" min="1" step="1" data-kind="frac" data-idx="${i}" data-field="min" value="${r.min}" style="width:70px;"></td>
      <td><input type="number" min="1" step="1" data-kind="frac" data-idx="${i}" data-field="max" value="${r.max}" style="width:80px;"></td>
      <td><input type="number" min="0" step="0.01" data-kind="frac" data-idx="${i}" data-field="precio" value="${r.precio}" style="width:120px;"></td>
      <td><button type="button" class="mini-btn" data-del="frac" data-idx="${i}">🗑️</button></td>`;
    tbody.appendChild(tr);
  });
  if(catProductoFraccionadoEmpty){
    catProductoFraccionadoEmpty.style.display = list.length ? 'none' : 'block';
  }
}

function addFraccionadoRange(){
  const base = getFraccionadoBaseInputValue();
  const sorted = tempPreciosFraccionados.slice().sort((a,b)=> a.min - b.min);
  const last = sorted[sorted.length-1];
  const nextMin = last ? Math.max(last.max + 1, 1) : 1;
  if(nextMin >= base){
    notify('No hay espacio para un tramo adicional debajo del millar.','info');
    return;
  }
  const newRange = { min: nextMin, max: base - 1, precio:0 };
  tempPreciosFraccionados.push(newRange);
  renderPreciosFraccionados();
}

function handleFraccionadoInputs(e){
  const target = e.target;
  let skipRender = e.type === 'input';
  if(target && target.matches('input[data-kind="frac"]')){
    const idx = parseInt(target.dataset.idx,10);
    const field = target.dataset.field;
    if(Number.isInteger(idx) && tempPreciosFraccionados[idx]){
      const raw = target.value;
      const val = raw === '' ? NaN : Number(raw);
      if(field === 'min'){
        if(Number.isFinite(val)) tempPreciosFraccionados[idx].min = val;
      } else if(field === 'max'){
        if(Number.isFinite(val)) tempPreciosFraccionados[idx].max = val;
      } else if(field === 'precio'){
        if(Number.isFinite(val)) tempPreciosFraccionados[idx].precio = val;
        skipRender = true;
      }
    }
  }
  const delBtn = target?.closest('button[data-del="frac"]');
  if(delBtn){
    const idx = parseInt(delBtn.dataset.idx,10);
    if(Number.isInteger(idx)) tempPreciosFraccionados.splice(idx,1);
    skipRender = false;
  }
  if(!skipRender){
    sanitizeFraccionadoRanges(getFraccionadoBaseInputValue());
    renderPreciosFraccionados();
  }
}

function validateFraccionadoRanges(base){
  const max = Math.max(2, base|0);
  const ranges = tempPreciosFraccionados.slice().map(r=>({
    min: Math.max(1, Number(r?.min)||0),
    max: Math.max(1, Number(r?.max)||0),
    precio: Number(r?.precio)||0
  })).sort((a,b)=> a.min - b.min);
  if(!ranges.length){
    return { ok:false, message:'Configura al menos un rango de precios por pieza.' };
  }
  let prevMax = 0;
  for(const r of ranges){
    if(r.min > r.max){
      return { ok:false, message:`El tramo ${r.min}-${r.max} no es válido (mínimo mayor que máximo).` };
    }
    if(r.max >= max){
      return { ok:false, message:`Los tramos deben ser menores a ${max} piezas (millar completo).` };
    }
    if(r.min <= prevMax){
      return { ok:false, message:'Los tramos fraccionados no pueden traslaparse. Ajusta los rangos.' };
    }
    prevMax = r.max;
  }
  return { ok:true, ranges };
}

