// Helpers para máquinas en selects
function fillMaquinasSelect(selectEl){
  try{
    if(!selectEl) return; selectEl.innerHTML='<option value="">SIN VINCULAR</option>';
    const list = Array.isArray(window.maquinasState)? window.maquinasState : [];
    list.forEach(m=>{ const opt=document.createElement('option'); opt.value=m.id; opt.textContent=m.nombre||m.id; selectEl.appendChild(opt); });
  }catch(_e){}
}
function fillContadoresForSelected(maqSel, contSel){
  try{
    if(!contSel) return; contSel.innerHTML='<option value="">(primero de la máquina)</option>';
    const mId = maqSel && maqSel.value; if(!mId) return;
    const list = Array.isArray(window.maquinasState)? window.maquinasState : [];
    const m = list.find(x=> x.id===mId);
    if(!m || !Array.isArray(m.contadores)) return;
    m.contadores.forEach(c=>{ const opt=document.createElement('option'); opt.value=c.id; opt.textContent=c.descripcion||c.id; contSel.appendChild(opt); });
  }catch(_e){}
}
