function handleCatProductosTableClick(e){
  const tr = e.target.closest('tr');
  if(tr && tr.dataset && tr.dataset.id){
    catProdState.selectedId = tr.dataset.id;
    // aplicar selección visual sin esperar re-render
    document.querySelectorAll('#catProductosBody tr').forEach(r=> r.classList.remove('row-selected'));
    tr.classList.add('row-selected');
  }
  const btn = e.target.closest('button[data-action]'); if(!btn) return;
  const action = btn.dataset.action;
  // Toggle row menu
  if(action==='menu'){
    const wrapper = btn.closest('.row-actions');
    if(!wrapper) return;
    // Close any other open menus
    document.querySelectorAll('#catProductosBody .row-menu').forEach(m=>{ if(m!==wrapper.querySelector('.row-menu')) m.classList.add('hidden'); });
    const menu = wrapper.querySelector('.row-menu');
    if(menu) menu.classList.toggle('hidden');
  return;
  }
  const id = btn.dataset.id || (btn.closest('.row-actions') && btn.closest('.row-actions').dataset.id) || (btn.closest('tr') && btn.closest('tr').dataset.id);
  const remote = (window.products||[]).find(p=> p._id===id);
  if(action==='edit' && remote){
      // Close any open menu
      document.querySelectorAll('#catProductosBody .row-menu').forEach(m=> m.classList.add('hidden'));
      // Abrir modal y dejar que se rellene con openCatProductoModal
      openCatProductoModal(remote._id);
  } else if(action==='delete' && remote){
    confirmAction('¿Deshabilitar producto?').then(ok=>{
      if(!ok) return;
      if(window._firebaseReady && window.firebaseApi){
        window.firebaseApi.updateProducto(id, { estatus:'Inactivo' })
          .then(()=> notify('Producto deshabilitado','info'))
          .catch(err=>{ console.warn('Error deshabilitando', err); notify('No se pudo deshabilitar','err'); });
      }
    });
  } else if(action==='enable' && remote){
    if(window._firebaseReady && window.firebaseApi){
      window.firebaseApi.updateProducto(id, { estatus:'Activo' })
        .then(()=> notify('Producto habilitado','ok'))
        .catch(err=> notify('No se pudo habilitar','err'));
    }
  }
}

// Cerrar menús de fila al hacer click fuera
document.addEventListener('click', (e)=>{
  const isInRowActions = e.target.closest && e.target.closest('.row-actions');
  const isInCatalogTable = e.target.closest && e.target.closest('#catProductosTable');
  if(!isInRowActions){
    document.querySelectorAll('#catProductosBody .row-menu').forEach(m=> m.classList.add('hidden'));
  }
  // limpiar selección si clic afuera de la tabla
  if(!isInCatalogTable){
    catProdState.selectedId = null;
    document.querySelectorAll('#catProductosBody tr').forEach(r=> r.classList.remove('row-selected'));
  }
});

function exportCatProductos(){
  const list = Array.isArray(window.products) ? window.products : [];
  if(!list.length){ notify('No hay productos','info'); return; }
  exportToExcel({
    filename:'productos_catalogo.xls',
    headers:['Código','Descripcion','Categoria','Proveedor','Unidad','PuedeComprar','PuedeFabricar','PuedeVender','Precio','Costo','Ganancia','Margen%','Inventario','StockMin','Existencias','Estatus'],
  rows: list.map(p=>{ const precio = (typeof p.precio==='number'? p.precio : (p.precioPublico||0)); const isServ = __isTrue(p.esServicio); const isCons = __isTrue(p.esConsumible); const costo = isServ? 0 : (p.costo||0); const ganancia = isCons ? null : (precio - costo); const margen = isCons ? null : (isServ? 100 : (costo>0? ((precio-costo)/costo*100):0)); return [p.codigoInterno||'',p.descripcion,p.categoria||'',p.proveedor||'',p.unidad||'',(p.puedeComprar? 'SI':'NO'),(p.puedeFabricar? 'SI':'NO'),(productoSePuedeVender(p)? 'SI':'NO'), (isCons?'NO INCLUYE':precio.toFixed(2)), costo.toFixed(2), (isCons?'NO INCLUYE':(ganancia||0).toFixed(2)), (isCons?'NO INCLUYE':(margen||0).toFixed(1)), p.inventario||'',p.stockMin||0,p.existencias||0,p.estatus||'']; })
  });
}

