// Delegación cambios y deletes
function handlePreciosInputs(e){
  const inp = e.target;
  if(inp.matches('input[data-kind]')){
    const kind = inp.dataset.kind; const idx = parseInt(inp.dataset.idx); const field = inp.dataset.field;
  if(kind==='mpub' && tempMayoristasPublico[idx]) tempMayoristasPublico[idx][field] = field==='min'? parseInt(inp.value)||1 : parseFloat(inp.value)||0;
    else if(kind==='esp' && tempPreciosEspeciales[idx]) tempPreciosEspeciales[idx][field] = field==='nombre'? inp.value : parseFloat(inp.value)||0;
  }
  const delBtn = inp.closest('button[data-del]');
  if(delBtn){
    const kind = delBtn.dataset.del; const idx = parseInt(delBtn.dataset.idx);
  if(kind==='mpub') tempMayoristasPublico.splice(idx,1);
  else if(kind==='esp') tempPreciosEspeciales.splice(idx,1);
    renderPreciosTablas();
  }
}
