function fillCatProductosFilterOptions(){
  try{
    if(filterCatProductosCategoria){
      // recolectar categorías desde window.categorias activas; fallback a productos si vacío
      const catsSrc = Array.isArray(window.categorias)? window.categorias.filter(c=> String(c.estatus||'Activa').toLowerCase()==='activa').map(c=> String(c.nombre||'').trim()).filter(Boolean) : [];
      const fromProducts = Array.isArray(window.products)? Array.from(new Set(window.products.map(p=> String(p.categoria||'').trim()).filter(Boolean))) : [];
      const all = Array.from(new Set([ ...catsSrc, ...fromProducts ])).sort((a,b)=> a.localeCompare(b));
      const current = filterCatProductosCategoria.value || '';
      filterCatProductosCategoria.innerHTML = ['<option value="">Todas</option>', ...all.map(n=> `<option value="${n.replace(/"/g,'&quot;')}">${n}</option>`)].join('');
      // restaurar selección si aún existe
      if(current && all.includes(current)) filterCatProductosCategoria.value = current; else if(!all.includes(current)) filterCatProductosCategoria.value = '';
    }
  }catch(_e){}
}

