// Infinite scroll para catálogo productos
(function initCatProdInfinite(){
  const sentinel = document.getElementById('catProductosSentinel');
  if(!sentinel || !('IntersectionObserver' in window)) return;
  const root = document.getElementById('catProductosScrollWrap') || document.querySelector('#cat-productos-section .table-container');
  const obs = new IntersectionObserver((entries)=>{
    const e = entries[0]; if(!e.isIntersecting) return;
    const max = Number(sentinel.dataset.max||'0');
    if(catProdState.visible < max){ catProdState.visible += 50; renderCatProductosTable(); }
  }, { root, rootMargin: '0px 0px 200px 0px', threshold: 0 });
  obs.observe(sentinel);
})();

// Teclas PageUp/PageDown/Home/End en catálogo productos
(function initCatProdKeys(){
  const wrap = document.getElementById('catProductosScrollWrap'); if(!wrap) return;
  wrap.addEventListener('keydown', (e)=>{
    // Solo flechas izquierda/derecha moverán horizontalmente.
    if(e.key === 'ArrowLeft'){
      e.preventDefault();
  const target = 0;
  wrap.scrollTo({ left: target, behavior: 'smooth' });
      return;
    }
    if(e.key === 'ArrowRight'){
      e.preventDefault();
  const target = Math.max(0, (wrap.scrollWidth - wrap.clientWidth));
  wrap.scrollTo({ left: target, behavior: 'smooth' });
      return;
    }
    // Bloquear desplazamiento vertical por teclado en este contenedor
    if(e.key === 'ArrowUp' || e.key === 'ArrowDown' || e.key === 'PageUp' || e.key === 'PageDown' || e.key === 'Home' || e.key === 'End'){
      e.preventDefault();
      return;
    }
  });
})();

// Flechas izquierda/derecha globales para cualquier sección visible (sin necesidad de enfocar)
(function initGlobalTableArrows(){
  document.addEventListener('keydown', (e)=>{
    if(e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
    // Evitar interferir cuando se escribe/edita en inputs o campos editables
    const ae = document.activeElement;
    const tag = (ae && ae.tagName) || '';
    const isEditable = (ae && (ae.isContentEditable || ['INPUT','TEXTAREA','SELECT'].includes(tag)));
    if(isEditable) return;
    // Encontrar la sección visible principal
    const activeSection = document.querySelector('.generic-section:not(.hidden)')
      || document.querySelector('section:not(.hidden)')
      || document.body;
    // Buscar contenedores de tabla dentro de la sección visible
    const candidates = Array.from(activeSection.querySelectorAll('.table-container, .hscroll-visible'));
    // Elegir el primer contenedor que realmente tenga overflow horizontal; si no, el primero
    let scroller = candidates.find(n => (n.scrollWidth - n.clientWidth) > 2) || candidates[0];
    // Si no encontramos dentro de la sección, buscar global
    if(!scroller){
      scroller = document.querySelector('.table-container.hscroll-visible, .hscroll-visible');
    }
    if(!scroller) return;
    e.preventDefault();
    const target = (e.key === 'ArrowLeft') ? 0 : Math.max(0, scroller.scrollWidth - scroller.clientWidth);
    scroller.scrollTo({ left: target, behavior: 'smooth' });
  });
})();

// Genérico: mismas interacciones para todas las tablas
(function initGenericTablesUX(){
  try{
    // Consider both outer table containers and inner wrappers that handle overflow
    const nodes = Array.from(document.querySelectorAll('.table-container, .hscroll-visible'));
    const seen = new Set();
    const containers = nodes.filter(n=>{ if(seen.has(n)) return false; seen.add(n); return true; });
    containers.forEach(wrap=>{
  // Asegurar estilo de scrollbar visible
  wrap.classList?.add('hscroll-visible');
      // Asegurar enfoque para recibir teclas
      if(!wrap.hasAttribute('tabindex')) wrap.tabIndex = 0;
      // Quitar soporte a flechas overlay (navegación horizontal solo con teclado)
      // Bloquear scroll horizontal con la rueda del mouse; forzar vertical solo en el contenedor scroller
      wrap.addEventListener('wheel', (e)=>{
        // Determinar elemento scroller (priorizar el que realmente desborda horizontalmente)
        const inner = wrap.querySelector('.hscroll-visible, .h-scroll, [style*="overflow-x"]');
        const scroller = (wrap.scrollWidth > wrap.clientWidth) ? wrap : (inner || wrap);
        const toPx = (d)=> e.deltaMode === 1 ? d * 16 : d;
        const dx = toPx(e.deltaX||0);
        const dy = toPx(e.deltaY||0);
        const canScrollVert = (scroller.scrollHeight - scroller.clientHeight) > 1;
        // Bloquear cualquier intento horizontal dentro del contenedor
        if (Math.abs(dx) > 0) { e.preventDefault(); return; }
        // Consumir y aplicar solo vertical si el contenedor puede desplazarse verticalmente
        if (canScrollVert) {
          e.preventDefault();
          scroller.scrollTop += dy;
        }
        // Si no puede desplazar vertical, permitir que el scroll siga a la página
      }, { passive: false });
      // Solo mover horizontal con flechas izq/der si el foco está en el contenedor
      wrap.addEventListener('keydown', (e)=>{
        const tag = (document.activeElement && document.activeElement.tagName) || '';
        const isEditable = (document.activeElement && (document.activeElement.isContentEditable || ['INPUT','TEXTAREA','SELECT'].includes(tag)));
        if(isEditable) return;
        // Determinar elemento scroller objetivo
        const inner = wrap.querySelector('.hscroll-visible, .h-scroll, [style*="overflow-x"]');
        const scroller = (wrap.scrollWidth > wrap.clientWidth) ? wrap : (inner || wrap);
        if(e.key === 'ArrowLeft'){
          e.preventDefault(); scroller.scrollTo({ left: 0, behavior: 'smooth' });
        } else if(e.key === 'ArrowRight'){
          e.preventDefault(); scroller.scrollTo({ left: Math.max(0, scroller.scrollWidth - scroller.clientWidth), behavior: 'smooth' });
        }
      });
      // Selección persistente por fila
      const table = wrap.querySelector('table'); if(!table) return;
      const tbody = table.querySelector('tbody') || table;
      tbody.addEventListener('click', (e)=>{
        const tr = e.target.closest('tr'); if(!tr) return;
        // Visual: resaltar solo la fila de este tbody
        tbody.querySelectorAll('tr.row-selected').forEach(r=> r.classList.remove('row-selected'));
        tr.classList.add('row-selected');
      });
    });
    // Limpiar selección si clic fuera de cualquier tabla
    document.addEventListener('click', (e)=>{
      const insideAnyTable = e.target.closest && e.target.closest('.table-container table');
      if(!insideAnyTable){ document.querySelectorAll('table tbody tr.row-selected').forEach(r=> r.classList.remove('row-selected')); }
    });
  }catch(_e){}
})();

// Bloqueo global de scroll horizontal: dentro de contenedores de tabla, la rueda solo mueve vertical
(function enforceVerticalWheelOnly(){
  const toPx = (delta, mode)=> mode === 1 ? delta * 16 : delta; // 1=line, 0=pixel
  document.addEventListener('wheel', (e)=>{
    // Solo si el evento ocurre dentro de un contenedor de tabla conocido
    const container = e.target && e.target.closest && e.target.closest('.hscroll-visible, .table-container');
    if(!container) return;
    // Determinar scroller efectivo (inner wrapper si existe)
    const inner = container.querySelector('.hscroll-visible, .h-scroll, [style*="overflow-x"]');
    const scroller = (container.scrollWidth > container.clientWidth) ? container : (inner || container);
    const canScrollVert = (scroller.scrollHeight - scroller.clientHeight) > 1;
    const hasHoriz = (scroller.scrollWidth - scroller.clientWidth) > 1;
    const dy = toPx(e.deltaY, e.deltaMode);
    const dx = toPx(e.deltaX, e.deltaMode);
    // Si hay intento horizontal (dx != 0) dentro de la tabla, bloquear siempre
    if(hasHoriz && Math.abs(dx) > 0){ e.preventDefault(); return; }
    // Si hay desplazamiento vertical disponible, consumirlo y aplicarlo solo al scroller
    if(canScrollVert){
      e.preventDefault();
      scroller.scrollTop += dy;
    }
  }, { passive: false, capture: true });
})();

// Toggle de UI cuando es servicio
function applyServicioToggle(on){
  if(!on){
    // No reset here to avoid re-habilitating controles cuando cambia a otro tipo;
    // los otros toggles se encargan al activarse.
    return;
  }
  // Abastecimiento: solo se puede vender (mostrar grupo, bloquear estados)
  if(catProductoPuedeComprarChk) { catProductoPuedeComprarChk.checked = false; catProductoPuedeComprarChk.disabled = !!on; }
  if(catProductoPuedeFabricarChk){ catProductoPuedeFabricarChk.checked = false; catProductoPuedeFabricarChk.disabled = !!on; }
  if(catProductoPuedeVenderChk){ catProductoPuedeVenderChk.checked = true; catProductoPuedeVenderChk.disabled = !!on; }
  if(catProductoChkInventario){ catProductoChkInventario.checked = !on; catProductoChkInventario.disabled = !!on; }
  if(catProductoExistenciasInput){ catProductoExistenciasInput.value = on? 0 : catProductoExistenciasInput.value; catProductoExistenciasInput.disabled = !!on; }
  if(catProductoStockMinInput){ catProductoStockMinInput.value = on? 0 : catProductoStockMinInput.value; catProductoStockMinInput.disabled = !!on; }
  // Ocultar grupos completos
  // Grupo Abastecimiento (mantener visible en servicios para mostrar bloqueo)
  const abastecimientoGroup = catProductoPuedeComprarChk && catProductoPuedeComprarChk.closest('.form-group');
  if(abastecimientoGroup) abastecimientoGroup.classList.remove('hidden');
  // Fieldset Inventario completo (usa legend "Inventario")
  const inventarioFieldset = document.querySelector('#catProductoForm fieldset.form-block:nth-of-type(3)');
  if(inventarioFieldset) inventarioFieldset.classList.toggle('hidden', !!on);
  // Costo: ocultarlo si es servicio
  const costoGroup = catProductoCostoInput && catProductoCostoInput.closest('.form-group');
  if(costoGroup) costoGroup.classList.toggle('hidden', !!on);
  // Ubicación: ocultar y deshabilitar en servicios
  const ubicacionGroup = catProductoUbicacionInput && catProductoUbicacionInput.closest('.form-group');
  if(ubicacionGroup) ubicacionGroup.classList.toggle('hidden', !!on);
  if(catProductoUbicacionInput){
    if(on) catProductoUbicacionInput.value = '';
    catProductoUbicacionInput.disabled = !!on;
  }
  // Ocultar margen estimado en servicios
  const margenInputSrv = document.getElementById('catProductoMargenPreview');
  const margenGroupSrv = margenInputSrv && margenInputSrv.closest('.form-group');
  if(margenGroupSrv) margenGroupSrv.classList.add('hidden');
  if(margenInputSrv) margenInputSrv.disabled = true;
  // Proveedor: ocultar y deshabilitar en servicios
  const proveedorGroup = catProductoProveedorInput && catProductoProveedorInput.closest('.form-group');
  if(proveedorGroup) proveedorGroup.classList.toggle('hidden', !!on);
  if(catProductoProveedorInput){
    if(on) catProductoProveedorInput.value = '';
    catProductoProveedorInput.disabled = !!on;
  }
  // Ajustes de proporción: visibles y habilitados en servicios por si se cobra por m² como servicio
  const ajusteGroupSrv = catProductoAjusteMenor1Input && catProductoAjusteMenor1Input.closest('.form-group');
  if(ajusteGroupSrv) ajusteGroupSrv.classList.remove('hidden');
  // Mostrar Ganancia en servicios (no ocultarla aquí)
  const gananciaInputSrv = document.getElementById('catProductoGananciaPreview');
  const gananciaGroupSrv = gananciaInputSrv && gananciaInputSrv.closest('.form-group');
  if(gananciaGroupSrv) gananciaGroupSrv.classList.remove('hidden');
  if(gananciaInputSrv) gananciaInputSrv.disabled = false;
  // En servicios el costo es 0 (la ganancia es todo el precio)
  if(on && catProductoCostoInput){
    catProductoCostoInput.value = (0).toFixed(2);
  }
  syncMedidasControls();
  updateMargenPreview();
}

// Toggle de UI cuando es insumo (insumos no se venden y no tienen precio de venta)
function syncInsumoVentaPublicoControls(){
  const isInsumoActive = !!(catProductoTipoInsumo && catProductoTipoInsumo.checked);
  if(!isInsumoActive) return;
  const ventaPubOn = !!(catProductoVentaPublicoChk && catProductoVentaPublicoChk.checked);
  const precioPubGroup = catProductoPrecioPublicoInput && catProductoPrecioPublicoInput.closest('.form-group');
  if(precioPubGroup) precioPubGroup.classList.toggle('hidden', !ventaPubOn);
  if(catProductoPrecioPublicoInput){
    catProductoPrecioPublicoInput.disabled = !ventaPubOn;
    if(!ventaPubOn) catProductoPrecioPublicoInput.value = 0;
  }
  const margenInput = document.getElementById('catProductoMargenPreview');
  const margenGroup = margenInput && margenInput.closest('.form-group');
  if(margenGroup) margenGroup.classList.toggle('hidden', !ventaPubOn);
  if(margenInput){
    margenInput.disabled = !ventaPubOn;
    if(!ventaPubOn) margenInput.value = '';
  }
  const ganInput = document.getElementById('catProductoGananciaPreview');
  const ganGroup = ganInput && ganInput.closest('.form-group');
  if(ganGroup) ganGroup.classList.toggle('hidden', !ventaPubOn);
  if(ganInput){
    ganInput.disabled = !ventaPubOn;
    if(!ventaPubOn) ganInput.value = '';
  }
  const escalasSwitchGroup = activarEscalasMayoreoChk && activarEscalasMayoreoChk.closest('.form-group');
  if(escalasSwitchGroup) escalasSwitchGroup.classList.toggle('hidden', !ventaPubOn);
  if(activarEscalasMayoreoChk){
    if(!ventaPubOn){
      activarEscalasMayoreoChk.checked = false;
      activarEscalasMayoreoChk.disabled = true;
      if(contenedorEscalasMayoreo) contenedorEscalasMayoreo.classList.add('hidden');
    } else {
      activarEscalasMayoreoChk.disabled = false;
    }
  }
}

function applyInsumoToggle(on){
  if(catProductoVentaPublicoWrap){ catProductoVentaPublicoWrap.classList.toggle('hidden', !on); }
  if(catProductoVentaPublicoChk){
    catProductoVentaPublicoChk.disabled = !on;
    if(!on){ catProductoVentaPublicoChk.checked = false; }
  }
  if(!on){
    const precioPubGroup = catProductoPrecioPublicoInput && catProductoPrecioPublicoInput.closest('.form-group');
    if(precioPubGroup) precioPubGroup.classList.remove('hidden');
    if(catProductoPrecioPublicoInput) catProductoPrecioPublicoInput.disabled = false;
    const margenInput = document.getElementById('catProductoMargenPreview');
    const margenGroup = margenInput && margenInput.closest('.form-group');
    if(margenGroup) margenGroup.classList.remove('hidden');
    if(margenInput) margenInput.disabled = false;
    const ganInput = document.getElementById('catProductoGananciaPreview');
    const ganGroup = ganInput && ganInput.closest('.form-group');
    if(ganGroup) ganGroup.classList.remove('hidden');
    if(ganInput) ganInput.disabled = false;
    const escalasSwitchGroup = activarEscalasMayoreoChk && activarEscalasMayoreoChk.closest('.form-group');
    if(escalasSwitchGroup) escalasSwitchGroup.classList.remove('hidden');
    if(activarEscalasMayoreoChk) activarEscalasMayoreoChk.disabled = false;
    updateMargenPreview();
    return;
  }
  syncInsumoVentaPublicoControls();
  // Asegurar que la sección de Costo esté visible y habilitada en INSUMO
  const costoGroupOnInsumo = catProductoCostoInput && catProductoCostoInput.closest('.form-group');
  if(costoGroupOnInsumo) costoGroupOnInsumo.classList.remove('hidden');
  if(catProductoCostoInput) catProductoCostoInput.disabled = false;
  // Insumo ON: ocultar "Enviar a producción"
  if(catProductoChkProduccion){
    catProductoChkProduccion.checked = false;
    catProductoChkProduccion.disabled = true;
    const produccionGroup = catProductoChkProduccion.closest('.form-group');
    if(produccionGroup) produccionGroup.classList.add('hidden');
  }
  if(catProductoSucursalProduccionSelect){
    catProductoSucursalProduccionSelect.value = '';
    catProductoSucursalProduccionSelect.classList.add('hidden');
    catProductoSucursalProduccionSelect.disabled = true;
  }
  // Abastecimiento visible y bloqueado: solo comprar activo
  const abastecimientoGroupIns = catProductoPuedeComprarChk && catProductoPuedeComprarChk.closest('.form-group');
  if(abastecimientoGroupIns) abastecimientoGroupIns.classList.remove('hidden');
  if(catProductoPuedeComprarChk){ catProductoPuedeComprarChk.checked = true; catProductoPuedeComprarChk.disabled = true; }
  if(catProductoPuedeFabricarChk){ catProductoPuedeFabricarChk.checked = false; catProductoPuedeFabricarChk.disabled = true; }
  if(catProductoPuedeVenderChk){ catProductoPuedeVenderChk.checked = false; catProductoPuedeVenderChk.disabled = true; }
  syncMedidasControls({ resetProporcional: true, resetLineal: true });
  updateMargenPreview();
}

// Toggle de UI cuando es consumible (no se vende, sin precios de venta, puede manejar inventario)
function applyConsumibleToggle(on){
  // Ya no forzar vender/comprar/fabricar aquí
  // Asegurar que la sección de Costo esté visible y habilitada en CONSUMIBLE
  const costoGroupOnCons = catProductoCostoInput && catProductoCostoInput.closest('.form-group');
  if(costoGroupOnCons) costoGroupOnCons.classList.remove('hidden');
  if(catProductoCostoInput) catProductoCostoInput.disabled = false;
  // Consumible: ocultar "Enviar a producción"
  if(catProductoChkProduccion){
    catProductoChkProduccion.checked = false;
    catProductoChkProduccion.disabled = !!on;
    const produccionGroup = catProductoChkProduccion.closest('.form-group');
    if(produccionGroup) produccionGroup.classList.toggle('hidden', !!on);
  }
  if(catProductoSucursalProduccionSelect){
    catProductoSucursalProduccionSelect.value = '';
    catProductoSucursalProduccionSelect.classList.add('hidden');
    catProductoSucursalProduccionSelect.disabled = !!on;
  }
  // Mostrar SIEMPRE el grupo Abastecimiento (comprar/fabricar/vender) en Consumibles
  const abastecimientoGroupCons = catProductoPuedeComprarChk && catProductoPuedeComprarChk.closest('.form-group');
  if(abastecimientoGroupCons) abastecimientoGroupCons.classList.remove('hidden');
  // Reglas de abastecimiento para CONSUMIBLE: solo se puede comprar (de ley)
  if(on){
    if(catProductoPuedeComprarChk){ catProductoPuedeComprarChk.checked = true; catProductoPuedeComprarChk.disabled = true; }
    if(catProductoPuedeFabricarChk){ catProductoPuedeFabricarChk.checked = false; catProductoPuedeFabricarChk.disabled = true; }
    if(catProductoPuedeVenderChk){ catProductoPuedeVenderChk.checked = false; catProductoPuedeVenderChk.disabled = true; }
  }
  // Ocultar/inhabilitar campos de precios de venta
  const precioPubGroup = catProductoPrecioPublicoInput && catProductoPrecioPublicoInput.closest('.form-group');
  if(precioPubGroup) precioPubGroup.classList.toggle('hidden', !!on);
  if(catProductoPrecioPublicoInput){ catProductoPrecioPublicoInput.value = on? 0 : catProductoPrecioPublicoInput.value; catProductoPrecioPublicoInput.disabled = !!on; }
  // Ocultar margen estimado
  const margenInput = document.getElementById('catProductoMargenPreview');
  const margenGroup = margenInput && margenInput.closest('.form-group');
  if(margenGroup) margenGroup.classList.add('hidden');
  if(margenInput){ margenInput.disabled = true; margenInput.value=''; }
  // Ocultar Ganancia
  const ganInput = document.getElementById('catProductoGananciaPreview');
  const ganGroup = ganInput && ganInput.closest('.form-group');
  if(ganGroup) ganGroup.classList.toggle('hidden', !!on);
  if(ganInput){ ganInput.disabled = !!on; if(on) ganInput.value=''; }
  // Escalas mayoreo ocultas
  const escalasSwitchGroup = activarEscalasMayoreoChk && activarEscalasMayoreoChk.closest('.form-group');
  if(escalasSwitchGroup) escalasSwitchGroup.classList.toggle('hidden', !!on);
  if(activarEscalasMayoreoChk){ activarEscalasMayoreoChk.checked = false; activarEscalasMayoreoChk.disabled = !!on; }
  if(contenedorEscalasMayoreo){ contenedorEscalasMayoreo.classList.add('hidden'); }
  // Ocultar ajuste por medidas mínimas (lonas y viniles) para consumibles
  const ajusteGroup = catProductoAjusteMenor1Input && catProductoAjusteMenor1Input.closest('.form-group');
  if(ajusteGroup) ajusteGroup.classList.toggle('hidden', !!on);
  if(catProductoAjusteMenor1Input){ catProductoAjusteMenor1Input.disabled = !!on; if(on) catProductoAjusteMenor1Input.value = 'none'; }
  if(catProductoAjusteMayor1Input){ catProductoAjusteMayor1Input.disabled = !!on; if(on) catProductoAjusteMayor1Input.value = 'none'; }
  // Consumible: inventario permitido (no tocar check de inventario aquí; se maneja en reset y payload)
  syncMedidasControls({ resetProporcional: !!on, resetLineal: !!on });
  updateMargenPreview();
}

// Toggle de UI cuando es producto: forzar 'se puede vender'
function applyProductoToggle(on){
  if(!on) return;
  // Ya no forzar ni ocultar controles de abastecimiento (vender/comprar/fabricar)
  // Para PRODUCTO: mostrar Abastecimiento y bloquear: solo vender activo
  const abastecimientoGroupProd = catProductoPuedeComprarChk && catProductoPuedeComprarChk.closest('.form-group');
  if(abastecimientoGroupProd) abastecimientoGroupProd.classList.remove('hidden');
  // Dejar COMPRAR/FABRICAR libres para el usuario (no forzar checked), pero bloquear VENDER en true
  if(catProductoPuedeComprarChk){ catProductoPuedeComprarChk.disabled = false; }
  if(catProductoPuedeFabricarChk){ catProductoPuedeFabricarChk.disabled = false; }
  if(catProductoPuedeVenderChk){ catProductoPuedeVenderChk.checked = true; catProductoPuedeVenderChk.disabled = true; }
  // Asegurar que el ajuste por medidas vuelva a mostrarse y habilitarse en PRODUCTO
  const ajusteGroup = catProductoAjusteMenor1Input && catProductoAjusteMenor1Input.closest('.form-group');
  if(ajusteGroup) ajusteGroup.classList.remove('hidden');
  // Asegurar que la sección de Costo esté visible y habilitada en PRODUCTO
  const costoGroupOnProd = catProductoCostoInput && catProductoCostoInput.closest('.form-group');
  if(costoGroupOnProd) costoGroupOnProd.classList.remove('hidden');
  if(catProductoCostoInput) catProductoCostoInput.disabled = false;
  syncMedidasControls();
}

// Escuchar cambios del checkbox servicio
function onTipoChange(){
  const servOn = !!(catProductoTipoServicio && catProductoTipoServicio.checked);
  const insOn = !!(catProductoTipoInsumo && catProductoTipoInsumo.checked);
  const consOn = !!(catProductoTipoConsumible && catProductoTipoConsumible.checked);
  // Normalizar selección exclusiva visualmente
  if(servOn && catProductoTipoInsumo) catProductoTipoInsumo.checked = false;
  if(servOn && catProductoTipoConsumible) catProductoTipoConsumible.checked = false;
  if(insOn && catProductoTipoServicio) catProductoTipoServicio.checked = false;
  if(insOn && catProductoTipoConsumible) catProductoTipoConsumible.checked = false;
  if(consOn && catProductoTipoServicio) catProductoTipoServicio.checked = false;
  if(consOn && catProductoTipoInsumo) catProductoTipoInsumo.checked = false;
  const newType = servOn ? 'SERVICIO' : (insOn ? 'INSUMO' : (consOn ? 'CONSUMIBLE' : 'PRODUCTO'));
  if(_catProductoCurrentType && _catProductoCurrentType !== newType){
    resetTypeSpecificFields(newType);
  }
  _catProductoCurrentType = newType;
  // Aplicar toggles
  applyServicioToggle(servOn);
  applyInsumoToggle(insOn);
  applyConsumibleToggle(consOn);
  applyProductoToggle(!servOn && !insOn && !consOn);
  renderVariantes();
  updateMargenPreview();
  // Siempre visible: Controles y métricas
  if(catConsumibleControls) catConsumibleControls.classList.remove('hidden');
  const modal = document.querySelector('#catProductoOverlay .modal.purchase-modal');
  if(modal){
    modal.classList.toggle('service-on', servOn);
    modal.classList.toggle('insumo-on', insOn);
    modal.classList.toggle('consumible-on', consOn);
  }
  applyVariantPriceCostLocks();
  syncUnidadSelections();
}
if(catProductoTipoProducto) catProductoTipoProducto.addEventListener('change', onTipoChange);
if(catProductoTipoServicio) catProductoTipoServicio.addEventListener('change', onTipoChange);
if(catProductoTipoInsumo) catProductoTipoInsumo.addEventListener('change', onTipoChange);
if(catProductoTipoConsumible) catProductoTipoConsumible.addEventListener('change', onTipoChange);

// Mejora UX: asegurar que el control segmentado "Tipo" cambie con un solo clic
// Hay navegadores/entornos donde el input radio oculto puede no togglear bien si está display:none.
// Este handler fuerza el checked y dispara el change al hacer clic en la etiqueta.
try{
  const tipoSegLabels = document.querySelectorAll('#catProductoForm .seg-control label.seg-item');
  tipoSegLabels.forEach(lbl => {
    lbl.addEventListener('click', (ev) => {
      const inp = lbl.querySelector('input[type="radio"][name="catProductoTipo"]');
      if(!inp || inp.disabled) return;
      ev.preventDefault();
      if(!inp.checked){
        inp.checked = true;
        inp.dispatchEvent(new Event('change', { bubbles:true }));
      }
    });
  });
}catch(_e){ /* no-op */ }

// Habilitar/deshabilitar reglas según el checkbox "Cobrar por proporción (m²)"
if(catProductoProporcionalInput){
  catProductoProporcionalInput.addEventListener('change', ()=>{
    const on = !!catProductoProporcionalInput.checked;
    const opts = {};
    if(on){
      if(catProductoLinealInput) catProductoLinealInput.checked = false;
      opts.resetLineal = true;
    }
    syncMedidasControls(opts);
  });
}
// Habilitar/deshabilitar ajuste lineal y exclusividad con proporcional
if(catProductoLinealInput){
  catProductoLinealInput.addEventListener('change', ()=>{
    const on = !!catProductoLinealInput.checked;
    const opts = { resetLineal: !on };
    if(on){
      if(catProductoProporcionalInput) catProductoProporcionalInput.checked = false;
      opts.resetProporcional = true;
    }
    syncMedidasControls(opts);
  });
}

// Margen preview dinámico
function updateMargenPreview(){
  const margenInput = document.getElementById('catProductoMargenPreview');
  const gananciaInput = document.getElementById('catProductoGananciaPreview');
  if(!margenInput && !gananciaInput) return;
  const isServ = !!(catProductoTipoServicio && catProductoTipoServicio.checked);
  const isIns = !!(catProductoTipoInsumo && catProductoTipoInsumo.checked);
  const isCons = !!(catProductoTipoConsumible && catProductoTipoConsumible.checked);
  if(isServ){
    if(catProductoCostoInput) catProductoCostoInput.value = (0).toFixed(2);
    if(margenInput) margenInput.value = '100';
    const p = parseFloat(catProductoPrecioPublicoInput && catProductoPrecioPublicoInput.value)||0;
    if(gananciaInput) gananciaInput.value = p.toFixed(2);
    return;
  }
  const insumoVentaPublicoOn = !!(catProductoTipoInsumo && catProductoTipoInsumo.checked && catProductoVentaPublicoChk && catProductoVentaPublicoChk.checked);
  if(isIns && !insumoVentaPublicoOn){
    if(margenInput) margenInput.value = '';
    if(gananciaInput) gananciaInput.value = '';
    return;
  }
  if(isCons){
    if(margenInput) margenInput.value = '';
    if(gananciaInput) gananciaInput.value = '';
    return;
  }
  const cBase = parseFloat(catProductoCostoInput && catProductoCostoInput.value)||0;
  const pBase = parseFloat(catProductoPrecioPublicoInput && catProductoPrecioPublicoInput.value)||0;
  // Sumar extras al preview (considerar 1 unidad/bloque por extra)
  const extras = Array.isArray(tempExtras) ? tempExtras : [];
  let extrasPrecio = 0, extrasCosto = 0;
  extras.forEach(ex=>{
    const nombre = String(ex?.nombre||'').trim(); if(!nombre) return;
    const tipo = (ex?.tipo==='puntadas'||ex?.tipo==='cantidad')? ex.tipo : 'fijo';
    const pEx = Number(ex?.precio)||0;
    const cEx = Number(ex?.costo)||0;
    // Vista previa: 1 bloque/unidad
    const bloques = 1;
    extrasPrecio += pEx * bloques;
    extrasCosto  += cEx * bloques;
  });
  const p = pBase + extrasPrecio;
  const c = cBase + extrasCosto;
  const g = p - c;
  if(gananciaInput) gananciaInput.value = isFinite(g) ? g.toFixed(2) : '';
  if(margenInput){
    if(c > 0){
      const m = ((p - c) / c) * 100;
      margenInput.value = String(isFinite(m) ? m.toFixed(1) : '');
    } else {
      margenInput.value = '';
    }
  }
}

// Recalcular margen cuando cambian costo o precio
if(catProductoCostoInput) catProductoCostoInput.addEventListener('input', updateMargenPreview);
if(catProductoPrecioPublicoInput) catProductoPrecioPublicoInput.addEventListener('input', updateMargenPreview);
// Si cambia precio y es servicio, recalcular costo para mantener 100%
if(catProductoPrecioPublicoInput) catProductoPrecioPublicoInput.addEventListener('input', ()=>{
  if(catProductoTipoServicio && catProductoTipoServicio.checked && catProductoCostoInput){
  const p = parseFloat(catProductoPrecioPublicoInput.value)||0;
  // Mantener costo en 0 para servicios (ganancia = precio)
  catProductoCostoInput.value = (0).toFixed(2);
  }
});

