  const CPM_FOCUSABLE_SELECTOR = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';
  function getVisibleFocusableInCpm(){
    if(!cpmModal) return [];
    const nodes = Array.from(cpmModal.querySelectorAll(CPM_FOCUSABLE_SELECTOR));
    return nodes.filter(el=>{
      if(!(el instanceof HTMLElement)) return false;
      if(el.disabled) return false;
      if(!cpmModal.contains(el)) return false;
      if(!el.offsetParent && getComputedStyle(el).position !== 'fixed') return false;
      return true;
    });
  }
  cpmModal?.addEventListener('keydown', (e)=>{
    if(e.key !== 'Tab') return;
    const focusables = getVisibleFocusableInCpm();
    if(!focusables.length){ e.preventDefault(); return; }
    const current = document.activeElement;
    let idx = focusables.indexOf(current);
    if(idx === -1) idx = 0;
    const dir = e.shiftKey ? -1 : 1;
    let next = idx + dir;
    if(next < 0) next = focusables.length - 1;
    if(next >= focusables.length) next = 0;
    e.preventDefault();
    focusables[next]?.focus();
  });
  document.addEventListener('focusin', (e)=>{
    const open = cpmModal && cpmModal.style.display === 'flex';
    if(!open) return;
    if(!cpmModal.contains(e.target)){
      const focusables = getVisibleFocusableInCpm();
      if(focusables.length){
        focusables[0].focus();
      }
    }
  });
