      chip.style.background='#eef2ff'; chip.style.color='#3730a3'; chip.style.borderRadius='999px'; chip.style.padding='2px 8px'; chip.style.fontSize='0.65rem';
      const label = ex.tipo==='puntadas' ? `${ex.nombre} (${ex.stitches||0} pts)` : ex.nombre;
