  function vcMoney(n){ return '$ '+Number(n||0).toFixed(2); }
  function vcTierContext(prod, qty){
    const ctx = { used:'base', base:0, pickMin:null, pickPrecio:null };
    if(!prod) return ctx;
    ctx.base = (Number.isFinite(Number(prod.precio)) && Number(prod.precio)>0) ? Number(prod.precio) : (Number(prod.precioPublico)||0);
    const escalas = (prod.escalasMayoreoActivas && Array.isArray(prod.escalasMayoreo)) ? prod.escalasMayoreo.slice() : [];
    if(!escalas.length) return ctx;
    const sorted = escalas.slice().sort((a,b)=> (Number(a?.min)||0) - (Number(b?.min)||0));
    let pick = null;
    for(const e of sorted){ if((Number(e?.min)||0) <= qty) pick = e; else break; }
    if(pick){ ctx.used='tier'; ctx.pickMin=Number(pick.min)||0; ctx.pickPrecio=Number(pick.precio)||0; }
    return ctx;
  }
  function vcComputePreview(){
    if(vcMode === 'qty-edit'){
      const qty = Math.max(1, Number(vcCantidad && vcCantidad.value) || 1);
      const item = (vcEditIndex>=0 && vcEditIndex<items.length) ? items[vcEditIndex] : null;
      const unit = item ? (Number(item.precio)||0) : 0;
      const total = unit * qty;
      if(vcUnitPrice) vcUnitPrice.textContent = money(unit);
      if(vcTotalPrice) vcTotalPrice.textContent = money(total);
      return;
    }
    const prod = vcState.prod; if(!prod) return;
    const qty = Math.max(1, Number(vcCantidad && vcCantidad.value)||1);
    const needsDim = shouldShowDims(prod);
    let unit = Number(getTierUnitRate(prod, qty)) || 0;
    if(!(unit>0)) unit = (Number(prod.precio)||0) || (Number(prod.precioPublico)||0) || 0;
    let area = 1;
    let calc = null;
    let dimsReady = true;
    if(needsDim){
      dimsReady = false;
      area = 0;
    }
    // Extras
    const extraUnit = (ex)=>{
      if(ex.tipo==='puntadas'){
        const base = Math.max(1, Number(ex.unidadBase)||1000);
        const pts = Math.max(0, Number(ex.stitches)||0);
        const whole = Math.floor(pts / base);
        const rem = pts % base;
        const bloques = pts<=0 ? 0 : (whole === 0 ? 1 : (whole + (rem > (base/2) ? 1 : 0)));
        return (Number(ex.precio)||0) * bloques;
      }
      return (Number(ex.precio)||0);
    };
    const extrasSum = vcState.extras.reduce((s,ex)=> s + extraUnit(ex), 0);
    // Preview del extra seleccionado actual (sin agregar)
    try{
      if(vcExtraPreview){
        const sel = vcExtraSelect && vcExtraSelect.value!=='' ? parseInt(vcExtraSelect.value) : -1;
        const extras = Array.isArray(vcState.prod?.extras) ? vcState.prod.extras : [];
        const exDef = Number.isInteger(sel) && extras[sel] ? extras[sel] : null;
        if(exDef){
          const tipo = (exDef.tipo==='puntadas'||exDef.tipo==='cantidad')? exDef.tipo : 'fijo';
          let preview = 0;
          if(tipo==='puntadas'){
            const pts = Math.max(0, Number(vcStitches && vcStitches.value)||0);
            const base = Math.max(1, Number(exDef.unidadBase)||1000);
            const whole = Math.floor(pts / base);
            const rem = pts % base;
            const bloques = pts<=0 ? 0 : (whole === 0 ? 1 : (whole + (rem > (base/2) ? 1 : 0)));
            preview = (Number(exDef.precio)||0) * bloques;
          } else {
            preview = (Number(exDef.precio)||0);
          }
          vcExtraPreview.textContent = preview>0 ? `+ ${vcMoney(preview)} c/u` : `+ $ 0.00 c/u`;
        } else {
          vcExtraPreview.textContent = '\u00A0';
        }
      }
    }catch(_e){}
    const previewExtras = (needsDim && !dimsReady) ? 0 : extrasSum;
    const totalUnitMain = needsDim ? (dimsReady && area>0 ? unit * area : 0) : unit;
    const totalUnit = totalUnitMain + previewExtras;
    const total = qty * totalUnit;
    // Info bar
    try{
      const ctx = vcTierContext(prod, qty);
      if(vcTarifaInfo){ vcTarifaInfo.textContent = ctx.used==='tier' ? `Tarifa: Mayoreo (min ${ctx.pickMin}) = ${vcMoney(ctx.pickPrecio)}` : `Tarifa: Base = ${vcMoney(ctx.base)}`; }
      if(vcAreaInfo){
        if(needsDim){
          vcAreaInfo.textContent = 'Las medidas se capturarán en el siguiente paso';
        } else {
          vcAreaInfo.textContent = '';
        }
      }
      if(vcExtrasInfo){
        vcExtrasInfo.textContent = (vcState.extras.length && !needsDim)
          ? `Extras incluidos: +${vcMoney(extrasSum)} c/u`
          : (vcState.extras.length && needsDim ? `Extras separados: +${vcMoney(extrasSum)} c/u` : '');
      }
    }catch(_e){}
  if(vcUnitPrice) vcUnitPrice.textContent = (needsDim && !dimsReady) ? 'Pendiente' : vcMoney(totalUnit);
  if(vcTotalPrice) vcTotalPrice.textContent = (needsDim && !dimsReady) ? 'Pendiente' : vcMoney(total);
  }
  // Live updates
  vcCantidad?.addEventListener('input', vcComputePreview);
  vcAncho?.addEventListener('input', vcComputePreview);
  vcAlto?.addEventListener('input', vcComputePreview);
  vcExtrasList?.addEventListener('DOMSubtreeModified', vcComputePreview);
