      if(!window.firebaseSalesApi){ notify('Backend ventas no listo','err'); return; }
      const t = window.ticketsStateRef?.tickets?.[window.ticketsStateRef.active];
      let cliente = t?.cliente || findClienteByInput(clienteInput?.value||'');
  if(!cliente){ promptAssignCliente(); return; }
