  function parsePositiveAmount(raw){
    const num = parseFloat(raw);
    if(!Number.isFinite(num)) return 0;
    return num > 0 ? +num.toFixed(2) : 0;
  }
  function getEnteredPayments(){
    const cash = parsePositiveAmount(pmPagoConInput?.value||'');
    const card = parsePositiveAmount(pmCardAmountInput?.value||'');
    const transfer = parsePositiveAmount(pmTransferAmountInput?.value||'');
    const total = +(cash + card + transfer).toFixed(2);
    return { cash, card, transfer, total };
  }
  function resolveMethodFromPayments(payments){
    const active = [];
    if(payments.cash>0) active.push('EFECTIVO');
    if(payments.card>0) active.push('TARJETA');
    if(payments.transfer>0) active.push('TRANSFERENCIA');
    if(active.length === 0){
      return pmPreferredMethod;
    }
    if(active.length === 1){
      return active[0];
    }
    return 'MIXTO';
  }
  function updateChangeSummary(payments, total){
    if(!pmChangeSummary) return;
    const diff = +(payments.total - total).toFixed(2);
    if(diff > 0){
      pmChangeSummary.classList.remove('pm-change-pending');
      pmChangeSummary.classList.add('pm-change-positive');
      if(pmChangeLabel) pmChangeLabel.textContent = 'Cambio';
      if(pmChangeAmount) pmChangeAmount.textContent = money(diff);
    } else if(diff === 0){
      pmChangeSummary.classList.remove('pm-change-pending');
      pmChangeSummary.classList.remove('pm-change-positive');
      if(pmChangeLabel) pmChangeLabel.textContent = 'Pagado';
      if(pmChangeAmount) pmChangeAmount.textContent = money(0);
    } else {
      pmChangeSummary.classList.remove('pm-change-positive');
      pmChangeSummary.classList.add('pm-change-pending');
      if(pmChangeLabel) pmChangeLabel.textContent = 'Falta';
      if(pmChangeAmount) pmChangeAmount.textContent = money(Math.abs(diff));
    }
  }

  const PM_UNITS = ['CERO','UNO','DOS','TRES','CUATRO','CINCO','SEIS','SIETE','OCHO','NUEVE'];
  const PM_TEENS = ['DIEZ','ONCE','DOCE','TRECE','CATORCE','QUINCE','DIECISEIS','DIECISIETE','DIECIOCHO','DIECINUEVE'];
  const PM_TENS = ['','DIEZ','VEINTE','TREINTA','CUARENTA','CINCUENTA','SESENTA','SETENTA','OCHENTA','NOVENTA'];
  const PM_HUNDREDS = ['','CIENTO','DOSCIENTOS','TRESCIENTOS','CUATROCIENTOS','QUINIENTOS','SEISCIENTOS','SETECIENTOS','OCHOCIENTOS','NOVECIENTOS'];

  function pmMasculinizeWord(word){
    if(!word) return '';
    return word
      .replace(/UNO$/, 'UN')
      .replace(/VEINTIUNO$/, 'VEINTIUN')
      .replace(/ Y UNO/g, ' Y UN');
  }
  function pmThreeDigitsToWords(num){
    const n = Math.abs(num|0);
    if(n === 0) return '';
    if(n === 100) return 'CIEN';
    const parts = [];
    const hundreds = Math.floor(n / 100);
    const tensUnits = n % 100;
    const units = n % 10;
    if(hundreds > 0){
      parts.push(PM_HUNDREDS[hundreds]);
    }
    if(tensUnits > 0){
      if(tensUnits < 10){
        parts.push(PM_UNITS[tensUnits]);
      } else if(tensUnits < 20){
        parts.push(PM_TEENS[tensUnits - 10]);
      } else if(tensUnits < 30){
        if(tensUnits === 20){
          parts.push('VEINTE');
        } else {
          parts.push(('VEINTI' + PM_UNITS[units].toLowerCase()).toUpperCase());
        }
      } else {
        const tensIndex = Math.floor(tensUnits / 10);
        const tensWord = PM_TENS[tensIndex];
        if(units){
          parts.push(`${tensWord} Y ${PM_UNITS[units]}`);
        } else {
          parts.push(tensWord);
        }
      }
    }
    return parts.join(' ').replace(/\s+/g,' ').trim();
  }
  function pmIntegerToWords(value){
    let num = Math.floor(Math.abs(Number(value)||0));
    if(num === 0) return 'CERO';
    const words = [];
    let groupIndex = 0;
    while(num > 0){
      const group = num % 1000;
      if(group){
        const groupText = pmThreeDigitsToWords(group);
        switch(groupIndex){
          case 0:
            words.push(groupText);
            break;
          case 1:
            words.push(group === 1 ? 'MIL' : `${pmMasculinizeWord(groupText)} MIL`);
            break;
          case 2:
            words.push(group === 1 ? 'UN MILLON' : `${pmMasculinizeWord(groupText)} MILLONES`);
            break;
          case 3:
            words.push(group === 1 ? 'MIL MILLONES' : `${pmMasculinizeWord(groupText)} MIL MILLONES`);
            break;
          case 4:
            words.push(group === 1 ? 'UN BILLON' : `${pmMasculinizeWord(groupText)} BILLONES`);
            break;
          case 5:
            words.push(group === 1 ? 'MIL BILLONES' : `${pmMasculinizeWord(groupText)} MIL BILLONES`);
            break;
          case 6:
            words.push(group === 1 ? 'UN TRILLON' : `${pmMasculinizeWord(groupText)} TRILLONES`);
            break;
          default:
            words.push(pmMasculinizeWord(groupText));
            break;
        }
      }
      num = Math.floor(num / 1000);
      groupIndex++;
    }
    return words.reverse().join(' ').replace(/\s+/g,' ').trim();
  }
  function pmAmountToWords(amount){
    const raw = Number(amount||0);
    if(!Number.isFinite(raw)) return 'CERO PESOS 00/100 MXN';
    const isNegative = raw < 0;
    const absolute = Math.abs(raw);
    const integerPart = Math.floor(absolute + 0.0000001);
    const cents = Math.round((absolute - integerPart) * 100);
    const centsStr = String(cents).padStart(2,'0');
    const integerWords = pmIntegerToWords(integerPart);
    const pesoLabel = integerPart === 1 ? 'PESO' : 'PESOS';
    const base = `${integerWords} ${pesoLabel} ${centsStr}/100 MXN`;
    return (isNegative ? `MENOS ${base}` : base).replace(/\s+/g,' ').trim();
  }
  function updatePmTotalDisplay(total){
    if(pmTotalAmount) pmTotalAmount.textContent = money(total);
    if(pmTotalAmountWords) pmTotalAmountWords.textContent = pmAmountToWords(total);
  }

  // ----------------------
  // Pago modal: helpers mínimos
