  let unsub = null;

  function isAdmin(){
    try{ const uid=window.auth?.currentUser?.uid; const us=Array.isArray(window.usuarios)?window.usuarios:[]; const me=uid? us.find(u=>String(u.id||u.uid)===String(uid)):null; const role=(me?.role||me?.perfil||'').toString().toLowerCase(); return role.includes('admin')||role.includes('super')||role.includes('gerente'); }catch(_e){ return false; }
  }
  function fmt(ts){ try{ if(ts?.toDate) return ts.toDate().toLocaleString(); return new Date(ts).toLocaleString(); }catch(_){ return '-'; } }
  function open(){ overlay.classList.remove('hidden'); load(false); }
