// ===================== Corte de Caja: Breakdown y Ticket =====================
function computeCutBreakdown(){
  const base = Array.isArray(window.historicalCashRecords)? window.historicalCashRecords: (Array.isArray(window.cashRecords)? window.cashRecords: []);
  let lista = base;
  try{
  if(!(window.__showAllTurnos && (typeof isAdminRole==='function' ? isAdminRole() : (String(window.currentUserRole||'').toLowerCase()==='admin')))){
      // Intentar filtrar por turno actual para evitar mezclar ventas entre empleados
      const turnoId = window.currentTurnoId || null;
      // Recuperar datos del turno abierto en cache si los hubiéramos almacenado
      const turnoAbierto = window.__lastTurnoOpen || null;
      const aperturaMs = (turnoAbierto && turnoAbierto.abiertoEnApproxMs)? turnoAbierto.abiertoEnApproxMs : null;
      if(turnoId){
        // Preferir coincidencia directa por turnoId en movimiento
        const conTurno = base.filter(r=> r && r.turnoId === turnoId);
        if(conTurno.length){
          lista = conTurno;
        } else if(aperturaMs){
          // Fallback: usar timestamp local de creación si está disponible
          lista = base.filter(r=> (r && typeof r.createdAtMs==='number' && r.createdAtMs >= aperturaMs));
        }
      }
    }
  }catch(_e){}
  let ventas=0, anticipos=0, abonos=0, entradas=0, gastos=0, retiros=0, cancelaciones=0, devolucionesAbonos=0;
  for(const rec of lista){
    if(!rec || String(rec.metodo||'').toUpperCase()!=='EFECTIVO') continue;
    const t = String(rec.tipo||'').toUpperCase();
    const m = Number(rec.monto||0);
  if(t==='INGRESO'){ entradas += m; }
  else if(t==='GASTO'){ gastos += Math.abs(m); }
  else if(t==='RETIRO'){ retiros += Math.abs(m); }
  else if(t==='VENTA_ABONO'){ abonos += m; }
    else if(t==='VENTA_ANTICIPO' || t==='VENTA_PAGO_INICIAL'){ anticipos += m; }
    else if(t==='FACTURA_ABONO'){ abonos += m; }
    else if(t==='VENTA_CANCELACION'){ cancelaciones += Math.abs(m); }
    else if(t==='DEVOLUCION_ABONO_PERSONAL'){ devolucionesAbonos += m; }
    else if(
      t==='VENTA' || t==='VENTA_EFECTIVO' || t==='VENTA_MIXTO' || t==='VENTA_DEPOSITO' ||
      (t.startsWith('VENTA_') && !['VENTA_ABONO','VENTA_ABONO_PERSONAL','VENTA_CANCELACION','DEVOLUCION_ABONO_PERSONAL','VENTA_ANTICIPO','VENTA_PAGO_INICIAL','FACTURA_ABONO'].includes(t))
    ){
      ventas += m; // incluye cobros de saldo en efectivo (contra-entrega) y ventas en efectivo del día
    }
  }
  const totalIngresos = ventas + anticipos + abonos + entradas;
  // Política: las devoluciones de abonos PERSONALES no descuentan del efectivo esperado en caja;
  // se separan para resguardo y control, pero no restan al "Esperado".
  const totalSalidas = gastos + retiros + cancelaciones; // excluye devolucionesAbonos
  const esperado = totalIngresos - totalSalidas;
  return { ventas, anticipos, abonos, entradas, gastos, retiros, cancelaciones, devolucionesAbonos, totalIngresos, totalSalidas, esperado };
}
function renderCutBreakdown(){
  try{
    const bd = computeCutBreakdown();
    if(cutExpectedInput) cutExpectedInput.value = bd.esperado.toFixed(2);
    let contado = 0; if(cutCashInput){ const v=parseFloat(String(cutCashInput.value||'').replace(/,/g,'.')); if(Number.isFinite(v)) contado=v; }
    if(cutDiffInput) cutDiffInput.value = (contado - bd.esperado).toFixed(2);
    if(cutBreakdownContent){
      cutBreakdownContent.innerHTML = `<div style="display:grid;grid-template-columns:1fr auto;gap:2px 12px;">
        <span>Ventas efectivo</span><span>$ ${bd.ventas.toFixed(2)}</span>
        <span>Anticipos / Inicial</span><span>$ ${bd.anticipos.toFixed(2)}</span>
        <span>Abonos</span><span>$ ${bd.abonos.toFixed(2)}</span>
        <span>Entradas</span><span>$ ${bd.entradas.toFixed(2)}</span>
        <span style='border-top:1px solid #e2e8f0;margin-top:4px;'>Total ingresos</span><span style='border-top:1px solid #e2e8f0;margin-top:4px;'>$ ${bd.totalIngresos.toFixed(2)}</span>
        <span>Gastos</span><span>$ ${bd.gastos.toFixed(2)}</span>
        <span>Retiros</span><span>$ ${bd.retiros.toFixed(2)}</span>
        <span>Cancelaciones</span><span>$ ${bd.cancelaciones.toFixed(2)}</span>
        <span>Devol. abonos (no descuenta)</span><span>$ ${bd.devolucionesAbonos.toFixed(2)}</span>
        <span style='border-top:1px solid #e2e8f0;margin-top:4px;'>Total salidas</span><span style='border-top:1px solid #e2e8f0;margin-top:4px;'>$ ${bd.totalSalidas.toFixed(2)}</span>
        <span style='font-weight:600;margin-top:4px;'>Esperado</span><span style='font-weight:600;margin-top:4px;'>$ ${bd.esperado.toFixed(2)}</span>
      </div>`;
    }
  }catch(e){ if(cutBreakdownContent) cutBreakdownContent.textContent='Error'; }
}
if(cutCashInput){ cutCashInput.addEventListener('input', renderCutBreakdown); }
// Envolver openCutModal si ya existe
const __origOpenCutModal__ = typeof openCutModal==='function'? openCutModal: null;
window.openCutModal = function(){
  if(__origOpenCutModal__){ try{ __origOpenCutModal__(); }catch(_e){} } else {
    const today = new Date().toISOString().substring(0,10);
    if(cutDateInput) cutDateInput.value = today;
  }
  // Mostrar opción admin si corresponde y resetear el flag cada vez que se abre
  try{
    const isAdmin = (typeof isAdminRole==='function' ? isAdminRole() : (String(window.currentUserRole||'').toLowerCase()==='admin'));
    if(cutAdminOptions) cutAdminOptions.style.display = isAdmin ? '' : 'none';
    if(cutShowAllTurnsChk){
      // Por defecto, apagado al abrir; admins pueden activarlo manualmente
      window.__showAllTurnos = false;
      cutShowAllTurnsChk.checked = false;
      // Asegurar que non-admin no pueda activar
      cutShowAllTurnsChk.disabled = !isAdmin;
    }
  }catch(_e){}
  renderCutBreakdown();
};
// Al cambiar el toggle, recalcular breakdown
if(cutShowAllTurnsChk){
  cutShowAllTurnsChk.addEventListener('change', function(){
    const isAdmin = (typeof isAdminRole==='function' ? isAdminRole() : (String(window.currentUserRole||'').toLowerCase()==='admin'));
    // Solo admins pueden encenderlo; si no es admin, forzar apagado
    if(!isAdmin){ this.checked = false; window.__showAllTurnos = false; return; }
    window.__showAllTurnos = !!this.checked;
    renderCutBreakdown();
  });
}
