async function openCashDrawerSignal(){
  try{
    const r = await fetch('/cash/open-drawer',{ method:'POST', headers:{ 'Content-Type':'application/json' }, body: JSON.stringify({ ts: Date.now() }) });
    if(!r.ok){ console.warn('[CASH] Señal cajón no OK', r.status); }
    else { console.log('[CASH] Cajón abierto (señal enviada)'); }
  }catch(e){ console.warn('[CASH] Error señal cajón', e); }
}
function escapeHtml(str){
  return String(str||'').replace(/[&<>"]/g, s=> ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[s]));
}
function handleCutSubmit(e){
  e?.preventDefault?.();
  const fecha = (cutDateInput && cutDateInput.value)? cutDateInput.value : new Date().toISOString().substring(0,10);
  const bd = computeCutBreakdown();
  let contado=0; if(cutCashInput){ const v=String(cutCashInput.value||'').replace(/,/g,'.').replace(/[^0-9.\-]/g,''); contado=parseFloat(v); }
  if(!Number.isFinite(contado) || contado<0){ notify&&notify('Monto contado inválido','err'); return; }
  const diferencia = contado - bd.esperado;
  // Guardar corte directamente y abrir popup
  (async ()=>{
    try{
      const tz = window.__CORTE_TZ__ || 'America/Mexico_City';
      const uid = window.auth?.currentUser?.uid || null;
      const userNombre = (window.auth?.currentUser?.displayName || (window.auth?.currentUser?.email? String(window.auth.currentUser.email).split('@')[0] : '')) || 'Usuario';
      const usuarios = Array.isArray(window.usuarios)? window.usuarios: [];
      const me = usuarios.find(u=> String(u.id||u.uid)===String(uid));
      const cajaId = me?.cajaId || null;
      const sucursal = (me?.sucursal? String(me.sucursal).toUpperCase(): null) || null;
      const turnoId = window.currentTurnoId || null;
      let cajaNombre=null; try{ if(cajaId && Array.isArray(window.cajas)){ const c=window.cajas.find(x=> String(x.id)===String(cajaId)); cajaNombre=c?.nombre||c?.caja||null; } }catch(_e){}
      // ID por caja+fecha+turno (si existe) para cortes personales múltiples en el mismo día
      const docId = (cajaId? `${cajaId}-${fecha}${turnoId? '-' + String(turnoId).slice(-6): ''}`: `NOID-${(cajaNombre||'SIN_CAJA')}-${fecha}${turnoId? '-' + String(turnoId).slice(-6): ''}`).replace(/[^A-Za-z0-9_-]/g,'_');
      const nowLocal = new Date();
      const payload = {
        fecha, timezone: tz, cajaId: cajaId||null, caja: cajaNombre||null, sucursal,
        mode:'manual-ui-popup', expectedEfectivo: bd.esperado, countedEfectivo: contado, differenceEfectivo: diferencia,
        detalle:{ ventasEfectivo: bd.ventas, anticiposEfectivo: bd.anticipos, abonosEfectivo: bd.abonos, entradasEfectivo: bd.entradas, gastosEfectivo: bd.gastos, retirosEfectivo: bd.retiros, cancelacionesEfectivo: bd.cancelaciones, devolucionesAbonosEfectivo: bd.devolucionesAbonos, totalIngresosEfectivo: bd.totalIngresos, totalSalidasEfectivo: bd.totalSalidas },
        ticketVersion:4,
        manualBy:{ uid, nombre: userNombre },
        userId: uid||null,
        turnoId: turnoId||null,
        manualAt:(window.firebase && window.firebase.firestore && window.firebase.firestore.FieldValue? window.firebase.firestore.FieldValue.serverTimestamp(): Date.now()),
        // Marcamos este popup como "impresión lógica" para auditoría futura
        printed:true,
        printedMode:'popup-window',
        printedAt: nowLocal.toISOString(),
        printedBy:{ uid, nombre: userNombre }
      };
      if(window.db){ await window.db.collection('caja_cortes').doc(docId).set(payload,{ merge:true }); try{ await window.db.collection('corte_caja').doc(docId).set(payload,{ merge:true }); }catch(_e){} }
      notify&&notify('Corte guardado','ok');
    }catch(err){ console.warn('Error guardando corte popup:', err); notify&&notify('No se pudo guardar el corte','err'); }
    // Abrir popup
    try{
      const w = window.open('', '_blank', 'width=480,height=700');
      if(!w){ notify&&notify('Popup bloqueado','warn'); return; }
      const css = 'body{font-family:monospace;font-size:12px;margin:8px;} h1{font-size:14px;margin:0 0 6px;} table{width:100%;border-collapse:collapse;} td{padding:2px 4px;vertical-align:top;} .r{text-align:right;} .b{font-weight:600;} .sep td{border-top:1px solid #000;}';
      const rows = `<tr><td>Ventas</td><td class='r'>$ ${bd.ventas.toFixed(2)}</td></tr>
        <tr><td>Anticipos</td><td class='r'>$ ${bd.anticipos.toFixed(2)}</td></tr>
        <tr><td>Abonos</td><td class='r'>$ ${bd.abonos.toFixed(2)}</td></tr>
        <tr><td>Entradas</td><td class='r'>$ ${bd.entradas.toFixed(2)}</td></tr>
        <tr class='sep'><td>Total Ingresos</td><td class='r'>$ ${bd.totalIngresos.toFixed(2)}</td></tr>
        <tr><td>Gastos</td><td class='r'>$ ${bd.gastos.toFixed(2)}</td></tr>
        <tr><td>Retiros</td><td class='r'>$ ${bd.retiros.toFixed(2)}</td></tr>
        <tr><td>Cancelaciones</td><td class='r'>$ ${bd.cancelaciones.toFixed(2)}</td></tr>
        <tr><td>Devol. Abonos</td><td class='r'>$ ${bd.devolucionesAbonos.toFixed(2)}</td></tr>
        <tr class='sep'><td>Total Salidas</td><td class='r'>$ ${bd.totalSalidas.toFixed(2)}</td></tr>
        <tr class='sep'><td class='b'>Esperado</td><td class='r b'>$ ${bd.esperado.toFixed(2)}</td></tr>
        <tr><td>Contado</td><td class='r'>$ ${contado.toFixed(2)}</td></tr>
        <tr><td>Diferencia</td><td class='r'>$ ${diferencia.toFixed(2)}</td></tr>`;
      const nowStr = new Date().toLocaleString('es-MX');
      w.document.write(`<!DOCTYPE html><html><head><meta charset='utf-8'><title>Corte ${fecha}</title><style>${css}</style></head><body>`+
        `<h1>CORTE DE CAJA</h1>`+
        `<div>Fecha: ${fecha}&nbsp; Hora: ${nowStr}</div>`+
        `<hr><table>${rows}</table><hr>`+
        `<div style='font-size:10px;'>Generado manualmente</div>`+
        `</body></html>`);
      w.document.close(); w.focus();
    }catch(err){ console.warn('Popup ticket fallo', err); notify&&notify('No se pudo abrir el popup','err'); }
    // Cerrar turno y cerrar sesión automáticamente tras generar el ticket
    try {
      if(window.firebaseApi && typeof window.firebaseApi.closeTurno==='function'){
        // Asegurar turnoId (si se perdió referencia en la sesión)
        if(!window.currentTurnoId && typeof window.firebaseApi.getTurnoAbierto==='function'){
          try { await window.firebaseApi.getTurnoAbierto(); } catch(_e){}
        }
        if(window.currentTurnoId){
          const resumen = {
            ventasEfectivo: bd.ventas,
            anticiposEfectivo: bd.anticipos,
            abonosEfectivo: bd.abonos,
            entradasEfectivo: bd.entradas,
            gastosEfectivo: bd.gastos,
            retirosEfectivo: bd.retiros,
            cancelacionesEfectivo: bd.cancelaciones,
            devolucionesAbonosEfectivo: bd.devolucionesAbonos,
            totalIngresosEfectivo: bd.totalIngresos,
            totalSalidasEfectivo: bd.totalSalidas,
            esperadoEfectivo: bd.esperado,
            contadoEfectivo: contado,
            diferenciaEfectivo: diferencia
          };
          // corteId es el docId generado
          await window.firebaseApi.closeTurno({ efectivo: contado, corteId: docId, expected: bd.esperado, difference: diferencia, resumen, modo:'auto-tras-corte' });
          console.log('[Corte] Turno cerrado automáticamente tras corte.');
        } else {
          console.warn('[Corte] No se encontró turno abierto para cerrar.');
        }
      }
    } catch(err){ console.warn('No se pudo cerrar turno automáticamente', err); }
    try {
      const auth = window.firebase?.auth?.();
      if(auth && auth.currentUser){
        await auth.signOut();
        notify && notify('Sesión cerrada tras corte','info');
      }
    } catch(err){ console.warn('No se pudo cerrar la sesión automáticamente', err); }
  })();
  closeCutModal();
}
if(typeof cutForm!=='undefined' && cutForm){
  try{ cutForm.removeEventListener('submit', handleCutSubmit); }catch(_e){}
  cutForm.addEventListener('submit', handleCutSubmit);
}

