/**
 * Exporta el historial de ingresos, gastos y retiros a Excel (.xls).
 */
function exportHistoricoToCSV() { // ahora exporta a Excel
  if (!historicalCashRecords.length) { notify('No hay registros para exportar','info'); return; }
  const headers = ['ID','Tipo','Fecha','Descripción','Monto','Método'];
  const rows = historicalCashRecords.map(r=> [r.id,r.tipo,r.fecha,r.descripcion, r.monto.toFixed(2), r.metodo]);
  if(window.exportToExcel) window.exportToExcel(headers, rows, 'historico.xls');
}

// Elementos para el modal de compra
const purchaseOverlay = document.getElementById('purchaseOverlay');
const closePurchaseBtn = document.getElementById('closePurchaseBtn');
const purchaseForm = document.getElementById('purchaseForm');
const purchaseDateInput = document.getElementById('purchaseDate');
const invoiceInput = document.getElementById('invoice');
const itemProductInput = document.getElementById('itemProduct');
const itemQuantityInput = document.getElementById('itemQuantity');
const itemProviderInput = document.getElementById('itemProvider');
const itemUnitCostInput = document.getElementById('itemUnitCost');
const addItemBtn = document.getElementById('addItemBtn');
const productDatalist = document.getElementById('productDatalist');
const purchaseItemsBody = document.getElementById('purchaseItemsBody');
const variantQuantityGroup = document.getElementById('variantQuantityGroup');
const variantQtyRows = document.getElementById('variantQtyRows');
const variantQtyNote = document.getElementById('variantQtyNote');

// Arreglo temporal para almacenar las líneas de compra en el modal
let purchaseItems = [];
let purchaseVariantState = null;

// ---------------------- Facturación de Compras (Folio) via Firestore Counter ----------------------
function padInvoice(n){ const num = Number(n)||0; return String(num).padStart(3,'0'); }
async function peekNextInvoice(){
  try{
    if(window._firebaseReady && window.firebaseApi && typeof window.firebaseApi.peekNextCounter==='function'){
      const next = await window.firebaseApi.peekNextCounter('purchaseInvoice', 0);
      return padInvoice(next);
    }
  }catch(err){ console.warn('peekNextInvoice error', err); }
  // Sin Firebase: no usar datos locales; devuelve el primer folio visual
  return padInvoice(1);
}
async function claimNextInvoice(){
  if(!(window._firebaseReady && window.firebaseApi && typeof window.firebaseApi.nextCounter==='function')) return null;
  const n = await window.firebaseApi.nextCounter('purchaseInvoice', 0);
  return padInvoice(n);
}

function resetPurchaseVariantUI(){
  purchaseVariantState = null;
  if(variantQtyRows) variantQtyRows.innerHTML = '';
  if(variantQuantityGroup) variantQuantityGroup.classList.add('hidden');
  if(variantQtyNote) variantQtyNote.textContent = 'Captura la cantidad por variante.';
  if(itemQuantityInput){
    itemQuantityInput.disabled = false;
    itemQuantityInput.classList.remove('readonly');
    itemQuantityInput.placeholder = '';
  }
}

function updateVariantQuantityTotal(){
  if(!purchaseVariantState) return;
  const total = purchaseVariantState.variantes.reduce((sum,v)=> sum + (Number(v.cantidad||0)||0), 0);
  if(itemQuantityInput){
    itemQuantityInput.value = total;
  }
  if(variantQtyNote){
    variantQtyNote.textContent = `Captura la cantidad por variante (total: ${total}).`;
  }
}

function applyPurchaseVariantContext(prod){
  if(!variantQtyRows || !variantQuantityGroup){ purchaseVariantState = null; return; }
  const variants = Array.isArray(prod?.variantes)
    ? prod.variantes.filter(v=> String(v?.nombre||'').trim().length>0)
    : [];
  if(!variants.length){
    resetPurchaseVariantUI();
    return;
  }
  const esc = (s)=> String(s==null?'':s)
    .replace(/&/g,'&amp;')
    .replace(/</g,'&lt;')
    .replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;');
  purchaseVariantState = {
    productoId: prod? (prod._id || prod.id || null) : null,
    descripcion: prod?.descripcion || '',
    variantes: variants.map(v=>({
      nombre: String(v.nombre||'').trim(),
      existencias: Number(v.existencias||0) || 0,
      cantidad: 0
    }))
  };
  variantQtyRows.innerHTML = '';
  purchaseVariantState.variantes.forEach((variant, idx)=>{
    const row = document.createElement('div');
    row.className = 'variant-qty-row';
    row.innerHTML = `
      <div class="variant-qty-name">${esc(variant.nombre)}</div>
      <div class="variant-qty-stock">Stock actual: ${Number(variant.existencias||0)}</div>
      <div><input type="number" min="0" step="1" data-variant-idx="${idx}" value="0"></div>
    `;
    variantQtyRows.appendChild(row);
  });
  variantQuantityGroup.classList.remove('hidden');
  if(itemQuantityInput){
    itemQuantityInput.disabled = true;
    itemQuantityInput.classList.add('readonly');
    itemQuantityInput.placeholder = 'Usa las variantes';
    itemQuantityInput.value = 0;
  }
  if(variantQtyNote){
    variantQtyNote.textContent = 'Captura la cantidad por variante (total: 0).';
  }
}

function updatePurchaseVariantContext(prodCandidate){
  if(!variantQtyRows || !variantQuantityGroup){ purchaseVariantState = null; return; }
  const list = Array.isArray(window.products)? window.products : (typeof products !== 'undefined' ? products : []);
  let prod = prodCandidate || null;
  if(!prod){
    const name = (itemProductInput && itemProductInput.value || '').trim();
    if(!name){
      resetPurchaseVariantUI();
      return;
    }
    const lowered = name.toLowerCase();
    prod = list.find(p=> String(p.descripcion||'').toLowerCase() === lowered) || null;
  }
  if(prod){
    applyPurchaseVariantContext(prod);
    updateVariantQuantityTotal();
  } else {
    resetPurchaseVariantUI();
  }
}

// Prefill proveedor y costo desde catálogo al elegir producto
function prefillProviderAndCost(){
  try{
    const name = (itemProductInput && itemProductInput.value || '').trim();
    if(!name){
      updatePurchaseVariantContext(null);
      return;
    }
  // Buscar siempre en catálogo de productos (Insumos es vista derivada)
  const list = Array.isArray(window.products)? window.products : [];
    const prod = list.find(p=> (p.descripcion||'').toLowerCase() === name.toLowerCase());
    if(!prod){
      updatePurchaseVariantContext(null);
      return;
    }
    if(itemProviderInput) itemProviderInput.value = prod.proveedor || '';
    if(itemUnitCostInput){
      const currentVal = parseFloat(itemUnitCostInput.value);
      if(!Number.isFinite(currentVal) || currentVal<=0){
        const costo = Number(prod.costo);
        const precio = Number(prod.precio);
        itemUnitCostInput.value = Number.isFinite(costo) && costo>0 ? String(costo) : (Number.isFinite(precio)? String(precio): '0');
      }
    }
    updatePurchaseVariantContext(prod);
  }catch(err){ /* no-op */ }
}

// Actualiza el costo del producto en catálogo cuando se edita el costo unitario en compras
async function updateCostFromUnitCostInput(){
  try{
    if(!itemProductInput || !itemUnitCostInput) return;
    const name = String(itemProductInput.value||'').trim();
    if(!name) return;
    const val = Number(itemUnitCostInput.value);
    if(!Number.isFinite(val) || !(val>0)) return;
    if(window._firebaseReady && window.firebaseApi && typeof window.firebaseApi.upsertProductoByDescripcionLower==='function'){
      await window.firebaseApi.upsertProductoByDescripcionLower(name, { costo: val });
      try { document.dispatchEvent(new Event('productosUpdated')); } catch(_e){}
    }
  }catch(_e){ /* no-op */ }
}

// Estado de búsqueda para productos e insumos
let currentSearchProducts = '';
let currentSearchSupplies = '';
let currentSearchInsumos = '';
// Toggles para incluir también los que están en cero (por defecto ocultar sin stock)
let includeZeroProducts = false;
includeZeroSupplies = typeof includeZeroSupplies !== 'undefined' ? includeZeroSupplies : false;
let includeZeroInsumos = false;
// Si el checkbox existe al cargar, sincronizar estado inicial
if (typeof includeZeroSuppliesEl !== 'undefined' && includeZeroSuppliesEl) {
  includeZeroSupplies = !!includeZeroSuppliesEl.checked;
}
// Insumos: sincronizar estado inicial del toggle si existe
if (typeof includeZeroInsumosEl !== 'undefined' && includeZeroInsumosEl) {
  includeZeroInsumos = !!includeZeroInsumosEl.checked;
}
// Productos: sincronizar estado inicial del toggle "incluir sin stock" si existe
if (typeof includeZeroProductsEl !== 'undefined' && includeZeroProductsEl) {
  // respeta el checkbox si existe (por defecto apagado)
  includeZeroProducts = !!includeZeroProductsEl.checked;
}

/**
 * Renderiza la tabla de productos en el DOM. Filtra según el término de búsqueda actual.
 */
function renderProductsTable() {
  if(currentInventoryView !== 'products') return;
  applyInventorySchema('products');
  if (!inventoryTableBody) return;
  inventoryTableBody.innerHTML = '';
  const data = Array.isArray(window.products) ? window.products : [];
  const search = (currentSearchProducts || '').toLowerCase();
  const isProduct = (p)=> (__isTrue(p?.esProducto)) || (__isFalseish(p?.esServicio) && __isFalseish(p?.esInsumo) && __isFalseish(p?.esConsumible));
  const hasStock = (p)=> {
    const inv = String(p?.inventario||'').toUpperCase();
    if(inv && inv !== 'SI') return true;
    return Number(p?.existencias||0) > 0;
  };
  const filtered = data.filter(prod =>
    isProduct(prod)
    && (includeZeroProducts ? true : hasStock(prod))
    && (prod.descripcion||'').toLowerCase().includes(search)
  );
  const schema = INVENTORY_SCHEMAS.products;
  const colCount = schema ? schema.columns.length : 9;
  filtered.forEach((prod) => {
    const code = prod.codigoInterno || '';
    const desc = prod.descripcion || '';
    const precio = Number(prod.precio || 0);
    const exist = Number(prod.existencias || 0);
    const otras = Number(prod.otrasSuc || 0);
    const cat = prod.categoria || '';
    const inv = prod.inventario || '';
    const costo = Number(prod.costo || 0);
    const row = document.createElement('tr');
    row.innerHTML = `
      <td>${code}</td>
      <td>${desc}</td>
      <td>$ ${precio.toFixed(2)}</td>
      <td>${exist}</td>
      <td>${otras}</td>
      <td>${cat}</td>
      <td>${inv}</td>
      <td>${costo.toFixed(2)}</td>
      <td><button class="action-btn" data-id="${code}" data-name="${desc.replace(/"/g,'&quot;')}" title="Historial de producto">⋮</button></td>
    `;
    inventoryTableBody.appendChild(row);
  });
  if(filtered.length === 0){
    const tr = document.createElement('tr');
    const msg = includeZeroProducts
      ? 'No hay productos para mostrar.'
      : 'No hay productos con stock para mostrar.';
    tr.innerHTML = `<td colspan="${colCount}" style="text-align:center;color:#64748b;">${msg}</td>`;
    inventoryTableBody.appendChild(tr);
  }
  if (inventoryTotalCount) inventoryTotalCount.textContent = String(filtered.length);
}

// Asegurar re-render cuando llegan cambios de Firestore
document.addEventListener('productosUpdated', ()=>{ try{ renderProductsTable(); }catch(_e){} });

// ===================== Consumibles Manager (uso y reemplazos) =====================
// Centraliza funciones para registrar uso por impresiones y marcar reemplazos.
// Nota: Las integraciones con producción/impresión deberán invocar estas funciones.
window.consumiblesManager = (function(){
  function findConsumibleById(prodId){
    const list = Array.isArray(window.products)? window.products : [];
    return list.find(p=> String(p._id||p.id)===String(prodId));
  }
  async function logHist(entry){
    try{
      if(window._firebaseReady && window.firebaseApi && typeof window.firebaseApi.logConsumibleHist==='function'){
        await window.firebaseApi.logConsumibleHist(entry);
      }
    }catch(_e){}
  }
  return {
    /** Registra uso por impresiones para un consumible vinculado a máquina/contador. No ajusta inventario automáticamente salvo que se indique. */
    async registerImpresiones({ productoId, impresiones, maquinaId, contadorId, fecha }){
      if(!productoId || !(impresiones>0)) return;
      const p = findConsumibleById(productoId); if(!p) return;
      const modo = (p.consumibleModo||'').toLowerCase(); if(modo!=='impresiones') return;
      // Actualizar desgaste e historial vía API
      try{
        if(window.firebaseApi && typeof window.firebaseApi.incrementarDesgasteConsumible==='function'){
          await window.firebaseApi.incrementarDesgasteConsumible({ productoId, unidades: Number(impresiones||0), maquinaId, contadorId, fecha });
        } else {
          // Fallback: solo historial
          await logHist({
            productoId: String(productoId), productoDesc: p.descripcion||'', modo:'impresiones', impresiones: Number(impresiones||0),
            maquinaId: maquinaId || p.consumibleMaquinaId || null, contadorId: contadorId || p.consumibleContadorId || null,
            fecha: fecha || (window.getTodayStrTZ? window.getTodayStrTZ() : new Date().toISOString().slice(0,10)), ts: Date.now(), createdBy: (window.auth?.currentUser?.uid)||null
          });
        }
      }catch(_e){ /* swallow */ }
    },
    /** Marca un reemplazo manual (por stock nuevo o cambio). */
    async markReemplazo({ productoId, motivo }){
      if(!productoId) return;
      const p = findConsumibleById(productoId); if(!p) return;
      const entry = {
        productoId: String(productoId),
        productoDesc: p.descripcion||'',
        modo: 'reemplazo',
        motivo: motivo||'reemplazo',
        fecha: (window.getTodayStrTZ? window.getTodayStrTZ() : new Date().toISOString().slice(0,10)),
        ts: Date.now(),
        createdBy: (window.auth?.currentUser?.uid)||null
      };
      await logHist(entry);
    }
  };
})();

function renderSuppliesTable() {
  if(currentInventoryView !== 'supplies') return;
  applyInventorySchema('supplies');
  if (!inventoryTableBody) return;
  try{ if(typeof includeZeroSuppliesEl !== 'undefined' && includeZeroSuppliesEl){ includeZeroSupplies = !!includeZeroSuppliesEl.checked; } }catch(_e){}
  inventoryTableBody.innerHTML = '';
  const data = getSuppliesView();
  const isAllowed = (x)=> __isTrue(x?.esConsumible) === true;
  const hasStock = (x)=> {
    const inv = String(x?.inventario||'').toUpperCase();
    if(inv && inv !== 'SI') return true;
    return Number(x?.existencias||0) > 0;
  };
  const byName = new Map();
  for (const ins of data) {
    const name = (ins.descripcion || '').trim();
    if (!name) continue;
    const prev = byName.get(name) || { ...ins, existencias: 0 };
    prev.existencias = Number(prev.existencias || 0) + Number(ins.existencias || 0);
    if (!prev.proveedor && ins.proveedor) prev.proveedor = ins.proveedor;
    if (!prev.costo && ins.costo) prev.costo = ins.costo;
    prev.otrasSuc = Math.max(Number(prev.otrasSuc || 0), Number(ins.otrasSuc || 0));
    prev.inventario = prev.inventario || ins.inventario || '';
    if (typeof prev.precio !== 'number' && typeof ins.precio === 'number') prev.precio = ins.precio;
    if (!prev.categoria && ins.categoria) prev.categoria = ins.categoria;
    byName.set(name, prev);
  }
  const aggregated = Array.from(byName.values());
  aggregated.forEach(a=>{ if(!a.codigoInterno){ const src = data.find(d=> (d.descripcion||'').trim() === (a.descripcion||'').trim() && d.codigoInterno); if(src) a.codigoInterno = src.codigoInterno; } });
  const search = (currentSearchSupplies || '').toLowerCase();
  const filtered = aggregated.filter(ins =>
    isAllowed(ins)
    && (includeZeroSupplies ? true : hasStock(ins))
    && (ins.descripcion || '').toLowerCase().includes(search)
  );
  const schema = INVENTORY_SCHEMAS.supplies;
  const colCount = schema ? schema.columns.length : 10;
  filtered.forEach((ins) => {
    const code = ins.codigoInterno || '';
    const desc = ins.descripcion || '';
    const wear = Number(ins.consumibleWearActual || 0);
    const exist = Number(ins.existencias || 0);
    const otras = Number(ins.otrasSuc || 0);
    const cat = ins.categoria || '';
    const inv = ins.inventario || '';
    const costo = Number(ins.costo || 0);
    const row = document.createElement('tr');
    row.innerHTML = `
      <td>${code}</td>
      <td>${desc}</td>
  <td>NO INCLUYE</td>
      <td>${wear}</td>
      <td>${exist}</td>
      <td>${otras}</td>
      <td>${cat}</td>
      <td>${inv}</td>
      <td>${costo.toFixed(2)}</td>
      <td><button class="action-btn" data-id="${code}" data-name="${desc.replace(/"/g,'&quot;')}" title="Historial de insumo">⋮</button></td>
    `;
    inventoryTableBody.appendChild(row);
  });
  if(filtered.length === 0){
    const tr = document.createElement('tr');
    const msg = includeZeroSupplies
      ? 'No hay consumibles para mostrar.'
      : 'No hay consumibles con stock para mostrar.';
    tr.innerHTML = `<td colspan="${colCount}" style="text-align:center;color:#64748b;">${msg}</td>`;
    inventoryTableBody.appendChild(tr);
  }
  if (inventoryTotalCount) {
    inventoryTotalCount.textContent = String(filtered.length);
  }
}

// -------- INsumos (módulo nuevo) --------
function getInsumosView(){
  try {
    const prods = Array.isArray(window.products) ? window.products : [];
    const sup = Array.isArray(window.supplies) ? window.supplies : [];
    const isInsumo = (x)=> x && __isTrue(x.esInsumo) === true;
    return prods.filter(isInsumo).concat(sup.filter(isInsumo));
  } catch(_e){
    const prods = Array.isArray(window.products) ? window.products : [];
    const isInsumo = (x)=> x && __isTrue(x.esInsumo) === true;
    return prods.filter(isInsumo);
  }
}

function renderInsumosTable(){
  if(currentInventoryView !== 'insumos') return;
  applyInventorySchema('insumos');
  if(!inventoryTableBody) return;
  try{ const el = document.getElementById('includeZeroInsumos'); if(el) includeZeroInsumos = !!el.checked; }catch(_e){}
  inventoryTableBody.innerHTML = '';
  const data = getInsumosView();
  const isAllowed = (x)=> __isTrue(x?.esInsumo) === true;
  const hasStock = (x)=>{ const inv = String(x?.inventario||'').toUpperCase(); if(inv && inv !== 'SI') return true; return Number(x?.existencias||0) > 0; };
  const search = (currentSearchInsumos||'').toLowerCase();
  const byName = new Map();
  for(const it of data){
    const name = (it.descripcion||'').trim(); if(!name) continue;
    const prev = byName.get(name) || { ...it, existencias:0 };
    prev.existencias = Number(prev.existencias||0) + Number(it.existencias||0);
    prev.otrasSuc = Math.max(Number(prev.otrasSuc||0), Number(it.otrasSuc||0));
    prev.inventario = prev.inventario || it.inventario || '';
    if(!prev.codigoInterno && it.codigoInterno) prev.codigoInterno = it.codigoInterno;
    if(!prev.categoria && it.categoria) prev.categoria = it.categoria;
    if(typeof prev.costo !== 'number' && typeof it.costo === 'number') prev.costo = it.costo;
    byName.set(name, prev);
  }
  const aggregated = Array.from(byName.values());
  const filtered = aggregated.filter(it => isAllowed(it) && (includeZeroInsumos ? true : hasStock(it)) && (it.descripcion||'').toLowerCase().includes(search));
  const schema = INVENTORY_SCHEMAS.insumos;
  const colCount = schema ? schema.columns.length : 9;
  filtered.forEach((ins)=>{
    const code = ins.codigoInterno||'';
    const desc = ins.descripcion||'';
    const exist = Number(ins.existencias||0);
    const otras = Number(ins.otrasSuc||0);
    const cat = ins.categoria||'';
    const inv = ins.inventario||'';
    const costo = Number(ins.costo||0);
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td>${code}</td>
      <td>${desc}</td>
      <td>NO INCLUYE</td>
      <td>${exist}</td>
      <td>${otras}</td>
      <td>${cat}</td>
      <td>${inv}</td>
      <td>${costo.toFixed(2)}</td>
      <td><button class="action-btn" data-id="${code}" data-name="${desc.replace(/"/g,'&quot;')}" title="Historial de insumo">⋮</button></td>
    `;
    inventoryTableBody.appendChild(tr);
  });
  if(filtered.length===0){
    const tr = document.createElement('tr');
    const msg = includeZeroInsumos ? 'No hay insumos para mostrar.' : 'No hay insumos con stock para mostrar.';
    tr.innerHTML = `<td colspan="${colCount}" style="text-align:center;color:#64748b;">${msg}</td>`;
    inventoryTableBody.appendChild(tr);
  }
  if(inventoryTotalCount) inventoryTotalCount.textContent = String(filtered.length);
}

function handleSearchInsumos(){
  const el = document.getElementById('searchInputInsumos');
  currentSearchInsumos = (el?.value||'').trim();
  renderInsumosTable();
}

function exportInsumos(){
  const data = getInsumosView();
  if(!Array.isArray(data) || data.length === 0){ notify('No hay insumos','info'); return; }
  const byName = new Map();
  for(const it of data){
    const name = (it.descripcion||'').trim(); if(!name) continue;
    const prev = byName.get(name) || { ...it, existencias:0 };
    prev.existencias = Number(prev.existencias||0) + Number(it.existencias||0);
    prev.otrasSuc = Math.max(Number(prev.otrasSuc||0), Number(it.otrasSuc||0));
    prev.inventario = prev.inventario || it.inventario || '';
    if(!prev.codigoInterno && it.codigoInterno) prev.codigoInterno = it.codigoInterno;
    if(!prev.categoria && it.categoria) prev.categoria = it.categoria;
    if(typeof prev.costo !== 'number' && typeof it.costo === 'number') prev.costo = it.costo;
    byName.set(name, prev);
  }
  const aggregated = Array.from(byName.values());
  const hasStock = (x)=>{ const inv = String(x?.inventario||'').toUpperCase(); if(inv && inv !== 'SI') return true; return Number(x?.existencias||0) > 0; };
  const search = (currentSearchInsumos||'').toLowerCase();
  const filtered = aggregated.filter(it =>
    __isTrue(it?.esInsumo) === true
    && (includeZeroInsumos ? true : hasStock(it))
    && (it.descripcion||'').toLowerCase().includes(search)
  );
  if(!filtered.length){ notify('No hay insumos','info'); return; }
  const headers = ['Código','Descripción','Precio','Existencias','Otras suc.','Categoría','Inventario','Costo'];
  const rows = filtered.map(ins => [
    ins.codigoInterno || '',
    ins.descripcion || '',
    'NO INCLUYE',
    Number(ins.existencias||0),
    Number(ins.otrasSuc||0),
    ins.categoria || '',
    ins.inventario || '',
    Number(ins.costo||0)
  ]);
  exportToExcel({ filename:'insumos.xls', headers, rows });
}

