/**
 * Abre el modal para registrar una nueva compra
 */
function generateId() {
  // Genera un ID único considerando productos e insumos (solo los que tengan id numérico)
  const prodArr = Array.isArray(window.products) ? window.products : (products || []);
  const supArr = Array.isArray(window.supplies) ? window.supplies : (supplies || []);
  const combined = prodArr.concat(supArr).map(p=>Number(p.id)).filter(n=>Number.isFinite(n));
  if (combined.length === 0) return 1;
  const maxId = Math.max(...combined);
  return maxId + 1;
}

