/**
 * Exporta los productos/insumos filtrados a Excel (.xls)
 */
function exportToCSV() { // nombre legacy conservado por compatibilidad
  if(isSupplies){
    // Replicar la vista de tabla para exportar exactamente lo que se ve
  const raw = getSuppliesView();
  const search = (currentSearchSupplies || '').toLowerCase();
  // Sincronizar estado del toggle desde el checkbox antes de filtrar
  try{ if(typeof includeZeroSuppliesEl !== 'undefined' && includeZeroSuppliesEl){ includeZeroSupplies = !!includeZeroSuppliesEl.checked; } }catch(_e){}
  const isAllowed = (x)=> __isTrue(x?.esConsumible) === true;
    const hasStock = (x)=> {
      const inv = String(x?.inventario||'').toUpperCase();
      if(inv && inv !== 'SI') return true;
      return Number(x?.existencias||0) > 0;
    };
    const byName = new Map();
    for (const ins of raw) {
      const name = (ins.descripcion || '').trim();
      if (!name) continue;
      const prev = byName.get(name) || { ...ins, existencias: 0 };
      prev.existencias = Number(prev.existencias || 0) + Number(ins.existencias || 0);
      prev.otrasSuc = Math.max(Number(prev.otrasSuc || 0), Number(ins.otrasSuc || 0));
      prev.inventario = prev.inventario || ins.inventario || '';
      if (typeof prev.precio !== 'number' && typeof ins.precio === 'number') prev.precio = ins.precio;
      if (!prev.categoria && ins.categoria) prev.categoria = ins.categoria;
      if (!prev.costo && ins.costo) prev.costo = ins.costo;
      if (!prev.codigoInterno && ins.codigoInterno) prev.codigoInterno = ins.codigoInterno;
      byName.set(name, prev);
    }
    const aggregated = Array.from(byName.values());
  const filtered = aggregated.filter(ins => isAllowed(ins) && (includeZeroSupplies ? true : hasStock(ins)) && (ins.descripcion || '').toLowerCase().includes(search));
    if(!filtered.length){ notify('No hay registros para exportar','info'); return; }
  const headers=['Código','Descripción','Precio','Existencias','Otras suc.','Categoría','Inventario','Costo'];
  const rows=filtered.map(i=> [i.codigoInterno||'', i.descripcion, 'NO INCLUYE', Number(i.existencias||0), Number(i.otrasSuc||0), i.categoria||'', i.inventario||'', Number(i.costo||0)]);
    const fecha=new Date().toISOString().substring(0,10);
    window.exportToExcel(headers, rows, `insumos_${fecha}.xls`);
    return;
  }
  // Productos (sin cambios)
  const data = products;
  const filtered = data.filter(item => (item.descripcion||'').toLowerCase().includes((currentSearchProducts||'').toLowerCase()));
  if(!filtered.length){ notify('No hay registros para exportar','info'); return; }
  let headers, rows, filenamePrefix;
  {
    headers=['Código','Descripción','Precio','Existencias','OtrasSuc','Categoría','Inventario','Costo'];
    rows=filtered.map(p=> [p.codigoInterno||'',p.descripcion,p.precio,p.existencias,p.otrasSuc,p.categoria,p.inventario,p.costo]);
    filenamePrefix='productos';
  }
  const fecha=new Date().toISOString().substring(0,10);
  window.exportToExcel(headers, rows, `${filenamePrefix}_${fecha}.xls`);
}

/**
 * Maneja el clic en acciones dentro de la tabla (por ejemplo, eliminar un producto)
 * Utilizamos la delegación de eventos para escuchar los clics en el botón de acciones.
 * @param {MouseEvent} e
 */
function handleTableClick(e) {
  const btn = e.target.closest && e.target.closest('.action-btn');
  if (!btn) return;
  const rawId = btn.getAttribute('data-id');
  const idNum = rawId != null && rawId !== '' ? Number(rawId) : NaN;
  const nameAttr = btn.getAttribute('data-name');
  const prodArr = Array.isArray(window.products) ? window.products : (products || []);
  const supArr = Array.isArray(window.supplies) ? window.supplies : (supplies || []);
  let item = null;
  if (Number.isFinite(idNum)) {
    item = prodArr.find(p => Number(p.id) === idNum) || supArr.find(s => Number(s.id) === idNum);
  }
  const name = item && item.descripcion ? item.descripcion : (nameAttr || '');
  if (!name) return;
  try { window._lastHistoryProductName = name; } catch(_){}
  openProductHistoryModal(name);
}

