function handleOptionsMenuClickSupplies(e) {
  const action = e.target.getAttribute('data-action');
  if (!action) return;
  hideOptionsMenuSupplies();
  switch (action) {
    case 'enviar':
      openSendModal();
      break;
    case 'recibir':
      openReceiveModal();
      break;
    case 'salida':
      openOutModal();
      break;
    case 'historial':
      if (window._lastHistoryProductName) {
        openProductHistoryModal(window._lastHistoryProductName);
      } else {
        openHistoryModal();
      }
      break;
    case 'reemplazar':
      (async ()=>{
        try{
          const sel = (window._lastSelectedConsumible||null);
          // Tomar del último click en tabla (name) si no hay objeto
          const name = sel?.descripcion || window._lastHistoryProductName || '';
          if(!name){ notify('Selecciona una fila primero','info'); return; }
          // Resolver productoId por nombre
          const data = getSuppliesView();
          const prod = data.find(p=> String(p.descripcion||'').toLowerCase() === String(name||'').toLowerCase());
          const prodId = prod ? (String(prod.id||prod._id||'').trim()) : '';
          if(!prod || !prodId){ notify('No se pudo identificar el consumible seleccionado','err'); return; }
          const ok = await confirmAction(`¿Marcar como reemplazado "${prod.descripcion}"? Se bajará 1 de existencias y el desgaste volverá a 0.`);
          if(!ok) return;
          if(window._firebaseReady && window.firebaseApi && typeof window.firebaseApi.marcarConsumibleAcabado==='function'){
            await window.firebaseApi.marcarConsumibleAcabado({ productoId: prodId, motivo: 'reemplazo desde almacén' });
            notify('Consumible reemplazado','ok');
            try{ await window.firebaseApi.refreshProductos?.(); }catch(_e){}
            renderSuppliesTable && renderSuppliesTable();
          } else {
            notify('Firebase no disponible','warn');
          }
        }catch(err){ console.warn(err); notify('No se pudo completar','err'); }
      })();
      break;
    case 'desglose':
      (async ()=>{
        try{
          const name = window._lastHistoryProductName || '';
          if(!name){ notify('Selecciona una fila primero','info'); return; }
          // Resolver id
          const data = getSuppliesView();
          const prod = data.find(p=> String(p.descripcion||'').toLowerCase() === String(name||'').toLowerCase());
          const prodId = prod ? (String(prod.id||prod._id||'').trim()) : '';
          if(!prod || !prodId){ notify('No se pudo identificar el consumible','warn'); return; }
          if(!(window._firebaseReady && window.firebaseApi && typeof window.firebaseApi.listConsumibleWearOrigen==='function')){
            notify('Función no disponible','warn'); return;
          }
          const rows = await window.firebaseApi.listConsumibleWearOrigen(prodId, 200);
          renderWearBreakdown(rows||[]);
          openWearBreakdown();
        }catch(err){ console.warn(err); notify('No se pudo cargar el desglose','err'); }
      })();
      break;
    default:
      break;
  }
}

