// -----------------------------------------------------------------------------
// Envío de productos a otra sucursal
// -----------------------------------------------------------------------------

/**
 * Abre el modal de envío y prepara campos.
 */
function openSendModal() {
  // Restablecer filtro del datalist para flujos que no son de compra
  datalistMode = 'default';
  // Establecer fecha actual
  const today = new Date().toISOString().substring(0, 10);
  sendDateInput.value = today;
  sendDestinationInput.value = '';
  sendProductInput.value = '';
  sendQuantityInput.value = 1;
  sendItems = [];
  renderSendItems();
  updateProductDatalist();
  sendOverlay.classList.remove('hidden');
}

/** Cierra el modal de envío */
function closeSendModal() {
  sendOverlay.classList.add('hidden');
}

/** Agrega una línea al arreglo de envío */
function addSendItem() {
  const prodName = sendProductInput.value.trim();
  const qty = parseInt(sendQuantityInput.value);
  if (!prodName) { notify('Producto requerido','warn'); return; }
  if (isNaN(qty) || qty <= 0) { notify('Cantidad inválida','err'); return; }
  // Verificar que el producto/insumo exista y tenga suficientes existencias
  const data = isSupplies ? getSuppliesView() : products;
  const existing = data.find((item) => item.descripcion.toLowerCase() === prodName.toLowerCase());
  if (!existing) { notify('No existe en inventario','err'); return; }
  if (existing.existencias < qty) { notify('Stock insuficiente '+existing.existencias,'warn'); return; }
  sendItems.push({ producto: prodName, cantidad: qty });
  sendProductInput.value = '';
  sendQuantityInput.value = 1;
  renderSendItems();
}

/** Renderiza las líneas de envío en la tabla */
function renderSendItems() {
  sendItemsBody.innerHTML = '';
  sendItems.forEach((item, index) => {
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td>${item.cantidad}</td>
      <td>PZA</td>
      <td>${item.producto}</td>
      <td><button type="button" data-index="${index}" title="Eliminar">×</button></td>
    `;
    sendItemsBody.appendChild(tr);
  });
}

/** Maneja clics en la tabla de envío para eliminar líneas */
function handleSendItemsClick(e) {
  if (e.target.tagName === 'BUTTON' && e.target.dataset.index !== undefined) {
    const idx = parseInt(e.target.dataset.index);
    sendItems.splice(idx, 1);
    renderSendItems();
  }
}

/** Maneja el envío al enviar el formulario de envío */
function handleSendSubmit(e) {
  e.preventDefault();
  if (sendItems.length === 0) { notify('Agrega productos','warn'); return; }
  const destination = sendDestinationInput.value.trim();
  if (!destination) { notify('Destino requerido','warn'); return; }
  // Validar cantidades disponibles y actualizar inventario en el conjunto activo
  const data = isSupplies ? getSuppliesView() : products;
  // Validación best-effort con datos locales (puede estar desfasada); Firestore hará la verificación real.
  for (const item of sendItems) {
    const prod = data.find((p) => (p.descripcion||'').toLowerCase() === item.producto.toLowerCase());
    if (!prod) { notify('Producto no encontrado: '+item.producto,'err'); return; }
  }
  // No ajustar localmente; se hará en Firestore y onSnapshot refrescará.
  // Agregar a historial
  // No mantener historial local; Firestore es la fuente de verdad
  // Persistir a Firestore si está disponible
  if(window._firebaseReady && window.firebaseApi){
    const ops = [];
    sendItems.forEach((item)=>{
      const prod = data.find((p) => p.descripcion.toLowerCase() === item.producto.toLowerCase());
      if(prod && prod._id){
        const FV = window.firebase?.firestore?.FieldValue;
        const patch = {};
        if(FV && FV.increment){
          patch.existencias = FV.increment(-Number(item.cantidad||0));
          patch.otrasSuc = FV.increment(Number(item.cantidad||0));
        }
        ops.push(window.firebaseApi.updateProducto(prod._id, patch));
      }
    });
    Promise.allSettled(ops).then(()=>{ notify('Envío sincronizado','ok'); }).catch(()=>{});
  }
  sendItems = [];
  closeSendModal();
  notify('Envío registrado','ok');
}

