function handleReceiveSubmit(e) {
  e.preventDefault();
  if (receiveItems.length === 0) { notify('Agrega productos','warn'); return; }
  const source = receiveSourceInput.value.trim();
  if (!source) { notify('Origen requerido','warn'); return; }
  const data = isSupplies ? getSuppliesView() : products;
  // Persistencia Firestore
  if(window._firebaseReady && window.firebaseApi){
    const ops = [];
    const FV = window.firebase?.firestore?.FieldValue;
    receiveItems.forEach((item)=>{
      const rec = data.find((p) => (p.descripcion||'').toLowerCase() === item.producto.toLowerCase());
      if(rec && rec._id){
        const patch = {};
        if(FV && FV.increment){
          patch.existencias = FV.increment(Number(item.cantidad||0));
          patch.otrasSuc = FV.increment(-Number(item.cantidad||0));
        }
        ops.push(window.firebaseApi.updateProducto(rec._id, patch));
      }
    });
    Promise.allSettled(ops).then(()=> notify('Recepción sincronizada','ok')).catch(()=>{});
  }
  receiveItems = [];
  closeReceiveModal();
  notify('Recepción registrada','ok');
}

