/**
 * Abre el modal de historial para un producto específico y renderiza su tabla.
 * @param {string} productName
 */
function openProductHistoryModal(productName) {
  renderProductHistory(productName);
  productHistoryOverlay.classList.remove('hidden');
}

/**
 * Cierra el modal de historial de producto.
 */
function closeProductHistoryModal() {
  productHistoryOverlay.classList.add('hidden');
}

/**
 * Genera y muestra el historial de movimientos para un producto específico.
 * Muestra las columnas Fecha, Detalle, Cantidad, Actual y Costo.
 * La columna Actual se calcula acumulando las entradas en orden cronológico.
 * @param {string} productName
 */
async function renderProductHistory(productName) {
  // Limpiar contenido
  productHistoryBody.innerHTML = '';
  const lowerName = String(productName||'').toLowerCase();
  // 1) Intentar obtener historial real desde Firestore (colección compras)
  let records = [];
  try {
    if (window._firebaseReady && window.firebaseApi && typeof window.firebaseApi.listCompras === 'function') {
      records = await window.firebaseApi.listCompras(500);
    }
  } catch(_e) { /* fallback abajo */ }
  // 2) Fallback a arrays locales si existen
  if (!Array.isArray(records) || records.length === 0) {
    const baseList = Array.isArray(window.productHistory)
      ? window.productHistory
      : (Array.isArray(window.historyRecords) ? window.historyRecords : []);
    records = baseList.slice();
  }
  // Normalizar estructura: esperamos [{fecha, items:[{producto,cantidad,costo,codigo?}], tipo?}]
  const entries = [];
  const sorted = records.slice().sort((a,b)=> String(a.fecha||'').localeCompare(String(b.fecha||'')));
  for (const rec of sorted) {
    const tipo = rec.tipo || 'Compra';
    const items = Array.isArray(rec.items) ? rec.items : [];
    for (const it of items) {
      if (!it || !it.producto) continue;
      if (String(it.producto).toLowerCase() !== lowerName) continue;
      let qty = Number(it.cantidad||0);
      let costo = Number(it.costo||0);
      // Sólo nos interesan compras para estas columnas (ignorar envíos/recepciones/salidas)
      // Resolver código: de item o buscando en catálogo local por descripción
      let codigo = it.codigo || it.codigoInterno || '';
      if(!codigo){
        try{
          const all = [];
          if(Array.isArray(window.products)) all.push(...window.products);
          if(Array.isArray(window.supplies)) all.push(...window.supplies);
          const found = all.find(p=> String(p.descripcion||'').toLowerCase()===lowerName);
          if(found && (found.codigoInterno||found.codigo)) codigo = found.codigoInterno || found.codigo || '';
        }catch(_e){}
      }
      entries.push({ codigo, fecha: rec.fecha || '', cantidad: qty, costo, costoTotal: qty * costo });
    }
  }
  // Construir tabla
  entries.sort((a,b)=> String(a.fecha||'').localeCompare(String(b.fecha||'')));
  for (const entry of entries) {
    const tr = document.createElement('tr');
    const qtyClass = entry.cantidad > 0 ? 'pos' : entry.cantidad < 0 ? 'neg' : '';
    const costoStr = Number(entry.costo||0) ? ('$ ' + Number(entry.costo).toFixed(2)) : '0';
    const costoTotStr = Number(entry.costoTotal||0) ? ('$ ' + Number(entry.costoTotal).toFixed(2)) : '0';
    tr.innerHTML = `
      <td>${entry.codigo||''}</td>
      <td>${entry.fecha}</td>
      <td class="${qtyClass}">${entry.cantidad}</td>
      <td>${costoStr}</td>
      <td>${costoTotStr}</td>
    `;
    productHistoryBody.appendChild(tr);
  }
  if (entries.length === 0) {
    const tr = document.createElement('tr');
    tr.innerHTML = `<td colspan="5" style="text-align:center;color:#64748b;padding:8px;">Sin historial para "${productName}"</td>`;
    productHistoryBody.appendChild(tr);
  }
}

// Permitir que el menú "Historial" use la última fila seleccionada (click o clic derecho)
function rememberRowProductName(target){
  try{
    const tr = target && target.closest ? target.closest('tr') : null;
    if(!tr) return;
    // segunda columna es la descripción
    const nameCell = tr.querySelector('td:nth-child(2)');
    const name = (nameCell && nameCell.textContent ? nameCell.textContent : '').trim();
    if(name) window._lastHistoryProductName = name;
    // Guardar objeto básico del consumible (si existe) para acciones como reemplazar
    try{
      const data = getSuppliesView();
      const found = data.find(p=> String(p.descripcion||'').trim() === name);
      if(found) window._lastSelectedConsumible = { id: found.id, descripcion: found.descripcion };
    }catch(_e){}
  }catch(_e){}
}

// ----------------------------
// Modal: Desglose de desgaste
// ----------------------------
// Idempotent assignments onto window to avoid redeclaration on re-evaluations
window.wearBreakdownOverlay = window.wearBreakdownOverlay || document.getElementById('wearBreakdownOverlay');
window.closeWearBreakdownBtn = window.closeWearBreakdownBtn || document.getElementById('closeWearBreakdownBtn');
window.wearBreakdownBody = window.wearBreakdownBody || document.getElementById('wearBreakdownBody');
// Backward local aliases (do not redeclare if they already exist in scope)
try{ /* eslint-disable no-undef */ wearBreakdownOverlay = window.wearBreakdownOverlay; /* eslint-enable */ }catch(_e){}
try{ /* eslint-disable no-undef */ closeWearBreakdownBtn = window.closeWearBreakdownBtn; /* eslint-enable */ }catch(_e){}
try{ /* eslint-disable no-undef */ wearBreakdownBody = window.wearBreakdownBody; /* eslint-enable */ }catch(_e){}
function openWearBreakdown(){ wearBreakdownOverlay?.classList.remove('hidden'); }
function closeWearBreakdown(){ wearBreakdownOverlay?.classList.add('hidden'); }
function renderWearBreakdown(rows){
  if(!wearBreakdownBody) return;
  wearBreakdownBody.innerHTML = '';
  const name = (window._lastHistoryProductName||'').trim();
  // Si conocemos el consumible seleccionado, intentamos filtrar desde su último reemplazo (consumibleWearDesde)
  let sinceMillis = null;
  try{
    const data = getSuppliesView();
    const prod = data.find(p=> String(p.descripcion||'').toLowerCase()===name.toLowerCase());
    const ts = prod && prod.consumibleWearDesde;
    if(ts && typeof ts.toDate==='function') sinceMillis = ts.toDate().getTime();
  }catch(_e){}
  const filtered = Array.isArray(rows) ? rows.filter(r=> !sinceMillis || (r.tsMillis ? r.tsMillis>=sinceMillis : true)) : [];
  if(!filtered.length){
    const tr = document.createElement('tr');
    tr.innerHTML = `<td colspan="2" style="text-align:center;color:#64748b;">Sin registros</td>`;
    wearBreakdownBody.appendChild(tr); return;
  }
  // Agregar sumatoria por producto
  const byProd = new Map();
  for(const r of filtered){
    const key = r.ventaProductoDesc || r.ventaProductoId || '—';
    const prev = byProd.get(key) || 0;
    const inc = Number(r.impresiones||r.unidades||0) || 0;
    byProd.set(key, prev + inc);
  }
  // Si se aplicó filtro, agregar un pequeño aviso como primera fila sutil
  if(sinceMillis){
    const d = new Date(sinceMillis);
    const tz = window.__FECHA_TZ__ || 'America/Mexico_City';
    const dateStr = new Intl.DateTimeFormat('es-MX',{ timeZone: tz, year:'numeric', month:'2-digit', day:'2-digit'}).format(d);
    const trInfo = document.createElement('tr');
    trInfo.innerHTML = `<td colspan="2" style="text-align:center;color:#64748b;padding:4px 0;">Desde reemplazo: ${dateStr}</td>`;
    wearBreakdownBody.appendChild(trInfo);
  }
  Array.from(byProd.entries()).sort((a,b)=> b[1]-a[1]).forEach(([k,v])=>{
    const tr = document.createElement('tr');
    tr.innerHTML = `<td>${k||'—'}</td><td>${v}</td>`;
    wearBreakdownBody.appendChild(tr);
  });
}

/**
 * Abre el modal de compra y prepara los campos iniciales.
 */
async function openPurchaseModal() {
  // Establecer modo de datalist según la vista actual:
  // - En vista de insumos, sugerir solo consumibles/insumos
  // - En vista normal, sugerir solo productos vendibles
  const insumosSection = document.getElementById('insumos-section');
  const insumosVisible = !!insumosSection && !insumosSection.classList.contains('hidden');
  datalistMode = ((typeof isSupplies !== 'undefined' && isSupplies) || insumosVisible) ? 'consumibles' : 'purchase';
  // Reiniciar campos de fecha e invoice
  const today = new Date();
  // Formatear fecha como yyyy-mm-dd para input type="date"
  const isoDate = today.toISOString().substring(0, 10);
  purchaseDateInput.value = isoDate;
  // Asignar folio tentativo automático desde Firestore (peek)
  if(invoiceInput) invoiceInput.value = await peekNextInvoice();
  // Limpiar entradas de item
  resetPurchaseVariantUI();
  itemProductInput.value = '';
  itemQuantityInput.value = 1;
  itemProviderInput.value = '';
  itemUnitCostInput.value = 0;
  // Limpiar listado de ítems
  purchaseItems = [];
  renderPurchaseItems();
  // Actualizar datalist de productos con los nombres actuales
  updateProductDatalist();
  purchaseOverlay.classList.remove('hidden');
}

/**
 * Cierra el modal de compra y limpia los datos temporales.
 */
function closePurchaseModal() {
  // Restaurar modo por defecto al cerrar
  datalistMode = 'default';
  resetPurchaseVariantUI();
  purchaseOverlay.classList.add('hidden');
}

/**
 * Actualiza el datalist de productos para autocompletar.
 */
function updateProductDatalist() {
  // Vaciar opciones actuales
  productDatalist.innerHTML = '';
  // Evitar ReferenceError si se llama muy temprano
  const mode = (typeof datalistMode === 'string' && datalistMode) ? datalistMode : 'default';
  // Seleccionar nombres según el modo: para 'purchase' y 'consumibles' usar SIEMPRE el catálogo completo
  let data;
  if (mode === 'purchase' || mode === 'consumibles') {
    data = Array.isArray(window.products) ? window.products : (products || []);
  } else {
    data = isSupplies 
      ? getSuppliesView()
      : (Array.isArray(window.products) ? window.products : (products || []));
  }
  // Si estamos en compras de productos, sugerir SOLO productos vendibles (no insumos/consumibles)
  if (mode === 'purchase') {
    const isVendibleProducto = (p)=>{
      if(!p) return false;
      // Prioriza banderas de tipo (tolerante)
      if(__isTrue(p.esProducto) || __isTrue(p.esServicio)) return true;
      if(__isTrue(p.esInsumo) || __isTrue(p.esConsumible)) return false;
      // Fallback legacy
      return p.puedeVender !== false;
    };
    data = (Array.isArray(data) ? data : []).filter(isVendibleProducto).filter(p=> String(p.estatus||'Activo').toLowerCase()==='activo');
  } else if (mode === 'consumibles') {
    // En compras desde vista de insumos: sugerir solo insumos/consumibles
    const isConsumible = (p)=>{
      if(!p) return false;
      if(__isTrue(p.esConsumible) || __isTrue(p.esInsumo)) return true;
      if(__isTrue(p.esProducto) || __isTrue(p.esServicio)) return false;
      // Si no hay banderas, por seguridad no lo incluimos
      return false;
    };
    data = (Array.isArray(data) ? data : []).filter(isConsumible).filter(p=> String(p.estatus||'Activo').toLowerCase()==='activo');
  }
  const normalize = (s)=> String(s||'')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'')
    .trim();
  const query = normalize(itemProductInput && itemProductInput.value);
  // Construir lista de nombres únicos
  const seen = new Set();
  const items = [];
  for(const p of (Array.isArray(data) ? data : [])){
    const name = p && p.descripcion;
    if(!name) continue;
    if(seen.has(name)) continue; // evitar duplicados
    seen.add(name);
    const nName = normalize(name);
    let score = 0;
    if(query){
      if(nName.startsWith(query)) score = 3;
      else if(nName.includes(' ' + query)) score = 2; // coincidencia en límite de palabra
      else if(nName.includes(query)) score = 1;
      else score = 0;
    }else{
      score = 0; // sin query, sin preferencia
    }
    items.push({ name, score, nName });
  }
  // Ordenar por mejor coincidencia y luego alfabético
  items.sort((a,b)=> (b.score - a.score) || a.nName.localeCompare(b.nName));
  // Limitar número de sugerencias para datalist
  const limit = 100;
  for(let i=0; i<items.length && i<limit; i++){
    // Si hay query, opcional: no mostrar entradas sin coincidencia alguna
    if(query && items[i].score === 0) break;
    const option = document.createElement('option');
    option.value = items[i].name;
    productDatalist.appendChild(option);
  }
}

/**
 * Agrega un ítem al arreglo de purchaseItems y re-renderiza la tabla de ítems.
 */
function addItemToPurchase() {
  const prodName = itemProductInput.value.trim();
  // Prefill por si el usuario seleccionó desde datalist pero no tabuló por los otros campos
  prefillProviderAndCost();
  let provider = itemProviderInput.value.trim();
  let unitCost = parseFloat(itemUnitCostInput.value);
  const list = Array.isArray(window.products)? window.products : (typeof products !== 'undefined' ? products : []);
  const foundProd = list.find(p=> (p.descripcion||'').toLowerCase() === prodName.toLowerCase());
  if(!provider || !Number.isFinite(unitCost) || unitCost<=0){
    if(foundProd){
      if(!provider) provider = foundProd.proveedor || '';
      if(!Number.isFinite(unitCost) || unitCost<=0){
        const costo = Number(foundProd.costo);
        const precio = Number(foundProd.precio);
        unitCost = Number.isFinite(costo) && costo>0 ? costo : (Number.isFinite(precio)? precio : 0);
      }
    }
  }
  if (!prodName) { notify('Debes especificar un producto','warn'); return; }
  const usingVariants = !!(purchaseVariantState && variantQuantityGroup && !variantQuantityGroup.classList.contains('hidden'));
  let quantity = 0;
  let variantDetails = [];
  if(usingVariants){
    variantDetails = purchaseVariantState.variantes
      .filter(v=> Number(v.cantidad||0) > 0)
      .map(v=> ({ nombre: v.nombre, cantidad: Number(v.cantidad||0), existenciasPrevias: Number(v.existencias||0) }));
    quantity = variantDetails.reduce((sum, v)=> sum + Number(v.cantidad||0), 0);
    if(!variantDetails.length){ notify('Captura al menos una variante con cantidad','warn'); return; }
  } else {
    quantity = parseInt(itemQuantityInput.value);
    if (isNaN(quantity) || quantity <= 0) { notify('La cantidad debe ser mayor a cero','warn'); return; }
  }
  if (!Number.isFinite(unitCost) || unitCost < 0) { notify('El costo por unidad no es válido','warn'); return; }
  const total = quantity * unitCost;
  const payload = {
    producto: prodName,
    cantidad: quantity,
    proveedor: provider,
    costo: unitCost,
    total
  };
  if(usingVariants){
    payload.variantes = variantDetails;
    if(purchaseVariantState?.productoId) payload.productoId = purchaseVariantState.productoId;
  }
  purchaseItems.push(payload);
  // Limpiar campos para siguiente entrada
  resetPurchaseVariantUI();
  itemProductInput.value = '';
  itemQuantityInput.value = 1;
  itemProviderInput.value = '';
  itemUnitCostInput.value = 0;
  renderPurchaseItems();
}

/**
 * Renderiza la tabla con los ítems agregados en la compra.
 */
function renderPurchaseItems() {
  purchaseItemsBody.innerHTML = '';
  purchaseItems.forEach((item, index) => {
    const tr = document.createElement('tr');
    const esc = (s)=> String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    const variantInfo = (Array.isArray(item.variantes) && item.variantes.length)
      ? `<div class="variant-summary">${item.variantes.map(v=>`${esc(v.nombre)} × ${Number(v.cantidad||0)}`).join('<br>')}</div>`
      : '';
    tr.innerHTML = `
      <td>${item.cantidad}</td>
      <td>PZA</td>
      <td>${esc(item.producto)}${variantInfo}</td>
      <td>${item.proveedor || ''}</td>
      <td>$ ${item.costo.toFixed(2)}</td>
      <td>$ ${(item.total).toFixed(2)}</td>
      <td><button type="button" data-index="${index}" title="Eliminar">×</button></td>
    `;
    purchaseItemsBody.appendChild(tr);
  });
}

/**
 * Actualiza localmente el inventario tras una compra (optimista, sin esperar Firestore).
 * Crea el producto si no existe, respetando reglas de insumos cuando aplique.
 * @param {Array<{producto:string,cantidad:number,costo:number,proveedor?:string}>} items
 * @param {boolean} asSuppliesFlow - true si la compra fue hecha desde la vista de insumos
 */
// Eliminado: applyLocalPurchase. Toda actualización de inventario ocurre en Firestore y la UI se actualiza vía onSnapshot.

/**
 * Maneja el clic en la tabla de ítems para eliminar una línea.
 */
function handlePurchaseItemsClick(e) {
  if (e.target.tagName === 'BUTTON' && e.target.dataset.index !== undefined) {
    const idx = parseInt(e.target.dataset.index);
    purchaseItems.splice(idx, 1);
    renderPurchaseItems();
  }
}

/**
 * Finaliza la compra: actualiza el inventario de productos, crea nuevos si no existen y cierra el modal.
 * @param {SubmitEvent} e
 */
async function handlePurchaseSubmit(e) {
  e.preventDefault();
  if (purchaseItems.length === 0) { notify('Agrega al menos un producto a la compra','warn'); return; }
  // Asegurar folio reclamado en Firestore para esta compra
  let claimedFolio = null;
  try{ claimedFolio = await claimNextInvoice(); }catch(err){ console.warn('No se pudo reclamar folio de compra', err); }
  if(invoiceInput && claimedFolio){ invoiceInput.value = claimedFolio; }
  // Persistencia directa en Firestore por ítem (upsert lógico)
  const isSupplyFlow = isSupplies; // conservar lectura (vista actual)
  // Importante: siempre operar sobre la colección de productos (insumos = productos no vendibles)
  const sourceArray = products;
  const recordItems = [];
  const ops = [];
  purchaseItems.forEach(item => {
    const recordEntry = { producto: item.producto, cantidad: item.cantidad, costo: item.costo };
    if(item.proveedor) recordEntry.proveedor = item.proveedor;
    if(Array.isArray(item.variantes) && item.variantes.length){
      recordEntry.variantes = item.variantes.map(v=> ({ nombre: v.nombre, cantidad: Number(v.cantidad||0) }));
    }
    recordItems.push(recordEntry);
    if(window._firebaseReady && window.firebaseApi){
      const fields = {
        proveedor: item.proveedor || '',
  // No sobrescribir el precio de venta desde compras: solo actualiza costo y existencias
        costo: item.costo,
        inventario: 'SI',
        existenciasIncrement: Number(item.cantidad||0)
      };
      if(isSupplyFlow){
        fields.esInsumo = true;
        fields.esServicio = false;
        fields.esProducto = false;
        fields.esConsumible = false;
      }
      if(Array.isArray(item.variantes) && item.variantes.length){
        fields.variantExistenciasAdjust = item.variantes.map(v=> ({ nombre: v.nombre, cantidad: Number(v.cantidad||0) }));
      }
      ops.push(window.firebaseApi.upsertProductoByDescripcionLower(item.producto, fields)
        .catch(err=>{ console.warn('Error upsert producto', item.producto, err); notify('Error con '+item.producto,'err'); }));
    } else {
      // Sin Firebase listo: bloquear compra para evitar datos locales
      notify('Firebase no disponible. Intenta de nuevo en unos segundos.','err');
    }
  });
  // Registrar compra como documento de historial en Firestore
  if(window._firebaseReady && window.firebaseApi && typeof window.firebaseApi.addCompra==='function'){
    try{
      const total = recordItems.reduce((s,it)=> s + Number((it.costo||0) * (it.cantidad||0)), 0);
      await window.firebaseApi.addCompra({
        fecha: purchaseDateInput.value,
        factura: (invoiceInput && invoiceInput.value) || null,
        vista: isSupplyFlow? 'INSUMOS':'PRODUCTOS',
        total,
        items: recordItems
      });
    }catch(err){ console.warn('No se pudo registrar documento de compra', err); }
  }
  // No actualizar localmente. onSnapshot actualizará la UI al confirmar los writes.
  // Cerrar modal y limpiar UI temprano
  purchaseItems = [];
  closePurchaseModal();
  notify('Registrando compra en Firebase...','info');
  if(ops.length){
    Promise.all(ops).then(()=>{
      notify('Compra registrada. Refrescando desde Firebase...','ok');
      // Disparar actualización inmediata de UI dependiente de productos (datalist, costos, etc.)
      try { document.dispatchEvent(new Event('productosUpdated')); } catch(_e){}
    }).catch(()=>{/* errores individuales ya notificados */});
  } else {
    notify('No se pudo registrar compra: Firebase no disponible','err');
  }
}

// -----------------------------------------------------------------------------
// Funciones para Caja (ingresos/gastos)
// -----------------------------------------------------------------------------

// Admin toggle: ver todos los turnos (estado global con persistencia simple)
window.__showAllTurnos = (function(){ try{ return localStorage.getItem('showAllTurnos')==='1'; }catch(_e){ return false; } })();
function isAdminRole(){ try{ return String(window.currentUserRole||'').toLowerCase()==='admin'; }catch(_e){ return false; } }
function setShowAllTurnos(val){
  try{ localStorage.setItem('showAllTurnos', val? '1':'0'); }catch(_e){}
  window.__showAllTurnos = !!val;
  try{ const c1 = document.getElementById('adminToggleAllTurnosCaja'); if(c1) c1.checked = !!val; }catch(_e){}
  try{ const c2 = document.getElementById('adminToggleAllTurnosHist'); if(c2) c2.checked = !!val; }catch(_e){}
  try{ renderCashTable(); }catch(_e){}
  try{ renderHistoricoTable(); }catch(_e){}
  try{ renderCutSummary(); }catch(_e){}
}
// Mostrar/ocultar controles según rol (escucha de authRoleReady definida en firebase.js)
try{
  document.addEventListener('authRoleReady', (ev)=>{
    const role = (ev && ev.detail && ev.detail.role) ? String(ev.detail.role) : (window.currentUserRole||'');
    const isAdmin = String(role||'').toLowerCase() === 'admin';
    const w1 = document.getElementById('toggleAllTurnosCajaWrap');
    const w2 = document.getElementById('toggleAllTurnosHistWrap');
    const c1 = document.getElementById('adminToggleAllTurnosCaja');
    const c2 = document.getElementById('adminToggleAllTurnosHist');
    if(w1) w1.style.display = isAdmin? 'inline-flex':'none';
    if(w2) w2.style.display = isAdmin? 'inline-flex':'none';
    if(!isAdmin){
      // Asegurar que no quede activo el bypass si no es admin
      if(window.__showAllTurnos){ setShowAllTurnos(false); }
    }
    if(c1){ c1.checked = !!window.__showAllTurnos; c1.onchange = (e)=> setShowAllTurnos(!!e.target.checked); }
    if(c2){ c2.checked = !!window.__showAllTurnos; c2.onchange = (e)=> setShowAllTurnos(!!e.target.checked); }
  });
}catch(_e){}

/**
 * Genera un ID único para un registro de caja.
 */
function generateCashId() {
  if (cashRecords.length === 0) return 1;
  const maxId = Math.max(...cashRecords.map((r) => r.id));
  return maxId + 1;
}

/**
 * Renderiza la tabla de caja con los registros actuales, filtrando por búsqueda.
 */
function renderCashTable() {
  const cashBody = document.getElementById('cashBody');
  if(!cashBody) return;
  cashBody.innerHTML = '';
  // Filtrar por búsqueda en descripción
  const termCaja = String(currentSearchCaja || '').toLowerCase();
  // Aplicar filtro por turno activo si existe
  // Usar la fuente viva desde window para evitar referencias obsoletas
  let baseList = Array.isArray(window.cashRecords) ? window.cashRecords : (Array.isArray(window.historicalCashRecords) ? window.historicalCashRecords : cashRecords);
  try{
    if(!(window.__showAllTurnos && isAdminRole())){
      const turnoId = window.currentTurnoId || null;
      const aperturaMs = window.__lastTurnoOpen?.abiertoEnApproxMs || null;
      if(turnoId){
        const byId = baseList.filter(r=> r && r.turnoId === turnoId);
          if(byId.length){
            baseList = byId;
          } else if(aperturaMs){
            // Normalizar createdAt a milisegundos si existe; si el filtro deja vacío, no aplicar
            const alt = baseList.filter(r=>{
              if(!r) return false;
              const ca = (typeof r.createdAtMs==='number' && r.createdAtMs)
                || (r.createdAt && typeof r.createdAt.toMillis==='function' && r.createdAt.toMillis())
                || (typeof r.createdAt==='number' && r.createdAt)
                || null;
              return (typeof ca==='number') && ca>=aperturaMs;
            });
            baseList = alt.length ? alt : baseList;
          }
      }
    }
  }catch(_e){}
  const filtered = baseList.filter((rec) => {
    const haystack = [rec && rec.descripcion, rec && rec.categoriaNombre, rec && rec.categoria, rec && rec.motivo]
      .map(v => String(v || '').toLowerCase())
      .join(' ');
    return haystack.includes(termCaja);
  });
  // Helper: resolver nombre de usuario a partir de userId/uid o correo
  const resolveUserName = (rec)=>{
    try{
      const list = Array.isArray(window.usuarios) ? window.usuarios : [];
      const uid = String(rec?.userId || rec?.uid || rec?.usuarioId || '').trim();
      if(uid){
        const u = list.find(x => String(x.id||x.uid) === uid);
        if(u){ return (u.nombre || u.displayName || u.correo || '').trim(); }
      }
      const raw = String(rec?.usuario||'').trim();
      if(raw){
        // Intentar match por correo si es email
        const byMail = list.find(x => String(x.correo||'').trim().toLowerCase() === raw.toLowerCase());
        if(byMail) return (byMail.nombre || byMail.displayName || byMail.correo || '').trim();
        // Si es email y no hay match, mostrar parte antes de @; si no, mostrar tal cual
        if(raw.includes('@')) return raw.split('@')[0];
        return raw;
      }
    }catch(_e){}
    return '';
  };
  // Recorrer cada registro filtrado y renderizar la fila correspondiente
  filtered.forEach((rec) => {
    const tr = document.createElement('tr');
    // Clasificación por tipo
    const t = String(rec?.tipo||'').toUpperCase();
    const isIngreso = (t==='INGRESO' || t==='VENTA' || t==='VENTA_PAGO_INICIAL' || t==='VENTA_ABONO' || t==='VENTA_ABONO_PERSONAL' || t==='FACTURA_ABONO');
    const isSalida = (t==='GASTO' || t==='RETIRO' || t==='DEVOLUCION_ABONO_PERSONAL' || t==='VENTA_CANCELACION');
    // Determinar clase para importe con colores específicos por tipo
    const amountClass = (
      t==='VENTA_ABONO_PERSONAL' ? 'amt-amber' :
      t==='DEVOLUCION_ABONO_PERSONAL' ? 'amt-orange' :
      (t==='GASTO' || t==='RETIRO' || t==='VENTA_CANCELACION') ? 'amt-red' :
      (t==='INGRESO' || t==='VENTA' || t.startsWith('VENTA_') || t==='FACTURA_ABONO') ? 'amt-green' :
      (isIngreso ? 'amt-green' : (isSalida ? 'amt-red' : ''))
    );
    let rowHtml = '';
    // Fecha y hora
    const fechaHora = rec.hora ? `${rec.fecha} ${rec.hora}` : rec.fecha;
    rowHtml += `<td>${fechaHora}</td>`;
    // Motivo: si es Gasto, mostrar la categoría; si no, la descripción/motivo
    // Resolver folio legible desde venta/factura si no viene en el registro
    let folioResolved = rec.ventaFolio || rec.facturaFolio || '';
    if(!folioResolved && rec.ventaId && Array.isArray(window.ventas)){
      const v = window.ventas.find(x=> x.id===rec.ventaId || x._id===rec.ventaId);
      if(v && v.folio) folioResolved = v.folio;
    }
    if(!folioResolved && rec.facturaId && Array.isArray(window.facturas)){
      const f = window.facturas.find(x=> x.id===rec.facturaId || x._docId===rec.facturaId);
      if(f && f.folio!=null) folioResolved = String(f.folio);
    }
    let motivoText = '';
    if (t==='GASTO') {
      // Base (se reemplaza por chip más abajo)
      motivoText = rec.categoriaNombre || rec.categoria || rec.descripcion || 'Gasto';
    } else if (t==='RETIRO') {
      // Base (se reemplaza por chip más abajo)
      motivoText = rec.descripcion || rec.motivo || 'Retiro de efectivo';
    } else if (t==='INGRESO') {
      // Base (se reemplaza por chip más abajo)
      motivoText = rec.descripcion || rec.motivo || 'Ingreso';
  } else if (t==='VENTA_PAGO_INICIAL' || t==='VENTA_ANTICIPO') {
      motivoText = rec.descripcion || `Pago inicial Venta ${folioResolved}`.trim();
    } else if (t==='VENTA_ABONO') {
      motivoText = rec.descripcion || `Abono Venta ${folioResolved}`.trim();
    } else if (t==='VENTA_ABONO_PERSONAL') {
      motivoText = rec.descripcion || `Abono personal Venta ${folioResolved}`.trim();
    } else if (t==='DEVOLUCION_ABONO_PERSONAL') {
      motivoText = rec.descripcion || `Devolución abono personal ${folioResolved}`.trim();
    } else if (t==='VENTA') {
      motivoText = rec.descripcion || `Cobro total Venta ${folioResolved}`.trim();
    } else if (t==='FACTURA_ABONO') {
      motivoText = rec.descripcion || `Abono Factura ${folioResolved}`.trim();
    } else {
      motivoText = rec.descripcion || rec.motivo || 'Movimiento de caja';
    }
    // Evitar mostrar IDs crudos si no hubo folio
    motivoText = motivoText.replace(/\s+[A-Za-z0-9]{10,}\s*$/, '').trim();
    // Distintivos: solo mostrar la etiqueta de color (sin texto plano previo)
    if(t==='INGRESO'){
      // Green (mismo formato que VENTA)
      motivoText = `<span style="margin-left:6px;background:#10b981;color:#fff;border-radius:10px;padding:2px 6px;font-size:0.65rem;font-weight:600;">INGRESO</span>`;
    } else if(t==='GASTO'){
      // Red
      motivoText = `<span style="margin-left:6px;background:#ef4444;color:#fff;border-radius:10px;padding:2px 6px;font-size:0.65rem;font-weight:600;">GASTO</span>`;
    } else if(t==='RETIRO'){
      // Red
      motivoText = `<span style="margin-left:6px;background:#ef4444;color:#fff;border-radius:10px;padding:2px 6px;font-size:0.65rem;font-weight:600;">RETIRO</span>`;
    } else if(t==='VENTA_ABONO_PERSONAL'){
      // Amber
      motivoText = `<span style="margin-left:6px;background:#f59e0b;color:#fff;border-radius:10px;padding:2px 6px;font-size:0.65rem;font-weight:600;">ABONO PERSONAL</span>`;
  } else if(t==='VENTA' || t.startsWith('VENTA_')){
      // Green
      motivoText = `<span style=\"margin-left:6px;background:#10b981;color:#fff;border-radius:10px;padding:2px 6px;font-size:0.65rem;font-weight:600;\">VENTA</span>`;
    } else if(t==='DEVOLUCION_ABONO_PERSONAL'){
      // Orange
      motivoText = `<span style="margin-left:6px;background:#f97316;color:#fff;border-radius:10px;padding:2px 6px;font-size:0.65rem;font-weight:600;">DEVOLUCIÓN ABONO</span>`;
  } else if(t==='VENTA_PAGO_INICIAL' || t==='VENTA_ANTICIPO'){
      // Blue
      motivoText = `<span style=\"margin-left:6px;background:#3b82f6;color:#fff;border-radius:10px;padding:2px 6px;font-size:0.65rem;font-weight:600;\">ANTICIPO</span>`;
    }
    rowHtml += `<td>${motivoText}</td>`;
  // Importe con color (mostrar valor absoluto, el color indica el tipo)
  const amtAbs = Math.abs(Number(rec.monto||0));
  rowHtml += `<td class="${amountClass}">$ ${amtAbs.toFixed(2)}</td>`;
  // Método de pago (texto)
  const metodoRaw = rec.metodo || rec.metodoPago || rec.formaPago || '';
  const metodoUp = String(metodoRaw).toUpperCase();
  let metodoName = 'Efectivo';
  if(metodoUp.includes('EFECT')) metodoName = 'Efectivo';
  else if(metodoUp.includes('TARJ')) metodoName = 'Tarjeta';
  else if(metodoUp.includes('TRANS') || metodoUp.includes('DEPOS')) metodoName = 'Transferencia';
  else if(metodoUp.includes('CHEQUE')) metodoName = 'Cheque';
  else if(metodoUp.includes('CONVENIO')) metodoName = 'Convenio';
  else if(metodoUp.includes('PUNTO')) metodoName = 'Puntos';
  else if(metodoUp.includes('MIXTO')) metodoName = 'Mixto';
  else if(metodoUp.includes('POR_COBRAR')) metodoName = 'Por cobrar';
  rowHtml += `<td>${metodoName}</td>`;
  // Usuario, referencias y sucursal
  rowHtml += `<td>${resolveUserName(rec)}</td>`;
  // Referencias: preferir folio de venta/factura; luego refs manuales; luego ingresoFolio/gastoFolio/retiroFolio; luego id8/folio de caja
  let refTxt = '';
  if(folioResolved){ refTxt = folioResolved; }
  else if(rec.facturaFolio!=null){ refTxt = String(rec.facturaFolio); }
  else if(rec.ref){ refTxt = String(rec.ref); }
  else if(rec.referencia){ refTxt = String(rec.referencia); }
  else if(rec.ingresoFolio){ refTxt = String(rec.ingresoFolio); }
  else if(rec.gastoFolio){ refTxt = String(rec.gastoFolio); }
  else if(rec.retiroFolio){ refTxt = String(rec.retiroFolio); }
  else if(rec.id8){ refTxt = String(rec.id8); }
  else if(rec.folioStr){ refTxt = String(rec.folioStr); }
  else if(rec.folio!=null){ refTxt = String(rec.folio).padStart(3,'0'); }
  rowHtml += `<td>${refTxt}</td>`;
  // Sucursal: best-effort (manual registros suelen tenerla); para caja de ventas puede venir vacío
  rowHtml += `<td>${rec.sucursal || ''}</td>`;
    tr.innerHTML = rowHtml;
    cashBody.appendChild(tr);
  });
  // Actualizar el encabezado de corte con los datos calculados del día
  try { renderCutSummary(); } catch(_e){}
}

/**
 * Renderiza la tabla histórica (misma lista de registros) con filtro propio.
 */
function renderHistoricoTable() {
  if(!historicoBody) return;
  historicoBody.innerHTML = '';
  let ingresosTotal = 0, gastosTotal = 0, retirosTotal = 0;
  // Aplicar filtro por turno activo si existe
  // Usar arreglo vivo desde window para evitar referencias obsoletas
  let baseHist = Array.isArray(window.historicalCashRecords) ? window.historicalCashRecords : (Array.isArray(window.cashRecords) ? window.cashRecords : historicalCashRecords);
  try{
    if(!(window.__showAllTurnos && isAdminRole())){
      const turnoId = window.currentTurnoId || null;
      const aperturaMs = window.__lastTurnoOpen?.abiertoEnApproxMs || null;
      if(turnoId){
        const byId = baseHist.filter(r=> r && r.turnoId === turnoId);
        baseHist = byId.length ? byId : (aperturaMs ? baseHist.filter(r=> (r && typeof r.createdAtMs==='number' && r.createdAtMs>=aperturaMs)) : baseHist);
      }
    }
  }catch(_e){}
  const filtered = baseHist.filter(rec => {
    const tUp = String(rec.tipo||'').toUpperCase();
    if (historicoFilterType === 'ingresos') {
      const ingresosSet = new Set(['INGRESO','VENTA_ANTICIPO','VENTA_PAGO_INICIAL','VENTA_ABONO','VENTA_ABONO_PERSONAL','FACTURA_ABONO']);
      if(!ingresosSet.has(tUp)) return false;
    }
    if (historicoFilterType === 'gastos') {
      if(tUp !== 'GASTO') return false;
    }
    if (historicoFilterType === 'retiros') {
      const retirosSet = new Set(['RETIRO','DEVOLUCION_ABONO_PERSONAL']);
      if(!retirosSet.has(tUp)) return false;
    }
    if (historicoStartDate && new Date(rec.fecha) < new Date(historicoStartDate)) return false;
    if (historicoEndDate && new Date(rec.fecha) > new Date(historicoEndDate)) return false;
    // Folio: aceptar contra folioStr (000-prefijado), numérico folio, ingresoFolio (I-xxxxx), gastoFolio (G-xxxxx) o retiroFolio (R-xxxxx)
    if (historicoFolio) {
      const folioStr = String(rec.folioStr||'');
      const folioNum = (rec.folio!=null && !Number.isNaN(Number(rec.folio))) ? Number(rec.folio) : null;
      const q = historicoFolio.trim();
      const qNum = Number(q);
      const gastoFolio = String(rec.gastoFolio||'');
      const ingresoFolio = String(rec.ingresoFolio||'');
      const retiroFolio = String(rec.retiroFolio||'');
      const match = (folioStr && folioStr.includes(q))
        || (ingresoFolio && ingresoFolio.toLowerCase().includes(q.toLowerCase()))
        || (gastoFolio && gastoFolio.toLowerCase().includes(q.toLowerCase()))
        || (retiroFolio && retiroFolio.toLowerCase().includes(q.toLowerCase()))
        || (Number.isFinite(qNum) && folioNum===qNum);
      if(!match) return false;
    }
    // Usuario: comparar contra userId si está seleccionado
    if (historicoFilterUser && historicoFilterUser!=='all') {
      const uid = String(rec.userId||rec.uid||rec.usuarioId||'');
      if(String(historicoFilterUser)!==uid) return false;
    }
    return true;
  });
  // Ordenar del más nuevo al más viejo: fecha desc, luego createdAt desc, luego folio desc, luego id8 desc
  const toRender = filtered.slice().sort((a,b)=>{
    // Fecha (YYYY-MM-DD) descendente
    const fa = String(a?.fecha||'');
    const fb = String(b?.fecha||'');
    if(fb>fa) return 1; if(fb<fa) return -1;
    // createdAt descendente
    const ca = a?.createdAt && a.createdAt.toMillis ? a.createdAt.toMillis() : (a?.createdAt? Number(a.createdAt): 0);
    const cb = b?.createdAt && b.createdAt.toMillis ? b.createdAt.toMillis() : (b?.createdAt? Number(b.createdAt): 0);
    if(cb!==ca) return cb - ca;
    // folio descendente como desempate
    const fA = (a && (a.folio!=null)) ? Number(a.folio) : (a && a.folioStr ? parseInt(a.folioStr,10) : NaN);
    const fB = (b && (b.folio!=null)) ? Number(b.folio) : (b && b.folioStr ? parseInt(b.folioStr,10) : NaN);
    const hasA = Number.isFinite(fA);
    const hasB = Number.isFinite(fB);
    if(hasA && hasB){ if(fB!==fA) return fB - fA; }
    else if(hasA && !hasB){ return -1; }
    else if(!hasA && hasB){ return 1; }
  // gastoFolio descendente como desempate si existe
    const gfA = String(a && a.gastoFolio ? a.gastoFolio : '');
    const gfB = String(b && b.gastoFolio ? b.gastoFolio : '');
    if(gfA || gfB){ const cmpGF = gfB.localeCompare(gfA); if(cmpGF!==0) return cmpGF; }
  // ingresoFolio descendente como siguiente desempate si existe
  const ifA = String(a && a.ingresoFolio ? a.ingresoFolio : '');
  const ifB = String(b && b.ingresoFolio ? b.ingresoFolio : '');
  if(ifA || ifB){ const cmpIF = ifB.localeCompare(ifA); if(cmpIF!==0) return cmpIF; }
  // retiroFolio descendente como siguiente desempate si existe
  const rfA = String(a && a.retiroFolio ? a.retiroFolio : '');
  const rfB = String(b && b.retiroFolio ? b.retiroFolio : '');
  if(rfA || rfB){ const cmpRF = rfB.localeCompare(rfA); if(cmpRF!==0) return cmpRF; }
    // id8 descendente como siguiente desempate
    const i8a = String(a && a.id8 != null ? a.id8 : '');
    const i8b = String(b && b.id8 != null ? b.id8 : '');
    if(i8a || i8b){
      const cmp = i8b.localeCompare(i8a);
      if(cmp!==0) return cmp;
    }
    // Último recurso: id desc
    return String(b?._id||'').localeCompare(String(a?._id||''));
  });

  toRender.forEach((rec)=>{
    const tr = document.createElement('tr');
    const t = String(rec?.tipo||'').toUpperCase();
    // Totales por tipo
    if (t==='INGRESO' || t==='VENTA_ANTICIPO' || t==='VENTA_PAGO_INICIAL' || t==='VENTA_ABONO' || t==='VENTA_ABONO_PERSONAL' || t==='FACTURA_ABONO' || t==='VENTA') ingresosTotal += Number(rec.monto||0);
    else if (t==='GASTO') gastosTotal += Number(rec.monto||0);
    else if (t==='RETIRO' || t==='DEVOLUCION_ABONO_PERSONAL' || t==='VENTA_CANCELACION') retirosTotal += Number(rec.monto||0);

    // Fecha y hora
    const fechaHora = rec.hora ? `${rec.fecha} ${rec.hora}` : rec.fecha || '';

    // Resolver folio/motivo base como en Caja
    let folioResolved = rec.ventaFolio || rec.facturaFolio || '';
    if(!folioResolved && rec.ventaId && Array.isArray(window.ventas)){
      const v = window.ventas.find(x=> x.id===rec.ventaId || x._id===rec.ventaId);
      if(v && v.folio) folioResolved = v.folio;
    }
    if(!folioResolved && rec.facturaId && Array.isArray(window.facturas)){
      const f = window.facturas.find(x=> x.id===rec.facturaId || x._docId===rec.facturaId);
      if(f && f.folio!=null) folioResolved = String(f.folio);
    }
    let motivoText = '';
    if (t==='GASTO') motivoText = rec.categoriaNombre || rec.categoria || rec.descripcion || 'Gasto';
    else if (t==='RETIRO') motivoText = rec.descripcion || rec.motivo || 'Retiro de efectivo';
    else if (t==='INGRESO') motivoText = rec.descripcion || rec.motivo || 'Ingreso';
    else if (t==='VENTA_PAGO_INICIAL' || t==='VENTA_ANTICIPO') motivoText = rec.descripcion || `Pago inicial Venta ${folioResolved}`.trim();
    else if (t==='VENTA_ABONO') motivoText = rec.descripcion || `Abono Venta ${folioResolved}`.trim();
    else if (t==='VENTA_ABONO_PERSONAL') motivoText = rec.descripcion || `Abono personal Venta ${folioResolved}`.trim();
    else if (t==='DEVOLUCION_ABONO_PERSONAL') motivoText = rec.descripcion || `Devolución abono personal ${folioResolved}`.trim();
    else if (t==='VENTA') motivoText = rec.descripcion || `Cobro total Venta ${folioResolved}`.trim();
    else if (t==='FACTURA_ABONO') motivoText = rec.descripcion || `Abono Factura ${folioResolved}`.trim();
    else motivoText = rec.descripcion || rec.motivo || 'Movimiento de caja';
    motivoText = String(motivoText).replace(/\s+[A-Za-z0-9]{10,}\s*$/, '').trim();
    // Reemplazar por chip de color
    if(t==='INGRESO') motivoText = `<span style="margin-left:6px;background:#10b981;color:#fff;border-radius:10px;padding:2px 6px;font-size:0.65rem;font-weight:600;">INGRESO</span>`;
    else if(t==='GASTO') motivoText = `<span style="margin-left:6px;background:#ef4444;color:#fff;border-radius:10px;padding:2px 6px;font-size:0.65rem;font-weight:600;">GASTO</span>`;
    else if(t==='RETIRO') motivoText = `<span style="margin-left:6px;background:#ef4444;color:#fff;border-radius:10px;padding:2px 6px;font-size:0.65rem;font-weight:600;">RETIRO</span>`;
    else if(t==='VENTA_ABONO_PERSONAL') motivoText = `<span style="margin-left:6px;background:#f59e0b;color:#fff;border-radius:10px;padding:2px 6px;font-size:0.65rem;font-weight:600;">ABONO PERSONAL</span>`;
    else if(t==='DEVOLUCION_ABONO_PERSONAL') motivoText = `<span style="margin-left:6px;background:#f97316;color:#fff;border-radius:10px;padding:2px 6px;font-size:0.65rem;font-weight:600;">DEVOLUCIÓN ABONO</span>`;
    else if(t==='VENTA_PAGO_INICIAL' || t==='VENTA_ANTICIPO') motivoText = `<span style="margin-left:6px;background:#3b82f6;color:#fff;border-radius:10px;padding:2px 6px;font-size:0.65rem;font-weight:600;">ANTICIPO</span>`;
    else if(t==='VENTA' || t.startsWith('VENTA_')) motivoText = `<span style=\"margin-left:6px;background:#10b981;color:#fff;border-radius:10px;padding:2px 6px;font-size:0.65rem;font-weight:600;\">VENTA</span>`;

    // Clase de importe
    const isIngreso = (t==='INGRESO' || t==='VENTA' || t==='VENTA_PAGO_INICIAL' || t==='VENTA_ABONO' || t==='VENTA_ABONO_PERSONAL' || t==='FACTURA_ABONO' || t==='VENTA_ANTICIPO');
    const isSalida = (t==='GASTO' || t==='RETIRO' || t==='DEVOLUCION_ABONO_PERSONAL' || t==='VENTA_CANCELACION');
    const amountClass = (
      t==='VENTA_ABONO_PERSONAL' ? 'amt-amber' :
      t==='DEVOLUCION_ABONO_PERSONAL' ? 'amt-orange' :
      (t==='GASTO' || t==='RETIRO' || t==='VENTA_CANCELACION') ? 'amt-red' :
      (t==='INGRESO' || t==='VENTA' || t.startsWith('VENTA_') || t==='FACTURA_ABONO') ? 'amt-green' :
      (isIngreso ? 'amt-green' : (isSalida ? 'amt-red' : ''))
    );
    const amtAbs = Math.abs(Number(rec.monto||0));

    // Método de pago
    const metodoRaw = rec.metodo || rec.metodoPago || rec.formaPago || '';
    const metodoUp = String(metodoRaw).toUpperCase();
    let metodoName = 'Efectivo';
    if(metodoUp.includes('EFECT')) metodoName = 'Efectivo';
    else if(metodoUp.includes('TARJ')) metodoName = 'Tarjeta';
    else if(metodoUp.includes('TRANS') || metodoUp.includes('DEPOS')) metodoName = 'Transferencia';
    else if(metodoUp.includes('CHEQUE')) metodoName = 'Cheque';
    else if(metodoUp.includes('CONVENIO')) metodoName = 'Convenio';
    else if(metodoUp.includes('PUNTO')) metodoName = 'Puntos';
    else if(metodoUp.includes('MIXTO')) metodoName = 'Mixto';
    else if(metodoUp.includes('POR_COBRAR')) metodoName = 'Por cobrar';

    // Usuario mostrado
    const resolveUserName = (rec)=>{
      try{
        const list = Array.isArray(window.usuarios) ? window.usuarios : [];
        const uid = String(rec?.userId || rec?.uid || rec?.usuarioId || '').trim();
        if(uid){
          const u = list.find(x => String(x.id||x.uid) === uid);
          if(u){ return (u.nombre || u.displayName || u.correo || '').trim(); }
        }
        const raw = String(rec?.usuario||'').trim();
        if(raw){
          const byMail = list.find(x => String(x.correo||'').trim().toLowerCase() === raw.toLowerCase());
          if(byMail) return (byMail.nombre || byMail.displayName || byMail.correo || '').trim();
          if(raw.includes('@')) return raw.split('@')[0];
          return raw;
        }
      }catch(_e){}
      return '';
    };

    // Referencias
    let refTxt = '';
    if(folioResolved){ refTxt = folioResolved; }
    else if(rec.facturaFolio!=null){ refTxt = String(rec.facturaFolio); }
  else if(rec.ref){ refTxt = String(rec.ref); }
  else if(rec.referencia){ refTxt = String(rec.referencia); }
  else if(rec.ingresoFolio){ refTxt = String(rec.ingresoFolio); }
  else if(rec.gastoFolio){ refTxt = String(rec.gastoFolio); }
  else if(rec.retiroFolio){ refTxt = String(rec.retiroFolio); }
  else if(rec.id8){ refTxt = String(rec.id8); }
    else if(rec.folioStr){ refTxt = String(rec.folioStr); }
    else if(rec.folio!=null){ refTxt = String(rec.folio).padStart(3,'0'); }

    tr.innerHTML = `
      <td>${fechaHora}</td>
      <td>${motivoText}</td>
      <td class="${amountClass}">$ ${amtAbs.toFixed(2)}</td>
      <td>${metodoName}</td>
      <td>${resolveUserName(rec)}</td>
      <td>${refTxt}</td>
      <td>${rec.sucursal || ''}</td>
    `;
    historicoBody.appendChild(tr);
  });
  const utilidadTotal = ingresosTotal - gastosTotal - retirosTotal;
  const totIngElem = document.getElementById('historicoTotalIngresos');
  const totGasElem = document.getElementById('historicoTotalGastos');
  const totRetElem = document.getElementById('historicoTotalRetiros');
  const totUtElem = document.getElementById('historicoTotalUtilidad');
  if (totIngElem) totIngElem.textContent = `$ ${ingresosTotal.toFixed(2)}`;
  if (totGasElem) totGasElem.textContent = `$ ${gastosTotal.toFixed(2)}`;
  if (totRetElem) totRetElem.textContent = `$ ${retirosTotal.toFixed(2)}`;
  if (totUtElem) totUtElem.textContent = `$ ${utilidadTotal.toFixed(2)}`;
}

// -------------------------------------------------------------------
// Resumen superior de Corte de caja (encima de la tabla de Caja)
// -------------------------------------------------------------------
function renderCutSummary() {
  const wrap = document.getElementById('cutSummary');
  if (!wrap) return; // no hay UI
  const tz = (window.__FECHA_TZ__ || 'America/Mexico_City');
  const today = (typeof window.getTodayStrTZ === 'function') ? window.getTodayStrTZ(tz) : new Date().toISOString().slice(0,10);
  // Helpers DOM
  const setTxt = (id, val) => { const el = document.getElementById(id); if(el) el.textContent = val; };
  const money = (n) => `$ ${Number(n||0).toFixed(2)}`;

  // Fecha header
  const hdr = document.getElementById('cutSummaryHeader');
  if (hdr) hdr.textContent = `CORTE DE ${today}`;

  // Tomar movimientos ya filtrados por fecha desde Firestore listener
  let cash = Array.isArray(window.historicalCashRecords) ? window.historicalCashRecords.slice() : [];
  // If a caja selector exists in the main UI (ventas del día modal may be closed), try to read it and filter by cajaId; fallback to caja name
  try{
    const sel = document.getElementById('vdCaja');
    const selId = sel && sel.value ? sel.value : 'all';
    if(selId && selId!=='all'){
      const selName = (Array.isArray(window.cajas)? window.cajas : []).find(c=> String(c.id)===String(selId))?.caja || null;
      cash = cash.filter(r=> {
        const rid = r && r.cajaId ? String(r.cajaId) : null;
        if(rid) return rid === String(selId);
        const rname = r && r.caja ? String(r.caja) : null;
        return !!(rname && selName && rname===selName);
      });
    }
  }catch(_e){}
  const ventas = Array.isArray(window.ventas) ? window.ventas.filter(v=> String(v?.fecha||'').slice(0,10)===today) : [];
  // Índice rápido de ventas por id para clasificar cobros de contra entrega
  const ventasIdx = {};
  try{ ventas.forEach(v=>{ if(v && (v.id!=null)) ventasIdx[String(v.id)] = v; }); }catch(_e){}

  // Dinero en caja
  let fondoCaja = 0; // No hay fuente explícita aún
  // Ventas del día (todas las formas de pago) para la columna "Dinero en caja"
  let ventasDiaCaja = 0;
  let entradas = 0;
  let salidas = 0; // positiva para mostrar
  let retiros = 0; // solo presentación, no doble-contar
  let devolucionesTotal = 0; // positiva para mostrar (todas las cancelaciones)
  let abonosPersonalesEntrada = 0; // efectivo adelantado del cajero
  let devolucionesAbonoPersonal = 0; // efectivo devuelto al cajero cuando paga el cliente

  // Listado separado de Abonos del día (todos los métodos)
  let abonosTotal = 0;           // total neto (clientes + facturas - devoluciones personales)
  let abonosCount = 0;
  const abonosItems = [];
  // Nuevos desgloses
  let abonosClientesTotal = 0;   // solo VENTA_ABONO (clientes)
  let abonosClientesCount = 0;
  let abonosPersonalesHoy = 0;   // VENTA_ABONO_PERSONAL
  let devolucionAbonosHoy = 0;   // DEVOLUCION_ABONO_PERSONAL

  let ventasDevolucionesTotal = 0;
  let ventasCanceladasTotal = 0; // Todas las ventas canceladas (cualquier método)
  let cobrosPendCaja = 0; // contra entrega entregados hoy (pendiente cobrado al entregar)
  cash.forEach(rec=>{
    const t = String(rec?.tipo||'').toUpperCase();
    const metodo = rec?.metodo || rec?.metodoPago || '';
    const m = Number(rec?.monto||0);
    // Filtrar para resumen del corte: solo hoy (timezone-aware) si rec.fecha existe
    if (rec && rec.fecha && String(rec.fecha) !== today) {
      // Aun si el listener ya filtra, evitamos incluir de otros días en la lista de abonos
      // pero sí dejamos que total de caja use los de hoy exclusivamente
    }
    // Entradas/salidas (independiente del método)
  if(t==='INGRESO') entradas += m;
  else if(t==='GASTO' || t==='RETIRO') { salidas += m; if(t==='RETIRO') retiros += m; } // m ya es positivo
    // Ventas cobradas: separar cobros de contra-entrega (ENTREGADOS) para no mezclarlos con las ventas del día
    else if(
      t==='VENTA' ||
      t==='VENTA_EFECTIVO' || t==='VENTA_TARJETA' || t==='VENTA_TRANSFERENCIA' ||
      t==='VENTA_MIXTO' || // por si existiera
      t==='VENTA_DEPOSITO' || // legacy
      (t.startsWith('VENTA_') && !['VENTA_ABONO','VENTA_ABONO_PERSONAL','VENTA_CANCELACION','DEVOLUCION_ABONO_PERSONAL'].includes(t))
    ){
      const desc = String(rec.descripcion||rec.description||'').toUpperCase();
      const vref = rec.ventaId!=null ? ventasIdx[String(rec.ventaId)] : null;
      const isCobroContra = desc.includes('COBRO SALDO') || (vref && String(vref.metodoPago||'').toUpperCase()==='POR_COBRAR');
      if(isCobroContra) cobrosPendCaja += m; else ventasDiaCaja += m;
    }
    // Abono personal (dinero del cajero): entrada del día pero no suma a ventas
    else if(t==='VENTA_ABONO_PERSONAL') { abonosPersonalesEntrada += m; }
    // Devolución del abono personal cuando el cliente paga: salida
  else if(t==='DEVOLUCION_ABONO_PERSONAL') { devolucionesAbonoPersonal += m; /* No afectar salidas/total de caja */ }
    // Devoluciones/cancelaciones – suelen venir negativas; contabilizar absoluto
    if(t==='VENTA_CANCELACION'){
      ventasDevolucionesTotal += Math.abs(m);
      devolucionesTotal += Math.abs(m);
    }

    // Construir lista de Abonos del día (independiente del método)
  if((t==='VENTA_ABONO' || t==='VENTA_ABONO_PERSONAL' || t==='FACTURA_ABONO' || t==='DEVOLUCION_ABONO_PERSONAL') && (!rec.fecha || String(rec.fecha)===today)){
      const isRefund = (t==='DEVOLUCION_ABONO_PERSONAL');
      abonosTotal += isRefund ? -m : m; // neto del día
      abonosCount += 1;
      if(t==='VENTA_ABONO'){ abonosClientesTotal += m; abonosClientesCount += 1; }
      else if(t==='FACTURA_ABONO'){ abonosClientesTotal += m; abonosClientesCount += 1; }
      else if(t==='VENTA_ABONO_PERSONAL'){ abonosPersonalesHoy += m; }
      else if(t==='DEVOLUCION_ABONO_PERSONAL'){ devolucionAbonosHoy += m; }
      abonosItems.push({
        fecha: rec.fecha,
        tipo: t,
        metodo: metodo,
        monto: isRefund ? -m : m, // mostrar negativa
        ventaId: rec.ventaId || rec.facturaId || '',
        personal: !!rec.personal
      });
    }
  });
  // Dinero en caja neto: VENTAS DEL DÍA (todas) + Cobros pendientes (entregados) + Entradas - Salidas - Ventas canceladas
  // Nota: Devolucion de abonos (DEVOLUCION_ABONO_PERSONAL) no descuenta del total; se reporta sólo como indicador.
  const totalDineroCaja = fondoCaja + ventasDiaCaja + cobrosPendCaja + entradas - salidas - ventasDevolucionesTotal;

  // Poblado de nuevos desgloses
  const personalAdvWrap = document.getElementById('cutSummaryPersonalAdv'); // (ya no visible en nueva UI, mantenido por compat.)
  if(personalAdvWrap){ personalAdvWrap.textContent = `Total abonado hoy: +$${abonosPersonalesHoy.toFixed(2)}  |  Devolucion de abonos: -$${devolucionAbonosHoy.toFixed(2)}`; }

  // Ajustar etiqueta a "Ventas del dia" en la UI
  try { const lbl = document.querySelector('#cutVentasEfectivo')?.previousElementSibling; if(lbl) lbl.textContent = 'Ventas del dia:'; } catch(_e){}
  setTxt('cutFondoCaja', money(fondoCaja));
  setTxt('cutVentasEfectivo', money(ventasDiaCaja));
  setTxt('cutCobrosPendCaja', money(cobrosPendCaja));
  setTxt('cutEntradas', money(entradas));
  setTxt('cutSalidas', money(salidas));
  setTxt('cutRetiros', money(retiros));
  // Línea UI de "Devoluciones en efectivo" eliminada; mantenemos el cálculo para el total de caja
  // setTxt('cutDevolucionesEfectivo', money(devolucionesEfectivo));
  setTxt('cutVentasCanceladasCaja', money(ventasDevolucionesTotal));
  // Mostrar cuánto separar por devoluciones de abonos (informativo; no afecta total)
  setTxt('cutAbonosSeparar', money(devolucionesAbonoPersonal));
  setTxt('cutDineroCajaTotal', `TOTAL ${money(totalDineroCaja)}`);

  // Renderizar SOLO el total y el conteo de abonos (ocultar listado por solicitud)
  const abonosList = document.getElementById('cutAbonosList');
  const abonosTotalEl = document.getElementById('cutAbonosTotal');
  const abonosCountEl = document.getElementById('cutAbonosCount');
  if (abonosList) {
    // Limpiar y no pintar elementos individuales
    abonosList.innerHTML = '';
    // Opcional: ocultar el contenedor si hace sentido en el DOM/CSS
    try { abonosList.style.display = 'none'; } catch(_e){}
  }
  if (abonosTotalEl) abonosTotalEl.textContent = money(abonosTotal);
  // Temporarily set with today's count; will be overridden below with pending count once computed
  if (abonosCountEl) abonosCountEl.textContent = `(${abonosCount})`;

  // Desglose de ventas por método y totales
  let ventasTotales = 0, costosTotales = 0;
  let ventasEfe = 0, ventasTar = 0, ventasTrans = 0, ventasContra = 0, ventasDev = 0;
  ventas.forEach(v=>{
    const status = String(v?.status||'').toUpperCase();
    const statusProd = String(v?.statusProd||'').toUpperCase();
    const total = Number(v?.total||0);
    const costo = Number(v?.costoTotal||0);
    const metodo = String(v?.metodoPago||'').toUpperCase();
    const pagoInicial = Number(v?.pagoInicial||v?.pagado||0);
    const saldo = Number(v?.saldo||0);
    if(status==='CANCELADA'){ ventasDev += Math.abs(total); return; }
    const delivered = (metodo !== 'POR_COBRAR') || statusProd==='ENTREGADO' || v?.entregadoAt;
    if(delivered){
      ventasTotales += total;
      costosTotales += costo;
    }
    if(metodo==='EFECTIVO'){
      ventasEfe += total;
      if(saldo>0) ventasContra += saldo;
    }
    else if(metodo==='TARJETA'){
      ventasTar += total;
      if(saldo>0) ventasContra += saldo;
    }
    else if(metodo==='TRANSFERENCIA'){
      ventasTrans += total;
      if(saldo>0) ventasContra += saldo;
    }
    else if(metodo==='POR_COBRAR'){
      ventasContra += saldo>0 ? saldo : total;
    }
    else if(metodo==='MIXTO'){
      ventasEfe += pagoInicial;
      if(saldo>0) ventasContra += saldo;
    }
  });
  // Total de VENTAS: métodos cobrados hoy + contra entrega ya ENTREGADOS, menos canceladas
  // (lo pendiente de cobro no afecta el total). No permitir negativos: si hay más devoluciones que cobros
  // el total se muestra en 0 para no "compensar" otras ventas.
  const ventasMetodoTotal = Math.max(0, ventasTotales - ventasDev);
  setTxt('cutVentasEfectivoDet', money(ventasEfe));
  setTxt('cutTarjetaDebito', money(ventasTar));
  setTxt('cutTransferencia', money(ventasTrans));
  // Placeholder; we'll override below with the "Ventas por cobrar" del día
  setTxt('cutContraEntrega', money(ventasContra));
  setTxt('cutDevolucionesVentas', money(ventasDev));
  setTxt('cutVentasTotal', `TOTAL ${money(ventasMetodoTotal)}`);

  // Pendiente de cobro (ventas con saldo > 0)
  const pendienteCobro = ventas.reduce((acc,v)=> acc + (String(v?.status||'')==='CANCELADA'?0:Number(v?.saldo||0)), 0);
  setTxt('cutPendienteCobro', money(pendienteCobro));

  // Pendiente personal acumulado (suma de abonosPersonalesPendientes): usar buffer histórico _ventasAll
  // para que refleje correctamente lo que está pendiente por devolver aunque no sea del día.
  const ventasAll = Array.isArray(window._ventasAll) ? window._ventasAll : (Array.isArray(window.ventas) ? window.ventas : []);
  const personalPendienteGlobal = ventasAll.reduce((acc,v)=> acc + Math.max(0, Number(v?.abonosPersonalesPendientes||0)), 0);
  const personalPendienteCount = ventasAll.reduce((acc,v)=> acc + ((Number(v?.abonosPersonalesPendientes||0) > 0) ? 1 : 0), 0);
  const ppEl = document.getElementById('cutPersonalPendingTotal');
  if(ppEl) ppEl.textContent = money(personalPendienteGlobal);
  // Override the "ABONOS DEL DÍA" count to reflect number of pending personal abonos (not yet returned to system)
  try {
    const abonosCountEl2 = document.getElementById('cutAbonosCount');
    if (abonosCountEl2) abonosCountEl2.textContent = `(${personalPendienteCount})`;
  } catch(_e){}
  // Ventas por cobrar (del día): sumar ventas POR_COBRAR entregadas HOY que ya se cobraron al cliente,
  // es decir, se devolvió el abono personal HOY (DEVOLUCION_ABONO_PERSONAL)
  try {
    const ventasPorCobrarHoy = ventas.reduce((acc,v)=>{
      const status = String(v?.status||'').toUpperCase();
      if(status==='CANCELADA') return acc;
      const saldo = Number(v?.saldo||0);
      if(!(saldo>0)) return acc;
      return acc + saldo;
    }, 0);
    setTxt('cutContraEntrega', money(ventasPorCobrarHoy));
  } catch(_e){}
  // Campos simplificados del card
  const cutAbonosSistema = document.getElementById('cutAbonosSistema');
  const cutAbonosDevueltos = document.getElementById('cutAbonosDevueltos');
  const cutPendientesDevolver = document.getElementById('cutPendientesDevolver');
  // "Abonos a sistema": solo costo del pedido -> usar abonos personales aplicados hoy (VENTA_ABONO_PERSONAL)
  // Si ya se devolvió el abono (mismo día), ocultar la línea completa (no debería aparecer)
  if(cutAbonosSistema){
    const netAbonoSistema = (abonosPersonalesHoy - devolucionAbonosHoy);
    const lineEl = (typeof cutAbonosSistema.closest === 'function') ? (cutAbonosSistema.closest('.cut-summary-line') || cutAbonosSistema.parentElement) : cutAbonosSistema.parentElement;
    if(netAbonoSistema <= 0){
      // Mantener el valor en 0 para consistencia, pero ocultar la fila
      try { cutAbonosSistema.textContent = money(0); } catch(_e){}
      try { if(lineEl) lineEl.style.display = 'none'; } catch(_e){}
    } else {
      try { cutAbonosSistema.textContent = money(netAbonoSistema); } catch(_e){}
      try { if(lineEl) lineEl.style.display = ''; } catch(_e){}
    }
  }
  if(cutAbonosDevueltos) cutAbonosDevueltos.textContent = money(devolucionAbonosHoy);
  if(cutPendientesDevolver) cutPendientesDevolver.textContent = money(Math.max(0, personalPendienteGlobal));

  // Totales y ganancia
  const ganancia = ventasTotales - costosTotales;
  setTxt('cutVentasTotales', money(ventasTotales));
  setTxt('cutGanancia', money(ganancia));

  // Top clientes
  const topVentasEl = document.getElementById('cutTopClientesVentas');
  const topGanEl = document.getElementById('cutTopClientesGanancia');
  if(topVentasEl) topVentasEl.innerHTML = '';
  if(topGanEl) topGanEl.innerHTML = '';
  const porCliente = {};
  ventas.forEach(v=>{
    if(String(v?.status||'')==='CANCELADA') return;
    const metodo = String(v?.metodoPago||'').toUpperCase();
    const statusProd = String(v?.statusProd||'').toUpperCase();
    const delivered = (metodo !== 'POR_COBRAR') || statusProd==='ENTREGADO' || v?.entregadoAt;
    if(!delivered) return; // diferir POR_COBRAR hasta ENTREGADO
    const key = v?.clienteNombre || v?.cliente || 'CLIENTE';
    if(!porCliente[key]) porCliente[key] = { ventas:0, ganancia:0 };
    const venta = Number(v?.total||0);
    const utilidad = venta - Number(v?.costoTotal||0);
    porCliente[key].ventas += venta;
    porCliente[key].ganancia += utilidad;
  });
  const arr = Object.entries(porCliente).map(([k,v])=>({ cliente:k, ...v }));
  const topVentas = arr.slice().sort((a,b)=> b.ventas - a.ventas).slice(0,5);
  const topGan = arr.slice().sort((a,b)=> b.ganancia - a.ganancia).slice(0,5);
  if(topVentasEl){ topVentas.forEach(it=>{ const li=document.createElement('li'); li.textContent = `${it.cliente} — ${money(it.ventas)}`; topVentasEl.appendChild(li); }); }
  if(topGanEl){ topGan.forEach(it=>{ const li=document.createElement('li'); li.textContent = `${it.cliente} — ${money(it.ganancia)}`; topGanEl.appendChild(li); }); }
}

