  const statusViewerText = document.getElementById('waStatusViewerText');
  const statusViewerCaption = document.getElementById('waStatusViewerCaption');
  const statusPrevBtn = document.getElementById('waStatusPrev');
  const statusNextBtn = document.getElementById('waStatusNext');
