/**
 * Realiza un corte de caja: guarda un resumen de los movimientos actuales y reinicia los registros.
 */
function handleMakeCut() {
  if (cashRecords.length === 0) { notify('No hay movimientos para realizar el corte','info'); return; }
  // Calcular totales por método para el corte
  const methods = ['Efectivo', 'Tarjeta', 'Cheques', 'Depósitos', 'Convenios', 'Puntos'];
  const summary = {};
  methods.forEach((m) => (summary[m] = 0));
  let cutDate = new Date().toISOString().substring(0, 10);
  let cutHour = new Date().toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' });
  cashRecords.forEach((rec) => {
    const factor = rec.tipo === 'Ingreso' ? 1 : -1;
    const metodoKey = (function resolveMetodo(){
      const raw = rec?.metodo || rec?.metodoPago || rec?.formaPago || '';
      const up = String(raw).toUpperCase();
      if(up.includes('TARJ')) return 'Tarjeta';
      if(up.includes('TRANS') || up.includes('DEPOS')) return 'Depósitos';
      if(up.includes('CHEQUE')) return 'Cheques';
      if(up.includes('CONVENIO')) return 'Convenios';
      if(up.includes('PUNTO')) return 'Puntos';
      if(up.includes('MIXTO')) return 'Mixto';
      if(up.includes('POR_COBRAR')) return 'Por cobrar';
      return 'Efectivo';
    })();
    if(typeof summary[metodoKey] !== 'number') summary[metodoKey] = 0;
    summary[metodoKey] += rec.monto * factor;
  });
  const cut = {
    fecha: cutDate,
    hora: cutHour,
    resumen: summary,
    registros: cashRecords.slice()
  };
  cuts.push(cut);
  // Vaciar movimientos y actualizar tablas
  cashRecords = [];
  renderCashTable();
  renderHistoricoTable();
  renderVentasTable();
  notify('Corte realizado correctamente','ok');
}

