/**
 * Maneja el envío del formulario de retiro.
 * Crea un registro de gasto con el importe y observaciones especificados.
 */
function handleWithdrawSubmit(e) {
  e.preventDefault();
  const fecha = withdrawDateInput.value;
  const monto = parseFloat(withdrawAmountInput.value);
  const observaciones = withdrawObservationsInput.value.trim();
  if (!observaciones) { notify('Las observaciones son obligatorias','warn'); return; }
  if (isNaN(monto) || monto <= 0) { notify('El importe no es válido','warn'); return; }
  const now = new Date();
  const hora = now.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' });
  // Registrar en Firestore (caja_movimientos)
  const submitBtn = e.target.querySelector('button[type=submit], .submit-btn');
  if(submitBtn) submitBtn.disabled = true;
  (async()=>{
    try {
  // Resolver usuario/sucursal actuales para persistirlos
  const uid = window.auth?.currentUser?.uid || null;
  const usuarioFromInput = (typeof usuarioNombreInput !== 'undefined' && usuarioNombreInput && usuarioNombreInput.value) ? usuarioNombreInput.value.trim() : '';
  const usuarioResolved = usuarioFromInput || (window.auth?.currentUser?.displayName || (window.auth?.currentUser?.email ? String(window.auth.currentUser.email).split('@')[0] : '')) || 'Administrador';
  // Sucursal: priorizar perfil de usuario
  const us1 = Array.isArray(window.usuarios) ? window.usuarios : [];
  const me1 = us1.find(u=> String(u.id||u.uid)===String(uid));
  const userSucursal1 = (me1 && typeof me1.sucursal==='string' && me1.sucursal.trim()) ? me1.sucursal.trim() : '';
  const sucFromInput = (typeof sucursalNombreInput !== 'undefined' && sucursalNombreInput && sucursalNombreInput.value) ? sucursalNombreInput.value.trim() : '';
  const sucResolved = (userSucursal1 || sucFromInput || (branchSelect ? branchSelect.value : '') || 'MATRIZ').toUpperCase();
  await window.firebaseApi.registrarMovimientoCaja({ tipo:'Retiro', fecha, monto, descripcion: observaciones, usuario: usuarioResolved, userId: uid, sucursal: sucResolved });
      closeWithdrawModal();
      notify('Retiro registrado','ok');
    } catch(err){ console.error('retirar', err); notify(err.message||'Error retiro','err'); }
    finally { if(submitBtn) submitBtn.disabled=false; }
  })();
}

