function closeCashHistory(){ cashHistoryOverlay?.classList.add('hidden'); }
function renderCashHistory(){
  if(!cashHistoryBody) return;
  const list = Array.isArray(window.historicalCashRecords)? window.historicalCashRecords: [];
  const tipo = chTipo?.value || 'todos';
  const q = (chQuery?.value||'').trim().toLowerCase();
  const rows = list
    .filter(r=> (tipo==='todos' || r.tipo===tipo))
    .filter(r=> !q || [r.categoriaNombre, r.categoria, r.descripcion, r.metodo].some(v=> String(v||'').toLowerCase().includes(q)))
    .slice(0, 300);
  cashHistoryBody.innerHTML = rows.map(r=>{
    const f = String(r.fecha||'').slice(0,10);
    const det = (r.tipo==='Ingreso' || r.tipo==='Retiro') ? (r.descripcion||'—') : (r.categoriaNombre||r.categoria||'—');
    const m = Number(r.monto||0).toFixed(2);
    return `<tr><td>${f}</td><td>${r.tipo}</td><td>${det}</td><td>${r.metodo||''}</td><td style="text-align:right;">${m}</td></tr>`;
  }).join('') || '<tr><td colspan="5" style="text-align:center;color:#64748b;padding:10px;">Sin movimientos</td></tr>';
}

