/**
 * Maneja el envío del formulario de caja.
 */
function handleCashSubmit(e) {
  e.preventDefault();
  const fecha = cashDateInput.value;
  const tipo = cashTypeInput.value;
  const metodo = cashMethodInput.value;
  const descripcion = cashDescriptionInput.value.trim();
  const monto = parseFloat(cashAmountInput.value);
  if (!descripcion) { notify('La descripción es obligatoria','warn'); return; }
  if (isNaN(monto) || monto < 0) { notify('El monto no es válido','err'); return; }
  // Obtener hora actual en formato HH:MM para mostrar en el registro
  const now = new Date();
  const hora = now.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' });
  // Tomar usuario/sucursal desde inputs si existen
  const usuarioFromInput = (typeof usuarioNombreInput !== 'undefined' && usuarioNombreInput && usuarioNombreInput.value) ? usuarioNombreInput.value.trim() : '';
  const usuarioResolved = usuarioFromInput || (window.auth?.currentUser?.displayName || (window.auth?.currentUser?.email ? String(window.auth.currentUser.email).split('@')[0] : '')) || 'Administrador';
  // Sucursal: priorizar perfil de usuario
  const uid4 = window.auth?.currentUser?.uid || null;
  const us4 = Array.isArray(window.usuarios) ? window.usuarios : [];
  const me4 = us4.find(u=> String(u.id||u.uid)===String(uid4));
  const userSucursal4 = (me4 && typeof me4.sucursal==='string' && me4.sucursal.trim()) ? me4.sucursal.trim() : '';
  const sucFromInput = (typeof sucursalNombreInput !== 'undefined' && sucursalNombreInput && sucursalNombreInput.value) ? sucursalNombreInput.value.trim() : '';
  const sucResolved = (userSucursal4 || sucFromInput || (branchSelect ? branchSelect.value : '') || 'MATRIZ').toUpperCase();
  const newRec = {
    id: generateCashId(),
    fecha: fecha,
    hora: hora,
    tipo: tipo,
    metodo: metodo,
    descripcion: descripcion,
    monto: monto,
  usuario: usuarioResolved,
  userId: window.auth?.currentUser?.uid || null,
    // Añadir turno/y marca de tiempo local para corte personal inmediato (antes de que llegue el snapshot de Firestore)
    turnoId: window.currentTurnoId || null,
    createdAtMs: Date.now(),
    turnoOpenApproxMs: (window.__lastTurnoOpen && window.__lastTurnoOpen.id === (window.currentTurnoId||null) ? window.__lastTurnoOpen.abiertoEnApproxMs : undefined),
    referencia: '',
    sucursal: sucResolved
  };
  cashRecords.push(newRec);
  historicalCashRecords.push(newRec);
  renderCashTable();
  renderHistoricoTable();
  renderVentasTable();
  closeCashModal();
  notify('Movimiento registrado','ok');
  if(window._firebaseReady && window.firebaseApi){
    window.firebaseApi.addMovimientoCaja(newRec).catch(err=> console.warn('Error guardando movimiento caja:',err));
  }
}

/**
 * Cambia la vista actual a una de las secciones de caja: 'caja', 'historico' o 'ventas'.
 * Oculta las secciones de almacén y muestra la correspondiente de caja.
 */
function switchCashSection(type) {
  // Ocultar secciones de almacén
  productsSection?.classList.add('hidden');
  suppliesSection?.classList.add('hidden');
  insumosSection?.classList.add('hidden');
  inventorySection?.classList.add('hidden');
  // Ocultar todas las secciones de caja
  cajaSection.classList.add('hidden');
  historicoSection.classList.add('hidden');
  ventasSection.classList.add('hidden');
  // Quitar clases activas en subitems de caja
  navCajaItem.classList.remove('active');
  navHistoricoItem.classList.remove('active');
  navVentasItem.classList.remove('active');
  // Quitar clases activas en inventario
  navInventory?.classList.remove('active');
  // Según la sección, mostrar y marcar activo
  switch (type) {
    case 'caja':
      cajaSection.classList.remove('hidden');
      navCajaItem.classList.add('active');
      renderCashTable();
  try { renderCutSummary(); } catch(_e){}
      break;
    case 'historico':
      historicoSection.classList.remove('hidden');
      navHistoricoItem.classList.add('active');
      renderHistoricoTable();
      break;
    case 'ventas':
      ventasSection.classList.remove('hidden');
      navVentasItem.classList.add('active');
      renderVentasTable();
      break;
    default:
      break;
  }
}

