/**
 * Cambia la vista activa dentro del módulo de Inventario.
 * @param {string} type 'products' | 'supplies' | 'insumos'
 * @param {{ skipNavHighlight?: boolean }} opts
 */
let currentInventoryView = inventoryFilter?.value || 'products';
function switchSection(type, opts = {}) {
  const viewKey = String(type || '').toLowerCase();
  const viewMap = {
    products: 'products',
    product: 'products',
    inventory: currentInventoryView,
    inventario: currentInventoryView,
    supplies: 'supplies',
    supply: 'supplies',
    consumibles: 'supplies',
    consumible: 'supplies',
    insumos: 'insumos',
    insumo: 'insumos'
  };
  const resolvedView = viewMap[viewKey] || 'products';
  currentInventoryView = resolvedView;
  window.__lastInventoryView = resolvedView;

  if(inventoryFilter && inventoryFilter.value !== resolvedView){
    inventoryFilter.value = resolvedView;
  }

  // Restringir acceso si no hay sesión iniciada
  try {
    const authed = !!(window.auth && window.auth.currentUser);
    if(!authed){
      const loginSec = document.getElementById('login-section');
      if(loginSec){
        document.querySelectorAll('section').forEach(sec => {
          if(sec.id === 'login-section') sec.classList.remove('hidden');
          else sec.classList.add('hidden');
        });
      }
      return;
    }
  } catch(_e){}

  if(inventorySection){
    inventorySection.classList.remove('hidden');
    inventorySection.setAttribute('data-view', resolvedView);
  }

  applyInventorySchema(resolvedView);

  if(navInventory && !opts.skipNavHighlight){
    navInventory.classList.add('active');
  }

  if(productsSection) productsSection.classList.toggle('hidden', resolvedView !== 'products');
  if(suppliesSection) suppliesSection.classList.toggle('hidden', resolvedView !== 'supplies');
  if(insumosSection) insumosSection?.classList.toggle('hidden', resolvedView !== 'insumos');

  resetInventoryScrollPosition();

  if(resolvedView === 'products'){
    if(searchInput) searchInput.value = '';
    currentSearchProducts = '';
    if(includeZeroProductsEl) includeZeroProductsEl.checked = false;
    includeZeroProducts = false;
    isSupplies = false;
    if(typeof renderTable === 'function') renderTable();
  } else if(resolvedView === 'supplies'){
    if(searchInputSupplies) searchInputSupplies.value = '';
    currentSearchSupplies = '';
    if(includeZeroSuppliesEl) includeZeroSuppliesEl.checked = false;
    includeZeroSupplies = false;
    isSupplies = true;
    if(typeof renderTable === 'function') renderTable();
  } else if(resolvedView === 'insumos'){
    if(typeof searchInputInsumos !== 'undefined' && searchInputInsumos) searchInputInsumos.value = '';
    if(typeof currentSearchInsumos !== 'undefined') currentSearchInsumos = '';
    const chk = document.getElementById('includeZeroInsumos');
    if(chk) chk.checked = false;
    if(typeof includeZeroInsumos !== 'undefined') includeZeroInsumos = false;
    isSupplies = false;
    if(typeof renderInsumosTable === 'function') renderInsumosTable();
  }

  if(typeof updateProductDatalist === 'function') updateProductDatalist();
}

