// Turnos: abrir/cerrar
async function refreshTurnoUi(){
  try{
    const t = await window.firebaseApi?.getTurnoAbierto?.();
    const abierto = !!t;
    if(turnoStatus) turnoStatus.textContent = abierto ? `Turno abierto${t?.abiertoEn? '' : ''}` : 'Turno: sin abrir';
    if(abrirTurnoBtn) abrirTurnoBtn.classList.toggle('hidden', abierto);
    if(cerrarTurnoBtn) cerrarTurnoBtn.classList.toggle('hidden', !abierto);
  }catch(_e){}
}
abrirTurnoBtn?.addEventListener('click', async ()=>{
  try{ await window.firebaseApi.openTurno(); notify && notify('Turno abierto','ok'); }catch(e){ notify && notify(e.message||'No se pudo abrir turno','err'); }
  refreshTurnoUi();
});
cerrarTurnoBtn?.addEventListener('click', async ()=>{
  try{
    let v = prompt('Efectivo al cierre (opcional):','');
    const ef = (v && Number.isFinite(parseFloat(v)))? parseFloat(v) : null;
    await window.firebaseApi.closeTurno({ efectivo: ef });
    notify && notify('Turno cerrado','ok');
  }catch(e){ notify && notify(e.message||'No se pudo cerrar turno','err'); }
  refreshTurnoUi();
});
