// Renderizado inicial: respetar ruta limpia (/nav-...) o hash legacy; si no, seleccionar sección disponible por defecto
try {
  // Detectar primero por pathname limpio
  const pathSeg = (location.pathname||'').split('/').filter(Boolean)[0] || '';
  let navId = pathSeg ? decodeURIComponent(pathSeg) : '';
  // Fallback a hash legacy
  if(!navId){
    const rawHash = (location.hash||'').replace(/^#/, '');
    navId = rawHash ? decodeURIComponent(rawHash) : '';
  }
  const defaultSection = (typeof suppliesSection !== 'undefined' && suppliesSection)
    ? 'supplies'
    : ((typeof productsSection !== 'undefined' && productsSection) ? 'products' : null);

  if(navId === 'nav-supplies') {
    // Si se pidió insumos, pero no existe, caer al default
    if(typeof suppliesSection !== 'undefined' && suppliesSection) switchSection('supplies');
    else if(defaultSection) switchSection(defaultSection);
  } else if(navId === 'nav-products') {
    // Ahora productos operativos existen como 'products-section'
    if(typeof productsSection !== 'undefined' && productsSection) {
      switchSection('products');
    } else if(defaultSection) {
      switchSection(defaultSection);
    }
  } else if(!navId) {
    // Sin ruta/navId → elegir sección disponible (preferimos insumos)
    // Solo navegar automáticamente si el usuario ya está autenticado
    if(window.auth?.currentUser && defaultSection) switchSection(defaultSection);
    else {
      // Asegurar que el login permanezca visible si no hay sesión
      const loginSec = document.getElementById('login-section');
      if(loginSec){
        document.querySelectorAll('section').forEach(sec => {
          if(sec.id === 'login-section') sec.classList.remove('hidden');
          else sec.classList.add('hidden');
        });
      }
    }
  } // Para otros navId (otros módulos), no forzamos nada aquí; el router posterior lo mostrará
} catch(_e) {
  // En caso de error, intentar mostrar alguna sección disponible
  if(window.auth?.currentUser){
    if(typeof suppliesSection !== 'undefined' && suppliesSection) switchSection('supplies');
    else if(typeof productsSection !== 'undefined' && productsSection) switchSection('products');
  } else {
    const loginSec = document.getElementById('login-section');
    if(loginSec){
      document.querySelectorAll('section').forEach(sec => {
        if(sec.id === 'login-section') sec.classList.remove('hidden');
        else sec.classList.add('hidden');
      });
    }
  }
}

