// Rellenar dropdown de historial de puntos medios
// Reúne todos los puntos medios existentes en el sistema (de todos los clientes)
function getAllPuntosMediosGlobal(){
  const all = [];
  try{
    const globalArr = Array.isArray(window.puntosMediosGlobal) ? window.puntosMediosGlobal : [];
    globalArr.forEach(pm=>{
      const normalized = {
        nombre: (pm?.nombre||'').trim(),
        calle: pm?.calle||'',
        numero: pm?.numero||'',
        colonia: pm?.colonia||'',
        cp: pm?.cp||'',
        ciudad: pm?.ciudad||'',
        estado: pm?.estado||'',
        pais: pm?.pais||'',
        coords: (pm?.coords||'').trim(),
        ts: pm?.ts||0,
        clienteId: pm?.clienteId||null,
        clienteNombre: pm?.clienteNombre||null,
        key: pm?.key||''
      };
      ensurePuntoMedioKey(normalized);
      all.push(normalized);
    });
  }catch(_e){}
  try{
    const list = (!Array.isArray(window.puntosMediosGlobal) || !window.puntosMediosGlobal.length) ? getClientesList() : [];
    (list||[]).forEach(c=>{
      const arr = Array.isArray(c?.puntosMedios) ? c.puntosMedios : [];
      arr.forEach(pm=>{
        const normalized = {
          nombre: (pm?.nombre||'').trim(),
          calle: pm?.calle||'',
          numero: pm?.numero||'',
          colonia: pm?.colonia||'',
          cp: pm?.cp||'',
          ciudad: pm?.ciudad||'',
          estado: pm?.estado||'',
          pais: pm?.pais||'',
          coords: (pm?.coords||'').trim(),
          ts: pm?.ts||0,
          clienteId: c?._id||c?.id||null,
          clienteNombre: c?.nombre||null
        };
        ensurePuntoMedioKey(normalized);
        all.push(normalized);
      });
    });
  }catch(_e){}
  // Incluir historial local aún no persistido del cliente activo (si existe)
  try{
    if(Array.isArray(clientePuntosMediosHist) && clientePuntosMediosHist.length){
      clientePuntosMediosHist.forEach(pm=>{
        const copy = { ...pm };
        ensurePuntoMedioKey(copy);
        all.push(copy);
      });
    }
  }catch(_e){}
  // Deduplicar por todos los campos básicos
  const deduped = dedupePuntosMedios(all);
  // Ordenar por timestamp descendente si existe, luego por nombre
  deduped.sort((a,b)=>{
    const at=+a.ts||0, bt=+b.ts||0; if(bt!==at) return bt-at; return (a.nombre||'').localeCompare(b.nombre||'');
  });
  return deduped;
}

function populatePuntoMedioSearchList(){
  if(!clientePuntoSearchList) return;
  clientePuntoSearchList.innerHTML = '';
  const q = (clientePuntoSearch?.value||'').trim().toLowerCase();
  const items = getAllPuntosMediosGlobal();
  const seen = new Set();
  let count = 0;
  for(const pm of items){
    const nameRaw = ((pm.nombre||'').trim()) || (pm.calle||pm.colonia||pm.ciudad||'Sin nombre');
    const name = nameRaw.trim();
    const coords = (pm.coords||'').trim();
    // Filtro por texto ingresado (nombre o coords)
    if(q){
      const hay = name.toLowerCase().includes(q) || coords.toLowerCase().includes(q);
      if(!hay) continue;
    }
    const key = (name.toLowerCase().replace(/\s+/g,' ').trim()) + '|' + coords;
    if(seen.has(key)) continue; // evitar duplicados exactos nombre+coords
    seen.add(key);
    const opt = document.createElement('option');
    opt.value = name; // búsqueda por nombre
    opt.label = coords ? `${name} • ${coords}` : name;
    clientePuntoSearchList.appendChild(opt);
    count++;
    if(count>=200) break; // limitar para rendimiento del datalist
  }
}
document.addEventListener('puntosMediosUpdated', ()=>{
  try{ populatePuntoMedioSearchList(); }catch(_e){}
});
if(clientePuntoSearch){
  clientePuntoSearch.addEventListener('input', (e)=>{
    // solo poblamos el datalist al escribir (ya está poblado, pero por si cambia historial)
    try{ populatePuntoMedioSearchList(); }catch(_e){}
  });
  clientePuntoSearch.addEventListener('change', ()=>{
    const q = (clientePuntoSearch.value||'').trim().toLowerCase(); if(!q) return;
    // buscar coincidencia global por nombre (empieza con q, luego incluye q), luego coords
    const items = getAllPuntosMediosGlobal();
    let pm = items.find(x=> (x.nombre||'').toLowerCase().startsWith(q));
    if(!pm) pm = items.find(x=> (x.nombre||'').toLowerCase().includes(q));
    if(!pm){
      pm = items.find(x=> (x.coords||'').toLowerCase().includes(q));
    }
    if(!pm) return;
    setActiveSlot && setActiveSlot('puntoMedio');
    if(clientePuntoNombreInput) clientePuntoNombreInput.value = pm.nombre||'';
    if(clienteCalleInput) clienteCalleInput.value = pm.calle||'';
    if(clienteNumeroInput) clienteNumeroInput.value = pm.numero||'';
    if(clienteColoniaInput) clienteColoniaInput.value = pm.colonia||'';
    if(clienteCPInput) clienteCPInput.value = pm.cp||'';
    if(clienteCiudadInput) clienteCiudadInput.value = pm.ciudad||'';
    if(clienteEstadoInput) clienteEstadoInput.value = pm.estado||'';
    if(clientePaisInput) clientePaisInput.value = pm.pais||'México';
    if(clienteCoordsInput) clienteCoordsInput.value = pm.coords||'';
    try{ saveActiveSlotFields(); }catch(_e){}
    clientePuntoMedioDirty = true;
    try{ const c = parseCoords(pm.coords||''); if(c){ initHere(); renderAllSlotMarkers(); setMapMarker(c.lat,c.lng); } }catch(_e){}
  });
}
