(function(){
  try{
    if(typeof flatpickr !== 'undefined' && clienteCumpleInput){
      flatpickr(clienteCumpleInput, {
        dateFormat: 'm-d',
        altInput: true,
        altFormat: 'd \\de M',
        allowInput: false,
        locale: (window.flatpickr && window.flatpickr.l10ns && window.flatpickr.l10ns.es) ? window.flatpickr.l10ns.es : undefined,
        defaultDate: clienteCumpleInput.value || null,
        parseDate: (dateStr) => {
          const s = (dateStr||'').trim();
          const m = /^([01]?\d)-([0-3]?\d)$/.exec(s);
          if(m){ const y = 2000; const mm = m[1].padStart(2,'0'); const dd = m[2].padStart(2,'0'); return new Date(`${y}-${mm}-${dd}T00:00:00`); }
          return window.flatpickr.parseDate(s, 'm-d');
        },
        formatDate: (date) => {
          const mm = String(date.getMonth()+1).padStart(2,'0');
          const dd = String(date.getDate()).padStart(2,'0');
          return `${mm}-${dd}`;
        },
        onChange: (selectedDates, dateStr) => {
          clienteCumpleInput.value = dateStr;
        }
      });
    }
  } catch(e){ console.warn('No se pudo inicializar flatpickr para cumpleaños', e); }
})();
