// --- Multi-direcciones wiring ---
function getActiveSlot(){ return clienteAddrActiveSlot || 'casa'; }
// Persistir historial de puntos medios inmediatamente si se está editando un cliente existente
async function persistPuntosMediosIfEditing(){
  try{
    const docId = (clienteEditingIdInput && clienteEditingIdInput.value)||'';
    if(!docId) return; // solo en edición
    if(!(window._firebaseReady && window.firebaseApi)) return;
    const uid = (window.auth && window.auth.currentUser && window.auth.currentUser.uid)||null;
    let arr = Array.isArray(clientePuntosMediosHist) ? dedupePuntosMedios(clientePuntosMediosHist.slice()) : [];
    if(arr.length > MAX_PUNTOS_MEDIOS){ arr = arr.slice(arr.length - MAX_PUNTOS_MEDIOS); }
    arr = arr.map(pm=>{
      const copy = { ...pm };
      if(!copy.ts) copy.ts = Date.now();
      ensurePuntoMedioKey(copy);
      return copy;
    });
    if(typeof window.firebaseApi.updateCliente === 'function'){
      await window.firebaseApi.updateCliente(docId, { puntosMedios: arr, updatedBy: uid });
    }
    if(typeof window.firebaseApi.syncPuntosMediosForCliente === 'function'){
      const clienteNombre = clienteNombreInput && clienteNombreInput.value ? clienteNombreInput.value.trim() : '';
      await window.firebaseApi.syncPuntosMediosForCliente(docId, arr, { clienteNombre, updatedBy: uid });
    }
  }catch(e){ console.warn('persistPuntosMediosIfEditing failed', e); }
}
function dedupePuntosMedios(arr){
  const out = [];
  const seen = new Set();
  (arr||[]).forEach(pm=>{
    const key = ensurePuntoMedioKey(pm);
    if(!key || seen.has(key)) return;
    seen.add(key);
    out.push(pm);
  });
  return out;
}
async function confirmPuntoMedioGuardado(entry){
  const nombre = entry && typeof entry.nombre === 'string' ? entry.nombre.trim() : '';
  if(!nombre){
    return false;
  }
  const displayName = nombre;
  const message = `¿Guardar el punto medio "${displayName}" en el historial del cliente?`;
  try {
    if(typeof confirmAction === 'function'){
      return await confirmAction(message, { variant:'info', confirmText:'Guardar punto medio', cancelText:'Solo usar' });
    }
  } catch(_e) {}
  if(typeof window !== 'undefined' && typeof window.confirm === 'function'){
    return window.confirm(message);
  }
  return true;
}
function loadActiveSlotFields(){
  const A = (clienteDirecciones[getActiveSlot()]||{});
  if(clienteCalleInput) clienteCalleInput.value = A.calle||'';
  if(clienteNumeroInput) clienteNumeroInput.value = A.numero||'';
  if(clienteColoniaInput) clienteColoniaInput.value = A.colonia||'';
  if(clienteCPInput) clienteCPInput.value = A.cp||'';
  if(clienteCiudadInput) clienteCiudadInput.value = A.ciudad||'';
  if(clienteEstadoInput) clienteEstadoInput.value = A.estado||'';
  if(clientePaisInput) clientePaisInput.value = A.pais||'México';
  if(clienteCoordsInput) clienteCoordsInput.value = A.coords||'';
  if(clientePuntoNombreInput) clientePuntoNombreInput.value = (getActiveSlot()==='puntoMedio' ? (A.nombre||'') : '');
  // Renderizar los 3 marcadores y centrar en el activo (si existe)
  initHere();
  renderAllSlotMarkers();
  const c = parseCoords(A.coords||'');
  if(c){ setMapMarker(c.lat,c.lng,{center:false}); }
}
function saveActiveSlotFields(){
  const slot = getActiveSlot();
  const A = clienteDirecciones[slot] = clienteDirecciones[slot] || {};
  A.calle = (clienteCalleInput?.value||'').trim();
  A.numero = (clienteNumeroInput?.value||'').trim();
  A.colonia = (clienteColoniaInput?.value||'').trim();
  A.cp = (clienteCPInput?.value||'').trim();
  A.ciudad = (clienteCiudadInput?.value||'').trim();
  A.estado = (clienteEstadoInput?.value||'').trim();
  A.pais = (clientePaisInput?.value||'').trim() || 'México';
  const c = parseCoords(clienteCoordsInput?.value||'');
  A.coords = c? `${(+c.lat).toFixed(6)}, ${(+c.lng).toFixed(6)}` : '';
  if(slot==='puntoMedio' && clientePuntoNombreInput){ A.nombre = (clientePuntoNombreInput.value||'').trim(); }
}
function setActiveSlot(slot){
  if(!slot) slot='casa';
  if(!['casa','trabajo','puntoMedio'].includes(slot)) slot='casa';
  // Guardar valores actuales en el slot previo
  saveActiveSlotFields();
  resetClienteAddrSearchUI({ cancelPending:true });
  setClienteAddrSearchLoading(false);
  clienteAddrActiveSlot = slot;
  // UI tabs highlight
  if(clienteAddrTabs){ styleAddrTabs(slot); }
  if(clienteAddrActiveLabel) clienteAddrActiveLabel.textContent = slot==='casa'?'CASA':(slot==='trabajo'?'TRABAJO':'PUNTO MEDIO');
  if(clientePuntoMedioExtras) clientePuntoMedioExtras.style.display = (slot==='puntoMedio') ? '' : 'none';
  loadActiveSlotFields();
  refreshMarkersDraggable();
}
