const usarImpContadorActualInput = document.getElementById('usarImpContadorActual');
const usarImpMaquinaSelectEl = usarImpMaquinaSelect; // alias por consistencia
const usarFechaOverlay = document.getElementById('usarFechaOverlay');
const closeUsarFechaBtn = document.getElementById('closeUsarFechaBtn');
const usarFechaForm = document.getElementById('usarFechaForm');
const usarFechaFechaInput = document.getElementById('usarFechaFecha');
const usarFechaConsumibleSelect = document.getElementById('usarFechaConsumible');

function fillConsumiblesSelect(selectEl){
  if(!selectEl) return;
  selectEl.innerHTML = '<option value="">SELECCIONE</option>';
  (window._consumiblesData||[]).forEach(c=>{
    const opt = document.createElement('option');
    opt.value = c.id; opt.textContent = c.descripcion; selectEl.appendChild(opt);
  });
}

function renderHistConsumibles(){
  if(!histConsumiblesBody) return;
  histConsumiblesBody.innerHTML='';
  let total=0;
  consumiblesHistorial.slice().sort((a,b)=> b.fecha.localeCompare(a.fecha) || b.id-a.id).forEach(reg=>{
    total++;
    const tr = document.createElement('tr');
    tr.innerHTML = `<td>${reg.id}</td><td>${reg.fecha}</td><td>${reg.tipo}</td><td>${reg.consumibleNombre||''}</td><td>${reg.maquina||''}</td><td>${reg.contadorInicial??''}</td><td>${reg.contadorFinal??''}</td><td>${reg.diasUso??''}</td><td>${reg.usuario||'Usuario'}</td><td>${reg.notas||''}</td>`;
    histConsumiblesBody.appendChild(tr);
  });
  if(histConsumiblesTotal) histConsumiblesTotal.textContent = total;
}

function openUsarImpresionModal(){
  // Llenar máquinas y consumibles
  try{ fillMaquinasSelect(usarImpMaquinaSelect); }catch(_e){}
  fillConsumiblesSelect(usarImpConsumibleSelect);
  if(usarImpContadorActualInput) usarImpContadorActualInput.value=0;
  usarImpresionOverlay?.classList.remove('hidden');
}
function closeUsarImpresionModal(){ usarImpresionOverlay?.classList.add('hidden'); }
function openUsarFechaModal(){ fillConsumiblesSelect(usarFechaConsumibleSelect); if(usarFechaFechaInput){ usarFechaFechaInput.value = new Date().toISOString().slice(0,10); } usarFechaOverlay?.classList.remove('hidden'); }
function closeUsarFechaModal(){ usarFechaOverlay?.classList.add('hidden'); }

async function handleUsarImpresionSubmit(e){
  e.preventDefault();
  const maquina = usarImpMaquinaSelect.value; const consumibleId = usarImpConsumibleSelect.value; const contador = parseInt(usarImpContadorActualInput.value)||0;
  if(!maquina||!consumibleId){ notify('Seleccione máquina y consumible','warn'); return; }
  const consumible = (window._consumiblesData||[]).find(c=> c.id==consumibleId);
  // Buscar último registro abierto (tipo impresion) de este consumible y máquina sin contadorFinal
  const prevOpen = [...consumiblesHistorial].reverse().find(r=> r.tipo==='impresion' && r.consumibleId==consumibleId && r.maquina===maquina && (r.contadorFinal===''||r.contadorFinal==null));
  if(prevOpen){
    // Cerrar ciclo: asignar contador final y calcular uso
    if(contador <= (prevOpen.contadorInicial||0)){
      const ok = await confirmAction('El contador actual es menor o igual al inicial previo. ¿Registrar de todos modos?');
      if(!ok) return;
    }
    prevOpen.contadorFinal = contador;
  // Incrementar contador de la máquina vinculada usando contador asociado (de producto o local)
  try{
    const prod = (window.products||[]).find(p=> String(p.id||p._id)===String(consumibleId));
    const preferCounterId = (prod && prod.consumibleContadorId) ? prod.consumibleContadorId : (consumible && consumible.contadorId ? consumible.contadorId : '');
    updateMachineCounter(maquina, prevOpen.contadorInicial, contador, consumibleId, preferCounterId||undefined);
  }catch(_e){}
  } else {
    // Crear nuevo ciclo abierto
    consumiblesHistorial.push({ id: generateConsumibleHistId(), fecha: new Date().toISOString().slice(0,10), tipo:'impresion', consumibleId: parseInt(consumibleId), consumibleNombre: consumible?consumible.descripcion:'', maquina, contadorInicial: contador, contadorFinal: '', diasUso:'', usuario:'Usuario'});
  }
  renderHistConsumibles(); notify('Uso registrado','ok'); closeUsarImpresionModal();
}
function handleUsarFechaSubmit(e){
  e.preventDefault();
  const fecha = usarFechaFechaInput.value; const consumibleId = usarFechaConsumibleSelect.value; if(!fecha||!consumibleId){ notify('Fecha y consumible obligatorios','warn'); return; }
  const consumible = (window._consumiblesData||[]).find(c=> c.id==consumibleId);
  // Buscar último registro fecha sin diasUso calculado para ese consumible
  const prevFecha = [...consumiblesHistorial].reverse().find(r=> r.tipo==='fecha' && r.consumibleId==consumibleId && (r.diasUso===''||r.diasUso===0));
  if(prevFecha){
    const d1 = new Date(prevFecha.fecha);
    const d2 = new Date(fecha);
    const diff = Math.max(0, Math.round((d2 - d1)/(1000*60*60*24)) );
    prevFecha.diasUso = diff;
  }
  consumiblesHistorial.push({ id: generateConsumibleHistId(), fecha, tipo:'fecha', consumibleId: parseInt(consumibleId), consumibleNombre: consumible?consumible.descripcion:'', maquina:'', contadorInicial:'', contadorFinal:'', diasUso:0, usuario:'Usuario'});
  renderHistConsumibles(); notify('Registro por fecha añadido','ok'); closeUsarFechaModal();
}

// Cuando cambia la máquina en el modal de uso, prellenar contador con el primer valor actual (si existe)
usarImpMaquinaSelectEl?.addEventListener('change', ()=>{
  try{
    const mId = usarImpMaquinaSelectEl.value; const list = Array.isArray(window.maquinasState)? window.maquinasState : [];
    const m = list.find(x=> x.id===mId);
    // Si hay un consumible seleccionado y está vinculado a un contador, prefiera ese valor actual
    let v = 0;
    if(m && Array.isArray(m.contadores) && m.contadores.length){
      const cSelId = (function(){
        const cid = (()=>{
          const consId = usarImpConsumibleSelect?.value;
          const prod = (window.products||[]).find(p=> String(p.id||p._id)===String(consId));
          if(prod && prod.consumibleContadorId) return prod.consumibleContadorId;
          const cons = (window._consumiblesData||[]).find(c=> String(c.id)===String(consId));
          if(cons && cons.contadorId) return cons.contadorId;
          return '';
        })();
        return cid||'';
      })();
      const counter = cSelId? m.contadores.find(c=> String(c.id)===String(cSelId)) : m.contadores[0];
      v = counter? (parseInt(counter.valorActual)||0) : 0;
    }
    if(usarImpContadorActualInput) usarImpContadorActualInput.value = v;
  }catch(_e){}
});

// Actualizar contador de máquina y dejar rastro en histórico propio de la máquina
function updateMachineCounter(maquinaId, fromVal, toVal, consumibleId, contadorId){
  const incr = (parseInt(toVal)||0) - (parseInt(fromVal)||0);
  if(!(incr>0)) return;
  const list = Array.isArray(window.maquinasState)? window.maquinasState : [];
  const m = list.find(x=> x.id===maquinaId); if(!m) return;
  const p = (window.products||[]).find(pp=> String(pp.id||pp._id)===String(consumibleId));
  // Determinar contador a afectar: preferir contadorId indicado (de producto/consumible), si no el primero
  let c = null;
  if(Array.isArray(m.contadores) && m.contadores.length){
    if(contadorId){ c = m.contadores.find(cc=> String(cc.id)===String(contadorId)) || m.contadores[0]; }
    else { c = m.contadores[0]; }
  }
  if(!c) return;
  c.valorActual = (parseInt(c.valorActual)||0) + incr;
  try{ c.historico.push({ fecha:new Date(), valor: c.valorActual }); }catch(_e){}
  // Persistir si API disponible
  try{ if(window.firebaseApi && typeof window.firebaseApi.updateMaquina==='function'){ window.firebaseApi.updateMaquina(m.id, { contadores: m.contadores.map(x=> ({...x, historico:[...x.historico]})) }); } }catch(_e){}
}

// Contar impresiones para items vendidos (solo modo 'impresiones')
function countImpressionsForItems(itemsList){
  try{
    const list = Array.isArray(itemsList)? itemsList : [];
    if(!list.length) return;
    list.forEach(it=>{
      try{
        const pid = it.productoId || it.id || it.p || null;
        const qty = parseInt(it.cantidad)||0;
        if(!(pid && qty>0)) return;
        const prod = (window.products||[]).find(p=> String(p.id||p._id)===String(pid));
        if(!prod) return;
        if(prod.consumibleModo === 'impresiones' && prod.consumibleMaquinaId){
          const maqId = prod.consumibleMaquinaId;
          const contId = prod.consumibleContadorId || '';
          // from 0 to qty => increment qty
          updateMachineCounter(maqId, 0, qty, pid, contId||undefined);
        }
      }catch(_e){}
    });
  }catch(_e){}
}

// Cuando se elija un consumible, si el producto está vinculado a una máquina/contador, preseleccionar y prellenar
usarImpConsumibleSelect?.addEventListener('change', ()=>{
  try{
    const consId = usarImpConsumibleSelect.value;
    const prod = (window.products||[]).find(p=> String(p.id||p._id)===String(consId));
    const maquinaId = prod?.consumibleMaquinaId || '';
    const contadorId = prod?.consumibleContadorId || '';
    if(maquinaId){
      if(usarImpMaquinaSelect){ try{ fillMaquinasSelect(usarImpMaquinaSelect); }catch(_e){} usarImpMaquinaSelect.value = maquinaId; }
      // Prefill contador actual preferido
      const list = Array.isArray(window.maquinasState)? window.maquinasState : [];
      const m = list.find(x=> x.id===maquinaId);
      if(m && usarImpContadorActualInput){
        const counter = contadorId? m.contadores?.find(c=> String(c.id)===String(contadorId)) : (m.contadores?.[0]);
        usarImpContadorActualInput.value = counter? (parseInt(counter.valorActual)||0) : 0;
      }
    }
  }catch(_e){}
});

// Eventos historial consumibles
if(histConsumiblesBuscarBtn) histConsumiblesBuscarBtn.addEventListener('click', renderHistConsumibles);
['keyup','change'].forEach(ev=>{
  if(histConsumibleFiltro) histConsumibleFiltro.addEventListener(ev, ()=>{/* opcional live */});
});
if(histConsumiblesUsarImpresionBtn) histConsumiblesUsarImpresionBtn.addEventListener('click', openUsarImpresionModal);
if(histConsumiblesUsarFechaBtn) histConsumiblesUsarFechaBtn.addEventListener('click', openUsarFechaModal);
if(closeUsarImpresionBtn) closeUsarImpresionBtn.addEventListener('click', closeUsarImpresionModal);
if(closeUsarFechaBtn) closeUsarFechaBtn.addEventListener('click', closeUsarFechaModal);
if(usarImpresionForm) usarImpresionForm.addEventListener('submit', handleUsarImpresionSubmit);
if(usarFechaForm) usarFechaForm.addEventListener('submit', handleUsarFechaSubmit);
if(histConsumiblesExportBtn) histConsumiblesExportBtn.addEventListener('click', ()=>{
  if(!guardExport(consumiblesHistorial,'No hay historial')) return;
  const headers = ['ID','Fecha','Tipo','Consumible','Maquina','ContInicial','ContFinal','DiasUso','Usuario'];
  const rows = consumiblesHistorial.map(r=> [r.id,r.fecha,r.tipo,r.consumibleNombre||'',r.maquina||'',r.contadorInicial||'',r.contadorFinal||'',r.diasUso||'',r.usuario||'']);
  window.exportToExcel(headers, rows, 'historial_consumibles.xls');
  notify('Exportado historial consumibles','ok');
});


