// Listener hook: firebase.js llamará esto cuando cambie la colección
window.updateUsuariosFromFirestore = function(list){
  try {
    usuarios = Array.isArray(list) ? list.slice() : [];
    window.usuarios = usuarios;
    renderUsuariosTable();
    // Avisar a otros módulos interesados
    document.dispatchEvent(new CustomEvent('usuarios:updated', { detail:{ total: usuarios.length } }));
    applyNavAccessControls();
  } catch(_e){}
};
