// Campo sucursal eliminado del modal de usuario: ya no se puebla ni se muestra

function ensureAdminPermChecks(perfilValue, opts={}){
  const isAdminPerfil = String(perfilValue||'').toLowerCase().includes('admin');
  if(!isAdminPerfil) return;
  const editingExisting = !!(usuarioEditingIdInput && usuarioEditingIdInput.value);
  if(editingExisting && !opts.force) return;
  [permMovilInput,permDescuentosInput,permPreciosInput,permVentasPorCobrarInput,permMultiSucursalInput,permEditarVentasInput,permIndicacionesProdInput,permCambiarFechaProdInput,permEliminarMovCajaInput,permEliminarVentasInput,permQuitarProductosVentaInput,permCambiarFormaPagoIngresoInput,notifVentasRequierenProdInput]
    .forEach(cb=>{ if(cb) cb.checked = true; });
}

// Rellena opciones de Caja fija para el modal de usuario desde catálogo de cajas
function populateUsuarioCajaOptions(){
  try{
    if(!usuarioCajaSel) return;
    const cajas = Array.isArray(window.cajas)? window.cajas : [];
    const active = cajas.filter(c=> String(c.estatus||'Activa').toLowerCase()==='activa');
    const current = usuarioCajaSel.value;
    const options = [{ value:'', label:'SELECCIONE' }].concat(active.map(c=> ({ value:String(c.id), label:`${c.sucursal? String(c.sucursal)+' - ' : ''}${String(c.nombre||'')}` })));
    usuarioCajaSel.innerHTML = options.map(o=> `<option value="${o.value}">${o.label}</option>`).join('');
    if(current && active.some(c=> String(c.id)===String(current))){ usuarioCajaSel.value = current; }
  }catch(_e){}
}
document.addEventListener('cajas:updated', ()=>{ try{ populateUsuarioCajaOptions(); }catch(_e){} });


function renderUsuariosTable(){
  if(!usuariosBody) return;
  usuariosBody.innerHTML='';
  const search = (searchUsuariosInput?.value||'').trim().toLowerCase();
  const showInact = !!document.getElementById('showInactUsuarios')?.checked;
  let total = 0;
  const permFlag = (flag, label)=> flag ? `<span class="perm-flag" title="${escapeHtml(label)}">✔</span>` : '';

  const deriveSucursal = (u)=>{
    try{
      const cajas = Array.isArray(window.cajas)? window.cajas : [];
      if(u.cajaId){
        const c = cajas.find(x=> String(x.id)===String(u.cajaId));
        if(c) return String(c.sucursal||'');
      }
      if(u.caja){
        const c = cajas.find(x=> String(x.nombre||'').toLowerCase()===String(u.caja).toLowerCase());
        if(c) return String(c.sucursal||'');
      }
      return String(u.sucursal||'');
    }catch(_e){ return String(u.sucursal||''); }
  };

  const formatCajaCell = (u)=>{
    try{
      const cajas = Array.isArray(window.cajas)? window.cajas : [];
      let cajaName = String(u.caja||'');
      let c = null;
      if(u.cajaId){
        c = cajas.find(x=> String(x.id)===String(u.cajaId));
        if(c && !cajaName) cajaName = String(c.nombre||'');
      }
      if(!c && cajaName){
        c = cajas.find(x=> String(x.nombre||'').toLowerCase()===cajaName.toLowerCase());
      }
      if(!cajaName) return '';
      if(!c){
        return `<span title="Caja no encontrada">${escapeHtml(cajaName)}</span><span style="margin-left:6px;padding:0 6px;border-radius:999px;font-size:0.65rem;font-weight:700;color:#6b7280;background:#f3f4f6;border:1px solid #e5e7eb;" title="No encontrada">?</span>`;
      }
      const activa = String(c.estatus||'Activa').toLowerCase()==='activa';
      const badge = activa
        ? '<span style="margin-left:6px;padding:0 6px;border-radius:999px;font-size:0.65rem;font-weight:700;color:#065f46;background:#d1fae5;border:1px solid #a7f3d0;" title="Caja activa">●</span>'
        : '<span style="margin-left:6px;padding:0 6px;border-radius:999px;font-size:0.65rem;font-weight:700;color:#991b1b;background:#fee2e2;border:1px solid #fecaca;" title="Caja inactiva">●</span>';
      return `${escapeHtml(cajaName)}${badge}`;
    }catch(_e){ return escapeHtml(String(u.caja||'')); }
  };

  usuarios.forEach(u=>{
    if(!showInact && String(u.estatus||'Activo').toLowerCase()!=='activo') return;
    const telefonoCombinado = composeTelefonoValue(u.telefono||'', u.telefonoPais||'', u.telefonoE164||u.telefonoCompleto||'');
    const telefonoSearch = telefonoCombinado.toLowerCase();
    const sucDer = deriveSucursal(u).toLowerCase();
    if(search && !(
      String(u.nombre||'').toLowerCase().includes(search) ||
      String(u.correo||'').toLowerCase().includes(search) ||
      telefonoSearch.includes(search) ||
      String(u.telefonoE164||'').toLowerCase().includes(search) ||
      String(u.perfil||'').toLowerCase().includes(search) ||
      (sucDer||'').includes(search) ||
      String(u.caja||'').toLowerCase().includes(search) ||
      String(u.codigo||'').toLowerCase().includes(search)
    )) return;

    total++;
    const porCobrarAllowed = (u.permVentasPorCobrar===undefined) ? true : !!u.permVentasPorCobrar;
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td>${escapeHtml(String(u.codigo||''))}</td>
      <td>${escapeHtml(u.nombre||'')}</td>
      <td>${escapeHtml(u.perfil||'')}</td>
      <td>${escapeHtml(deriveSucursal(u)||'')}</td>
      <td>${formatCajaCell(u)}</td>
      <td>${permFlag(u.permMovil,'Puede usar el POS movil')}</td>
      <td>${permFlag(u.permDescuentos,'Puede otorgar descuentos en ventas')}</td>
      <td>${permFlag(u.permPrecios,'Puede editar el precio unitario en ventas')}</td>
      <td>${permFlag(porCobrarAllowed,'Puede registrar ventas por cobrar')}</td>
      <td>${permFlag(u.permMultiSucursal,'Puede operar en cualquier sucursal')}</td>
      <td>${(function(){ const en=String(u.estatus||'Activo').toLowerCase()==='activo'; return `<span style="padding:2px 8px;border-radius:999px;font-size:0.7rem;font-weight:700;color:${en?'#065f46':'#991b1b'};background:${en?'#d1fae5':'#fee2e2'};border:1px solid ${en?'#a7f3d0':'#fecaca'};">${en?'SI':'NO'}</span>`; })()}</td>
      <td>
        <button type="button" class="mini-btn" data-action="edit" data-id="${u.id||u.uid}" title="Editar">✏️</button>
      </td>`;
    usuariosBody.appendChild(tr);
  });

  if(usuariosTotalCount) usuariosTotalCount.textContent = total;
}

function openUsuarioModal(editId=null){
  if(!usuarioOverlay) return;
  if(editId){
  const u = usuarios.find(x=> String(x.id||x.uid)===String(editId)); if(!u) return;
    usuarioModalTitle.textContent='Editar usuario';
  usuarioEditingIdInput.value= String(u.id||u.uid||'');
    usuarioNombreInput.value=u.nombre;
  // No se edita password aquí
  if(usuarioPasswordInput){ usuarioPasswordInput.value=''; usuarioPasswordInput.required = false; }
    usuarioCorreoInput.value=u.correo||'';
  if(usuarioTelefonoInput){
    const telPrefill = composeTelefonoValue(u.telefono||'', u.telefonoPais||'', u.telefonoE164||u.telefonoCompleto||'');
    usuarioTelefonoInput.value = telPrefill;
    usuarioTelefonoInput.placeholder = '+529514138990';
  }
    usuarioPerfilInput.value=u.perfil||'';
  if(usuarioCodigoAdminInput) usuarioCodigoAdminInput.value = u.codigoAdmin||u.approvalCode||u.pin||u.codigoAutorizacion||'';
  // Preparar select de Caja y preseleccionar por cajaId o por nombre
  populateUsuarioCajaOptions();
  if(usuarioCajaSel){
    let pre = String(u.cajaId||'');
    if(!pre && u.caja){
      try{
        const list = Array.isArray(window.cajas)? window.cajas : [];
        const match = list.find(c=> String(c.nombre||'').toLowerCase()===String(u.caja||'').toLowerCase());
        if(match) pre = String(match.id);
      }catch(_e){}
    }
    if(pre){ usuarioCajaSel.value = pre; }
  }
  if(usuarioEstatusInput){ usuarioEstatusInput.value = String(u.estatus||'Activo'); }
  // comisión eliminada
    permMovilInput.checked=!!u.permMovil;
    permDescuentosInput.checked=!!u.permDescuentos;
    permPreciosInput.checked=!!u.permPrecios;
  if(permVentasPorCobrarInput) permVentasPorCobrarInput.checked = (u.permVentasPorCobrar !== false);
    permMultiSucursalInput.checked=!!u.permMultiSucursal;
    permEditarVentasInput.checked=!!u.permEditarVentas;
    permIndicacionesProdInput.checked=!!u.permIndicacionesProd;
    permCambiarFechaProdInput.checked=!!u.permCambiarFechaProd;
    permEliminarMovCajaInput.checked=!!u.permEliminarMovCaja;
    permEliminarVentasInput.checked=!!u.permEliminarVentas;
    permQuitarProductosVentaInput.checked=!!u.permQuitarProductosVenta;
    permCambiarFormaPagoIngresoInput.checked=!!u.permCambiarFormaPagoIngreso;
    notifVentasRequierenProdInput.checked=!!u.notifVentasRequierenProd;
  } else {
    usuarioModalTitle.textContent='Nuevo usuario';
    usuarioEditingIdInput.value='';
  [usuarioNombreInput,usuarioPasswordInput,usuarioCorreoInput].forEach(i=>{ if(i) i.value=''; });
  if(usuarioTelefonoInput){ usuarioTelefonoInput.value=''; usuarioTelefonoInput.placeholder = '+529514138990'; }
  if(usuarioPasswordInput){ usuarioPasswordInput.required = true; }
    usuarioPerfilInput.value='';
  if(usuarioCodigoAdminInput) usuarioCodigoAdminInput.value='';
  populateUsuarioCajaOptions(); if(usuarioCajaSel){ usuarioCajaSel.value=''; }
  if(usuarioEstatusInput){ usuarioEstatusInput.value='Activo'; }
  // comisión eliminada
  [permMovilInput,permDescuentosInput,permPreciosInput,permVentasPorCobrarInput,permMultiSucursalInput,permEditarVentasInput,permIndicacionesProdInput,permCambiarFechaProdInput,permEliminarMovCajaInput,permEliminarVentasInput,permQuitarProductosVentaInput,permCambiarFormaPagoIngresoInput,notifVentasRequierenProdInput].forEach(cb=>{ if(cb) cb.checked=false; });
    ensureAdminPermChecks(usuarioPerfilInput.value||'', { force:true });
  }
  usuarioOverlay.classList.remove('hidden');
}
function closeUsuarioModal(){ if(usuarioOverlay) usuarioOverlay.classList.add('hidden'); }

async function handleUsuarioSubmit(e){
  e.preventDefault();
  const nombre = usuarioNombreInput.value.trim();
  const password = usuarioPasswordInput.value;
  const correo = usuarioCorreoInput.value.trim();
  const telefonoRaw = (usuarioTelefonoInput?.value||'').trim();
  const perfil = usuarioPerfilInput.value;
  let cajaId = (usuarioCajaSel?.value||'').trim();
  let caja = '';
  try{ if(cajaId){ const c = (Array.isArray(window.cajas)? window.cajas : []).find(x=> String(x.id)===String(cajaId)); caja = c ? String(c.nombre||'') : ''; } }catch(_e){}
  const estatus = usuarioEstatusInput ? usuarioEstatusInput.value : 'Activo';
  // Obtener el id de edición antes de usarlo en validaciones
  const editingId = usuarioEditingIdInput.value ? String(usuarioEditingIdInput.value) : null;
  if(!nombre||!correo||!perfil||!telefonoRaw){ notify('Campos obligatorios faltantes','warn'); return; }
  // Password requerido solo al crear
  if(!editingId){ if(!password || password.length<6){ notify('Password mínimo 6 caracteres','warn'); return; } }
  if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(correo)){ notify('Correo inválido','err'); return; }
  const telefonoNormalized = telefonoRaw ? normalizePhone(telefonoRaw) : '';
  if(!telefonoNormalized || !/^\+[0-9]{8,15}$/.test(telefonoNormalized)){
    notify('Teléfono inválido. Usa formato internacional (+código país y dígitos).','err');
    return;
  }
  const telefonoPersist = buildTelefonoPersistence(telefonoNormalized);
  // Caja fija requerida para usuarios Activos
  if(String(estatus).toLowerCase()==='activo'){
    if(!cajaId){ notify('Selecciona una caja fija para el usuario activo','warn'); return; }
  } else {
    cajaId = ''; caja = '';
  }
  ensureAdminPermChecks(perfil, { force: !editingId });
  const payload = {
    nombre,
    password,
    correo,
    telefono: telefonoPersist.telefono,
    telefonoPais: telefonoPersist.telefonoPais,
    telefonoE164: telefonoPersist.telefonoE164,
    telefonoCompleto: telefonoPersist.telefonoCompleto,
    perfil,
    codigoAdmin: (usuarioCodigoAdminInput?.value||'').trim() || undefined,
    permMovil: permMovilInput.checked,
    permDescuentos: permDescuentosInput.checked,
    permPrecios: permPreciosInput.checked,
  permVentasPorCobrar: permVentasPorCobrarInput?.checked || false,
    permMultiSucursal: permMultiSucursalInput.checked,
    permEditarVentas: permEditarVentasInput.checked,
    permIndicacionesProd: permIndicacionesProdInput.checked,
    permCambiarFechaProd: permCambiarFechaProdInput.checked,
    permEliminarMovCaja: permEliminarMovCajaInput.checked,
    permEliminarVentas: permEliminarVentasInput.checked,
    permQuitarProductosVenta: permQuitarProductosVentaInput.checked,
    permCambiarFormaPagoIngreso: permCambiarFormaPagoIngresoInput.checked,
  notifVentasRequierenProd: notifVentasRequierenProdInput.checked,
  caja,
  cajaId,
  estatus
  };
  // Persistir en Firestore
  try{
    if(editingId){
      // No enviar password en updates (no se modifica Auth aquí); si se quiere resetear, implementar flujo aparte
      const { password: _pw, ...patch } = payload;
      await window.firebaseApi.updateUsuario(editingId, patch); notify('Usuario actualizado','ok');
    } else {
      // Alta: crea en Auth con correo/password y guarda metadatos
      await window.firebaseApi.addUsuario(payload); notify('Usuario agregado','ok');
    }
    closeUsuarioModal();
    // Re-render llegará por listener; como fallback, refrescar tabla localmente
    renderUsuariosTable();
  } catch(e){ notify('Error guardando usuario: '+(e.message||e),'err'); }
}

function handleUsuariosTableClick(e){
  const btn = e.target.closest('button[data-action]'); if(!btn) return;
  const id = String(btn.dataset.id); const action = btn.dataset.action; const u = usuarios.find(x=> String(x.id||x.uid)===id); if(!u) return;
  if(action==='edit') openUsuarioModal(u.id||u.uid);
}

function exportUsuarios(){
  if(!guardExport(usuarios,'No hay usuarios')) return;
  const headers = ['Código','Nombre','Correo','Teléfono','Perfil','Sucursal','Caja','Estatus'];
  const rows = usuarios.map(u=> {
    const cajas = Array.isArray(window.cajas)? window.cajas : [];
    let suc = '';
    if(u.cajaId){ const c = cajas.find(x=> String(x.id)===String(u.cajaId)); suc = c?.sucursal||''; }
    else if(u.caja){ const c = cajas.find(x=> String(x.nombre||'').toLowerCase()===String(u.caja).toLowerCase()); suc = c?.sucursal||''; }
    else { suc = u.sucursal||''; }
    const telefonoCombinado = composeTelefonoValue(u.telefono||'', u.telefonoPais||'', u.telefonoE164||u.telefonoCompleto||'');
    const telefonoExport = formatDisplayPhone(telefonoCombinado) || telefonoCombinado || (u.telefono||'');
    return [u.codigo||'',u.nombre,u.correo||'',telefonoExport,u.perfil||'',suc,u.caja||'',u.estatus||''];
  });
  window.exportToExcel(headers, rows, 'usuarios.xls');
  notify('Exportado usuarios','ok');
}

