// ----------------------------
// Catálogo de Cajas – UI wiring (render básico + modal)
// ----------------------------
(function(){
  const tbody = document.getElementById('cajasBody');
  const totalEl = document.getElementById('cajasTotalCount');
  const searchInput = document.getElementById('searchCajasInput');
  const showInact = document.getElementById('showInactCajas');
  const newBtn = document.getElementById('newCajaBtn');
  const overlay = document.getElementById('cajaOverlay') || document.getElementById('cajaModal');
  const form = document.getElementById('cajaForm');
  const idInput = document.getElementById('cajaId');
  const nombreInput = document.getElementById('cajaNombre');
  const sucursalInput = document.getElementById('cajaSucursal');
  const estatusInput = document.getElementById('cajaEstatus');
  const closeBtn = document.getElementById('closeCajaBtn') || document.getElementById('cajaCloseBtn') || document.getElementById('cajaModalClose');

  function populateCajaSucursalOptions(){
    if(!sucursalInput) return;
    const prev = sucursalInput.value;
    const sucs = Array.isArray(window.sucursales)? window.sucursales : [];
    const options = [{ value:'', label:'SELECCIONE' }].concat(sucs.map(s=> ({ value:String(s.nombre||''), label:String(s.nombre||'') })));
    if(sucursalInput.tagName === 'SELECT'){
      sucursalInput.innerHTML = options.map(o=> `<option value="${o.value}">${o.label}</option>`).join('');
      if(prev && options.some(o=> o.value===prev)) sucursalInput.value = prev;
    }
  }
  document.addEventListener('sucursales:updated', ()=>{ try{ populateCajaSucursalOptions(); }catch(_e){} });

  function render(){
    if(!tbody) return;
    const q = (searchInput?.value||'').trim().toLowerCase();
    const show = !!(showInact && showInact.checked);
    const list = Array.isArray(window.cajas)? window.cajas : [];
    let total=0;
    tbody.innerHTML='';
    list
      .filter(c=> show || String(c.estatus||'Activa').toLowerCase()==='activa')
      .filter(c=> !q || String(c.sucursal||'').toLowerCase().includes(q))
      .forEach(c=>{
        total++;
        const tr=document.createElement('tr');
        const en = String(c.estatus||'Activa').toLowerCase()==='activa';
        tr.innerHTML = `
          <td>${escapeHtml(String(c.nombre||''))}</td>
          <td>${escapeHtml(String(c.sucursal||''))}</td>
          <td>${en?'<span style="padding:2px 8px;border-radius:999px;font-size:0.7rem;font-weight:700;color:#065f46;background:#d1fae5;border:1px solid #a7f3d0;">SI</span>':'<span style="padding:2px 8px;border-radius:999px;font-size:0.7rem;font-weight:700;color:#991b1b;background:#fee2e2;border:1px solid #fecaca;">NO</span>'}</td>
          <td><button type="button" class="mini-btn" data-id="${c.id}" data-action="edit">✏️</button></td>
        `;
        tbody.appendChild(tr);
      });
    if(totalEl) totalEl.textContent = total;
  }

  function openModal(c=null){ if(!overlay) return; if(!form) return;
  populateCajaSucursalOptions();
    idInput && (idInput.value = c?.id||'');
    nombreInput && (nombreInput.value = c?.nombre||'');
    sucursalInput && (sucursalInput.value = c?.sucursal||'');
    estatusInput && (estatusInput.value = String(c?.estatus||'Activa'));
    try{ overlay.classList.remove('hidden'); }catch(_e){ overlay.style.display='flex'; }
  }
  function closeModal(){ if(!overlay) return; try{ overlay.classList.add('hidden'); }catch(_e){ overlay.style.display='none'; } }

  async function onSubmit(e){ e.preventDefault();
    const id = idInput?.value.trim();
    const nombre = nombreInput?.value.trim();
    const sucursal = sucursalInput?.value.trim();
    const estatus = estatusInput?.value || 'Activa';
    if(!nombre||!sucursal){ notify('Nombre y sucursal requeridos','warn'); return; }
    try{
      if(id){ await window.firebaseApi.updateCajaFields(id, { nombre, sucursal, estatus }); notify('Caja actualizada','ok'); }
      else { await window.firebaseApi.addCaja({ nombre, sucursal, estatus }); notify('Caja creada','ok'); }
      closeModal(); render();
    }catch(e){ notify('Error guardando caja: '+(e.message||e),'err'); }
  }

  function onClickTable(e){ const btn=e.target.closest('button[data-action]'); if(!btn) return; const id=String(btn.dataset.id||''); const c=(Array.isArray(window.cajas)?window.cajas:[]).find(x=> String(x.id)===id); if(!c) return; openModal(c); }

  document.addEventListener('cajas:updated', render);
  searchInput && searchInput.addEventListener('keyup', render);
  showInact && showInact.addEventListener('change', render);
  tbody && tbody.addEventListener('click', onClickTable);
  newBtn && newBtn.addEventListener('click', ()=> openModal());
  form && form.addEventListener('submit', onSubmit);
  closeBtn && closeBtn.addEventListener('click', closeModal);
  overlay && overlay.addEventListener('click', (e)=>{ if(e.target===overlay) closeModal(); });
  render();
})();


