// === Producción: Hardening adicional ===
(function(){
  // Forzar modo estricto de algunas acciones si rol viewer
  function guardWriteButtons(){
    if(window.currentUserRole==='viewer'){
      document.querySelectorAll('[data-requires="write"]').forEach(b=>{ b.setAttribute('disabled','disabled'); b.classList.add('btn-disabled'); });
    } else {
      document.querySelectorAll('[data-requires="write"]').forEach(b=>{ b.removeAttribute('disabled'); b.classList.remove('btn-disabled'); });
    }
  }
  document.addEventListener('authRoleReady', guardWriteButtons);
  // Aplicar guardas básicas de permisos si tenemos el usuario actual cargado
  document.addEventListener('usuarios:updated', ()=>{
    try {
      const uid = window.auth?.currentUser?.uid;
      const me = (window.usuarios||[]).find(u=> String(u.id||u.uid)===String(uid));
      if(!me) return;
      // Deshabilitar controles sensibles si faltan permisos
      function toggle(selector, enabled){ document.querySelectorAll(selector).forEach(el=>{ if(enabled){ el.removeAttribute('disabled'); el.classList.remove('btn-disabled'); } else { el.setAttribute('disabled','disabled'); el.classList.add('btn-disabled'); } }); }
      // Descuentos/precios en venta
      toggle('[data-perm="descuentos"]', !!me.permDescuentos || (me.role==='admin'));
      toggle('[data-perm="precios"]', !!me.permPrecios || (me.role==='admin'));
  toggle('[data-perm="ventas-por-cobrar"]', (me.permVentasPorCobrar !== false) || (me.role==='admin'));
      // Eliminar ventas / movimientos caja
      toggle('[data-perm="eliminar-ventas"]', !!me.permEliminarVentas || (me.role==='admin'));
      toggle('[data-perm="eliminar-mov-caja"]', !!me.permEliminarMovCaja || (me.role==='admin'));
      // Cambiar forma de pago ingreso
      toggle('[data-perm="cambiar-forma-pago-ingreso"]', !!me.permCambiarFormaPagoIngreso || (me.role==='admin'));
      // Forzar habilitado del botón de eliminar ticket local (no es eliminación de venta histórica)
      try{
        const elimTicketBtn = document.getElementById('ventaEliminarBtn');
        if(elimTicketBtn){ elimTicketBtn.removeAttribute('disabled'); elimTicketBtn.classList.remove('btn-disabled'); }
      }catch(_e){}
      // Salvaguarda: si hay venta seleccionada no cancelada, asegurar botón cancelar activo aunque permiso actual lo haya bloqueado.
      try{
        const btn = document.getElementById('vdCancelarBtn');
        if(btn && window.selectedVenta && (window.selectedVenta.status||'')!=='CANCELADA'){
          btn.removeAttribute('disabled');
          btn.classList.remove('btn-disabled');
        }
      }catch(_e){}
    } catch(_e){}
  });
  // Aviso offline
  window.addEventListener('offline', ()=>{ notify && notify('Conexión perdida (modo offline)','warn'); });
  window.addEventListener('online', ()=>{ notify && notify('Conectado','ok'); });
})();

