// Realtime ligero global para solicitudes de cancelación pendientes (sólo ventaId) para refrescar color del botón cancelar
;(function initGlobalPendingApprovalsWatcher(){
  if(window.__globalPendingApprovalsWatcher) return; // singleton
  window.__globalPendingApprovalsWatcher = true;
  function start(){
    try{
      if(!window.db) { setTimeout(start,1000); return; }
      window.db.collection('admin_approvals').where('estado','==','PENDIENTE').onSnapshot(snap=>{
        try{
          const ventaIds=[]; snap.forEach(d=>{ const data=d.data(); if(data.ventaId) ventaIds.push(data.ventaId); });
          window.__pendingVentaApprovals = ventaIds;
          window.dispatchEvent(new CustomEvent('approvalsPendingChanged',{ detail:{ ventaIds } }));
        }catch(_e){}
      });
    }catch(_e){ setTimeout(start,3000); }
  }
  start();
})();

function getCurrentUserAccess(){
  const info = {
    authenticated:false,
    user:null,
    tags:new Set(),
    isAdmin:false,
    canPurchasing:false,
    canWarehouse:false,
    canCash:false,
    canSales:false,
    canProduction:false,
    canReports:false,
    canConfig:false,
    canCatalogs:false,
    canWhatsApp:false,
    canIntegrations:false,
    canAccountsPayable:false,
    canUsers:false,
    canSalesPorCobrar:false,
    explicitAllows:new Set(),
    explicitDenies:new Set()
  };
  try{
    const uid = window.auth?.currentUser?.uid;
    if(!uid) return info;
    info.authenticated = true;
    const users = Array.isArray(window.usuarios) ? window.usuarios : [];
    const me = users.find(u=> String(u.id||u.uid)===String(uid)) || null;
    info.user = me || null;
    const addTag = (val)=>{
      if(!val) return;
      String(val).split(/[\s,;\/]+/).map(s=> s.trim().toLowerCase()).filter(Boolean).forEach(tok=> info.tags.add(tok));
    };
    addTag(me?.role);
    addTag(me?.perfil);
    if(Array.isArray(me?.roles)) me.roles.forEach(addTag);
    if(Array.isArray(me?.permisos)) me.permisos.forEach(addTag);
    if(typeof me?.rol === 'string') addTag(me.rol);
    const tagsArr = Array.from(info.tags);
    tagsArr.forEach(tag=>{
      if(tag.startsWith('allow:')){ const token = tag.slice(6).trim(); if(token) info.explicitAllows.add(token.toLowerCase()); }
      if(tag.startsWith('deny:')){ const token = tag.slice(5).trim(); if(token) info.explicitDenies.add(token.toLowerCase()); }
    });
    const includesAny = (keywords)=> tagsArr.some(tag=> keywords.some(word=> tag.indexOf(word) !== -1));
    info.isAdmin = tagsArr.some(tag=> tag.includes('admin') || tag.includes('super') || tag.includes('gerente'));
    const purchasingKeywords = ['compras','purchase','purchasing','almacen','almacén','inventario','inventory','restock','bodega'];
    info.canPurchasing = info.isAdmin || includesAny(purchasingKeywords);
    info.canWarehouse = info.isAdmin || includesAny(['almacen','almacén','inventario','warehouse','logistica','logística','bodega']) || info.canPurchasing;
    info.canCash = info.isAdmin || includesAny(['caja','cash','teso','tesorera','tesorería','finan','finanzas','cajero']);
    info.canSales = info.isAdmin || includesAny(['venta','ventas','comercial','mostrador','cajero']);
    info.canProduction = info.isAdmin || includesAny(['produccion','producción','operacion','operación','maquina','máquina','mantenimiento','manufactura']);
    info.canReports = info.isAdmin || includesAny(['reporte','reportes','analytics','analitica','analítica','gerente','director','direccion','dirección','kpi']);
    info.canConfig = info.isAdmin || includesAny(['sistemas','system','config','setup','soporte','support','tech','tecnico','técnico','developer','devops','ti','it']);
    info.canCatalogs = info.isAdmin || info.canWarehouse || includesAny(['catalogo','catálogo','catalogos','catálogos']);
    info.canWhatsApp = info.isAdmin || info.canConfig || includesAny(['whatsapp','marketing','comunicacion','comunicación','soporte']);
    info.canIntegrations = info.canConfig || info.canWhatsApp;
    info.canAccountsPayable = info.isAdmin || includesAny(['cxp','cxc','pagar','proveedor','proveedores','finanzas','tesorer','tesorería','compras']);
    info.canUsers = info.isAdmin || includesAny(['usuarios','rrhh','humano','talento','recurso']);
    let porCobrarAllowed = true;
    if(me){
      if(me.permVentasPorCobrar === false) porCobrarAllowed = false;
      else if(me.permVentasPorCobrar === true) porCobrarAllowed = true;
      else if(info.isAdmin) porCobrarAllowed = true;
    }
    info.canSalesPorCobrar = porCobrarAllowed;
  }catch(_e){}
  return info;
}

