// Router global (History API): usar rutas limpias /nav-... en lugar de #hash
if(!window.__installedHistoryRouter){
  window.__installedHistoryRouter = true;

  function getNavIdFromUrl(){
    try {
      // Prioridad: pathname limpio /nav-...  Fallback: hash legacy #nav-...
      const path = (location.pathname||'').replace(/\/+$/,'');
      if(path && path !== '/'){
        const clean = decodeURIComponent(path.slice(1));
        if(navSectionMap[clean]) return clean;
      }
      const raw = (location.hash||'').replace(/^#/, '');
      if(raw && navSectionMap[raw]) return raw;
      return '';
    }catch(_e){}
  }

  function migrateHashToPath(){
    try{
      const raw = (location.hash||'').replace(/^#/, '');
      if(raw && navSectionMap[raw]){
        const newUrl = '/' + encodeURIComponent(raw) + (location.search || '');
        history.replaceState({}, '', newUrl);
      }
    }catch(_e){}
  }

  window.__navigateFromUrl = function(){
    try{
      let navId = getNavIdFromUrl();
      if(navId && typeof window.__handleNavigation === 'function'){
        window.__handleNavigation(navId, { skipPush:true });
        return;
      }
      if(!navId){
        let storedNav = '';
        try{ storedNav = localStorage.getItem('maq:lastNavId') || ''; }catch(_ls){}
        if(storedNav && navSectionMap[storedNav] && typeof window.__handleNavigation === 'function'){
          window.__handleNavigation(storedNav, { skipPush:true });
          return;
        }
        let storedSection = '';
        try{ storedSection = localStorage.getItem('maq:lastSectionId') || ''; }catch(_ls2){}
        if(storedSection){
          if(typeof window.mostrarSeccion === 'function'){
            window.mostrarSeccion(storedSection);
          } else {
            const secs = document.querySelectorAll('.generic-section');
            secs.forEach(s=> s.classList.add('hidden'));
            const el = document.getElementById(storedSection);
            if(el) el.classList.remove('hidden');
          }
        }
      }
    }catch(_e){}
  };

  function onReady(){
    migrateHashToPath();
    window.__navigateFromUrl();
  }

  window.addEventListener('popstate', ()=> window.__navigateFromUrl());
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', onReady);
  } else {
    onReady();
  }
}

// Manejar clics en los elementos de navegación para mostrar la sección adecuada
const navContainer = document.querySelector('.nav');
if (navContainer) {
  navContainer.addEventListener('click', (e) => {
    const target = e.target.closest('.sub-item, .nav-item');
    if (!target) return;
      // Bloquear navegación si no hay sesión; mantener login visible
      if(!(window.auth && window.auth.currentUser)){
        const loginSec = document.getElementById('login-section');
        if(loginSec){
          document.querySelectorAll('section').forEach((sec) => {
            if(sec.id === 'login-section') sec.classList.remove('hidden');
            else sec.classList.add('hidden');
          });
        }
        return;
      }
  const sectionId = navSectionMap[target.id];
    if (!sectionId) return;
  if(!ensureSectionAccess(sectionId)) return;
    e.stopPropagation();
    // Ocultar todas las secciones
      document.querySelectorAll('section').forEach((sec) => {
        if(!window.auth?.currentUser && sec.id === 'login-section') return;
        sec.classList.add('hidden');
      });
    // Mostrar la sección correspondiente
    const section = document.getElementById(sectionId);
    if (section) section.classList.remove('hidden');
    // Actualizar clases activas
    document.querySelectorAll('.sub-item.active, .nav-item.active').forEach((el) => el.classList.remove('active'));
    target.classList.add('active');
    // Si se accede a categorías, renderizar la tabla
    if (sectionId === 'cat-categorias-section') {
      renderCategoriasTable();
    }
    // Si se accede a Ventas/Utilidad, inicializar la sección de ventas
    if (sectionId === 'ventas-section') {
      initVentasSection();
    }
    // Al entrar a historial de consumibles, asegurar render y datos sincronizados
    if (sectionId === 'consumibles-historial-section') {
      if(!window._consumiblesData && window.consumibles){ window._consumiblesData = window.consumibles; }
      if (typeof renderHistConsumibles === 'function') renderHistConsumibles();
    }
      // Dashboard: inicializar al entrar
      if(sectionId === 'dashboard-section'){
        if(typeof initDashboard === 'function') initDashboard();
      }
  });
}

