  function renderRelaciones(){
    if(!elRelacionesBody) return;
    elRelacionesBody.innerHTML='';
    if(!relacionesState.items.length){
      const tr=document.createElement('tr'); tr.innerHTML='<td colspan="3" style="text-align:center;font-size:0.65rem;">No hay datos a mostrar</td>'; elRelacionesBody.appendChild(tr); return;
    }
    relacionesState.items.forEach(it=>{
      const tr=document.createElement('tr');
      tr.innerHTML=`<td style="font-size:0.6rem;">${escapeHtml(it.uuid)}</td><td style="font-size:0.6rem;">${escapeHtml(it.folio||'')}</td><td><button class="btn-icon" data-del-rel="${it.id}">🗑️</button></td>`;
      elRelacionesBody.appendChild(tr);
    });
  }
  elRelacionesBody?.addEventListener('click',e=>{ const btn=e.target.closest('button'); if(!btn) return; const del=btn.getAttribute('data-del-rel'); if(del){ relacionesState.items = relacionesState.items.filter(x=>x.id!==del); renderRelaciones(); }});
  // Modal relaciones
  const relOverlay = document.getElementById('relacionOverlay');
  const relForm = document.getElementById('relacionForm');
  const relUuid = document.getElementById('relacionUuid');
  const relFolio = document.getElementById('relacionFolio');
  const relCloseX = document.getElementById('relacionCloseX');
  const relCancelBtn = document.getElementById('relacionCancelBtn');
  function openRelacionModal(){ if(!relOverlay) return; relForm?.reset(); relOverlay.classList.remove('hidden'); relOverlay.style.display='flex'; setTimeout(()=> relUuid?.focus(),40); }
  function closeRelacionModal(){ if(!relOverlay) return; relOverlay.classList.add('hidden'); relOverlay.style.display='none'; }
  relCloseX?.addEventListener('click',closeRelacionModal); relCancelBtn?.addEventListener('click',closeRelacionModal); relOverlay?.addEventListener('click',e=>{ if(e.target===relOverlay) closeRelacionModal(); });
  relForm?.addEventListener('submit',e=>{ e.preventDefault(); if(!relUuid.value.trim()){ notify('UUID requerido','warn'); return; } relacionesState.items.push({ id:'rel'+Date.now()+Math.random().toString(36).slice(2), uuid: relUuid.value.trim(), folio: relFolio.value.trim() }); renderRelaciones(); closeRelacionModal(); notify('Relación agregada','ok'); });
  elAgregarRelacion?.addEventListener('click', openRelacionModal);
