  const pagPagoCancelarBtn = document.getElementById('pagPagoCancelarBtn');
  const pagPagoGuardarBtn = document.getElementById('pagPagoGuardarBtn');
  const pagFecha = document.getElementById('pagFecha');
  const pagSerie = document.getElementById('pagSerie');
  const pagFolio = document.getElementById('pagFolio');
  const pagImporte = document.getElementById('pagImporte');
