  function syncHistCanceladas(){
    const ventas = Array.isArray(window.ventas)? window.ventas: [];
    histCanceladasState = ventas.filter(v=> String(v.status||'').toUpperCase()==='CANCELADA').map(v=>{
      // Resolver fecha de cancelación como Date
      let fElim = null;
      try{
        if(v.cancelAt && typeof v.cancelAt.toDate==='function') fElim = v.cancelAt.toDate();
        else if(v.cancelAt) fElim = new Date(v.cancelAt);
      }catch(_e){/* ignore */}
      if(!fElim){
        try{ if(v.lastAbonoDate) fElim = new Date(v.lastAbonoDate); }catch(_e){}
      }
      if(!fElim) fElim = new Date();
  const users = Array.isArray(window.usuarios)? window.usuarios: [];
  const uAt = users.find(u=> String(u.id)===String(v.createdBy) || String(u.email||'')===String(v.createdBy) || String(u.displayName||'')===String(v.createdBy));
  const uEl = users.find(u=> String(u.id)===String(v.cancelBy) || String(u.email||'')===String(v.cancelBy) || String(u.displayName||'')===String(v.cancelBy));
  const atendioNom = uAt ? (uAt.nombre || uAt.displayName || uAt.email || uAt.id) : (v.createdByName || 'Usuario');
  const eliminoNom = uEl ? (uEl.nombre || uEl.displayName || uEl.email || uEl.id) : (v.cancelByName || 'Usuario');
      // Extraer productos de la venta cancelada (conceptos/items)
  // Preferir productosText guardado en la venta; si no, construirlo de conceptos/items
  let productosText = (typeof v.productosText==='string' && v.productosText.trim()) ? String(v.productosText).trim() : '';
  if(!productosText){
    const conceptos = Array.isArray(v.conceptos)? v.conceptos : (Array.isArray(v.items)? v.items : []);
    const prodsArr = conceptos.map(c=> hcResolveItemName(c)).filter(Boolean);
    productosText = prodsArr.join(', ');
  }
      return {
        id: v.id,
  folio: v.folio || '',
        fecha: v.fecha,
        cliente: v.clienteNombre||v.cliente||'CLIENTE',
        concepto: 'CANCELADA',
        importe: Number(v.total||0),
        pago: Number((v.total||0)-(v.saldo||0)),
        saldo: Number(v.saldo||0),
        atendio: atendioNom,
  atendioId: v.createdBy || null,
        elimino: eliminoNom,
  eliminoId: v.cancelBy || null,
        fechaElim: fElim,
        productosText
      };
    });
    // Construir universos únicos para sugerencias
    // Clientes: preferir universo desde Firebase (window.clientes)
    const cliSet = new Set();
    const seenLower = new Set();
    const allClientes = Array.isArray(window.clientes)? window.clientes : [];
    if(allClientes.length){
      for(const c of allClientes){
        const raw = c && (c.nombre || c.razonSocial);
        const name = (raw==null? '' : String(raw)).trim();
        if(name.length >= 3){ const key = name.toLowerCase(); if(!seenLower.has(key)){ seenLower.add(key); cliSet.add(name); } }
      }
    } else {
      // Fallback: usar los clientes presentes en canceladas
      for(const r of histCanceladasState){
        const name = (r && r.cliente)? String(r.cliente).trim() : '';
        if(name.length >= 3){ const key = name.toLowerCase(); if(!seenLower.has(key)){ seenLower.add(key); cliSet.add(name); } }
      }
    }
    // Productos: preferir catálogo de Firebase (window.products)
    const prodSet = new Set();
    const prodSeen = new Set();
    const allProds = Array.isArray(window.products)? window.products : [];
    if(allProds.length){
      for(const p of allProds){
        const raw = p && (p.descripcion || p.nombre);
        const name = (raw==null? '' : String(raw)).trim();
        if(name.length >= 3){ const key=name.toLowerCase(); if(!prodSeen.has(key)){ prodSeen.add(key); prodSet.add(name); } }
      }
    } else {
      // Fallback: extraer nombres desde ventas canceladas
      for(const r of histCanceladasState){
        if(r.productosText){
          String(r.productosText).split(',').forEach(p=>{ const t=p.trim(); if(t.length>=3){ const k=t.toLowerCase(); if(!prodSeen.has(k)){ prodSeen.add(k); prodSet.add(t); } } });
        }
      }
    }
    hcClientesUniverse = Array.from(cliSet).sort();
    hcProductosUniverse = Array.from(prodSet).sort();
    // Asegurar datalists y refrescar sugerencias visibles según texto actual
    ensureHcDatalists();
    updateHcClienteDatalist();
    updateHcProductoDatalist();
    filtrarHistCanceladas();
  // (backfill removido) deshabilitado backfill de productosText
  }
  window.updateHistCanceladasFromFirestore = syncHistCanceladas;
  syncHistCanceladas();

  function filtrarHistCanceladas(){
    if(!hcBody) return;
    const folio= hcFiltroFolio.value.trim().toLowerCase();
    const cliente= hcNorm(hcFiltroCliente.value.trim());
    const prod= hcNorm(hcFiltroProducto.value.trim());
  const usuario= hcFiltroUsuario.value;
    const saldoFiltro= hcFiltroSaldo.value;
  const sd = hcFechaInicio.value? new Date(hcFechaInicio.value+'T00:00:00'): null;
  const ed = hcFechaFin.value? new Date(hcFechaFin.value+'T23:59:59'): null;
  const rows = histCanceladasState.filter(r=>{
  if(folio && !String(r.folio||'').toLowerCase().includes(folio)) return false;
      if(cliente && !hcNorm(r.cliente).includes(cliente)) return false;
      if(prod && !hcNorm(r.productosText||'').includes(prod)) return false;
      if(usuario!=='all'){
        const users = Array.isArray(window.usuarios)? window.usuarios: [];
        const u = users.find(x=> String(x.id)===String(usuario) || String(x.nombre||x.displayName||x.email||'')===String(usuario));
        if(u){
          const name = String(u.nombre||u.displayName||u.email||'');
          const uid = String(u.id);
          const match = String(r.atendioId||'')===uid || String(r.eliminoId||'')===uid || String(r.atendio||'')===name || String(r.elimino||'')===name;
          if(!match) return false;
        } else {
          // Value could be a plain name present in options
          const val = String(usuario);
          if(String(r.atendio||'')!==val && String(r.elimino||'')!==val) return false;
        }
      }
      if(saldoFiltro==='con' && r.saldo<=0) return false;
      if(saldoFiltro==='sin' && r.saldo>0) return false;
  const rf = (r.fechaElim instanceof Date)? r.fechaElim : (r.fechaElim ? new Date(r.fechaElim) : null);
  if(sd && rf < sd) return false;
  if(ed && rf > ed) return false;
      return true;
    });
    renderHistCanceladas(rows);
  }

  // (backfill removido) función backfillHcProductosText eliminada

  function renderHistCanceladas(data){
    hcBody.innerHTML='';
  if(!data.length){ hcBody.innerHTML='<tr class="no-data"><td colspan="13" style="text-align:center;padding:16px;color:#64748b;font-size:0.75rem;">No hay datos a mostrar</td></tr>'; return; }
    data.forEach(r=>{
      const tr=document.createElement('tr');
  const folio = r.folio || '-';
  const cliente = r.cliente || 'CLIENTE';
  const prodTxt = (r.productosText && String(r.productosText).trim()) ? r.productosText : '—';
  const fecha = r.fecha || r.fechaElim || null;
  const concepto = r.concepto || '—';
  const importe = isFinite(r.importe)? r.importe: 0;
  const pago = isFinite(r.pago)? r.pago: 0;
  const saldo = isFinite(r.saldo)? r.saldo: 0;
  const atendio = r.atendio || 'Usuario';
  const elimino = r.elimino || 'Usuario';
      tr.innerHTML=`
        <td style="text-align:center;">✖</td>
  <td>${escapeHtml(folio)}</td>
    <td>${escapeHtml(cliente)}</td>
    <td>${escapeHtml(prodTxt)}</td>
    <td>${formatDateYMD(fecha)}</td>
    <td>${escapeHtml(concepto)}</td>
    <td>${money(importe)}</td>
    <td>${money(pago)}</td>
    <td>${money(saldo)}</td>
    <td>${escapeHtml(atendio)}</td>
    <td>${escapeHtml(elimino)}</td>
  <td>${formatDateYMD(r.fechaElim)}</td>`;
      hcBody.appendChild(tr);
    });
  }

