  [hcFiltroFolio,hcFiltroCliente,hcFiltroProducto,hcFiltroUsuario,hcFiltroSaldo,hcFechaInicio,hcFechaFin].forEach(el=> el?.addEventListener('change', filtrarHistCanceladas));
