  function populateHcUsuarios(){
    if(!hcFiltroUsuario) return;
    const current = hcFiltroUsuario.value || 'all';
    const users = Array.isArray(window.usuarios)? window.usuarios: [];
    const opts = [{ value:'all', label:'Todos los usuarios' }].concat(users.map(u=> ({ value:String(u.id), label:String(u.nombre||u.displayName||u.email||u.id) })));
    hcFiltroUsuario.innerHTML = opts.map(o=> `<option value="${o.value}">${o.label}</option>`).join('');
    // También incluir nombres que aparezcan en canceladas pero no estén en usuarios (por seguridad)
    try{
      const extra = new Set();
      histCanceladasState.forEach(r=>{ if(r.atendio) extra.add(String(r.atendio)); if(r.elimino) extra.add(String(r.elimino)); });
      extra.forEach(n=>{ if(!opts.some(o=> o.label===n)){ const opt=document.createElement('option'); opt.value=n; opt.textContent=n; hcFiltroUsuario.appendChild(opt); } });
    }catch(_e){}
    hcFiltroUsuario.value = current;
  }
