  function togglePeriodicidadUI(){
    const p = (cxpPeriodicidad?.value)||'UNICA';
    const unica = p==='UNICA';
    if(grpFechaEntrega) grpFechaEntrega.style.display = unica? '' : 'none';
    if(grpProximoVencimiento) grpProximoVencimiento.style.display = unica? 'none' : '';
    if(grpPreavisoDias) grpPreavisoDias.style.display = unica? 'none' : '';
  // Mostrar controles de configuración según tipo
    const showInterval = ['DIARIA','SEMANAL','MENSUAL','ANUAL','PERSONALIZADA'].includes(p);
  if(grpRecInterval) grpRecInterval.style.display = (!unica && showInterval)? '' : 'none';
    if(grpRecWeekdays) grpRecWeekdays.style.display = (p==='SEMANAL' || p==='PERSONALIZADA')? '' : 'none';
    if(grpRecMonthDay) grpRecMonthDay.style.display = (['MENSUAL','ANUAL','PERSONALIZADA'].includes(p))? '' : 'none';
  }
