    if(!lista.length){ rgBody.innerHTML='<tr class="no-data"><td colspan="5" style="text-align:center;padding:18px;color:#64748b;font-size:0.7rem;">No hay datos</td></tr>'; if(rgTotalImporte) rgTotalImporte.textContent = '$ 0.00'; drawRgCharts([]); return; }
    let total=0;
