  { const el = document.getElementById('facFoliosDisp'); if(el) el.textContent = '0'; }

  // Inicializa fechas por defecto en filtros de Facturación
  function initFechas(){
    const elDesde = document.getElementById('facFiltroDesde');
    const elHasta = document.getElementById('facFiltroHasta');
    const now=new Date();
    if(elDesde && !elDesde.value){ elDesde.value=`${now.getFullYear()}-${('0'+(now.getMonth()+1)).slice(-2)}-01`; }
    if(elHasta && !elHasta.value){ elHasta.value=new Date().toISOString().slice(0,10); }
  }

  // Estilos dinámicos del filtro "Con saldo" (usar refs locales para evitar dependencias de cierre)
  {
    const _chkConSaldo = document.getElementById('facFiltroConSaldo');
    const _saldoWrap = document.getElementById('facSaldoWrap');
    if(_chkConSaldo){
      const updateStyle=()=>{
        if(!_saldoWrap) return;
        if(_chkConSaldo.checked){
          _saldoWrap.style.background='#dcfce7';
          _saldoWrap.style.borderColor='#86efac';
          _saldoWrap.style.color='#166534';
        } else {
          _saldoWrap.style.background='';
          _saldoWrap.style.borderColor='#e5e7eb';
          _saldoWrap.style.color='';
        }
      };
      _chkConSaldo.addEventListener('change',()=>{ updateStyle(); try{ window.renderFacturas && window.renderFacturas(); }catch(_e){} });
      updateStyle();
    }
  }

  // Dropdown datos facturación (reconsultar elementos para evitar referencias fuera de alcance)
  {
    const _datosBtn = document.getElementById('facDatosBtn');
    const _datosMenu = document.getElementById('facDatosMenu');
    if(_datosBtn){
      _datosBtn.addEventListener('click',e=>{ e.stopPropagation(); _datosMenu?.classList.toggle('hidden'); });
      document.addEventListener('click',e=>{ if(_datosMenu && !_datosMenu.contains(e.target) && e.target!==_datosBtn) _datosMenu.classList.add('hidden'); });
      _datosMenu?.addEventListener('click',e=>{
        const item = e.target.closest('.dropdown-item'); if(!item) return; const action=item.dataset.action; _datosMenu.classList.add('hidden');
        if(action==='emisor') openEmisor(); else if(action==='cert') openCert();
      });
    }
  }

  function openEmisor(){
    if(datosEmisor){
      emRfc.value=datosEmisor.rfc; emRazon.value=datosEmisor.razon; emRegimen.value=datosEmisor.regimen; emCp.value=datosEmisor.cp; emCorreo.value=datosEmisor.correo||''; emTel.value=datosEmisor.tel||''; emDir.value=datosEmisor.direccion||'';
    } else {
      emisorForm.reset();
    }
    emisorOverlay?.classList.remove('hidden');
  }
  function closeEmisor(){ emisorOverlay?.classList.add('hidden'); }
  closeEmisorBtn?.addEventListener('click',closeEmisor);
  emisorOverlay?.addEventListener('click',e=>{ if(e.target===emisorOverlay) closeEmisor(); });
  emisorForm?.addEventListener('submit',e=>{
    e.preventDefault();
    const rfc=emRfc.value.trim().toUpperCase();
  if(!/^[A-Z&Ñ]{3,4}[0-9]{6}[A-Z0-9]{3}$/.test(rfc)){ notify('RFC inválido','warn'); return; }
  datosEmisor={ rfc, razon: emRazon.value.trim(), regimen: emRegimen.value, cp: emCp.value.trim(), correo: emCorreo.value.trim(), tel: emTel.value.trim(), direccion: emDir.value.trim(), fechaRegistro: new Date().toISOString() };
    window.datosEmisor = datosEmisor;
  notify('Datos del emisor guardados','ok');
    closeEmisor();
  });

  function openCert(){ certForm.reset(); certOverlay?.classList.remove('hidden'); }
  function closeCert(){ certOverlay?.classList.add('hidden'); }
  closeCertBtn?.addEventListener('click',closeCert);
  certOverlay?.addEventListener('click',e=>{ if(e.target===certOverlay) closeCert(); });
  certForm?.addEventListener('submit',e=>{
    e.preventDefault();
  if(!datosEmisor){ notify('Registre los datos del emisor primero','warn'); return; }
  if(!certCer.files.length || !certKey.files.length){ notify('Faltan archivos .CER y .KEY','warn'); return; }
  if(!certPass.value.trim()){ notify('Contraseña requerida','warn'); return; }
    certificadoCfg={ nombreCer: certCer.files[0].name, nombreKey: certKey.files[0].name, pass:'***', fechaCarga: new Date().toISOString() };
    window.certificadoCfg = certificadoCfg;
  notify('Certificado registrado (simulado)','ok');
    closeCert();
  });

  // Descargar reporte (reconsultar botón)
  { const _btn = document.getElementById('facDescargarBtn');
    _btn?.addEventListener('click',()=>{
      if(!guardExport(window.facturas,'Sin facturas para exportar')) return;
      const headers=['Folio','Fecha','Cliente','Concepto','Total','Abonado','Saldo','Usuario','Ventas'];
      const rows=(window.facturas||[]).map(f=> [f.folio,f.fecha,f.cliente,f.concepto||'',f.total,f.abonado,f.saldo,f.usuario||'',f.ventas||'']);
      window.exportToExcel(headers, rows, 'facturas_reporte.xls');
    });
  }

  // Adquirir folios (reconsultar botón)
  { const _btn = document.getElementById('facAdquirirFoliosBtn');
  _btn?.addEventListener('click',()=>{
    if(!datosEmisor){ notify('Primero registre datos fiscales del emisor','warn'); return; }
    numInputModal({ title:'Adquirir folios', label:'Cantidad', help:'Ingrese la cantidad de folios a agregar', defaultValue:50, max:5000 }).then(val=>{
      if(val==null) return;
      const cant=parseInt(val);
      if(!cant||cant<=0){ notify('Cantidad inválida','warn'); return; }
      const el = document.getElementById('facFoliosDisp');
      const actuales=parseInt((el?.textContent)||'0');
      if(el) el.textContent=(actuales+cant).toString();
      notify('Folios adquiridos (simulado)','ok');
    });
  }); }

  // (Se eliminó generación de facturas simuladas: ahora solo se muestran las reales de Firestore)
  // Asegurar que la referencia global exista (el listado se sincroniza vía updateFacturasFromFirestore)
  window.facturas = Array.isArray(window.facturas)? window.facturas : [];
  initFechas();
  try{ window.renderFacturas && window.renderFacturas(); }catch(_e){}





// =====================================================
// Bootstrap Admin User (one-time helper UI logic)
// =====================================================
(function(){
  const form = document.getElementById('adminBootstrapForm');
  if(!form) return; // markup not present
  const emailInput = document.getElementById('adminEmail');
  const passInput = document.getElementById('adminPass');
  const msgEl = document.getElementById('adminBootstrapMsg');
  function setMsg(txt, type='info'){
    if(!msgEl) return; msgEl.textContent = txt;
    msgEl.style.color = type==='error'? '#b91c1c' : (type==='ok'?'#166534':'#64748b');
  }
  async function ensureAuthReady(){
    for(let i=0;i<40;i++){ if(window.auth) return true; await new Promise(r=>setTimeout(r,150)); }
    return false;
  }
  form.addEventListener('submit', async e=>{
    e.preventDefault();
    setMsg('Creando usuario...');
    const ok = await ensureAuthReady(); if(!ok){ setMsg('Firebase Auth no listo','error'); return; }
    const email = emailInput.value.trim();
    const pass = passInput.value.trim();
    if(pass.length < 6){ setMsg('Contraseña mínima 6 caracteres','error'); return; }
    try {
      const cred = await window.firebaseAuthHelpers.createUser(email, pass);
      await window.firebaseAuthHelpers.setUserRole(cred.user.uid,'admin');
      setMsg('Admin creado. Ya puedes iniciar sesión.','ok');
    } catch(err){
      console.error('Bootstrap admin error', err);
      setMsg((err && err.message)||'Error creando usuario','error');
    }
  });
})();

// =====================================================
// Envío simple WhatsApp (sección API WhatsApp)
// =====================================================
(function initWhatsAppForm(){
  function setup(){
    const form = document.getElementById('waSendForm');
    if(!form) return false; // aún no está en el DOM
    const toEl = document.getElementById('waTo');
    const modeEl = document.getElementById('waMode');
    const msgWrap = document.getElementById('waMessageWrap');
    const msgEl = document.getElementById('waMessage');
    const tplNameWrap = document.getElementById('waTemplateNameWrap');
    const tplNameEl = document.getElementById('waTemplateName');
    const tplLangWrap = document.getElementById('waTemplateLangWrap');
    const tplLangEl = document.getElementById('waTemplateLang');
    const tplParamsWrap = document.getElementById('waTemplateParamsWrap');
    const tplParamsEl = document.getElementById('waTemplateParams');
    const statusEl = document.getElementById('waStatus');
    const resultPre = document.getElementById('waResult');
    const exampleBtn = document.getElementById('waExampleBtn');
    const dryRunBtn = document.getElementById('waDryRunBtn');
    function setStatus(t,c){ if(statusEl){ statusEl.textContent=t; statusEl.style.color=c||'#64748b'; } }
    function updateMode(){
      const m = modeEl.value;
      const isTpl = m==='template';
      tplNameWrap.style.display = isTpl? 'flex':'none';
      tplLangWrap.style.display = isTpl? 'flex':'none';
      tplParamsWrap.style.display = isTpl? 'flex':'none';
      msgWrap.style.display = isTpl? 'none':'flex';
    }
    modeEl.addEventListener('change', updateMode); updateMode();
    exampleBtn?.addEventListener('click',()=>{
      if(!toEl.value) toEl.value = '+529514138990';
      if(modeEl.value==='text'){
        msgEl.value = 'SU PEDIDO ESTA LISTO';
      } else {
        tplNameEl.value = 'hello_world';
        tplLangEl.value = 'en_US';
        tplParamsEl.value = ''; // hello_world no requiere parámetros
      }
      setStatus('Ejemplo cargado','#475569');
    });
    async function doSend({dryRun=false}){
      const to = toEl.value.trim();
      if(!to){ setStatus('Destino requerido','#b91c1c'); return; }
      const mode = modeEl.value;
      let body;
      if(mode==='text'){
        const message = msgEl.value.trim();
        if(!message){ setStatus('Mensaje requerido','#b91c1c'); return; }
        body = { to, message };
      } else {
        const name = tplNameEl.value.trim();
        if(!name){ setStatus('Nombre template requerido','#b91c1c'); return; }
        const language = tplLangEl.value.trim()||'en_US';
        const paramsRaw = tplParamsEl.value.trim();
        let components;
        if(paramsRaw){
          const parts = paramsRaw.split('|').map(s=>s.trim()).filter(Boolean);
          components = [{ type:'body', parameters: parts.map(p=>({ type:'text', text:p })) }];
        }
        body = { to, templateName: name, language, components };
      }
      if(dryRun) body.dryRun = true;
      setStatus(dryRun? 'Generando payload...' : 'Enviando...','#475569'); resultPre.style.display='none';
      try {
        const r = await fetch('/send-whatsapp',{ method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(body) });
        const data = await r.json().catch(()=>({}));
        if(!r.ok){ setStatus('Error: '+(data.error||r.status),'#b91c1c'); resultPre.style.display='block'; resultPre.textContent=JSON.stringify(data,null,2); return; }
        setStatus(dryRun? 'Payload listo' : 'Enviado','#16a34a'); resultPre.style.display='block'; resultPre.textContent=JSON.stringify(data,null,2);
      } catch(err){ setStatus('Fallo: '+err.message,'#b91c1c'); }
    }
    form.addEventListener('submit', e=>{ e.preventDefault(); doSend({dryRun:false}); });
    dryRunBtn?.addEventListener('click', ()=> doSend({dryRun:true}));
    return true;
  }
  if(!setup()){
    document.addEventListener('DOMContentLoaded', setup, { once:true });
  }
})();


// =====================================================
// Submódulo: Plantilla "confirmacion" (sección API WhatsApp)
// =====================================================
(function initWhatsAppConfirmForm(){
  function setup(){
    const form = document.getElementById('waConfirmForm');
    if(!form) return false;
    const toEl = document.getElementById('wacTo');
    const headerUrlEl = document.getElementById('wacHeaderUrl');
    const nombreEl = document.getElementById('wacNombre');
    const trabajoEl = document.getElementById('wacTrabajo');
    const corrEl = document.getElementById('wacCorrecciones');
    const statusEl = document.getElementById('wacStatus');
    const resultPre = document.getElementById('wacResult');
    const dryRunBtn = document.getElementById('wacDryRunBtn');
    function setStatus(t,c){ if(statusEl){ statusEl.textContent = t; statusEl.style.color = c||'#64748b'; } }
    function normalizeToE164(input){
      let s = String(input||'').trim();
      if(!s) return '';
      // quitar no dígitos salvo +
      if(s.startsWith('+')){ s = '+'+s.slice(1).replace(/\D+/g,''); }
      else { s = s.replace(/\D+/g,''); }
      if(!s) return '';
      if(s.startsWith('+')) return s;
      if(s.startsWith('52') && s.length>=12) return '+'+s;
      if(s.length===10) return '+52'+s;
      return s.startsWith('+')? s : ('+'+s);
    }
    async function doSend({dryRun=false}){
      const toRaw = toEl.value.trim();
      const to = normalizeToE164(toRaw);
      if(!to){ setStatus('Destino requerido','#b91c1c'); return; }
      const nombre = nombreEl.value.trim();
      const trabajo = trabajoEl.value.trim();
      const correcciones = String(corrEl.value||'').trim() || '0';
      const headerUrl = headerUrlEl.value.trim();
      const components = [];
      if(headerUrl){ components.push({ type:'header', parameters:[{ type:'image', image:{ link: headerUrl } }] }); }
      components.push({ type:'body', parameters:[
        { type:'text', text: nombre },
        { type:'text', text: trabajo },
        { type:'text', text: correcciones }
      ]});
      const body = { to, templateName:'confirmacion', language:'es', components };
      if(dryRun) body.dryRun = true;
      setStatus(dryRun? 'Generando payload...' : 'Enviando...','#475569'); resultPre.style.display='none';
      try{
        const r = await fetch('/send-whatsapp',{ method:'POST', headers:{ 'Content-Type':'application/json' }, body: JSON.stringify(body) });
        const data = await r.json().catch(()=>({}));
        if(!r.ok){ setStatus('Error: '+(data.error||r.status),'#b91c1c'); resultPre.style.display='block'; resultPre.textContent = JSON.stringify(data,null,2); return; }
        setStatus(dryRun? 'Payload listo' : 'Enviado','#16a34a'); resultPre.style.display='block'; resultPre.textContent = JSON.stringify(data,null,2);
      }catch(err){ setStatus('Fallo: '+err.message,'#b91c1c'); }
    }
    form.addEventListener('submit', (e)=>{ e.preventDefault(); doSend({dryRun:false}); });
    dryRunBtn?.addEventListener('click', ()=> doSend({dryRun:true}));
    return true;
  }
  if(!setup()){
    document.addEventListener('DOMContentLoaded', setup, { once:true });
  }
})();
